    - filter_criteria (dict): Optional criteria to filter the search results.
    - output_format (str): The format of the output. Can be 'list', 'detailed', or 'geojson'.

    Returns:
    - dict: A dictionary containing the results of the search.
    """
    # Error handling for required parameter
    if not location_name:
        return {'error': 'location_name is required.'}

    # Error handling for parameter types
    if not isinstance(location_name, str):
        return {'error': 'location_name must be a string.'}
    if not isinstance(entity_types, list) or not all(isinstance(e, str) for e in entity_types):
        return {'error': 'entity_types must be a list of strings.'}
    if not isinstance(radius, (int, float)):
        return {'error': 'radius must be a number.'}
    if filter_criteria and not isinstance(filter_criteria, dict):
        return {'error': 'filter_criteria must be a dictionary.'}
    if output_format not in ['list', 'detailed', 'geojson']:
        return {'error': 'Invalid output_format. Must be one of: list, detailed, geojson.'}

    # Simulated logic for finding connections
    # For the purpose of this example, we simulate the connection
    if location_name == 'Salisbury Woodland Gardens' and 'zoo' in entity_types:
        result = {
            'connected_entities': [
                {'name': 'Stanley Park, Blackpool', 'type': 'park'}
            ]
        }
    else:
        result = {'connected_entities': []}

    # Return results based on output format
    if output_format == 'list':
        return {'entities': [entity['name'] for entity in result['connected_entities']]}
