def film_voice_actor_search(actor_name, release_year, film_database, genre=None, director_name=None, output_format='title_only'):
    """
    Searches for films in the provided database based on the given criteria.

    Parameters:
    - actor_name (str): The name of the voice actor to search for.
    - release_year (int): The year of the film's release.
    - film_database (list): A list of film dictionaries to search through.
    - genre (str, optional): The genre of the film to filter the search.
    - director_name (str, optional): The name of the director to filter the search.
    - output_format (str, optional): The format of the output. Defaults to 'title_only'.

    Returns:
    - list: A list of films matching the search criteria in the specified output format.
    """
    # Validate required parameters
    if not isinstance(actor_name, str) or not isinstance(release_year, int) or not isinstance(film_database, list):
        return {'error': 'Invalid input types for required parameters.'}

    # Validate optional parameters
    if genre is not None and not isinstance(genre, str):
        return {'error': 'Invalid input type for genre.'}
    if director_name is not None and not isinstance(director_name, str):
        return {'error': 'Invalid input type for director_name.'}
    if output_format not in ['title_only', 'full_details', 'detailed_with_genre_director']:
        return {'error': 'Invalid output format specified.'}

    # Search for films
    results = []
    for film in film_database:
        if (film['year'] == release_year and
            actor_name in film['voice_actors'] and
            (genre is None or film['genre'] == genre) and
            (director_name is None or film['director'] == director_name)):
            if output_format == 'title_only':
                results.append(film['title'])
            elif output_format == 'full_details':
                results.append(film)
            elif output_format == 'detailed_with_genre_director':
                results.append({
                    'title': film['title'],
                    'genre': film['genre'],
                    'director': film['director']
                })

    return results

