def film_info_retriever(film_title: str, release_year: int, info_type: list) -> dict:
    """
    Retrieve specific information about a film based on the title, release year, and requested info types.

    :param film_title: The title of the film to retrieve information for.
    :param release_year: The release year of the film to ensure accuracy.
    :param info_type: A list of information types to retrieve (e.g., ['director', 'writer']).
    :return: A dictionary containing the requested information or an error message.
    """
    # Simulated database of films for demonstration purposes
    film_database = {
        ('Sing', 2016): {
            'director': 'Garth Jennings',
            'writer': 'Garth Jennings',
            'cast': ['Matthew McConaughey', 'Reese Witherspoon'],
            'genre': 'Animation',
            'runtime': '108 minutes'
        }
    }

    # Validate input parameters
    if not isinstance(film_title, str) or not film_title:
        return {'error': 'Invalid or missing film_title parameter.'}
    if not isinstance(release_year, int):
        return {'error': 'Invalid or missing release_year parameter.'}
    if not isinstance(info_type, list) or not info_type:
        return {'error': 'Invalid or missing info_type parameter.'}
    if not all(item in ['director', 'writer', 'cast', 'genre', 'runtime'] for item in info_type):
        return {'error': 'Invalid info_type values. Allowed values are director, writer, cast, genre, runtime.'}

    # Retrieve film information
    film_key = (film_title, release_year)
    if film_key not in film_database:
        return {'error': 'Film not found in the database.'}

    film_info = film_database[film_key]
    result = {key: film_info[key] for key in info_type if key in film_info}

    return result

