def extract_last_name(full_name, delimiter=' ', name_format='first_last', suffix_handling=False, title_handling=False, custom_delimiters=None):
    # Validate input
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full name provided.'}
    if name_format not in ['first_last', 'first_middle_last', 'last_first', 'first_last_suffix', 'title_first_last']:
        return {'error': 'Unsupported name format.'}

    # Use custom delimiters if provided
    if custom_delimiters:
        for custom_delimiter in custom_delimiters:
            full_name = full_name.replace(custom_delimiter, delimiter)

    # Split the full name using the delimiter
    name_parts = full_name.split(delimiter)

    # Extract last name based on the name format
    last_name = ''
    if name_format == 'first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first':
        last_name = name_parts[0]
    elif name_format == 'first_last_suffix':
        last_name = name_parts[-2] if suffix_handling else name_parts[-1]
    elif name_format == 'title_first_last':
        last_name = name_parts[-1] if title_handling else name_parts[-1]

    # Return the extracted last name
    return {'last_name': last_name}

