def athlete_draft_info(athlete_name: str, sport: str, year_range: list = None, output_format: str = 'year', draft_position: int = None, team: str = None, round: int = None, league_filter: str = None):
    """
    Retrieve comprehensive draft information for athletes.

    :param athlete_name: The full name of the athlete whose draft information is being queried.
    :param sport: The sport in which the athlete was drafted, e.g., NFL, NBA, etc.
    :param year_range: The range of years to search within, useful for athletes who may have been drafted multiple times.
    :param output_format: The format of the output. 'year' returns just the draft year, 'detailed' provides additional information such as team and round, 'summary' gives a brief overview, and 'full' provides all available details.
    :param draft_position: The draft position of the athlete, if applicable.
    :param team: The team that drafted the athlete.
    :param round: The round in which the athlete was drafted.
    :param league_filter: Filter results by specific league, e.g., 'NCAA', 'EuroLeague'.
    :return: Draft information based on the specified output format.
    """
    # Simulated database of draft information
    draft_data = {
        'Boss Bailey': {'sport': 'NFL', 'year': 2003, 'team': 'Detroit Lions', 'round': 2, 'position': 34}
    }

    # Error handling for required parameters
    if not athlete_name or not sport:
        return {'error': 'athlete_name and sport are required parameters.'}

    # Check if athlete exists in the database
    athlete_info = draft_data.get(athlete_name)
    if not athlete_info or athlete_info['sport'] != sport:
        return {'error': 'No draft information found for the specified athlete and sport.'}

    # Prepare the output based on the requested format
    if output_format == 'year':
        return {'year': athlete_info['year']}
