def closest_palindrome_finder(input_number, search_direction='both', equidistant_preference='lower', search_range_limit=None, output_detail='basic'):
    # Helper function to check if a number is a palindrome
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    # Validate input parameters
    if not isinstance(input_number, int):
        return {'error': 'input_number must be an integer'}
    if search_direction not in ['both', 'up', 'down']:
        return {'error': 'Invalid search_direction value'}
    if equidistant_preference not in ['lower', 'higher', 'both']:
        return {'error': 'Invalid equidistant_preference value'}
    if search_range_limit is not None and not isinstance(search_range_limit, int):
        return {'error': 'search_range_limit must be an integer if specified'}
    if output_detail not in ['basic', 'detailed']:
        return {'error': 'Invalid output_detail value'}

    # Initialize variables
    lower_palindrome = None
    higher_palindrome = None
    distance = 0

    # Search for the closest palindrome
    while True:
        if search_range_limit is not None and distance > search_range_limit:
            break

        # Check lower palindrome
        if search_direction in ['both', 'down']:
            if is_palindrome(input_number - distance):
                lower_palindrome = input_number - distance

        # Check higher palindrome
        if search_direction in ['both', 'up']:
            if is_palindrome(input_number + distance):
                higher_palindrome = input_number + distance

        # Determine the closest palindrome based on preferences
        if lower_palindrome is not None and higher_palindrome is not None:
            if equidistant_preference == 'lower':
                return {'palindrome': lower_palindrome}
            elif equidistant_preference == 'higher':
                return {'palindrome': higher_palindrome}
            elif equidistant_preference == 'both':
                return {'palindrome': (lower_palindrome, higher_palindrome)}

        if lower_palindrome is not None:
            return {'palindrome': lower_palindrome}

        if higher_palindrome is not None:
            return {'palindrome': higher_palindrome}

        distance += 1

    # If no palindrome found within the range limit
    return {'error': 'No palindrome found within the specified range'}

