def enhanced_alphabetical_sorter(input, case_sensitive=False, exclude_characters=[], output_format='string', reverse_order=False, include_numbers=False, exclude_whitespace=False):
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Convert input to lowercase if case_sensitive is False
    if not case_sensitive:
        input = input.lower()

    # Exclude specified characters
    input = ''.join([char for char in input if char not in exclude_characters])

    # Exclude whitespace if exclude_whitespace is True
    if exclude_whitespace:
        input = input.replace(' ', '')

    # Include numbers if include_numbers is True
    if not include_numbers:
        input = ''.join([char for char in input if not char.isdigit()])

    # Sort the characters
    sorted_chars = sorted(input, reverse=reverse_order)

    # Return the result in the specified format
    if output_format == 'array':
        return sorted_chars
    else:
        return ''.join(sorted_chars)

