def extract_first_name(names, include_prefix=False, include_suffix=False, output_format='string', case_sensitive=False):
    # Validate input parameters
    if not isinstance(names, list) or len(names) < 1:
        return {'error': 'Invalid input: names must be a non-empty list of strings.'}
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid output_format: must be one of string, array, or json.'}

    # Helper function to extract first name
    def get_first_name(full_name):
        # Split the name into parts
        parts = full_name.split()
        # Check for prefixes and suffixes
        if include_prefix and parts[0].lower() in ['mr.', 'ms.', 'mrs.', 'dr.']:
            first_name = parts[0] + ' ' + parts[1]
        else:
            first_name = parts[0]
        # Handle case sensitivity
        if not case_sensitive:
            first_name = first_name.capitalize()
        return first_name

    # Process each name in the list
    extracted_names = [get_first_name(name) for name in names]

    # Format the output based on the specified output_format
    if output_format == 'string':
        return extracted_names[0]  # Return the first name of the first entry
    elif output_format == 'array':
        return extracted_names
    elif output_format == 'json':
        return {'first_names': extracted_names, 'metadata': {'count': len(extracted_names)}}

