def historical_relationship_finder(person_name: str, relationship_type: str = 'marriage', time_period: str = None, relationship_duration: str = None, relationship_significance: str = None, output_format: str = 'text') -> str:
    """
    Finds and analyzes relationships of historical figures and celebrities.

    Parameters:
    - person_name (str): The name of the person whose relationships are being queried.
    - relationship_type (str): The type of relationship to query. Defaults to 'marriage'.
    - time_period (str): The time period to consider for the relationship, formatted as 'YYYY-YYYY'. Optional.
    - relationship_duration (str): The duration of the relationship in years, formatted as 'X-Y'. Optional.
    - relationship_significance (str): The significance of the relationship. Optional.
    - output_format (str): The format of the output. Defaults to 'text'.

    Returns:
    - str: The result of the query in the specified output format.
    """
    # Simulated database query result
    relationships_db = {
        'Barbara Bach': {
            'marriage': [
                {'partner': 'Ringo Starr', 'time_period': '1981-present', 'duration': '42', 'significance': 'high'}
            ]
        }
    }

    # Validate relationship_type
    if relationship_type not in ['marriage', 'partnership', 'association', 'affair', 'friendship']:
        return "Error: Invalid relationship type."

    # Validate output_format
    if output_format not in ['text', 'json', 'xml']:
        return "Error: Invalid output format."

    # Retrieve relationships for the person
    person_relationships = relationships_db.get(person_name, {})
    relationships = person_relationships.get(relationship_type, [])

    # Filter relationships based on optional parameters
    filtered_relationships = []
    for relationship in relationships:
        if time_period and not relationship['time_period'].startswith(time_period.split('-')[0]):
            continue
        if relationship_duration and not relationship['duration'].startswith(relationship_duration.split('-')[0]):
            continue
        if relationship_significance and relationship['significance'] != relationship_significance:
            continue
        filtered_relationships.append(relationship)

    # Format the output
    if output_format == 'text':
        return f"{person_name} has the following {relationship_type}(s): " + ", ".join([rel['partner'] for rel in filtered_relationships])
    elif output_format == 'json':
        import json
        return json.dumps(filtered_relationships)
    elif output_format == 'xml':
        import xml.etree.ElementTree as ET
        root = ET.Element('Relationships')
        for rel in filtered_relationships:
            rel_elem = ET.SubElement(root, 'Relationship')
            for key, value in rel.items():
                child = ET.SubElement(rel_elem, key)
                child.text = value
        return ET.tostring(root, encoding='unicode')

    return "No relationships found."

# Example usage
