print(result)  # Expected output: 'Barbara Bach has the following marriage(s): Ringo Starr'

def advanced_character_counter(input, characters, output_format='integer', case_sensitive=True, ignore_whitespace=False):
    # Validate input parameters
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) for c in characters):
        return {'error': 'Invalid characters: characters must be a list of strings.'}
    if output_format not in ['integer', 'text', 'json', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, json, detailed.'}

    # Initialize count
    total_count = 0
    detailed_counts = {}

    # Process each string in input
    for string in input:
        # Optionally ignore whitespace
        if ignore_whitespace:
            string = ''.join(string.split())

        # Count occurrences of each character or character set
        for char_set in characters:
            count = 0
            if not case_sensitive:
                string = string.lower()
                char_set = char_set.lower()
            count = sum(string.count(char) for char in char_set)
            total_count += count
            detailed_counts[char_set] = detailed_counts.get(char_set, 0) + count

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total count: {total_count}'
    elif output_format == 'json':
        return {'total_count': total_count, 'details': detailed_counts}
    elif output_format == 'detailed':
        return {'total_count': total_count, 'details': detailed_counts, 'input_length': len(input), 'character_sets': len(characters)}

