def first_digit_extractor_v2(numbers, output_format='integer', handle_zero=False, include_sign=False):
    """
    Extracts the first digit from each number in the list, with options for output customization.

    :param numbers: List of numbers (integers or floating-point).
    :param output_format: Format of the output ('integer', 'string', 'detailed').
    :param handle_zero: Boolean indicating whether to handle zero as a special case.
    :param include_sign: Boolean indicating whether to include the sign in the output.
    :return: List of first digits in the specified format.
    """
    if not isinstance(numbers, list) or len(numbers) == 0:
        raise ValueError("'numbers' must be a non-empty list of numbers.")
    if output_format not in ['integer', 'string', 'detailed']:
        raise ValueError("'output_format' must be one of 'integer', 'string', 'detailed'.")

    results = []
    for number in numbers:
        if not isinstance(number, (int, float)):
            raise ValueError("Each item in 'numbers' must be an integer or a floating-point number.")

        num_str = str(abs(number))
        first_digit = next((char for char in num_str if char.isdigit()), None)

        if first_digit is None:
            if handle_zero:
                first_digit = '0'
            else:
                raise ValueError("No valid digit found in the number.")

        if output_format == 'integer':
            result = int(first_digit)
        elif output_format == 'string':
            result = first_digit
        elif output_format == 'detailed':
            sign = '-' if number < 0 else '+' if include_sign else ''
            result = {
                'first_digit': first_digit,
                'sign': sign,
                'position': num_str.index(first_digit)
            }

        results.append(result)

    return results

