    if ignore_sign and number.startswith('-'):
        number = number[1:]

    # Handle decimal consideration
    if decimal_handling == 'consider' and '.' in number:
        number = number.split('.')[-1]

    # Extract the last character
    last_character = number[-1]

    # Return based on output_format
    if output_format == 'integer':
        return int(last_character)
