    if output_format not in ['string', 'json', 'array']:
        raise ValueError('Invalid output_format. Must be one of: string, json, array.')
    if not isinstance(trim_whitespace, bool):
        raise ValueError('trim_whitespace must be a boolean.')
    if null_handling not in ['ignore', 'include', 'replace']:
        raise ValueError('Invalid null_handling. Must be one of: ignore, include, replace.')
    if not isinstance(null_replacement, str):
        raise ValueError('null_replacement must be a string.')

    # Process inputs
    processed_inputs = []
    for item in inputs:
        if item is None:
            if null_handling == 'ignore':
                continue
            elif null_handling == 'include':
                item = ''
            elif null_handling == 'replace':
                item = null_replacement
        if trim_whitespace and isinstance(item, str):
            item = item.strip()
        processed_inputs.append(str(item))

    # Concatenate values
    result = separator.join(processed_inputs)

    # Format output
    if output_format == 'json':
        import json
        return json.dumps(result)
    elif output_format == 'array':
        return processed_inputs
    return result

