    - award_nominations (bool, optional): Filter results to include only actors with award nominations.

    Returns:
    - List of actors matching the criteria or an error message.
    """
    # Simulated database of movie casts
    movie_casts = {
        'Streak': [
            {'name': 'Rumer Willis', 'role': 'lead', 'billing_order': 1, 'character_name': 'Leah', 'nationality': 'American', 'award_nominations': False},
            {'name': 'Brittany Snow', 'role': 'lead', 'billing_order': 2, 'character_name': 'Eva', 'nationality': 'American', 'award_nominations': True}
        ]
    }

    # Error handling for missing required parameter
    if not movie_title:
        return {'error': 'The movie_title parameter is required.'}

    # Retrieve the cast list for the specified movie
    cast_list = movie_casts.get(movie_title)
    if not cast_list:
