def date_calculator(start_date, amount, time_units='months', output_format='YYYY-MM-DD', time_zone='UTC', adjust_for_dst=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate time_units
    if time_units not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid time_units. Must be one of days, weeks, months, years.'}

    # Validate output_format
    valid_formats = ['YYYY-MM-DD', 'MM/DD/YYYY', 'DD-MM-YYYY', 'YYYY/MM/DD', 'DD/MM/YYYY']
    if output_format not in valid_formats:
        return {'error': 'Invalid output_format. Must be one of ' + ', '.join(valid_formats) + '.'}

    # Adjust start_date for time zone
    if time_zone != 'UTC':
        try:
            tz = pytz.timezone(time_zone)
            start_date_obj = tz.localize(start_date_obj)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Invalid time_zone specified.'}

    # Calculate new date
    if time_units == 'days':
        new_date_obj = start_date_obj + timedelta(days=amount)
    elif time_units == 'weeks':
        new_date_obj = start_date_obj + timedelta(weeks=amount)
    elif time_units == 'months':
        new_date_obj = start_date_obj + relativedelta(months=amount)
    elif time_units == 'years':
        new_date_obj = start_date_obj + relativedelta(years=amount)

    # Adjust for daylight saving time if needed
    if adjust_for_dst:
        new_date_obj = new_date_obj.astimezone(pytz.utc).astimezone(tz)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        result_date = new_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        result_date = new_date_obj.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        result_date = new_date_obj.strftime('%d-%m-%Y')
    elif output_format == 'YYYY/MM/DD':
        result_date = new_date_obj.strftime('%Y/%m/%d')
    elif output_format == 'DD/MM/YYYY':
        result_date = new_date_obj.strftime('%d/%m/%Y')

    return {'result_date': result_date}

