    - preserve_case (bool): Indicates if the case of characters should be preserved. Defaults to True.

    Returns:
    - Reversed input in the specified format.
    """
    # Error handling for invalid output_format
    if output_format not in ['string', 'number', 'array']:
        return {'error': 'Invalid output_format specified.'}

    # Handle negative numbers
    if handle_negative and isinstance(input, str) and input.startswith('-'):
        reversed_input = '-' + input[:0:-1]
    else:
        reversed_input = input[::-1]

    # Convert to appropriate output format
    if output_format == 'number':
        try:
            return int(reversed_input)
        except ValueError:
            return {'error': 'Cannot convert reversed input to number.'}
    elif output_format == 'array':
        return list(reversed_input)
    else:  # Default to string
        return reversed_input

