def year_calculator(base_year, operation_sequence, calendar_system='gregorian', output_format='integer'):
    # Validate base_year
    if not isinstance(base_year, int):
        return {'error': 'Invalid base_year: must be an integer.'}

    # Validate operation_sequence
    if not isinstance(operation_sequence, list) or not all(isinstance(op, dict) for op in operation_sequence):
        return {'error': 'Invalid operation_sequence: must be a list of operations.'}

    # Validate each operation in the sequence
    for op in operation_sequence:
        if 'operation' not in op or 'value' not in op:
            return {'error': 'Each operation must include an operation and a value.'}
        if op['operation'] not in ['add', 'subtract']:
            return {'error': f"Invalid operation: {op['operation']} is not supported."}
        if not isinstance(op['value'], int):
            return {'error': 'Operation value must be an integer.'}

    # Validate calendar_system
    if calendar_system not in ['gregorian', 'julian']:
        return {'error': f"Invalid calendar_system: {calendar_system} is not supported."}

    # Validate output_format
    if output_format not in ['integer', 'string', 'detailed']:
        return {'error': f"Invalid output_format: {output_format} is not supported."}

    # Perform operations
    result_year = base_year
    for op in operation_sequence:
        if op['operation'] == 'add':
            result_year += op['value']
        elif op['operation'] == 'subtract':
            result_year -= op['value']

    # Format output
    if output_format == 'integer':
        return result_year
    elif output_format == 'string':
        return str(result_year)
    elif output_format == 'detailed':
        return {
            'year': result_year,
            'calendar_system': calendar_system,
            'operations': operation_sequence
        }

# Example usage based on the question
result = year_calculator(
    base_year=1976,
    operation_sequence=[{'operation': 'subtract', 'value': 9}],
    calendar_system='gregorian',
    output_format='integer'
)
# The result should be 1967, as 9 years are subtracted from 1976.

def chemist_identifier(query: str, nationality: str = None, contribution: str = None, era: str = None, field_of_study: str = None, output_format: str = 'name_only', include_awards: bool = False):
    """
    Identifies a chemist based on the provided query and optional parameters.
    """
    # Error handling for required parameter
    if not query:
        return {'error': 'The query parameter is required.'}

    # Simulated database of chemists
    chemists_db = [
        {'name': 'S. P. L. Sørensen', 'nationality': 'Danish', 'contribution': 'pH', 'era': '20th century', 'field_of_study': 'biochemistry', 'awards': ['Nobel Prize']},
        # Additional chemist entries can be added here
    ]

    # Search logic
    results = []
    for chemist in chemists_db:
        if query.lower() in chemist['contribution'].lower():
            if nationality and nationality.lower() != chemist['nationality'].lower():
                continue
            if contribution and contribution.lower() not in chemist['contribution'].lower():
                continue
            if era and era.lower() != chemist['era'].lower():
                continue
            if field_of_study and field_of_study.lower() != chemist['field_of_study'].lower():
                continue
            results.append(chemist)

    # Format the output based on 'output_format'
    if not results:
        return {'error': 'No chemist found matching the criteria.'}

    chemist = results[0]  # Assuming we return the first match
    if output_format == 'name_only':
        return {'name': chemist['name']}
    elif output_format == 'detailed':
        return {
            'name': chemist['name'],
            'nationality': chemist['nationality'],
            'contribution': chemist['contribution'],
            'era': chemist['era'],
            'field_of_study': chemist['field_of_study'],
            'awards': chemist['awards'] if include_awards else None
        }
    elif output_format == 'summary':
        return {
            'summary': f"{chemist['name']} is a {chemist['nationality']} chemist known for {chemist['contribution']} in the {chemist['era']}."
        }
    else:
        return {'error': 'Invalid output format specified.'}

