def string_length_counter(input: str, ignore_characters: list = [], ignore_position: list = [], output_format: str = 'integer', case_sensitive: bool = False, count_types: list = ['alphabets', 'digits', 'whitespace', 'special'], ignore_whitespace: bool = False):
    # Validate input parameters
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid ignore_characters type. Must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position value. Must be a list containing "first" or "last".'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be "integer", "text", or "detailed".'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Must be a boolean.'}
    if not isinstance(count_types, list) or not all(ct in ['alphabets', 'digits', 'whitespace', 'special'] for ct in count_types):
        return {'error': 'Invalid count_types value. Must be a list containing "alphabets", "digits", "whitespace", or "special".'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'Invalid ignore_whitespace type. Must be a boolean.'}

    # Prepare the string for counting
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Remove ignored characters
    input = ''.join(char for char in input if char not in ignore_characters)

    # Remove ignored positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]

    # Count characters based on count_types
    count = 0
    for char in input:
        if 'alphabets' in count_types and char.isalpha():
            count += 1
        elif 'digits' in count_types and char.isdigit():
            count += 1
        elif 'whitespace' in count_types and char.isspace():
            count += 1
        elif 'special' in count_types and not char.isalnum() and not char.isspace():
            count += 1

    # Ignore whitespace if specified
    if ignore_whitespace:
        count -= sum(1 for char in input if char.isspace())

    # Return the result in the specified format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The count is {count}.'
    elif output_format == 'detailed':
        return {
            'total_count': count,
            'details': {
                'alphabets': sum(1 for char in input if char.isalpha()),
                'digits': sum(1 for char in input if char.isdigit()),
                'whitespace': sum(1 for char in input if char.isspace()),
                'special': sum(1 for char in input if not char.isalnum() and not char.isspace())
            }
        }

# Example usage based on the question
result = string_length_counter(input='Nelson', count_types=['alphabets'], output_format='integer')
# The expected result is 6, as 'Nelson' has 6 letters.

def name_length_counter(name, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, count_type='all'):
    # Validate required parameter
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}

    # Initialize variables
    vowels = 'aeiouAEIOU'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'

    # Apply case sensitivity
    if not case_sensitive:
        name = name.lower()
        ignore_characters = [char.lower() for char in ignore_characters]
        vowels = vowels.lower()
        consonants = consonants.lower()

    # Remove ignored characters
    filtered_name = ''.join([char for char in name if char not in ignore_characters])

    # Remove ignored positions
    if 'first' in ignore_position and len(filtered_name) > 0:
        filtered_name = filtered_name[1:]
    if 'last' in ignore_position and len(filtered_name) > 0:
        filtered_name = filtered_name[:-1]

    # Count based on count_type
    if count_type == 'vowels':
        count = sum(1 for char in filtered_name if char in vowels)
    elif count_type == 'consonants':
        count = sum(1 for char in filtered_name if char in consonants)
    else:
        count = len(filtered_name)

    # Return output in specified format
    if output_format == 'text':
        return f'The name "{name}" has {count} letters.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for char in filtered_name if char in vowels)
        consonant_count = sum(1 for char in filtered_name if char in consonants)
        return {
            'total': count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }
    else:
        return count

# Example usage based on the question:
# How many letters does Charles have?
# Assuming no characters are ignored, no positions are ignored, case insensitivity, and counting all characters.
result = name_length_counter('Charles')
print(result)  # Output: 7

def date_calculator(start_date, months_to_add=0, days_to_add=0, years_to_add=0, output_format='ISO', time_zone='UTC'):
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate and parse the start_date
    try:
        date = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date = tz.localize(date)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone specified.'}

    # Perform date arithmetic
    try:
        date = date + relativedelta(months=months_to_add, days=days_to_add, years=years_to_add)
    except Exception as e:
        return {'error': f'Date arithmetic error: {str(e)}'}

    # Format the output date
    if output_format == 'ISO':
        result_date = date.strftime('%Y-%m-%d')
    elif output_format == 'human_readable':
        result_date = date.strftime('%B %d, %Y')
    elif output_format == 'custom':
        # Custom format can be defined here if needed
        result_date = date.strftime('%Y-%m-%d')  # Defaulting to ISO for simplicity
    else:
        return {'error': 'Invalid output_format specified.'}

    return {'result_date': result_date}

# Example usage based on the question:
# What is the date 3 months after June 11, 1986?
# Answer: 1986-09-11
result = date_calculator(start_date='1986-06-11', months_to_add=3)
print(result)  # Expected output: {'result_date': '1986-09-11'}

