def extract_last_name(full_name, delimiter=' ', multiple_delimiters=None, output_format='string', handle_suffix=False, compound_last_name=False, normalize_case='none'):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'full_name must be a string'}
    if not isinstance(delimiter, str):
        return {'error': 'delimiter must be a string'}
    if multiple_delimiters and not all(isinstance(d, str) for d in multiple_delimiters):
        return {'error': 'all items in multiple_delimiters must be strings'}
    if output_format not in ['string', 'array']:
        return {'error': 'output_format must be either "string" or "array"'}
    if normalize_case not in ['none', 'uppercase', 'lowercase', 'titlecase']:
        return {'error': 'normalize_case must be one of "none", "uppercase", "lowercase", "titlecase"'}

    # Use multiple delimiters if provided
    if multiple_delimiters:
        import re
        pattern = '|'.join(map(re.escape, multiple_delimiters))
        parts = re.split(pattern, full_name)
    else:
        parts = full_name.split(delimiter)

    # Handle suffixes if needed
    if handle_suffix and len(parts) > 1 and parts[-1].lower() in ['jr', 'sr', 'ii', 'iii', 'iv']:
        parts = parts[:-1]

    # Extract last name
    if compound_last_name:
        last_name = ' '.join(parts[1:]) if len(parts) > 1 else parts[0]
    else:
        last_name = parts[-1]

    # Normalize case
    if normalize_case == 'uppercase':
        last_name = last_name.upper()
    elif normalize_case == 'lowercase':
        last_name = last_name.lower()
    elif normalize_case == 'titlecase':
        last_name = last_name.title()

    # Return in the requested format
    if output_format == 'array':
        return [last_name]
    return last_name

# Example usage based on the question
result = extract_last_name('Don Hahn')
# The expected result is 'Hahn'

def distinct_combinations(input_string, combination_length=2, case_sensitive=True, unique=True, include_characters='', ordered=False, allow_non_alphabetic=False):
    # Validate input_string
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}

    # Validate combination_length
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be a positive integer'}

    # Adjust input_string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Filter input_string for allowed characters
    if not allow_non_alphabetic:
        input_string = ''.join(filter(str.isalpha, input_string))

    # Generate combinations
    from itertools import combinations, permutations
    if ordered:
        comb_func = permutations
    else:
        comb_func = combinations

    all_combinations = set(comb_func(input_string, combination_length))

    # Filter for uniqueness
    if unique:
        all_combinations = set(all_combinations)

    # Filter to include required characters
    if include_characters:
        all_combinations = {comb for comb in all_combinations if all(char in comb for char in include_characters)}

    # Return the number of combinations
    return len(all_combinations)

# Example usage based on the question
result = distinct_combinations('Hahn')
print(result)  # Expected output: 4

