def digit_sum_calculator(number, absolute_value=True, base=10, digit_separator='', return_digits=False):
    # Validate the base
    if not isinstance(base, int) or base < 2:
        return {'error': 'Invalid base. Base must be an integer greater than or equal to 2.'}

    # Handle absolute value
    if absolute_value:
        number = abs(number)

    # Convert number to the specified base
    if base != 10:
        try:
            num_str = ''
            n = int(number)
            while n > 0:
                num_str = str(n % base) + num_str
                n //= base
        except ValueError:
            return {'error': 'Invalid number for conversion to base.'}
    else:
        num_str = str(number)

    # Extract digits
    digits = [int(d) for d in num_str if d.isdigit()]
    digit_sum = sum(digits)

    # Prepare the result
    result = {'sum': digit_sum}
    if return_digits:
        result['digits'] = digit_separator.join(map(str, digits))

    return result

