def advanced_power_calculator(base, exponent=3, output_format='integer', precision=2, rounding_mode='nearest'):
    import math

    # Validate base
    if not isinstance(base, (int, float, complex)):
        return {'error': 'Invalid base type. Base must be a number.'}

    # Validate exponent
    if not isinstance(exponent, (int, float)):
        return {'error': 'Invalid exponent type. Exponent must be a number.'}

    # Validate output_format
    if output_format not in ['integer', 'float', 'text', 'scientific', 'complex']:
        return {'error': 'Invalid output format. Must be one of integer, float, text, scientific, complex.'}

    # Validate precision
    if not isinstance(precision, int) or precision < 0:
        return {'error': 'Invalid precision. Precision must be a non-negative integer.'}

    # Validate rounding_mode
    if rounding_mode not in ['up', 'down', 'nearest']:
        return {'error': 'Invalid rounding mode. Must be one of up, down, nearest.'}

    # Calculate power
    result = base ** exponent

    # Apply rounding
    if output_format == 'float':
        if rounding_mode == 'up':
            result = math.ceil(result * (10 ** precision)) / (10 ** precision)
        elif rounding_mode == 'down':
            result = math.floor(result * (10 ** precision)) / (10 ** precision)
        else:  # nearest
            result = round(result, precision)

    # Format output
    if output_format == 'integer':
        result = int(round(result))
    elif output_format == 'text':
        result = str(result)
    elif output_format == 'scientific':
        result = f'{result:.{precision}e}'
    elif output_format == 'complex':
        result = complex(result)

    return {'result': result}

