def distinct_combinations(input_string, combination_length=2, case_sensitive=False, output_format='array', character_filter='all', custom_pattern=''):
    import re
    from itertools import combinations

    # Error handling for input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be an integer greater than or equal to 1'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if output_format not in ['array', 'count', 'dictionary']:
        return {'error': "output_format must be one of ['array', 'count', 'dictionary']"}
    if character_filter not in ['all', 'letters', 'digits', 'custom']:
        return {'error': "character_filter must be one of ['all', 'letters', 'digits', 'custom']"}

    # Apply character filter
    if character_filter == 'letters':
        input_string = ''.join(filter(str.isalpha, input_string))
    elif character_filter == 'digits':
        input_string = ''.join(filter(str.isdigit, input_string))
    elif character_filter == 'custom':
        if not custom_pattern:
            return {'error': 'custom_pattern must be provided when character_filter is set to custom'}
        input_string = ''.join(re.findall(custom_pattern, input_string))

    # Handle case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Generate combinations
    unique_combinations = set(combinations(input_string, combination_length))

    # Prepare output
    if output_format == 'array':
        result = [''.join(comb) for comb in unique_combinations]
    elif output_format == 'count':
        result = len(unique_combinations)
    elif output_format == 'dictionary':
        result = {''.join(comb): input_string.count(''.join(comb)) for comb in unique_combinations}

    return result

