    # Validate the 'number' parameter
    if not isinstance(number, (int, float)):
        return {'error': 'Invalid input: number must be an integer or a float.'}

    # Validate the 'output_format' parameter
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': "Invalid output_format: must be 'integer', 'text', or 'detailed'."}

    # Convert the number to a string and handle negative numbers
    num_str = str(int(abs(number))) if isinstance(number, float) else str(abs(number))
    if include_negative_sign and number < 0:
        num_str = '-' + num_str

    # Calculate the sum of the digits
    digit_sum = sum(int(digit) for digit in num_str if digit.isdigit())

    # Handle different output formats
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return str(digit_sum)
    elif output_format == 'detailed':
        breakdown = ' + '.join(num_str)
        return f'{breakdown} = {digit_sum}'

