def reverse_number(number, output_format='string', delimiter=''):
    """
    Reverses the order of digits in a number.

    Parameters:
    number (int or float): The number to be reversed.
    output_format (str): The format of the output ('string', 'integer', 'float'). Defaults to 'string'.
    delimiter (str): A string to be used as a delimiter between reversed digits. Defaults to no delimiter.

    Returns:
    str, int, or float: The reversed number in the specified format.
    """
    # Error handling for incorrect input types
    if not isinstance(number, (int, float)):
        raise ValueError("The 'number' parameter must be an integer or a float.")
    if output_format not in ['string', 'integer', 'float']:
        raise ValueError("The 'output_format' parameter must be one of 'string', 'integer', or 'float'.")

    # Convert number to string and reverse it
    number_str = str(number)
    if '.' in number_str:
        integer_part, fractional_part = number_str.split('.')
        reversed_number_str = integer_part[::-1] + '.' + fractional_part[::-1]
    else:
        reversed_number_str = number_str[::-1]

    # Apply delimiter if specified
    if delimiter:
        reversed_number_str = delimiter.join(reversed_number_str)

    # Format the output based on the specified output_format
    if output_format == 'string':
        return reversed_number_str
    elif output_format == 'integer':
        return int(reversed_number_str.replace(delimiter, ''))
    elif output_format == 'float':
        return float(reversed_number_str.replace(delimiter, ''))

