    Parameters:
    - input_number (int): The numeric input whose digits will be summed.
    - output_format (str): The format of the output ('integer', 'text', 'detailed').
    - base (int): The base of the input number (default is 10).
    - filter_digits (list of int): Specific digits to include in the sum.
    - handle_negative (str): How to handle negative numbers ('ignore', 'absolute', 'include').

    Returns:
    - The sum of the digits in the specified format.
    """
    # Error handling for invalid base
    if not (2 <= base <= 36):
        return {'error': 'Base must be between 2 and 36.'}

    # Handle negative numbers based on the 'handle_negative' parameter
    if input_number < 0:
        if handle_negative == 'ignore':
            input_number = abs(input_number)
        elif handle_negative == 'absolute':
            input_number = abs(input_number)
        # 'include' means we do nothing special

    # Convert the number to the specified base
    num_str = ''
    n = abs(input_number)
    while n > 0:
        num_str = str(n % base) + num_str
        n //= base

    # Calculate the sum of digits
    digit_sum = 0
    detailed_info = []
    for char in num_str:
        digit = int(char, base)
        if filter_digits is None or digit in filter_digits:
            digit_sum += digit
            detailed_info.append(digit)

    # Format the output
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of the digits is {digit_sum}.'
    elif output_format == 'detailed':
        return {
            'sum': digit_sum,
            'details': detailed_info
        }
    else:
        return {'error': 'Invalid output format specified.'}

