def date_difference_calculator(start_date: str, end_date: str, output_format: str = 'days', include_time: bool = False, time_zone: str = 'UTC', business_days_only: bool = False):
    from datetime import datetime, timedelta
    import pytz
    from dateutil import parser

    # Error handling for invalid date formats
    try:
        start_dt = parser.parse(start_date)
        end_dt = parser.parse(end_date)
    except ValueError as e:
        return {'error': 'Invalid date format', 'message': str(e)}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_dt = tz.localize(start_dt)
        end_dt = tz.localize(end_dt)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone'}

    # Calculate difference
    if business_days_only:
        # Calculate business days difference
        day_count = 0
        current_date = start_dt
        while current_date < end_dt:
            if current_date.weekday() < 5:  # Monday to Friday are business days
                day_count += 1
            current_date += timedelta(days=1)
        difference = day_count
    else:
        difference = (end_dt - start_dt).days

    # Convert difference to requested format
    if output_format == 'weeks':
        difference /= 7
    elif output_format == 'months':
        difference /= 30  # Approximation
    elif output_format == 'years':
        difference /= 365  # Approximation
    elif output_format == 'text':
        return {'result': f'The difference is {difference} days.'}

    return {'result': difference}

