def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DD', output_format='integer', exclude_weekends=False, holidays=None, time_zone='UTC'):
    from datetime import datetime, timedelta
    import pytz

    # Helper function to parse date based on the format
    def parse_date(date_str, date_format):
        formats = {
            'YYYY-MM-DD': '%Y-%m-%d',
            'MM-DD-YYYY': '%m-%d-%Y',
            'DD-MM-YYYY': '%d-%m-%Y',
            'YYYY/MM/DD': '%Y/%m/%d',
            'DD.MM.YYYY': '%d.%m.%Y'
        }
        try:
            return datetime.strptime(date_str, formats[date_format])
        except ValueError:
            raise ValueError(f"Date '{date_str}' does not match format '{date_format}'")

    # Parse the start and end dates
    try:
        start = parse_date(start_date, date_format)
        end = parse_date(end_date, date_format)
    except ValueError as e:
        return str(e)

    # Ensure start date is before end date
    if start > end:
        return "Start date must be before end date."

    # Calculate the difference in days
    delta = end - start
    total_days = delta.days

    # Exclude weekends if specified
    if exclude_weekends:
        current_date = start
        while current_date <= end:
            if current_date.weekday() >= 5:  # Saturday or Sunday
                total_days -= 1
            current_date += timedelta(days=1)

    # Exclude holidays if specified
    if holidays:
        for holiday in holidays:
            holiday_date = parse_date(holiday, date_format)
            if start <= holiday_date <= end:
                total_days -= 1

    # Return the result based on the output format
    if output_format == 'integer':
        return total_days
    elif output_format == 'text':
        return f"The number of days between {start_date} and {end_date} is {total_days}."
    elif output_format == 'detailed':
        weeks = total_days // 7
        months = total_days // 30  # Approximation
        return {
            'days': total_days,
            'weeks': weeks,
            'months': months
        }
    else:
        return "Invalid output format specified."

