def extract_last_name(full_name, ignore_suffixes=True, output_format='string', case_sensitivity=False, delimiter=','):
    # Validate input types
    if not isinstance(full_name, list) or not all(isinstance(name, str) for name in full_name):
        return {'error': 'Invalid input: full_name must be a list of strings.'}
    if not isinstance(ignore_suffixes, bool):
        return {'error': 'Invalid input: ignore_suffixes must be a boolean.'}
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid input: output_format must be one of string, array, json.'}
    if not isinstance(case_sensitivity, bool):
        return {'error': 'Invalid input: case_sensitivity must be a boolean.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}

    # Define common suffixes to ignore
    suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV'] if ignore_suffixes else []

    # Function to extract last name
    def get_last_name(name):
        parts = name.split()
        # Remove suffixes if applicable
        if ignore_suffixes and parts[-1] in suffixes:
            parts = parts[:-1]
        # Return the last part as the last name
        return parts[-1] if parts else ''

    # Extract last names
    last_names = [get_last_name(name) for name in full_name]

    # Format output
    if output_format == 'string':
        return delimiter.join(last_names)
    elif output_format == 'array':
        return last_names
    elif output_format == 'json':
        return {'last_names': last_names, 'count': len(last_names)}

    # Default return in case of unexpected format
    return {'error': 'Unexpected error occurred.'}

