def last_letter_extractor_v2(input, output_format='character', encoding='utf-8'):
    """
    Extract the last letter from a given string or list of strings.

    Parameters:
    - input (str or list of str): The string or list of strings from which to extract the last letter.
    - output_format (str): The format of the output. Options are 'character', 'text', or 'position'. Defaults to 'character'.
    - encoding (str): The character encoding to use. Options are 'utf-8', 'ascii', or 'latin-1'. Defaults to 'utf-8'.

    Returns:
    - str or int: The last letter or its position, depending on the output format.
    """
    # Validate encoding
    if encoding not in ['utf-8', 'ascii', 'latin-1']:
        return {'error': 'Unsupported encoding. Choose from utf-8, ascii, latin-1.'}

    # Validate output_format
    if output_format not in ['character', 'text', 'position']:
        return {'error': "Invalid output format. Choose from 'character', 'text', 'position'."}

    # Helper function to extract last letter
    def extract_last_letter(s):
        if not s:
            return ''
        return s[-1]

    # Process input
    if isinstance(input, str):
        last_letter = extract_last_letter(input)
        if output_format == 'character':
            return last_letter
        elif output_format == 'text':
            return f'The last letter is {last_letter}'
        elif output_format == 'position':
            return len(input) - 1 if last_letter else -1
    elif isinstance(input, list):
        results = []
        for item in input:
            last_letter = extract_last_letter(item)
            if output_format == 'character':
                results.append(last_letter)
            elif output_format == 'text':
                results.append(f'The last letter is {last_letter}')
            elif output_format == 'position':
                results.append(len(item) - 1 if last_letter else -1)
        return results
    else:
        return {'error': 'Invalid input type. Input must be a string or list of strings.'}

