def character_to_binary(input: str, output_format: str = 'binary_string', include_prefix: bool = False, encoding: str = 'UTF-8', delimiter: str = '', case_sensitive: bool = True) -> str:
    # Validate parameters
    if output_format not in ['binary_string', 'binary_list']:
        return 'Error: Invalid output_format. Choose either binary_string or binary_list.'
    if encoding not in ['UTF-8', 'ASCII']:
        return 'Error: Invalid encoding. Choose either UTF-8 or ASCII.'
    if not isinstance(include_prefix, bool) or not isinstance(case_sensitive, bool):
        return 'Error: include_prefix and case_sensitive must be boolean values.'

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Convert each character to binary
    binary_codes = []
    for char in input:
        if encoding == 'UTF-8':
            binary_code = format(ord(char), 'b')
        elif encoding == 'ASCII':
            try:
                binary_code = format(ord(char.encode('ascii')), 'b')
            except UnicodeEncodeError:
                return f'Error: Character {char} cannot be encoded in ASCII.'

        if include_prefix:
            binary_code = '0b' + binary_code

        binary_codes.append(binary_code)

    # Format output
    if output_format == 'binary_string':
        return delimiter.join(binary_codes)
    elif output_format == 'binary_list':
        return binary_codes

