def last_letter_extractor(input: str, ignore_special_characters: bool = False, case_sensitive: bool = True, multi_character_suffix: int = 1, output_format: str = 'character') -> str:
    # Error handling for input types
    if not isinstance(input, str):
        return 'Error: Input must be a string.'
    if not isinstance(ignore_special_characters, bool):
        return 'Error: ignore_special_characters must be a boolean.'
    if not isinstance(case_sensitive, bool):
        return 'Error: case_sensitive must be a boolean.'
    if not isinstance(multi_character_suffix, int) or multi_character_suffix < 1:
        return 'Error: multi_character_suffix must be a positive integer.'
    if output_format not in ['character', 'ascii', 'unicode', 'hex']:
        return 'Error: Invalid output_format.'

    # Process input based on parameters
    if ignore_special_characters:
        input = ''.join(filter(str.isalnum, input))

    # Extract the last meaningful characters
    extracted = input[-multi_character_suffix:]

    # Handle case sensitivity
    if not case_sensitive:
        extracted = extracted.lower()

    # Format the output
    if output_format == 'character':
        return extracted
    elif output_format == 'ascii':
        return ' '.join(str(ord(char)) for char in extracted)
    elif output_format == 'unicode':
        return ' '.join(f'U+{ord(char):04X}' for char in extracted)
    elif output_format == 'hex':
        return ' '.join(f'{ord(char):02x}' for char in extracted)

    return 'Error: Unexpected error occurred.'

