        {'title': 'Another Film', 'actors': ['Nicolas Cage'], 'genre': 'Action', 'release_year': 2005, 'language': 'English', 'rating': 6.5}
    ]

    # Filter films based on actors
    filtered_films = [film for film in films if all(actor in film['actors'] for actor in actors)]

    # Apply additional filters
    if genre:
        filtered_films = [film for film in filtered_films if film['genre'] == genre]
    if release_year:
        filtered_films = [film for film in filtered_films if film['release_year'] == release_year]
    if language:
        filtered_films = [film for film in filtered_films if film['language'] == language]

    # Sort films based on output_format
    if output_format == 'sorted_by_date':
        filtered_films.sort(key=lambda x: x['release_year'])
    elif output_format == 'sorted_by_rating':
        filtered_films.sort(key=lambda x: x['rating'], reverse=True)

    # Format output
    if output_format == 'list':
        return [film['title'] for film in filtered_films]
    elif output_format == 'detailed':
        return filtered_films

    return filtered_films

