def string_length_calculator(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, character_type=['letters']):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Invalid input type, expected a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid ignore_characters type, expected a list of strings.'}
    if not isinstance(ignore_position, list) or not all(p in ['first', 'last', 'even', 'odd'] for p in ignore_position):
        return {'error': 'Invalid ignore_position value, expected a list with values first, last, even, or odd.'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'Invalid output_format, expected integer, text, or json.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type, expected a boolean.'}
    if not isinstance(character_type, list) or not all(t in ['letters', 'digits', 'symbols'] for t in character_type):
        return {'error': 'Invalid character_type, expected a list with values letters, digits, or symbols.'}

    # Initialize count
    count = 0

    # Process input string
    for i, char in enumerate(input):
        # Check if character should be ignored
        if char in ignore_characters:
            continue
        if 'letters' in character_type and not char.isalpha():
            continue
        if 'digits' in character_type and not char.isdigit():
            continue
        if 'symbols' in character_type and char.isalnum():
            continue

        # Check position
        if 'first' in ignore_position and i == 0:
            continue
        if 'last' in ignore_position and i == len(input) - 1:
            continue
        if 'even' in ignore_position and i % 2 == 0:
            continue
        if 'odd' in ignore_position and i % 2 != 0:
            continue

        # Case sensitivity
        if not case_sensitive:
            char = char.lower()

        # Increment count
        count += 1

    # Format output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'Total count: {count}'
    elif output_format == 'json':
        return {'total_count': count}

# Example usage
