        }
    }

    # Error handling for required parameters
    if not band_name or not member_role:
        return {'error': 'Both band_name and member_role are required parameters.'}

    # Check if the band exists in the data
    if band_name not in band_data:
        return {'error': f'Band {band_name} not found in the database.'}

    # Initialize the result dictionary
    result = {}

    # Iterate over the requested roles
    for role in member_role:
        if role in band_data[band_name]:
            member_info = band_data[band_name][role]
            role_info = {}

            # Retrieve current member information
            if current_status:
                role_info['current'] = member_info['current']

            # Include tenure information if requested
            if tenure:
                role_info['tenure'] = member_info['tenure']

            # Include past roles if requested
            if past_roles:
                role_info['past'] = member_info['past']

            # Include additional attributes if requested
            if additional_attributes:
                role_info['additional_attributes'] = {}
                if additional_attributes.get('age', False):
                    role_info['additional_attributes']['age'] = member_info['age']
                if additional_attributes.get('nationality', False):
                    role_info['additional_attributes']['nationality'] = member_info['nationality']

            result[role] = role_info
        else:
            result[role] = {'error': f'Role {role} not found for band {band_name}.'}

