def extract_first_name(full_name, name_delimiter=' ', case_sensitive=True, include_middle_name=False, title_handling='ignore', international_format=False):
    # Error handling for incorrect input types
    if not isinstance(full_name, str):
        return {'error': 'full_name must be a string'}
    if not isinstance(name_delimiter, str):
        return {'error': 'name_delimiter must be a string'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if not isinstance(include_middle_name, bool):
        return {'error': 'include_middle_name must be a boolean'}
    if title_handling not in ['ignore', 'include', 'separate']:
        return {'error': "title_handling must be one of 'ignore', 'include', 'separate'"}
    if not isinstance(international_format, bool):
        return {'error': 'international_format must be a boolean'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(name_delimiter)

    # Handle title based on the title_handling parameter
    if title_handling == 'ignore':
        name_parts = [part for part in name_parts if part.lower() not in ['mr', 'mrs', 'ms', 'dr', 'prof']]
    elif title_handling == 'separate':
        titles = [part for part in name_parts if part.lower() in ['mr', 'mrs', 'ms', 'dr', 'prof']]
        name_parts = [part for part in name_parts if part.lower() not in ['mr', 'mrs', 'ms', 'dr', 'prof']]

    # Extract the first name and optionally the middle name
    if include_middle_name and len(name_parts) > 1:
        first_name = name_delimiter.join(name_parts[:2])
    else:
        first_name = name_parts[0]

    # Return the first name, considering case sensitivity
    if not case_sensitive:
        first_name = first_name.lower()

    return first_name

# Example usage
