def extract_character_v2(input, position='first', custom_index=None, range_indices=None, pattern=None, case_sensitive=True, output_format='character'):
    """
    Extracts specific characters or substrings from input strings based on the specified position or method.
    """
    # Error handling for required parameters
    if not input or not isinstance(input, list) or len(input) < 1:
        return {'error': 'Input must be a list with at least one string.'}
    if position not in ['first', 'last', 'custom', 'range', 'pattern']:
        return {'error': 'Invalid position specified.'}

    # Extract based on position
    results = []
    for string in input:
        if position == 'first':
            results.append(string[0] if string else '')
        elif position == 'last':
            results.append(string[-1] if string else '')
        elif position == 'custom':
            if custom_index is not None and 0 <= custom_index < len(string):
                results.append(string[custom_index])
            else:
                return {'error': 'Invalid custom index.'}
        elif position == 'range':
            if range_indices and len(range_indices) == 2:
                start, end = range_indices
                if 0 <= start < len(string) and 0 < end <= len(string) and start < end:
                    results.append(string[start:end])
                else:
                    return {'error': 'Invalid range indices.'}
            else:
                return {'error': 'Range indices must be a list of two integers.'}
        elif position == 'pattern':
            import re
            flags = 0 if case_sensitive else re.IGNORECASE
            match = re.search(pattern, string, flags)
            if match:
                results.append(match.group(0))
            else:
                results.append('')

    # Format output
    if output_format == 'character':
        return results[0] if results else ''
    elif output_format == 'text':
        return ''.join(results)
    elif output_format == 'array':
        return results
    else:
        return {'error': 'Invalid output format specified.'}

# Example usage for the given question
result = extract_character_v2(input=['Herbert'], position='first')

def enhanced_ascii_converter(characters, output_format='list', handle_non_ascii='ignore'):
    # Validate parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'dictionary', 'json', 'csv']:
        raise ValueError("'output_format' must be one of 'list', 'dictionary', 'json', 'csv'.")
    if handle_non_ascii not in ['ignore', 'replace', 'error']:
        raise ValueError("'handle_non_ascii' must be one of 'ignore', 'replace', 'error'.")

    # ASCII conversion logic
    ascii_codes = {}
    for char in characters:
        try:
            ascii_code = ord(char)
            if ascii_code > 127 and handle_non_ascii == 'error':
                raise ValueError(f"Non-ASCII character '{char}' encountered.")
            elif ascii_code > 127 and handle_non_ascii == 'replace':
                ascii_codes[char] = '?'  # Placeholder for non-ASCII
            else:
                ascii_codes[char] = ascii_code
        except TypeError:
            if handle_non_ascii == 'ignore':
                continue
            elif handle_non_ascii == 'replace':
                ascii_codes[char] = '?'
            else:
                raise

    # Format output
    if output_format == 'list':
        return list(ascii_codes.values())
    elif output_format == 'dictionary':
        return ascii_codes
    elif output_format == 'json':
        import json
        return json.dumps(ascii_codes)
    elif output_format == 'csv':
        import csv
        from io import StringIO
        output = StringIO()
        writer = csv.writer(output)
        for char, code in ascii_codes.items():
            writer.writerow([char, code])
        return output.getvalue().strip()

