def enhanced_year_calculator(year, output_format='integer', calendar_system='Gregorian', error_handling='strict'):
    """
    Calculate the year immediately preceding a given year, considering calendar systems and output formats.

    Parameters:
    - year (int): The year for which the previous year is to be calculated.
    - output_format (str): The format of the output. Options are 'integer', 'string', 'detailed'.
    - calendar_system (str): The calendar system to use. Options are 'Gregorian', 'Julian'.
    - error_handling (str): The mode of error handling. Options are 'strict', 'lenient'.

    Returns:
    - The previous year in the specified format.
    """
    # Error handling for invalid year input
    if not isinstance(year, int):
        if error_handling == 'strict':
            raise ValueError("Year must be an integer.")
        elif error_handling == 'lenient':
            try:
                year = int(year)
            except ValueError:
                return "Invalid year input."

    # Calculate the previous year
    if year == 1:
        previous_year = -1  # Transition from 1 AD to 1 BC
    else:
        previous_year = year - 1

    # Format the output
    if output_format == 'integer':
        return previous_year
    elif output_format == 'string':
        return str(previous_year)
    elif output_format == 'detailed':
        context = "AD" if previous_year > 0 else "BC"
        return f"{abs(previous_year)} {context}"

    # Default return in case of unexpected output_format
    return previous_year

