def extract_last_name(full_name, delimiter=' ', name_format='first_last', include_titles=False, include_suffixes=False):
    # Error handling for required parameter
    if not full_name:
        return {'error': 'The full_name parameter is required.'}

    # Error handling for name_format
    valid_formats = ['first_last', 'first_middle_last', 'last_first', 'title_first_last', 'first_last_suffix', 'first_middle_last_suffix']
    if name_format not in valid_formats:
        return {'error': f'Invalid name_format. Must be one of {valid_formats}.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Logic to extract last name based on the name_format
    if name_format == 'first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first':
        last_name = name_parts[0]
    elif name_format == 'title_first_last':
        last_name = name_parts[-1] if not include_titles else name_parts[-2]
    elif name_format == 'first_last_suffix':
        last_name = name_parts[-2] if include_suffixes else name_parts[-1]
    elif name_format == 'first_middle_last_suffix':
        last_name = name_parts[-2] if include_suffixes else name_parts[-1]
    else:
        return {'error': 'Unsupported name format.'}

    return {'last_name': last_name}

