def game_character_lookup(character_name: str, role: str, game_genre: str = 'wrestling', release_year: int = None, platform: str = None, developer: str = None, region: str = None, output_format: str = 'list') -> dict:
    """
    Function to look up video games featuring a specific sports figure in a defined role.

    Parameters:
    - character_name (str): The name of the sports figure to look up.
    - role (str): The role or title of the character in the game.
    - game_genre (str): The genre of the video game. Defaults to 'wrestling'.
    - release_year (int, optional): The year the game was released.
    - platform (str, optional): The gaming platform.
    - developer (str, optional): The developer of the game.
    - region (str, optional): The region where the game was released.
    - output_format (str): The format of the output.

    Returns:
    - dict: A dictionary containing the lookup results or error messages.
    """
    # Simulated database of games
    games_db = [
        {'title': 'WWE 2K20', 'character_name': 'Mark Henry', 'role': 'legend', 'game_genre': 'wrestling', 'release_year': 2019, 'platform': 'PlayStation', 'developer': '2K Sports', 'region': 'North America'},
        {'title': 'WWE 2K19', 'character_name': 'Mark Henry', 'role': 'legend', 'game_genre': 'wrestling', 'release_year': 2018, 'platform': 'Xbox', 'developer': '2K Sports', 'region': 'Europe'},
        # Additional game entries...
    ]

    # Validate required parameters
    if not character_name or not role:
        return {'error': 'Both character_name and role are required parameters.'}

    # Validate output_format
    if output_format not in ['list', 'detailed', 'full']:
        return {'error': 'Invalid output_format. Choose from list, detailed, or full.'}

    # Filter games based on parameters
    filtered_games = [game for game in games_db if game['character_name'] == character_name and game['role'] == role and game['game_genre'] == game_genre]

    # Apply additional filters if provided
    if release_year:
        filtered_games = [game for game in filtered_games if game['release_year'] == release_year]
    if platform:
        filtered_games = [game for game in filtered_games if game['platform'] == platform]
    if developer:
        filtered_games = [game for game in filtered_games if game['developer'] == developer]
    if region:
        filtered_games = [game for game in filtered_games if game['region'] == region]

    # Format output
    if output_format == 'list':
        return {'games': [game['title'] for game in filtered_games]}
    elif output_format == 'detailed':
        return {'games': [{'title': game['title'], 'release_year': game['release_year'], 'platform': game['platform']} for game in filtered_games]}
    elif output_format == 'full':
        return {'games': [{'title': game['title'], 'release_year': game['release_year'], 'platform': game['platform'], 'developer': game['developer'], 'region': game['region']} for game in filtered_games]}

    # Default return if no games found
    return {'games': []}

def game_release_date_finder(game_titles, platform='all', region='global', developer=None, publisher=None, edition=None, output_format='date'):
    """
    Finds the release dates of video games based on the specified parameters.

    Parameters:
    - game_titles (list of str): A list of video game titles for which the release dates are being queried.
    - platform (str): The platform for which the release date is needed. Default is all platforms.
    - region (str): The region for which the release date is needed. Default is global.
    - developer (str): The developer of the video game. Optional parameter to refine the search.
    - publisher (str): The publisher of the video game. Optional parameter to refine the search.
    - edition (str): The specific edition or version of the game. Optional parameter.
    - output_format (str): The format of the output. Defaults to 'date'.

    Returns:
    - str: The release date in the specified format or an error message.
    """
    # Simulated database of release dates
    release_dates = {
        'WWE 2K18': 'October 17, 2017'
    }

    # Validate required parameter
    if not isinstance(game_titles, list) or not all(isinstance(title, str) for title in game_titles):
        return "Error: 'game_titles' must be a list of strings."

    # Initialize results
    results = {}

    # Process each game title
    for title in game_titles:
        if title in release_dates:
            date = release_dates[title]
            if output_format == 'date':
                results[title] = date
            elif output_format == 'text':
                results[title] = f'The release date for {title} is {date}.'
            elif output_format == 'json':
                results[title] = {"title": title, "release_date": date}
            else:
                return "Error: Invalid 'output_format'. Choose from 'date', 'text', or 'json'."
        else:
            results[title] = "Error: Release date not found."

    # Return results based on output format
    if output_format == 'json':
        return results
    else:
        return '\n'.join(results.values())

