        parsed_date = parser.parse(date)
    except ValueError:
        return {'error': 'Invalid date format. Please provide a date in a recognized format such as YYYY-MM-DD or DD/MM/YYYY.'}

    # Error handling for calendar system
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return {'error': 'Unsupported calendar system. Supported systems are: gregorian, julian, islamic, hebrew.'}

    # Error handling for output format
    if output_format not in ['full', 'abbreviated', 'numeric']:
        return {'error': 'Invalid output format. Supported formats are: full, abbreviated, numeric.'}

    # Error handling for time zone
    try:
        tz = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone. Please provide a valid IANA time zone format.'}

    # Convert date to the specified time zone
    localized_date = parsed_date.astimezone(tz)

    # Determine the day of the week
    weekday_number = localized_date.weekday()  # Monday is 0 and Sunday is 6
    weekdays_full = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    weekdays_abbr = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

    if output_format == 'full':
        weekday = weekdays_full[weekday_number]
    elif output_format == 'abbreviated':
        weekday = weekdays_abbr[weekday_number]
    elif output_format == 'numeric':
        weekday = weekday_number

    return {'weekday': weekday}

