def ascii_converter(input, output_format='integer', delimiter=',', case_sensitive=True):
    # Validate input
    if not isinstance(input, list) or not (1 <= len(input) <= 20):
        return {'error': 'Input must be a list with 1 to 20 items.'}
    if output_format not in ['integer', 'text', 'hexadecimal', 'binary']:
        return {'error': 'Invalid output format. Choose from integer, text, hexadecimal, binary.'}
    if not isinstance(delimiter, str):
        return {'error': 'Delimiter must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case_sensitive must be a boolean.'}

    # Convert characters to ASCII
    ascii_codes = []
    for item in input:
        if not isinstance(item, str):
            return {'error': 'Each input item must be a string.'}
        for char in item:
            if not case_sensitive:
                char = char.lower()
            ascii_code = ord(char)
            if output_format == 'integer':
                ascii_codes.append(str(ascii_code))
            elif output_format == 'text':
                ascii_codes.append(char)
            elif output_format == 'hexadecimal':
                ascii_codes.append(hex(ascii_code)[2:])
            elif output_format == 'binary':
                ascii_codes.append(bin(ascii_code)[2:])

    # Join ASCII codes with delimiter
    result = delimiter.join(ascii_codes)
    return {'result': result}

