def extract_last_name(full_name: str, name_format: str = 'first_last', delimiter: str = ' ', include_suffix: bool = False, cultural_format: str = 'western') -> str:
    """
    Extracts the last name from a full name string based on the specified format and options.

    :param full_name: The full name from which to extract the last name.
    :param name_format: The format of the name, which helps in determining the position of the last name.
    :param delimiter: The character(s) used to separate names in the string.
    :param include_suffix: Indicates whether to include suffixes in the extraction.
    :param cultural_format: Specifies the cultural naming convention to be used for extraction.
    :return: The extracted last name.
    """
    # Error handling for missing full_name
    if not full_name:
        raise ValueError("The 'full_name' parameter is required.")

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Determine the last name based on the name_format
    if name_format == 'first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first':
        last_name = name_parts[0]
    elif name_format == 'custom':
        # Custom logic can be implemented here
        last_name = name_parts[-1]
    elif name_format == 'cultural':
        if cultural_format == 'western':
            last_name = name_parts[-1]
        elif cultural_format == 'eastern':
            last_name = name_parts[0]
        elif cultural_format == 'latin':
            last_name = name_parts[-1]
        elif cultural_format == 'arabic':
            last_name = name_parts[0]
        else:
            last_name = name_parts[-1]
    else:
        raise ValueError("Unsupported 'name_format' value.")

    # Include suffix if required
    if include_suffix and len(name_parts) > 1:
        suffixes = ['Jr.', 'Sr.', 'III', 'IV']
        if name_parts[-1] in suffixes:
            last_name = name_parts[-2] + ' ' + name_parts[-1]

    return last_name

