def date_calculator(start_date: str, duration: int, unit: str = 'days', operation: str = 'subtract', output_format: str = 'YYYY-MM-DD', business_days: bool = False, time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate and parse the start_date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS.'

    # Adjust for the time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone specified.'

    # Calculate the delta based on the unit
    if unit == 'days':
        delta = timedelta(days=duration)
    elif unit == 'weeks':
        delta = timedelta(weeks=duration)
    elif unit == 'months':
        # Approximate month as 30 days for simplicity
        delta = timedelta(days=30 * duration)
    elif unit == 'hours':
        delta = timedelta(hours=duration)
    elif unit == 'minutes':
        delta = timedelta(minutes=duration)
    else:
        return 'Error: Invalid unit specified.'

    # Perform the operation
    if operation == 'add':
        result_date = start_date_obj + delta
    elif operation == 'subtract':
        result_date = start_date_obj - delta
    else:
        return 'Error: Invalid operation specified.'

    # Format the result date
    if output_format == 'YYYY-MM-DD':
        result_str = result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        result_str = result_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        result_str = result_date.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        result_str = result_date.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return 'Error: Invalid output format specified.'

    return result_str

