    if not case_sensitive:
        input = input.lower()
        vowels = [v.lower() for v in vowels]

    # Count vowels
    vowel_count = {v: 0 for v in vowels} if count_mode == 'individual' else 0
    for char in input:
        if char in vowels:
            if count_mode == 'individual':
                vowel_count[char] += 1
            else:
