        if count_mode == 'individual':
            return ', '.join([f'{v}: {c}' for v, c in vowel_count.items()])
        else:
            return f'Total vowels: {vowel_count}'

    # Default return in case of unexpected output format
    return {'error': 'Unexpected output format.'}

