def date_calculator(input_date, days_offset=-1, output_format='YYYY-MM-DD', time_zone='UTC', business_days_only=False, calculate_difference=False, second_date=None):
    from datetime import datetime, timedelta
    import pytz

    # Validate input_date format
    try:
        input_date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid input_date format. Expected YYYY-MM-DD.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        input_date_obj = tz.localize(input_date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone specified.'}

    # Calculate new date
    if business_days_only:
        # Adjust only for business days
        days_added = 0
        while days_added < abs(days_offset):
            input_date_obj += timedelta(days=1 if days_offset > 0 else -1)
            if input_date_obj.weekday() < 5:  # Monday to Friday are business days
                days_added += 1
    else:
        input_date_obj += timedelta(days=days_offset)

    # Format output date
    if output_format == 'YYYY-MM-DD':
        output_date = input_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        output_date = input_date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        output_date = input_date_obj.strftime('%d-%m-%Y')
    else:
        return {'error': 'Invalid output format specified.'}

    # Calculate difference if required
    if calculate_difference:
        if not second_date:
            return {'error': 'second_date is required when calculate_difference is true.'}
        try:
            second_date_obj = datetime.strptime(second_date, '%Y-%m-%d')
            second_date_obj = tz.localize(second_date_obj)
            difference = (second_date_obj - input_date_obj).days
            return {'difference': difference}
        except ValueError:
            return {'error': 'Invalid second_date format. Expected YYYY-MM-DD.'}

    return {'output_date': output_date}

# Example usage based on the question
