def date_time_calculator(input_datetime: str, days_offset: int, hours_offset: int = 0, calendar_system: str = 'gregorian', output_format: str = 'YYYY-MM-DDTHH:MM:SS', time_zone: str = 'UTC', exclude_weekends: bool = False, exclude_holidays: list = None) -> str:
    import datetime
    from dateutil import parser, tz
    import pytz

    # Validate input parameters
    try:
        # Parse the input date
        dt = parser.isoparse(input_datetime)
    except ValueError:
        return 'Error: Invalid input_datetime format. Expected ISO 8601 format.'

    # Handle calendar system
    if calendar_system not in ['gregorian', 'julian']:
        return 'Error: Unsupported calendar system. Choose either "gregorian" or "julian".'

    # Convert to the specified time zone
    try:
        target_tz = tz.gettz(time_zone)
        dt = dt.astimezone(target_tz)
    except Exception:
        return 'Error: Invalid time zone specified.'

    # Adjust for days and hours offset
    dt += datetime.timedelta(days=days_offset, hours=hours_offset)

    # Handle exclude weekends and holidays
    if exclude_weekends or exclude_holidays:
        while True:
            if exclude_weekends and dt.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
                dt -= datetime.timedelta(days=1)
                continue
            if exclude_holidays and dt.strftime('%Y-%m-%d') in exclude_holidays:
                dt -= datetime.timedelta(days=1)
                continue
            break

    # Format the output
    if output_format == 'YYYY-MM-DDTHH:MM:SS':
        return dt.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'MM/DD/YYYY HH:MM':
        return dt.strftime('%m/%d/%Y %H:%M')
    elif output_format == 'DD-MM-YYYY HH:MM':
        return dt.strftime('%d-%m-%Y %H:%M')
    else:
        return 'Error: Unsupported output format.'

