    from datetime import datetime, timedelta
    import pytz

    # Error handling for invalid date format
    try:
        start_date_obj = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
    except ValueError:
        return 'Invalid start_date format. Please use ISO 8601 format (YYYY-MM-DDTHH:MM:SSZ).'

    # Adjust for timezone
    try:
        timezone_offset = pytz.timezone('Etc/GMT' + timezone.replace(':', ''))
        start_date_obj = start_date_obj.astimezone(timezone_offset)
    except pytz.UnknownTimeZoneError:
        return 'Invalid timezone format. Please use a valid UTC offset (e.g., +00:00, -05:00).'

    # Calculate new date
    new_date_obj = start_date_obj + timedelta(days=days_to_add)

    # Format output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = new_date_obj.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date_obj.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SSZ':
        formatted_date = new_date_obj.strftime('%Y-%m-%dT%H:%M:%SZ')
    else:
        return 'Invalid output_format. Supported formats are YYYY-MM-DD, MM/DD/YYYY, DD-MM-YYYY, YYYY-MM-DDTHH:MM:SSZ.'

    return formatted_date

