def closest_palindrome_finder(year, direction='both', output_format='integer', range_limit=None, multiple_results=False):
    """
    Finds the closest palindrome number to the given year.

    Parameters:
    - year (int): The year for which the closest palindrome number is to be found.
    - direction (str): The direction to search for palindromes ('both', 'lower', 'higher').
    - output_format (str): The format of the output ('integer', 'text').
    - range_limit (int): The maximum distance from the given year to search for palindromes.
    - multiple_results (bool): If true, returns a list of closest palindromes within the specified range.

    Returns:
    - int or list: The closest palindrome(s) in the specified format.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    if not isinstance(year, int):
        raise ValueError("Year must be an integer.")
    if direction not in ['both', 'lower', 'higher']:
        raise ValueError("Direction must be 'both', 'lower', or 'higher'.")
    if output_format not in ['integer', 'text']:
        raise ValueError("Output format must be 'integer' or 'text'.")

    closest_palindromes = []
    distance = 0
    while True:
        if range_limit is not None and distance > range_limit:
            break
        candidates = []
        if direction in ['both', 'lower']:
            lower_candidate = year - distance
            if lower_candidate >= 0 and is_palindrome(lower_candidate):
                candidates.append(lower_candidate)
        if direction in ['both', 'higher']:
            higher_candidate = year + distance
            if is_palindrome(higher_candidate):
                candidates.append(higher_candidate)
        if candidates:
            closest_palindromes.extend(candidates)
            if not multiple_results:
                break
        distance += 1
    if not closest_palindromes:
        return None
    if output_format == 'text':
        closest_palindromes = [str(pal) for pal in closest_palindromes]
    return closest_palindromes if multiple_results else closest_palindromes[0]

