def distinct_combinations(input_string, case_sensitive=True, output_format='count', combination_length=2, ignore_characters='', character_set='all'):
    from itertools import combinations
    import string

    # Error handling for invalid parameters
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if output_format not in ['count', 'list']:
        return {'error': 'output_format must be either "count" or "list"'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be an integer greater than 0'}
    if not isinstance(ignore_characters, str):
        return {'error': 'ignore_characters must be a string'}
    if character_set not in ['all', 'alphabetic', 'numeric', 'alphanumeric']:
        return {'error': 'character_set must be one of "all", "alphabetic", "numeric", "alphanumeric"'}

    # Adjust input string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        ignore_characters = ignore_characters.lower()

    # Filter characters based on character_set
    if character_set == 'alphabetic':
        valid_chars = string.ascii_letters
    elif character_set == 'numeric':
        valid_chars = string.digits
    elif character_set == 'alphanumeric':
        valid_chars = string.ascii_letters + string.digits
    else:
        valid_chars = input_string  # 'all' means no filtering

    # Remove ignored characters
    filtered_string = ''.join([ch for ch in input_string if ch not in ignore_characters and ch in valid_chars])

    # Generate combinations
    unique_combinations = set(combinations(filtered_string, combination_length))

    # Return based on output_format
    if output_format == 'count':
        return len(unique_combinations)
    else:
        return [''.join(comb) for comb in unique_combinations]

