print(result)  # Output: 'Martha'

def distinct_combinations(input_string, case_sensitive=True, output_format='count', filter_characters='', max_combinations=None):
    # Validate input types
    if not isinstance(input_string, str):
        return {'error': 'Invalid input: input_string must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if output_format not in ['count', 'list', 'detailed_list']:
        return {'error': 'Invalid input: output_format must be one of count, list, detailed_list.'}
    if not isinstance(filter_characters, str):
        return {'error': 'Invalid input: filter_characters must be a string.'}
    if max_combinations is not None and not isinstance(max_combinations, int):
        return {'error': 'Invalid input: max_combinations must be an integer or None.'}

    # Apply case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        filter_characters = filter_characters.lower()

    # Filter out unwanted characters
    filtered_string = ''.join([ch for ch in input_string if ch not in filter_characters])

    # Generate distinct two-letter combinations
    from itertools import combinations
    all_combinations = set(combinations(filtered_string, 2))

    # Prepare the output
    if output_format == 'count':
        result = len(all_combinations)
    elif output_format == 'list':
        result = [''.join(comb) for comb in all_combinations]
        if max_combinations is not None:
            result = result[:max_combinations]
    elif output_format == 'detailed_list':
        from collections import Counter
        combination_counts = Counter([''.join(comb) for comb in all_combinations])
        result = [{'combination': comb, 'frequency': freq} for comb, freq in combination_counts.items()]
        if max_combinations is not None:
            result = result[:max_combinations]

    return result

