def nearest_palindrome_year(year, direction='both', range=100, return_multiple=False):
    # Helper function to check if a year is a palindrome
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    # Validate inputs
    if not isinstance(year, int):
        return {'error': 'Invalid input: year must be an integer.'}
    if direction not in ['past', 'future', 'both']:
        return {'error': "Invalid input: direction must be 'past', 'future', or 'both'."}
    if not isinstance(range, int) or range < 0:
        return {'error': 'Invalid input: range must be a non-negative integer.'}
    if not isinstance(return_multiple, bool):
        return {'error': 'Invalid input: return_multiple must be a boolean.'}

    closest_palindromes = []
    min_distance = float('inf')

    # Search for palindrome years
    for offset in range(1, range + 1):
        if direction in ['past', 'both']:
            past_year = year - offset
            if is_palindrome(past_year):
                distance = offset
                if distance < min_distance:
                    closest_palindromes = [past_year]
                    min_distance = distance
                elif distance == min_distance and return_multiple:
                    closest_palindromes.append(past_year)

        if direction in ['future', 'both']:
            future_year = year + offset
            if is_palindrome(future_year):
                distance = offset
                if distance < min_distance:
                    closest_palindromes = [future_year]
                    min_distance = distance
                elif distance == min_distance and return_multiple:
                    closest_palindromes.append(future_year)

    # Return the result
    if not closest_palindromes:
        return {'error': 'No palindrome year found within the specified range.'}
    return {'closest_palindrome_years': closest_palindromes}

