def date_calculator(start_date: str, end_date: str = None, years_to_add: int = 1, months_to_add: int = 0, days_to_add: int = 0, time_zone: str = 'UTC', output_format: str = 'date', calculate_difference: bool = False) -> str:
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    try:
        # Parse the start date
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')

        # Adjust for the time zone
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)

        if calculate_difference:
            if not end_date:
                raise ValueError("'end_date' must be provided when 'calculate_difference' is True.")
            end_date_obj = datetime.strptime(end_date, '%Y-%m-%d')
            end_date_obj = tz.localize(end_date_obj)
            difference = end_date_obj - start_date_obj
            return str(difference.days) + ' days'
        else:
            # Add years, months, and days
            new_date = start_date_obj + relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)

            # Format the output
            if output_format == 'date':
                return new_date.strftime('%Y-%m-%d')
            elif output_format == 'text':
                return new_date.strftime('%A, %B %d, %Y')
            elif output_format == 'iso':
                return new_date.isoformat()
            elif output_format == 'timestamp':
                return str(int(new_date.timestamp()))
            else:
                raise ValueError("Invalid 'output_format' specified.")
    except Exception as e:
        return f"Error: {str(e)}"

