def extract_first_name(full_name, delimiter=' ', ignore_case=True, handle_special_characters=True, include_middle_name=False, prefixes=None, suffixes=None, cultural_convention='Western'):
    # Validate required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Default values for optional parameters
    if prefixes is None:
        prefixes = []
    if suffixes is None:
        suffixes = []

    # Normalize case if ignore_case is True
    if ignore_case:
        full_name = full_name.lower()
        prefixes = [prefix.lower() for prefix in prefixes]
        suffixes = [suffix.lower() for suffix in suffixes]

    # Split the full name using the delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes
    name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes
    name_parts = [part for part in name_parts if part not in suffixes]

    # Handle special characters if needed
    if handle_special_characters:
        name_parts = [part.strip('.,') for part in name_parts]

    # Extract first name based on cultural convention
    if cultural_convention == 'Western':
        first_name = name_parts[0] if name_parts else ''
    elif cultural_convention == 'Eastern':
        first_name = name_parts[-1] if name_parts else ''
    else:
        return {'error': 'Unsupported cultural convention.'}

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + ' '.join(name_parts[1:-1])

    return {'first_name': first_name.capitalize() if ignore_case else first_name}

