def date_calculator(start_date: str, years_to_add: int, months_to_add: int = 0, days_to_add: int = 0, hours_to_add: int = 0, minutes_to_add: int = 0, seconds_to_add: int = 0, output_format: str = 'YYYY-MM-DDTHH:MM:SS', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate and parse the start_date
    try:
        start_dt = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS.'

    # Apply the date arithmetic
    try:
        new_date = start_dt + relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)
        new_date += timedelta(hours=hours_to_add, minutes=minutes_to_add, seconds=seconds_to_add)
    except Exception as e:
        return f'Error: {str(e)}'

    # Handle time zone conversion
    try:
        tz = pytz.timezone(time_zone)
        new_date = new_date.astimezone(tz)
    except Exception as e:
        return f'Error: Invalid time zone. {str(e)}'

    # Format the output date
    formats = {
        'YYYY-MM-DD': '%Y-%m-%d',
        'MM/DD/YYYY': '%m/%d/%Y',
        'DD-MM-YYYY': '%d-%m-%Y',
        'YYYY-MM-DDTHH:MM:SS': '%Y-%m-%dT%H:%M:%S',
        'MM/DD/YYYY HH:MM:SS': '%m/%d/%Y %H:%M:%S',
        'DD-MM-YYYY HH:MM:SS': '%d-%m-%Y %H:%M:%S'
    }

    if output_format not in formats:
        return 'Error: Invalid output format.'

    return new_date.strftime(formats[output_format])

