def extract_first_name(full_name, output_format='string', handle_prefixes=True, handle_suffixes=True):
    # Define prefixes and suffixes to ignore
    prefixes = ['Dr.', 'Mr.', 'Ms.', 'Mrs.']
    suffixes = ['Jr.', 'Sr.', 'III']

    # Validate input
    if not isinstance(full_name, list) or not all(isinstance(name, str) for name in full_name):
        return {'error': 'Invalid input: full_name must be a list of strings.'}
    if len(full_name) < 1 or len(full_name) > 100:
        return {'error': 'Invalid input: full_name list must have between 1 and 100 items.'}
    if output_format not in ['string', 'list', 'json', 'csv']:
        return {'error': 'Invalid output format. Supported formats are string, list, json, csv.'}

    # Process each name
    first_names = []
    for name in full_name:
        parts = name.split()
        # Remove prefixes
        if handle_prefixes:
            parts = [part for part in parts if part not in prefixes]
        # Remove suffixes
        if handle_suffixes and len(parts) > 1:
            if parts[-1] in suffixes:
                parts = parts[:-1]
        # Extract the first name
        if parts:
            first_names.append(parts[0])

    # Format output
    if output_format == 'string':
        return first_names[0] if first_names else ''
    elif output_format == 'list':
        return first_names
    elif output_format == 'json':
        import json
        return json.dumps(first_names)
    elif output_format == 'csv':
        return ','.join(first_names)

    return {'error': 'Unexpected error occurred.'}

