def extract_last_name(full_name, delimiter=' ', case_sensitive=True, handle_suffix=False, cultural_convention='western', return_format='last_name_only'):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Error handling for optional parameters
    if not isinstance(delimiter, str):
        return {'error': 'Invalid delimiter. It must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive. It must be a boolean.'}
    if not isinstance(handle_suffix, bool):
        return {'error': 'Invalid handle_suffix. It must be a boolean.'}
    if cultural_convention not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid cultural_convention. It must be one of ["western", "eastern", "custom"].'}
    if return_format not in ['last_name_only', 'last_name_and_rest']:
        return {'error': 'Invalid return_format. It must be one of ["last_name_only", "last_name_and_rest"].'}

    # Splitting the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handling different cultural conventions
    if cultural_convention == 'western':
        last_name_index = -1 if not handle_suffix else -2
    elif cultural_convention == 'eastern':
        last_name_index = 0
    else:  # custom
        last_name_index = -1

    # Extracting the last name
    last_name = name_parts[last_name_index]

    # Handling case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    # Returning the result based on the return format
    if return_format == 'last_name_only':
        return last_name
    else:
        rest_of_name = delimiter.join(name_parts[:last_name_index])
        return {'last_name': last_name, 'rest_of_name': rest_of_name}

