def date_digit_sum(date, date_format='MM-DD-YYYY', output_format='integer', components_to_sum=['day', 'month', 'year'], error_handling='warn'):
    import datetime
    import re

    # Helper function to sum digits in a string
    def sum_digits(s):
        return sum(int(char) for char in s if char.isdigit())

    # Parse the date based on the provided format
    try:
        if date_format == 'MM-DD-YYYY':
            parsed_date = datetime.datetime.strptime(date, '%m-%d-%Y')
        elif date_format == 'DD-MM-YYYY':
            parsed_date = datetime.datetime.strptime(date, '%d-%m-%Y')
        else:
            if error_handling == 'strict':
                raise ValueError('Unsupported date format')
            elif error_handling == 'warn':
                print('Warning: Unsupported date format, defaulting to MM-DD-YYYY')
                parsed_date = datetime.datetime.strptime(date, '%m-%d-%Y')
            else:
                return None
    except ValueError as e:
        if error_handling == 'strict':
            raise e
        elif error_handling == 'warn':
            print(f'Warning: {e}')
        return None

    # Extract components
    components = {
        'day': parsed_date.day,
        'month': parsed_date.month,
        'year': parsed_date.year
    }

    # Calculate the sum of digits for specified components
    total_sum = 0
    detailed_breakdown = {}
    for component in components_to_sum:
        if component in components:
            component_sum = sum_digits(str(components[component]))
            total_sum += component_sum
            detailed_breakdown[component] = component_sum

    # Return the result based on the output format
    if output_format == 'integer':
        return total_sum
    elif output_format == 'text':
        return f'The sum of digits is {total_sum}'
    elif output_format == 'detailed':
        return detailed_breakdown
    else:
        if error_handling == 'strict':
            raise ValueError('Unsupported output format')
        elif error_handling == 'warn':
            print('Warning: Unsupported output format, defaulting to integer')
