def first_letter_extractor_v2(input, case_sensitive=True, output_format='character', handle_empty='error', non_alphabetic_handling='include'):
    # Error handling for empty input
    if not input:
        if handle_empty == 'error':
            raise ValueError('Input string is empty.')
        elif handle_empty == 'null':
            return None
        elif handle_empty == 'default_character':
            return 'A'  # Assuming 'A' as a default character

    # Extract the first character
    first_char = input[0]

    # Handle non-alphabetic characters
    if not first_char.isalpha():
        if non_alphabetic_handling == 'error':
            raise ValueError('First character is non-alphabetic.')
        elif non_alphabetic_handling == 'ignore':
            return None

    # Adjust case sensitivity
    if not case_sensitive:
        first_char = first_char.lower()

    # Format the output
    if output_format == 'character':
        return first_char
    elif output_format == 'ascii':
        return ord(first_char)
    elif output_format == 'unicode':
        return f'U+{ord(first_char):04X}'

