def char_to_binary(input, output_format='binary_string', include_prefix=False, encoding='utf-8', include_metadata=False):
    # Validate input
    if not input or len(input) < 1:
        return {'error': 'Input must be at least one character long.'}
    if output_format not in ['binary_string', 'binary_list', 'binary_dict']:
        return {'error': 'Invalid output format specified.'}
    if encoding not in ['utf-8', 'ascii', 'utf-16']:
        return {'error': 'Unsupported encoding type.'}

    # Convert input to binary
    try:
        binary_codes = [format(ord(char), 'b') for char in input.encode(encoding).decode(encoding)]
    except Exception as e:
        return {'error': str(e)}

    # Include prefix if required
    if include_prefix:
        binary_codes = ['0b' + code for code in binary_codes]

    # Generate output based on format
    if output_format == 'binary_string':
        result = ''.join(binary_codes)
    elif output_format == 'binary_list':
        result = binary_codes
    elif output_format == 'binary_dict':
        result = {char: code for char, code in zip(input, binary_codes)}

    # Include metadata if required
    if include_metadata:
        metadata = {'input_length': len(input), 'encoding': encoding}
        return {'result': result, 'metadata': metadata}
    else:
        return {'result': result}

