def extract_last_name(full_name, name_delimiter=' ', consider_suffix=False, handle_middle_names=False, cultural_context='Western', compound_last_name_handling=True):
    # Validate input
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name provided. It must be a non-empty string.'}
    if not isinstance(name_delimiter, str):
        return {'error': 'Invalid name_delimiter provided. It must be a string.'}
    if not isinstance(consider_suffix, bool):
        return {'error': 'Invalid consider_suffix provided. It must be a boolean.'}
    if not isinstance(handle_middle_names, bool):
        return {'error': 'Invalid handle_middle_names provided. It must be a boolean.'}
    if not isinstance(cultural_context, str):
        return {'error': 'Invalid cultural_context provided. It must be a string.'}
    if not isinstance(compound_last_name_handling, bool):
        return {'error': 'Invalid compound_last_name_handling provided. It must be a boolean.'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(name_delimiter)

    # Handle suffixes if required
    if consider_suffix and len(name_parts) > 1:
        suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV']
        if name_parts[-1] in suffixes:
            name_parts = name_parts[:-1]

    # Handle middle names if required
    if not handle_middle_names and len(name_parts) > 2:
        name_parts = [name_parts[0], name_parts[-1]]

    # Extract last name based on cultural context
    if cultural_context == 'Western':
        last_name = name_parts[-1]
    elif cultural_context == 'Eastern':
        last_name = name_parts[0]
    elif cultural_context == 'Hispanic' and compound_last_name_handling:
        last_name = ' '.join(name_parts[-2:]) if len(name_parts) > 1 else name_parts[-1]
    else:
        last_name = name_parts[-1]

    return {'last_name': last_name}

