def first_letter_extractor(input: str, case_sensitive: bool = True, handle_empty: str = 'error', ignore_leading_whitespace: bool = False, character_set: str = 'all', custom_error_message: str = 'Invalid input.') -> str:
    # Handle empty input based on 'handle_empty' parameter
    if not input:
        if handle_empty == 'error':
            return custom_error_message
        elif handle_empty == 'empty':
            return ''
        elif handle_empty == 'null':
            return 'null'

    # Ignore leading whitespace if specified
    if ignore_leading_whitespace:
        input = input.lstrip()

    # Extract the first character
    first_char = input[0] if input else ''

    # Check if the character is in the specified character set
    if character_set != 'all' and first_char not in character_set:
        return custom_error_message

    # Handle case sensitivity
    if not case_sensitive:
        first_char = first_char.lower()

    return first_char

