def advanced_date_calculator(start_date, months_offset, days_offset=0, output_format='date', calendar_system='gregorian', time_zone='UTC', recurrence=None):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone specified.'}

    # Calculate new date
    try:
        new_date_obj = start_date_obj + relativedelta(months=months_offset, days=days_offset)
    except Exception as e:
        return {'error': str(e)}

    # Format output
    if output_format == 'date':
        result = new_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'text':
        result = new_date_obj.strftime('%A, %B %d, %Y')
    elif output_format == 'timestamp':
        result = int(new_date_obj.timestamp())
    elif output_format == 'iso':
        result = new_date_obj.isoformat()
    else:
        return {'error': 'Invalid output format specified.'}

    # Handle recurrence if specified
    if recurrence:
        interval = recurrence.get('interval')
        count = recurrence.get('count', 1)
        recurrence_dates = []
        for i in range(count):
            if interval == 'daily':
                recurrence_dates.append((new_date_obj + timedelta(days=i)).strftime('%Y-%m-%d'))
            elif interval == 'weekly':
                recurrence_dates.append((new_date_obj + timedelta(weeks=i)).strftime('%Y-%m-%d'))
            elif interval == 'monthly':
                recurrence_dates.append((new_date_obj + relativedelta(months=i)).strftime('%Y-%m-%d'))
            elif interval == 'yearly':
                recurrence_dates.append((new_date_obj + relativedelta(years=i)).strftime('%Y-%m-%d'))
            else:
                return {'error': 'Invalid recurrence interval specified.'}
        return {'result': recurrence_dates}

    return {'result': result}

