def extract_first_name(names, output_format='string', case_sensitivity=False, include_middle_initial=False):
    # Validate input types
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        return {'error': 'Invalid input: names must be a list of strings.'}
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid output_format: must be one of string, array, json.'}
    if not isinstance(case_sensitivity, bool) or not isinstance(include_middle_initial, bool):
        return {'error': 'Invalid input: case_sensitivity and include_middle_initial must be boolean.'}

    # Process each name to extract the first name
    extracted_names = []
    for full_name in names:
        # Split the name by spaces
        parts = full_name.split()
        if not parts:
            extracted_names.append('')
            continue
        # Extract the first name
        first_name = parts[0]
        # Include middle initial if required
        if include_middle_initial and len(parts) > 1 and len(parts[1]) == 1:
            first_name += ' ' + parts[1]
        # Adjust case sensitivity
        if not case_sensitivity:
            first_name = first_name.capitalize()
        extracted_names.append(first_name)

    # Format the output
    if output_format == 'string':
        return extracted_names[0] if len(extracted_names) == 1 else ', '.join(extracted_names)
    elif output_format == 'array':
        return extracted_names
    elif output_format == 'json':
        return {'first_names': extracted_names, 'metadata': {'count': len(extracted_names)}}

