def extract_last_letter_v2(input: str, trim_whitespace: bool = True, ignore_punctuation: bool = False, output_format: str = 'character', case_sensitive: bool = True, language_support: str = 'any'):
    import string

    # Error handling for input type
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Expected a string.'}

    # Trim whitespace if required
    if trim_whitespace:
        input = input.strip()

    # Handle case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Ignore punctuation if required
    if ignore_punctuation:
        input = ''.join(char for char in input if char not in string.punctuation)

    # Determine the last letter based on language support
    if language_support == 'latin':
        input = ''.join(char for char in input if char.isalpha() and char.isascii())
    elif language_support == 'cyrillic':
        input = ''.join(char for char in input if 'А' <= char <= 'я')
    elif language_support == 'arabic':
        input = ''.join(char for char in input if '؀' <= char <= 'ۿ')
    # 'any' does not filter further

    # Error handling for empty input after processing
    if not input:
        return {'error': 'No valid characters found in input.'}

    # Extract the last letter
    last_letter = input[-1]

    # Return based on output format
    if output_format == 'character':
        return last_letter
    elif output_format == 'text':
        return f'The last letter is: {last_letter}'
    elif output_format == 'json':
        return {
            'last_letter': last_letter,
            'original_input': input,
            'trim_whitespace': trim_whitespace,
            'ignore_punctuation': ignore_punctuation,
            'case_sensitive': case_sensitive,
            'language_support': language_support
        }
    else:
        return {'error': 'Invalid output format specified.'}

