def char_to_binary(input: str, output_format: str = 'binary_string', include_non_ascii: bool = False, encoding: str = 'utf-8', bit_length: int = 8, delimiter: str = '') -> str:
    # Validate input
    if not isinstance(input, str) or len(input) == 0:
        raise ValueError('Input must be a non-empty string.')
    if output_format not in ['binary_string', 'binary_list']:
        raise ValueError("Output format must be 'binary_string' or 'binary_list'.")
    if encoding not in ['utf-8', 'ascii', 'utf-16']:
        raise ValueError("Encoding must be 'utf-8', 'ascii', or 'utf-16'.")
    if bit_length <= 0:
        raise ValueError('Bit length must be a positive integer.')

    # Convert each character to binary
    binary_codes = []
    for char in input:
        # Skip non-ASCII characters if include_non_ascii is False
        if not include_non_ascii and ord(char) > 127:
            continue
        # Encode character and convert to binary
        encoded_char = char.encode(encoding)
        binary_code = ''.join(format(byte, f'0{bit_length}b') for byte in encoded_char)
        binary_codes.append(binary_code)

    # Prepare output
    if output_format == 'binary_string':
        return delimiter.join(binary_codes)
    elif output_format == 'binary_list':
        return binary_codes

