def date_calculator(start_date: str, months_offset: int, days_offset: int = 0, hours_offset: int = 0, calendar_system: str = 'gregorian', output_format: str = 'date') -> str:
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate calendar system
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return 'Error: Unsupported calendar system.'

    # Validate output format
    if output_format not in ['date', 'text', 'timestamp']:
        return 'Error: Unsupported output format.'

    try:
        # Parse the start date
        start_date_obj = datetime.fromisoformat(start_date.replace('Z', '+00:00'))

        # Apply the offsets
        new_date = start_date_obj + relativedelta(months=months_offset, days=days_offset, hours=hours_offset)

        # Format the output
        if output_format == 'date':
            return new_date.strftime('%Y-%m-%d')
        elif output_format == 'text':
            return new_date.strftime('%A, %B %d, %Y %H:%M:%S')
        elif output_format == 'timestamp':
            return str(int(new_date.timestamp()))
    except Exception as e:
        return f'Error: {str(e)}'

