def extract_last_name(full_name, delimiter=' ', case_sensitive=True, ignore_prefixes=True, ignore_suffixes=True, cultural_convention='western'):
    """
    Extracts the last name from a full name string based on specified parameters.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}

    # Error handling for cultural_convention
    if cultural_convention not in ['western', 'eastern', 'custom']:
        return {'error': "Invalid input: cultural_convention must be 'western', 'eastern', or 'custom'."}

    # Common prefixes and suffixes
    prefixes = ['Dr.', 'Mr.', 'Mrs.', 'Ms.']
    suffixes = ['Jr.', 'Sr.', 'II', 'III']

    # Split the full name using the delimiter
    name_parts = full_name.split(delimiter)

    # Filter out prefixes if required
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Filter out suffixes if required
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Determine the last name based on cultural convention
    if cultural_convention == 'western':
        last_name = name_parts[-1] if name_parts else ''
    elif cultural_convention == 'eastern':
        last_name = name_parts[0] if name_parts else ''
    else:  # 'custom'
        last_name = name_parts[-1] if name_parts else ''  # Default to western logic for custom

    # Return the last name, considering case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    return {'last_name': last_name}

