def advanced_character_counter(input, characters_to_count=['a', 'e', 'i', 'o', 'u'], case_sensitive=False, output_format='integer', include_patterns=[], exclude_characters=[], range=None):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(characters_to_count, list) or not all(isinstance(c, str) for c in characters_to_count):
        return {'error': 'Characters to count must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed_report', 'visualization']:
        return {'error': 'Invalid output format.'}
    if not isinstance(include_patterns, list) or not all(isinstance(p, str) for p in include_patterns):
        return {'error': 'Include patterns must be a list of strings.'}
    if not isinstance(exclude_characters, list) or not all(isinstance(e, str) for e in exclude_characters):
        return {'error': 'Exclude characters must be a list of strings.'}
    if range is not None:
        if not isinstance(range, dict) or 'start' not in range or 'end' not in range:
            return {'error': 'Range must be a dictionary with start and end keys.'}
        if not isinstance(range['start'], int) or not isinstance(range['end'], int):
            return {'error': 'Range start and end must be integers.'}
        if range['start'] < 0 or range['end'] > len(input) or range['start'] >= range['end']:
            return {'error': 'Invalid range values.'}

    # Apply range if specified
    if range:
        input = input[range['start']:range['end']]

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        characters_to_count = [c.lower() for c in characters_to_count]
        include_patterns = [p.lower() for p in include_patterns]
        exclude_characters = [e.lower() for e in exclude_characters]

    # Count characters and patterns
    count = 0
    for char in characters_to_count:
        count += input.count(char)
    for pattern in include_patterns:
        count += input.count(pattern)
    for exclude in exclude_characters:
        count -= input.count(exclude)

    # Format output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'Total count: {count}'
    elif output_format == 'detailed_report':
        return {'total_count': count, 'details': {'characters_counted': characters_to_count, 'patterns_included': include_patterns, 'characters_excluded': exclude_characters}}
    elif output_format == 'visualization':
        return {'visualization': f'Count: {count}'}

