def enhanced_difference_calculator(numbers, absolute_difference=False, percentage_difference=False, precision=2):
    # Validate input
    if not isinstance(numbers, list) or len(numbers) < 2:
        return {'error': 'Invalid input: numbers must be a list with at least two elements.'}
    if not all(isinstance(n, (int, float)) for n in numbers):
        return {'error': 'Invalid input: all elements in numbers must be integers or floats.'}
    if not isinstance(absolute_difference, bool):
        return {'error': 'Invalid input: absolute_difference must be a boolean.'}
    if not isinstance(percentage_difference, bool):
        return {'error': 'Invalid input: percentage_difference must be a boolean.'}
    if not isinstance(precision, int) or precision < 0:
        return {'error': 'Invalid input: precision must be a non-negative integer.'}

    # Calculate difference
    diff = numbers[0] - numbers[1]

    # Apply absolute difference if required
    if absolute_difference:
        diff = abs(diff)

    # Apply percentage difference if required
    if percentage_difference:
        if numbers[1] == 0:
            return {'error': 'Cannot calculate percentage difference with a denominator of zero.'}
        diff = (diff / numbers[1]) * 100

    # Round the result to the specified precision
    diff = round(diff, precision)

    return {'result': diff}

