def extract_first_name(names, include_prefixes=False, output_format='string', name_format='western', custom_delimiter=' '):
    """
    Extracts the first name from a list of full name strings.

    Parameters:
    - names (list of str): The full names from which to extract the first name.
    - include_prefixes (bool): Whether to include prefixes in the extraction.
    - output_format (str): The format of the output ('string', 'array', 'json').
    - name_format (str): Specifies the expected name format ('western', 'eastern', 'custom').
    - custom_delimiter (str): A custom delimiter to use when parsing names.

    Returns:
    - str, list, or dict: The extracted first names in the specified format.
    """
    if not names or not isinstance(names, list):
        return {'error': 'Invalid input: names must be a non-empty list of strings.'}

    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid output format specified.'}

    if name_format not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid name format specified.'}

    first_names = []
    for full_name in names:
        if not isinstance(full_name, str):
            return {'error': 'Invalid input: each name must be a string.'}

        parts = full_name.split(custom_delimiter)
        if name_format == 'western':
            first_name = parts[0] if parts else ''
        elif name_format == 'eastern':
            first_name = parts[-1] if parts else ''
        else:  # custom
            first_name = parts[0] if parts else ''

        if include_prefixes:
            first_name = ' '.join(parts[:2]) if len(parts) > 1 else first_name

        first_names.append(first_name)

    if output_format == 'string':
        return first_names[0] if len(first_names) == 1 else ', '.join(first_names)
    elif output_format == 'array':
        return first_names
    elif output_format == 'json':
        return {'first_names': first_names}

