def extract_first_letter(input: str, ignore_whitespace: bool = True, output_format: str = 'character', case_sensitive: bool = False, special_character_handling: str = 'ignore', default_character: str = '') -> str:
    # Validate 'output_format'
    if output_format not in ['character', 'ascii', 'unicode']:
        return 'Error: Invalid output_format. Must be one of [character, ascii, unicode].'

    # Validate 'special_character_handling'
    if special_character_handling not in ['ignore', 'include']:
        return 'Error: Invalid special_character_handling. Must be one of [ignore, include].'

    # Trim leading whitespace if 'ignore_whitespace' is True
    if ignore_whitespace:
        input = input.lstrip()

    # Handle special characters
    if special_character_handling == 'ignore':
        input = ''.join(filter(str.isalpha, input))

    # Check if input is empty after processing
    if not input:
        return default_character

    # Extract the first character
    first_char = input[0]

    # Handle case sensitivity
    if not case_sensitive:
        first_char = first_char.lower()

    # Format the output
    if output_format == 'ascii':
        return str(ord(first_char))
    elif output_format == 'unicode':
        return f'U+{ord(first_char):04X}'
    else:  # 'character'
        return first_char

