def advanced_letter_counter(input, ignore_non_letters=True, case_sensitive=False, output_format='integer', count_vowels=False, count_consonants=False, exclude_characters=''):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_non_letters, bool) or not isinstance(case_sensitive, bool) or not isinstance(count_vowels, bool) or not isinstance(count_consonants, bool):
        return {'error': 'Boolean parameters must be of type bool.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format.'}
    if count_vowels and count_consonants:
        return {'error': 'Cannot count both vowels and consonants simultaneously.'}

    # Initialize variables
    vowels = 'aeiouAEIOU' if case_sensitive else 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ' if case_sensitive else 'bcdfghjklmnpqrstvwxyz'
    letter_count = 0
    detailed_count = {'vowels': 0, 'consonants': 0, 'others': 0}

    # Process each character in the input
    for char in input:
        if char in exclude_characters:
            continue
        if ignore_non_letters and not char.isalpha():
            continue
        if not case_sensitive:
            char = char.lower()

        if count_vowels and char in vowels:
            letter_count += 1
            detailed_count['vowels'] += 1
        elif count_consonants and char in consonants:
            letter_count += 1
            detailed_count['consonants'] += 1
        elif not count_vowels and not count_consonants:
            if char.isalpha():
                letter_count += 1
                if char in vowels:
                    detailed_count['vowels'] += 1
                else:
