def calculate_difference(number1, number2, operation, output_format='integer', precision=2, handle_negative=False, handle_division_by_zero='error'):
    """
    Perform arithmetic operations between two numbers with flexible options.
    """
    try:
        # Perform the specified operation
        if operation == 'subtract':
            result = number1 - number2
        elif operation == 'add':
            result = number1 + number2
        elif operation == 'multiply':
            result = number1 * number2
        elif operation == 'divide':
            if number2 == 0:
                if handle_division_by_zero == 'error':
                    raise ZeroDivisionError('Division by zero is not allowed.')
                elif handle_division_by_zero == 'infinity':
                    result = float('inf')
                elif handle_division_by_zero == 'zero':
                    result = 0
            else:
                result = number1 / number2
        else:
            raise ValueError('Invalid operation specified.')

        # Handle negative results if required
        if handle_negative and result < 0:
            result = abs(result)

        # Format the result according to the output_format
        if output_format == 'integer':
            result = int(result)
        elif output_format == 'float':
            result = round(float(result), precision)
        elif output_format == 'text':
            result = str(result)
        else:
            raise ValueError('Invalid output format specified.')

        return result

    except Exception as e:
        return str(e)

