from datetime import datetime, timedelta

class InvalidInputError(Exception):
    pass

def enhanced_year_calculator(start_year, start_month=1, start_day=1, year_increment=0, month_increment=0, day_increment=0, calendar_system='Gregorian', consider_leap_years=True):
    """
    Calculate a future or past date based on a given starting year, month, and day,
    with options to specify the increment or decrement in years, months, and days,
    and to choose the calendar system.
    """
    # Validate inputs
    if not (1 <= start_month <= 12):
        raise InvalidInputError("Invalid start month. Must be between 1 and 12.")
    if not (1 <= start_day <= 31):
        raise InvalidInputError("Invalid start day. Must be between 1 and 31.")
    if calendar_system not in ['Gregorian', 'Julian']:
        raise InvalidInputError("Unsupported calendar system. Choose 'Gregorian' or 'Julian'.")

    try:
        # Create a starting date object
        start_date = datetime(start_year, start_month, start_day)

        # Calculate the new date
        new_year = start_date.year + year_increment
        new_month = start_date.month + month_increment
        new_day = start_date.day + day_increment

        # Adjust for month overflow
        while new_month > 12:
            new_month -= 12
            new_year += 1
        while new_month < 1:
            new_month += 12
            new_year -= 1

        # Adjust for day overflow
        try:
            new_date = datetime(new_year, new_month, new_day)
        except ValueError:
            # Handle day overflow by adjusting the day
            if new_month == 2 and consider_leap_years:
                # Handle February in leap years
                if (new_year % 4 == 0 and new_year % 100 != 0) or (new_year % 400 == 0):
                    new_day = min(new_day, 29)
                else:
                    new_day = min(new_day, 28)
            else:
                # Handle months with 30 days
                if new_month in [4, 6, 9, 11]:
                    new_day = min(new_day, 30)
                else:
                    new_day = min(new_day, 31)
            new_date = datetime(new_year, new_month, new_day)

        # Return the calculated date
        return {
            'year': new_date.year,
            'month': new_date.month,
            'day': new_date.day,
            'calendar_system': calendar_system
        }

    except Exception as e:
        return {'error': str(e)}

