def extract_date_component(date_input, component='year', output_format='integer', time_zone='UTC', error_handling='strict'):
    from datetime import datetime
    import pytz

    # Define a helper function to handle errors
    def handle_error(message):
        if error_handling == 'strict':
            raise ValueError(message)
        elif error_handling == 'lenient':
            return None

    # Attempt to parse the date_input
    try:
        # Assume date_input is in ISO 8601 format for simplicity
        date_obj = datetime.fromisoformat(date_input)
    except ValueError:
        return handle_error('Invalid date format')

    # Adjust for time zone if necessary
    if time_zone != 'UTC':
        try:
            tz = pytz.timezone(time_zone)
            date_obj = date_obj.astimezone(tz)
        except pytz.UnknownTimeZoneError:
            return handle_error('Unknown time zone')

    # Extract the requested component
    component_value = None
    if component == 'year':
        component_value = date_obj.year
    elif component == 'month':
        component_value = date_obj.month
    elif component == 'day':
        component_value = date_obj.day
    elif component == 'hour':
        component_value = date_obj.hour
    elif component == 'minute':
        component_value = date_obj.minute
    elif component == 'second':
        component_value = date_obj.second

    # Format the output
    if output_format == 'string':
        component_value = str(component_value)
    elif output_format == 'timestamp':
        component_value = date_obj.timestamp()

    return component_value

