def name_length_counter(name, ignore_characters=[], ignore_position=[], case_sensitive=False, character_type='all', output_format='integer'):
    # Validate required parameter
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}

    # Initialize variables
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Adjust for case sensitivity
    if not case_sensitive:
        name = name.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Apply ignore positions
    if 'first' in ignore_position and len(name) > 0:
        name = name[1:]
    if 'last' in ignore_position and len(name) > 0:
        name = name[:-1]

    # Filter out ignored characters
    name = ''.join([char for char in name if char not in ignore_characters])

    # Count characters based on type
    if character_type == 'vowels':
        count = sum(1 for char in name if char in vowels)
    elif character_type == 'consonants':
        count = sum(1 for char in name if char in consonants)
    else:
        count = len(name)

    # Format output
    if output_format == 'text':
        return f'The name "{name}" has {count} letters.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for char in name if char in vowels)
        consonant_count = sum(1 for char in name if char in consonants)
        return {
            'total': count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }
    else:  # Default to integer
        return count

