from datetime import datetime, timedelta
from dateutil.relativedelta import relativedelta
import pytz

# Function to calculate the new date based on the given parameters
def date_calculator(start_date: str, months_to_add: int, days_to_add: int = 0, years_to_add: int = 0, output_format: str = 'YYYY-MM-DD', business_days_only: bool = False, holiday_list: list = None, time_zone: str = 'UTC') -> str:
    try:
        # Parse the start date
        date = datetime.strptime(start_date, '%Y-%m-%d')

        # Adjust for time zone
        tz = pytz.timezone(time_zone)
        date = tz.localize(date)

        # Add years, months, and days
        date += relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)

        # If business days only, adjust for weekends and holidays
        if business_days_only:
            while date.weekday() >= 5 or (holiday_list and date.strftime('%Y-%m-%d') in holiday_list):
                date += timedelta(days=1)

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            return date.strftime('%Y-%m-%d')
        elif output_format == 'MM-DD-YYYY':
            return date.strftime('%m-%d-%Y')
        elif output_format == 'DD-MM-YYYY':
            return date.strftime('%d-%m-%Y')
        else:
            raise ValueError('Invalid output format specified.')
    except Exception as e:
        return f'Error: {str(e)}'

