def extract_year(date_input: str, date_format: str = None, error_handling: str = 'strict', timezone: str = 'UTC', output_format: str = 'year') -> str:
    """
    Extracts the year from a given date string.

    Parameters:
    - date_input (str): The date string from which the year needs to be extracted.
    - date_format (str, optional): The format of the input date string, if known.
    - error_handling (str, optional): The error handling strategy for invalid dates.
    - timezone (str, optional): The timezone of the input date string.
    - output_format (str, optional): The format of the output.

    Returns:
    - str: The extracted year or full date string based on the output format.
    """
    from datetime import datetime
    import pytz

    try:
        # Parse the date with the given format or auto-detect
        if date_format:
            date_obj = datetime.strptime(date_input, date_format)
        else:
            date_obj = datetime.fromisoformat(date_input)

        # Adjust for timezone
        if timezone:
            tz = pytz.timezone(timezone)
            date_obj = date_obj.astimezone(tz)

        # Extract year
        year = date_obj.year

        # Return based on output format
        if output_format == 'year':
            return str(year)
        elif output_format == 'full_date':
            return date_obj.strftime('%Y-%m-%d')

    except ValueError as e:
        if error_handling == 'strict':
            raise ValueError(f"Invalid date input: {e}")
        elif error_handling == 'lenient':
            return 'Unknown'
        elif error_handling == 'default_year':
            return '1900'

    return 'Error: Invalid parameters'

