def extract_first_name(full_name, delimiter=' ', ignore_prefixes=True, ignore_suffixes=True, handle_middle_names=False, initial_handling='ignore'):
    # Define common prefixes and suffixes to ignore
    prefixes = ['Mr.', 'Mrs.', 'Ms.', 'Dr.'] if ignore_prefixes else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if ignore_suffixes else []

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle initials based on the initial_handling parameter
    if initial_handling == 'ignore':
        name_parts = [part for part in name_parts if len(part) > 1]
    elif initial_handling == 'extract':
        name_parts = [part[0] for part in name_parts if len(part) == 1]
    elif initial_handling == 'include':
        pass  # Include initials as they are

    # Extract the first name
    first_name = name_parts[0] if name_parts else ''

    # Error handling for empty or invalid input
    if not full_name:
        return {'error': 'Full name is required.'}
    if not isinstance(full_name, str):
        return {'error': 'Full name must be a string.'}

    return first_name

