def extract_first_letter(input: str, case_sensitive: bool = True, handle_empty: str = 'error', default_character: str = '', ignore_whitespace: bool = False, character_set: str = '', error_message: str = 'Invalid input') -> str:
    # Validate input
    if not isinstance(input, str):
        raise ValueError(error_message)
    if handle_empty not in ['error', 'empty', 'default']:
        raise ValueError('Invalid handle_empty option')
    if handle_empty == 'default' and (not isinstance(default_character, str) or len(default_character) != 1):
        raise ValueError('default_character must be a single character')

    # Handle empty input
    if not input:
        if handle_empty == 'error':
            raise ValueError(error_message)
        elif handle_empty == 'empty':
            return ''
        elif handle_empty == 'default':
            return default_character

    # Ignore leading whitespace if specified
    if ignore_whitespace:
        input = input.lstrip()

    # Extract first letter based on character set
    for char in input:
        if character_set and char not in character_set:
            continue
        if case_sensitive:
            return char
        else:
            return char.lower()

    # If no valid character is found
    if handle_empty == 'default':
        return default_character
    raise ValueError(error_message)

