def extract_last_name(full_name: str, name_format: str = 'western', custom_delimiter: str = None, case_sensitive: bool = False, handle_middle_names: bool = False, fallback_format: str = 'western') -> str:
    """
    Extracts the last name from a full name string based on the specified cultural convention and options.
    """
    if not full_name:
        raise ValueError('The full_name parameter is required.')

    # Determine the delimiter to use
    delimiter = custom_delimiter if custom_delimiter else ' '

    # Split the full name using the determined delimiter
    name_parts = full_name.split(delimiter)

    # Handle different name formats
    if name_format == 'western':
        # Western format assumes the last part is the last name
        last_name = name_parts[-1]
    elif name_format == 'eastern':
        # Eastern format assumes the first part is the last name
        last_name = name_parts[0]
    else:
        # Use fallback format if the specified format is not recognized
        if fallback_format == 'western':
            last_name = name_parts[-1]
        elif fallback_format == 'eastern':
            last_name = name_parts[0]
        else:
            raise ValueError('Unsupported name format and fallback format.')

    # Handle case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    # Return the extracted last name
    return last_name

