    # Consider weekdays and exclude holidays if specified
    if consider_weekdays or exclude_holidays:
        while start_date.weekday() >= 5 or start_date.strftime('%Y-%m-%d') in exclude_holidays:
            if consider_weekdays and start_date.weekday() >= 5:
                start_date += timedelta(days=1)
            if start_date.strftime('%Y-%m-%d') in exclude_holidays:
                start_date += timedelta(days=1)

    return {'result': start_date.strftime('%Y-%m-%d')}

