def year_calculator(year, calendar_system='gregorian', output_format='integer', include_leap_year_info=False):
    """
    Calculate the year before the given year based on the specified calendar system.

    Parameters:
    year (int): The year for which the preceding year is to be calculated.
    calendar_system (str): The calendar system to use for the calculation.
    output_format (str): The format of the output.
    include_leap_year_info (bool): Whether to include leap year information.

    Returns:
    The preceding year in the specified format.
    """
    # Error handling for invalid inputs
    if not isinstance(year, int):
        return {'error': 'Invalid input: year must be an integer.'}
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': f'Invalid calendar system: {calendar_system} is not supported.'}
    if output_format not in ['integer', 'string', 'detailed']:
        return {'error': f'Invalid output format: {output_format} is not supported.'}

    # Calculate the preceding year
    preceding_year = year - 1

    # Determine if the preceding year is a leap year (simplified for Gregorian calendar)
    is_leap_year = False
    if calendar_system == 'gregorian':
        if (preceding_year % 4 == 0 and preceding_year % 100 != 0) or (preceding_year % 400 == 0):
            is_leap_year = True

    # Prepare the output based on the specified format
    if output_format == 'integer':
        return preceding_year
    elif output_format == 'string':
        return str(preceding_year)
    elif output_format == 'detailed':
        details = {
            'year': preceding_year,
            'is_leap_year': is_leap_year if include_leap_year_info else None,
            'first_day_of_week': 'Monday'  # Placeholder for demonstration
        }
        return details

