def count_repeated_letters(input: str, ignore_case: bool = False, ignore_characters: list = [], min_repetitions: int = 2, count_sequences: bool = False, detailed_count: bool = False):
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_case, bool):
        return {'error': 'ignore_case must be a boolean.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'ignore_characters must be a list of strings.'}
    if not isinstance(min_repetitions, int) or min_repetitions < 1:
        return {'error': 'min_repetitions must be a positive integer.'}
    if not isinstance(count_sequences, bool):
        return {'error': 'count_sequences must be a boolean.'}
    if not isinstance(detailed_count, bool):
        return {'error': 'detailed_count must be a boolean.'}

    # Normalize case if ignore_case is True
    if ignore_case:
        input = input.lower()

    # Remove ignored characters
    for char in ignore_characters:
        input = input.replace(char, '')

    # Count repeated letters or sequences
    from collections import Counter
    if count_sequences:
        # Count sequences
        sequences = [input[i:i+min_repetitions] for i in range(len(input) - min_repetitions + 1)]
        counts = Counter(sequences)
    else:
        # Count individual letters
        counts = Counter(input)

    # Filter counts based on min_repetitions
    repeated_counts = {k: v for k, v in counts.items() if v >= min_repetitions}

    # Prepare the result
    if detailed_count:
        return {'detailed_counts': repeated_counts}
    else:
        return {'total_repeated': len(repeated_counts)}

# Example usage based on the question
