def find_closest_palindrome(number, direction='both', max_iterations=1000, min_range=0, max_range=None, return_all=False):
    """
    Finds the closest palindrome number to a given integer.

    Parameters:
    - number (int): The integer for which the closest palindrome number is to be found.
    - direction (str): The direction in which to search for the palindrome ('both', 'higher', 'lower').
    - max_iterations (int): The maximum number of iterations to perform in each direction.
    - min_range (int): The minimum range from the given number to start searching for a palindrome.
    - max_range (int): The maximum range from the given number to search for a palindrome.
    - return_all (bool): If true, returns all palindromes found within the specified range.

    Returns:
    - int or list: The closest palindrome or a list of palindromes if return_all is True.
    """
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    if not isinstance(number, int):
        raise ValueError("'number' must be an integer.")
    if direction not in ['both', 'higher', 'lower']:
        raise ValueError("'direction' must be one of 'both', 'higher', 'lower'.")
    if not isinstance(max_iterations, int) or max_iterations <= 0:
        raise ValueError("'max_iterations' must be a positive integer.")
    if not isinstance(min_range, int) or min_range < 0:
        raise ValueError("'min_range' must be a non-negative integer.")
    if max_range is not None and (not isinstance(max_range, int) or max_range < min_range):
        raise ValueError("'max_range' must be an integer greater than or equal to 'min_range'.")

    closest_palindrome = None
    palindromes = []
    range_limit = max_range if max_range is not None else max_iterations

    # Search in both directions
    for i in range(min_range, range_limit + 1):
        if direction in ['both', 'higher']:
            higher_candidate = number + i
            if is_palindrome(higher_candidate):
                palindromes.append(higher_candidate)
                if closest_palindrome is None:
                    closest_palindrome = higher_candidate

        if direction in ['both', 'lower']:
            lower_candidate = number - i
            if lower_candidate >= 0 and is_palindrome(lower_candidate):
                palindromes.append(lower_candidate)
                if closest_palindrome is None:
                    closest_palindrome = lower_candidate

        if closest_palindrome is not None and not return_all:
            break

    if return_all:
        return sorted(palindromes)
    return closest_palindrome

