def extract_first_name(full_name, ignore_titles=False, ignore_suffixes=False, output_format='string', handle_middle_names=False, nickname_handling='ignore', cultural_format='western'):
    """
    Extracts the first name from a full name string based on various parameters.
    """
    import re

    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Error handling for parameter types
    if not isinstance(ignore_titles, bool) or not isinstance(ignore_suffixes, bool) or not isinstance(handle_middle_names, bool):
        return {'error': 'Invalid input: ignore_titles, ignore_suffixes, and handle_middle_names must be boolean.'}

    if output_format not in ['string', 'array', 'object']:
        return {'error': 'Invalid input: output_format must be one of ["string", "array", "object"].'}

    if nickname_handling not in ['ignore', 'include', 'replace']:
        return {'error': 'Invalid input: nickname_handling must be one of ["ignore", "include", "replace"].'}

    if cultural_format not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid input: cultural_format must be one of ["western", "eastern", "custom"].'}

    # Define common titles and suffixes
    titles = ['Mr.', 'Ms.', 'Mrs.', 'Dr.']
    suffixes = ['Jr.', 'Sr.', 'III']

    # Remove titles if ignore_titles is True
    if ignore_titles:
        for title in titles:
            full_name = re.sub(rf'\b{title}\b', '', full_name)

    # Remove suffixes if ignore_suffixes is True
    if ignore_suffixes:
        for suffix in suffixes:
            full_name = re.sub(rf'\b{suffix}\b', '', full_name)

    # Split the name based on spaces
    name_parts = full_name.split()

    # Handle cultural format
    if cultural_format == 'eastern':
        name_parts.reverse()

    # Handle nickname
    if nickname_handling == 'replace':
        for part in name_parts:
            if part.startswith('"') and part.endswith('"'):
                return part.strip('"')

    # Extract first name
    first_name = name_parts[0] if name_parts else ''

    # Handle middle names
    if handle_middle_names and len(name_parts) > 1:
        first_name = ' '.join(name_parts[:2])

    # Prepare output
    if output_format == 'string':
        return first_name
    elif output_format == 'array':
        return [first_name]
    elif output_format == 'object':
        return {
            'first_name': first_name,
            'metadata': {
                'original_name': full_name,
                'cultural_format': cultural_format,
                'nickname_handling': nickname_handling
            }
        }

    return {'error': 'Unexpected error occurred.'}

