def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', ignore_characters: str = '', consecutive_only: bool = False):
    # Validate output_format
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of integer, list, detailed.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = ignore_characters.lower()

    # Remove ignored characters
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Initialize variables for counting
    letter_count = {}
    repeated_letters = set()

    # Iterate over the string to count repetitions
    for i, char in enumerate(filtered_input):
        if char.isalpha():
            if char in letter_count:
                if consecutive_only and i > 0 and filtered_input[i-1] != char:
                    continue
                letter_count[char] += 1
                repeated_letters.add(char)
            else:
                letter_count[char] = 1

    # Prepare the output based on the requested format
    if output_format == 'integer':
        return len(repeated_letters)
    elif output_format == 'list':
        return list(repeated_letters)
    elif output_format == 'detailed':
        detailed_report = {char: {'count': count, 'positions': [i for i, c in enumerate(filtered_input) if c == char]} for char, count in letter_count.items() if count > 1}
        return detailed_report

