def extract_last_digit(number, output_format='integer', digits_count=1, handle_negative=False):
    """
    Extract the last digit(s) of a given number based on the specified parameters.

    :param number: The number from which to extract the last digit(s).
    :param output_format: The format of the output ('integer', 'string', 'list').
    :param digits_count: The number of last digits to extract.
    :param handle_negative: Whether to consider the sign of the number.
    :return: The last digit(s) in the specified format.
    """
    # Error handling for invalid inputs
    if not isinstance(number, (int, float)):
        return {'error': 'Invalid input: number must be an integer or float.'}
    if output_format not in ['integer', 'string', 'list']:
        return {'error': 'Invalid output_format: must be one of ["integer", "string", "list"].'}
    if not isinstance(digits_count, int) or digits_count < 1:
        return {'error': 'Invalid digits_count: must be an integer greater than or equal to 1.'}

    # Handle negative numbers if specified
    if not handle_negative:
        number = abs(number)

    # Convert number to string to easily extract digits
    number_str = str(number)
    if '.' in number_str:
        number_str = number_str.split('.')[0]  # Remove decimal part

    # Extract the last 'digits_count' digits
    last_digits = number_str[-digits_count:]

    # Format the output based on 'output_format'
    if output_format == 'integer':
        return int(last_digits)
    elif output_format == 'string':
        return last_digits
    elif output_format == 'list':
        return list(last_digits)

