def find_closest_palindrome(number, return_both_if_tie=False, search_range=None, detailed_output=False):
    import math

    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    if not isinstance(number, int):
        return {'error': 'Invalid input: number must be an integer.'}

    if search_range:
        if not isinstance(search_range, dict) or 'min' not in search_range or 'max' not in search_range:
            return {'error': 'Invalid search_range: must be a dictionary with min and max keys.'}
        min_range = search_range['min']
        max_range = search_range['max']
    else:
        min_range = number - 100
        max_range = number + 100

    closest_palindrome = None
    closest_distance = math.inf
    tie_palindrome = None

    for i in range(min_range, max_range + 1):
        if is_palindrome(i):
            distance = abs(number - i)
            if distance < closest_distance:
                closest_palindrome = i
                closest_distance = distance
                tie_palindrome = None
            elif distance == closest_distance and return_both_if_tie:
                tie_palindrome = i

    if tie_palindrome and return_both_if_tie:
        result = (closest_palindrome, tie_palindrome)
    else:
        result = closest_palindrome

    if detailed_output:
        return {'palindrome': result, 'distance': closest_distance}
    else:
        return result

