def count_repeated_letters(input: str, case_sensitive: bool = False, ignore_characters: list = [], min_repetition: int = 2, output_format: str = 'count') -> int:
    # Validate input parameters
    if not isinstance(input, str):
        raise ValueError('Input must be a string.')
    if not isinstance(case_sensitive, bool):
        raise ValueError('case_sensitive must be a boolean.')
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        raise ValueError('ignore_characters must be a list of strings.')
    if not isinstance(min_repetition, int) or min_repetition < 1:
        raise ValueError('min_repetition must be a positive integer.')
    if output_format not in ['count', 'list']:
        raise ValueError("output_format must be either 'count' or 'list'.")

    # Prepare the input string
    if not case_sensitive:
        input = input.lower()
    for char in ignore_characters:
        input = input.replace(char, '')

    # Count character occurrences
    from collections import Counter
    char_count = Counter(input)

    # Filter characters based on min_repetition
    repeated_chars = {char: count for char, count in char_count.items() if count >= min_repetition}

    # Return result based on output_format
    if output_format == 'count':
        return len(repeated_chars)
    elif output_format == 'list':
        return list(repeated_chars.keys())

