def distinct_two_letter_combinations(input_string, case_sensitive=True, include_non_alphabetic=False, output_delimiter=',', max_combinations=None):
    # Validate input
    if not isinstance(input_string, str) or len(input_string) < 2:
        return 'Error: Input string must be at least 2 characters long.'
    if not isinstance(case_sensitive, bool) or not isinstance(include_non_alphabetic, bool):
        return 'Error: Boolean parameters must be of type bool.'
    if not isinstance(output_delimiter, str):
        return 'Error: Output delimiter must be a string.'
    if max_combinations is not None and not isinstance(max_combinations, int):
        return 'Error: Max combinations must be an integer or None.'

    # Prepare the string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Generate combinations
    combinations = set()
    for i in range(len(input_string) - 1):
        for j in range(i + 1, len(input_string)):
            pair = input_string[i] + input_string[j]
            if include_non_alphabetic or pair.isalpha():
                combinations.add(pair)

    # Convert set to list and apply max_combinations limit
    combinations = list(combinations)
    if max_combinations is not None:
        combinations = combinations[:max_combinations]

    # Join combinations with the specified delimiter
    result = output_delimiter.join(combinations)
    return result

