    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import re

    # Helper function to parse date based on the given format
    def parse_date(date_str, date_format):
        try:
            if date_format == 'YYYY-MM-DD':
                return datetime.strptime(date_str, '%Y-%m-%d')
            elif date_format == 'DD-MM-YYYY':
                return datetime.strptime(date_str, '%d-%m-%Y')
            elif date_format == 'MM/DD/YYYY':
                return datetime.strptime(date_str, '%m/%d/%Y')
        except ValueError:
            raise ValueError(f"Date '{date_str}' does not match format '{date_format}'")

    # Parse the start date
    try:
        start_date_parsed = parse_date(start_date, date_format)
    except ValueError as e:
        return str(e)

    # Calculate the new date by adding years, months, and days
    new_date = start_date_parsed + relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)

    # Format the output based on the output_format
    if output_format == 'date':
        return new_date.strftime('%Y-%m-%d')
