def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DD', calendar_system='gregorian', output_format='integer', time_zone='UTC', business_days_only=False):
    from datetime import datetime, timedelta
    import pytz

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system.'}

    # Error handling for date format
    try:
        start_dt = datetime.strptime(start_date, '%Y-%m-%d')
        end_dt = datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Adjust for time zone
    if time_zone != 'UTC':
        try:
            tz = pytz.timezone(time_zone)
            start_dt = tz.localize(start_dt)
            end_dt = tz.localize(end_dt)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown time zone.'}

    # Calculate the difference in days
    delta = end_dt - start_dt
    days_difference = delta.days

    # Calculate business days only if required
    if business_days_only:
        business_days = 0
        for single_date in (start_dt + timedelta(n) for n in range(days_difference)):
            if single_date.weekday() < 5:  # Monday to Friday are 0-4
                business_days += 1
        days_difference = business_days

    # Format the output
    if output_format == 'text':
        return {'result': f'The number of days between {start_date} and {end_date} is {days_difference} days.'}
    elif output_format == 'detailed':
        return {'result': {'days': days_difference, 'start_date': start_date, 'end_date': end_date, 'calendar_system': calendar_system}}
    else:  # Default to integer
        return {'result': days_difference}

