def vowel_counter(input: str, case_sensitive: bool = False, output_format: str = 'integer', specific_vowels: list = [], exclude_characters: str = '') -> str:
    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return 'Error: Invalid output format specified.'

    # Define vowels based on case sensitivity
    vowels = 'aeiouAEIOU' if case_sensitive else 'aeiou'

    # Filter specific vowels if provided
    if specific_vowels:
        vowels = ''.join([v for v in vowels if v in specific_vowels])

    # Initialize count dictionary for detailed output
    vowel_count = {v: 0 for v in vowels}

    # Count vowels
    count = 0
    for char in input:
        if char in exclude_characters:
            continue
        if char in vowels:
            count += 1
            vowel_count[char] += 1

    # Return based on output format
    if output_format == 'integer':
        return str(count)
    elif output_format == 'text':
        return f'There are {count} vowels in the input.'
    elif output_format == 'detailed':
        return str(vowel_count)

