def count_repeated_letters(input, case_sensitive=False, output_format='integer', include_characters=None, exclude_characters=None, min_repetition=2):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': 'Invalid output_format. Choose from integer, list, or detailed.'}
    if include_characters and not isinstance(include_characters, str):
        return {'error': 'include_characters must be a string.'}
    if exclude_characters and not isinstance(exclude_characters, str):
        return {'error': 'exclude_characters must be a string.'}
    if not isinstance(min_repetition, int) or min_repetition < 1:
        return {'error': 'min_repetition must be a positive integer.'}

    # Normalize case if case_sensitive is False
    if not case_sensitive:
        input = input.lower()

    # Initialize character count dictionary
    char_count = {}
    for char in input:
        if include_characters and char not in include_characters:
            continue
        if exclude_characters and char in exclude_characters:
            continue
        if char.isalpha():  # Consider only alphabetic characters
            char_count[char] = char_count.get(char, 0) + 1

    # Filter characters based on min_repetition
    repeated_chars = {char: count for char, count in char_count.items() if count >= min_repetition}

    # Prepare output based on output_format
    if output_format == 'integer':
        return len(repeated_chars)
    elif output_format == 'list':
        return list(repeated_chars.keys())
    elif output_format == 'detailed':
        return repeated_chars

