def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DD', calendar_system='Gregorian', output_format='integer', time_zone='UTC', business_days_only=False):
    from datetime import datetime
    from dateutil import parser
    import pytz

    # Error handling for unsupported calendar systems
    if calendar_system not in ['Gregorian', 'Julian', 'Hebrew', 'Islamic']:
        return {'error': 'Unsupported calendar system'}

    # Error handling for unsupported date formats
    if date_format not in ['YYYY-MM-DD', 'DD/MM/YYYY', 'MM-DD-YYYY', 'DD-MM-YYYY']:
        return {'error': 'Unsupported date format'}

    # Parse the dates according to the specified format
    try:
        if date_format == 'YYYY-MM-DD':
            start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
            end_date_obj = datetime.strptime(end_date, '%Y-%m-%d')
        elif date_format == 'DD/MM/YYYY':
            start_date_obj = datetime.strptime(start_date, '%d/%m/%Y')
            end_date_obj = datetime.strptime(end_date, '%d/%m/%Y')
        elif date_format == 'MM-DD-YYYY':
            start_date_obj = datetime.strptime(start_date, '%m-%d-%Y')
            end_date_obj = datetime.strptime(end_date, '%m-%d-%Y')
        elif date_format == 'DD-MM-YYYY':
            start_date_obj = datetime.strptime(start_date, '%d-%m-%Y')
            end_date_obj = datetime.strptime(end_date, '%d-%m-%Y')
    except ValueError:
        return {'error': 'Invalid date format'}

    # Adjust for time zone if necessary
    if time_zone != 'UTC':
        try:
            tz = pytz.timezone(time_zone)
            start_date_obj = tz.localize(start_date_obj)
            end_date_obj = tz.localize(end_date_obj)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown time zone'}

    # Calculate the difference in days
    delta = end_date_obj - start_date_obj
    total_days = delta.days

    # If business days only, adjust the count
    if business_days_only:
        from numpy import busday_count
        total_days = busday_count(start_date_obj.date(), end_date_obj.date())

    # Return the result in the specified output format
    if output_format == 'integer':
        return {'days': total_days}
    elif output_format == 'text':
        return {'days': f'The number of days is {total_days}'}
    elif output_format == 'detailed':
        years = total_days // 365
        months = (total_days % 365) // 30
        days = (total_days % 365) % 30
        return {'years': years, 'months': months, 'days': days}

    return {'error': 'Unsupported output format'}

