def date_calculator(input_date: str, years_to_add: int = 0, months_to_add: int = 0, days_to_add: int = 0, hours_to_add: int = 0, minutes_to_add: int = 0, seconds_to_add: int = 0, output_format: str = 'YYYY-MM-DDTHH:MM:SSZ', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    try:
        # Parse the input date
        date = datetime.strptime(input_date, '%Y-%m-%dT%H:%M:%SZ')

        # Adjust for the time zone
        timezone = pytz.timezone(time_zone)
        date = timezone.localize(date)

        # Add the specified time increments
        date += relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)
        date += timedelta(hours=hours_to_add, minutes=minutes_to_add, seconds=seconds_to_add)

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            return date.strftime('%Y-%m-%d')
        elif output_format == 'DD-MM-YYYY':
            return date.strftime('%d-%m-%Y')
        elif output_format == 'MM-DD-YYYY':
            return date.strftime('%m-%d-%Y')
        elif output_format == 'YYYY-MM-DDTHH:MM:SSZ':
            return date.strftime('%Y-%m-%dT%H:%M:%SZ')
        else:
            raise ValueError('Invalid output format specified.')

    except Exception as e:
        return f'Error: {str(e)}'

