def extract_first_name(full_name, ignore_special_characters=False, case_sensitive=True, include_middle_name=False, handle_prefix_suffix=False, cultural_format='Western'):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Handle special characters if needed
    if ignore_special_characters:
        import re
        full_name = re.sub(r'[^\w\s]', '', full_name)

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefix and suffix if specified
    if handle_prefix_suffix:
        # Example logic to remove common prefixes and suffixes
        prefixes = ['Dr.', 'Mr.', 'Ms.', 'Mrs.']
        suffixes = ['Jr.', 'Sr.', 'II', 'III']
        if name_parts[0] in prefixes:
            name_parts = name_parts[1:]
        if name_parts[-1] in suffixes:
            name_parts = name_parts[:-1]

    # Extract first name based on cultural format
    if cultural_format == 'Western':
        first_name = name_parts[0]
    else:
        # Default to Western if unknown format
        first_name = name_parts[0]

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + name_parts[1]

    # Return the first name, considering case sensitivity
    if not case_sensitive:
        first_name = first_name.lower()

    return {'first_name': first_name}

