def string_length_calculator_v2(input, ignore_characters=[], ignore_position=[], case_sensitive=False, alphabetic_only=False, output_format='integer'):
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Initialize count
    count = 0

    # Convert input to lowercase if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Define positions to ignore
    positions_to_ignore = []
    if 'first' in ignore_position:
        positions_to_ignore.append(0)
    if 'last' in ignore_position:
        positions_to_ignore.append(len(input) - 1)

    # Iterate over each character in the input string
    for i, char in enumerate(input):
        # Skip ignored positions
        if i in positions_to_ignore:
            continue

        # Skip ignored characters
        if char in ignore_characters:
            continue

        # Check if alphabetic_only is True and skip non-alphabetic characters
        if alphabetic_only and not char.isalpha():
            continue

        # Increment count
        count += 1

    # Return the result based on the output_format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The total number of letters is {count}.'
    elif output_format == 'detailed':
        return {
            'total_count': count,
            'details': {
                'input_length': len(input),
                'ignored_characters': ignore_characters,
                'ignored_positions': ignore_position,
                'case_sensitive': case_sensitive,
                'alphabetic_only': alphabetic_only
            }
        }
    else:
        return {'error': 'Invalid output format specified.'}

