    import pytz
    import calendar
    from babel.dates import format_date

    # Error handling for date format
    try:
        # Attempt to parse the date in various formats
        date_obj = None
        for fmt in ('%Y-%m-%d', '%d-%m-%Y', '%B %d, %Y', '%m/%d/%Y'):
            try:
                date_obj = datetime.strptime(date, fmt)
                break
            except ValueError:
                continue
        if date_obj is None:
            raise ValueError('Date format not recognized.')
    except Exception as e:
        return {'error': str(e)}

    # Error handling for calendar system
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system.'}

    # Error handling for output format
    if output_format not in ['full', 'abbreviated', 'numeric']:
        return {'error': 'Invalid output format.'}

    # Error handling for timezone
    try:
        timezone_obj = pytz.timezone(timezone)
        date_obj = timezone_obj.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown timezone.'}

    # Calculate the day of the week
    day_of_week = date_obj.weekday()  # Monday is 0 and Sunday is 6

    # Format the output
    if output_format == 'full':
        day_name = format_date(date_obj, 'EEEE', locale=localization)
    elif output_format == 'abbreviated':
        day_name = format_date(date_obj, 'EEE', locale=localization)
    elif output_format == 'numeric':
