def string_length_counter(input: str, ignore_spaces: bool = False, ignore_special_characters: bool = False, ignore_digits: bool = False, ignore_user_defined: str = '', detailed_breakdown: bool = False):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize counters
    letter_count = 0
    digit_count = 0
    special_character_count = 0

    # Define helper functions
    def is_letter(char):
        return char.isalpha()

    def is_digit(char):
        return char.isdigit()

    def is_special_character(char):
        return not char.isalnum() and not char.isspace()

    # Iterate over each character in the input string
    for char in input:
        if ignore_spaces and char.isspace():
            continue
        if ignore_special_characters and is_special_character(char):
            continue
        if ignore_digits and is_digit(char):
            continue
        if char in ignore_user_defined:
            continue

        # Count letters
        if is_letter(char):
            letter_count += 1
        elif is_digit(char):
            digit_count += 1
        elif is_special_character(char):
            special_character_count += 1

    # Prepare the result
    if detailed_breakdown:
        return {
            'letters': letter_count,
            'digits': digit_count,
            'special_characters': special_character_count
        }
    else:
        return {'letters': letter_count}

