def reverse_string(input: str, case_transformation: str = 'none', reverse_scope: str = 'full', trim_whitespace: bool = False, prefix: str = '', suffix: str = '') -> str:
    # Error handling for parameter types and values
    if not isinstance(input, str):
        return 'Error: Input must be a string.'
    if case_transformation not in ['none', 'uppercase', 'lowercase']:
        return 'Error: Invalid case_transformation value.'
    if reverse_scope not in ['full', 'words', 'characters']:
        return 'Error: Invalid reverse_scope value.'
    if not isinstance(trim_whitespace, bool):
        return 'Error: trim_whitespace must be a boolean.'

    # Trim whitespace if required
    if trim_whitespace:
        input = input.strip()

    # Reverse logic based on reverse_scope
    if reverse_scope == 'full':
        reversed_string = input[::-1]
    elif reverse_scope == 'words':
        reversed_string = ' '.join(input.split()[::-1])
    elif reverse_scope == 'characters':
        reversed_string = ' '.join(word[::-1] for word in input.split())

    # Apply case transformation
    if case_transformation == 'uppercase':
        reversed_string = reversed_string.upper()
    elif case_transformation == 'lowercase':
        reversed_string = reversed_string.lower()

    # Add prefix and suffix
    result = f'{prefix}{reversed_string}{suffix}'

    return result

