    if component not in ['first', 'middle', 'last', 'prefix', 'suffix']:
        raise ValueError('Invalid component: must be one of "first", "middle", "last", "prefix", or "suffix".')

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.lower() for part in name_parts]
        component = component.lower()

    # Extract the desired component
    if component == 'first':
        return name_parts[0] if name_parts else ''
    elif component == 'middle':
        if len(name_parts) > 2:
            return delimiter.join(name_parts[1:-1]) if handle_multiple_middle_names else name_parts[1]
        return ''
    elif component == 'last':
        return name_parts[-1] if len(name_parts) > 1 else ''
    elif component == 'prefix':
        # Assuming prefix is the first part if it exists
        return name_parts[0] if len(name_parts) > 2 else ''
    elif component == 'suffix':
        # Assuming suffix is the last part if it exists
        return name_parts[-1] if len(name_parts) > 2 else ''

