def reverse_string_advanced(input, output_format='string', case_sensitive=True, filter_characters=None, delimiter=None):
    """
    Reverses the order of characters in the input string with options for output format,
    case sensitivity, character filtering, and delimiter-based splitting.
    """
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Expected a string.'}
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid output format. Supported formats are string, array, json.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Expected a boolean.'}
    if filter_characters is not None:
        if not all(isinstance(char, str) and len(char) == 1 for char in filter_characters):
            return {'error': 'Invalid filter_characters. Expected an array of single-character strings.'}
    if delimiter is not None and not isinstance(delimiter, str):
        return {'error': 'Invalid delimiter type. Expected a string.'}

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter characters
    if filter_characters:
        input = ''.join(char for char in input if char not in filter_characters)

    # Split by delimiter if provided
    if delimiter:
        parts = input.split(delimiter)
        reversed_parts = [part[::-1] for part in parts]
        reversed_string = delimiter.join(reversed_parts)
    else:
        reversed_string = input[::-1]

    # Format output
    if output_format == 'string':
        return reversed_string
    elif output_format == 'array':
        return list(reversed_string)
    elif output_format == 'json':
        return {'reversed': reversed_string}

