def closest_palindrome_finder(input_number, direction='either', output_format='integer', search_range=None, return_multiple=False, ignore_digits=None):
    """
    Find the closest palindrome number to a given integer.

    Parameters:
    - input_number (int): The integer number for which the closest palindrome is to be found.
    - direction (str): The direction in which to search for the closest palindrome. Defaults to 'either'.
    - output_format (str): The format of the output. Defaults to integer (the palindrome number).
    - search_range (dict): Optional parameter to specify a range within which to search for the closest palindrome.
    - return_multiple (bool): If true, returns all closest palindromes if they exist at the same distance. Defaults to false.
    - ignore_digits (list): An optional list of digits to ignore in the input number when searching for palindromes.

    Returns:
    - The closest palindrome number(s) based on the specified parameters.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    def next_palindrome(num, direction):
        if direction == 'above':
            num += 1
            while not is_palindrome(num):
                num += 1
        elif direction == 'below':
            num -= 1
            while not is_palindrome(num):
                num -= 1
        else:  # either
            above = num + 1
            below = num - 1
            while True:
                if is_palindrome(below):
                    return below
                if is_palindrome(above):
                    return above
                below -= 1
                above += 1
        return num

    if not isinstance(input_number, int):
        return {'error': 'input_number must be an integer'}

    if direction not in ['above', 'below', 'either']:
        return {'error': 'Invalid direction value'}

    if search_range:
        min_range = search_range.get('min', float('-inf'))
        max_range = search_range.get('max', float('inf'))
    else:
        min_range = float('-inf')
        max_range = float('inf')

    if ignore_digits:
        input_number = int(''.join([d for d in str(input_number) if int(d) not in ignore_digits]))

    closest_palindrome = next_palindrome(input_number, direction)

    if closest_palindrome < min_range or closest_palindrome > max_range:
        return {'error': 'No palindrome found within the specified range'}

    if output_format == 'text':
        return f'The closest palindrome to {input_number} is {closest_palindrome}'
    else:
        return closest_palindrome

