    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'
    count = 0

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()
        vowels = vowels.lower()
        consonants = consonants.lower()

    # Apply ignore_position logic
    if ignore_position:
        if 'first' in ignore_position and len(input) > 0:
            input = input[1:]
        if 'last' in ignore_position and len(input) > 0:
            input = input[:-1]

    # Apply ignore_characters logic
    if ignore_characters:
        input = ''.join([char for char in input if char not in ignore_characters])

    # Count characters based on count_type
    for char in input:
        if count_type == 'all':
            count += 1
        elif count_type == 'vowels' and char in vowels:
            count += 1
        elif count_type == 'consonants' and char in consonants:
            count += 1

    # Prepare output in specified formats
    results = {}
    if 'integer' in output_format:
        results['integer'] = count
    if 'text' in output_format:
        results['text'] = f'The count is {count}.'
    if 'json' in output_format:
        results['json'] = {'count': count}

    return results

