def date_calculator(base_date: str, months_offset: int, days_offset: int = 0, hours_offset: int = 0, minutes_offset: int = 0, calendar_system: str = 'gregorian', time_zone: str = 'UTC', output_format: str = 'date') -> str:
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for incorrect input formats
    try:
        base_date_obj = datetime.strptime(base_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return 'Error: Invalid base_date format. Expected YYYY-MM-DDTHH:MM:SS.'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        base_date_obj = tz.localize(base_date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone specified.'

    # Perform date arithmetic
    try:
        new_date_obj = base_date_obj + relativedelta(months=months_offset, days=days_offset, hours=hours_offset, minutes=minutes_offset)
    except Exception as e:
        return f'Error: {str(e)}'

    # Format output
    if output_format == 'date':
        return new_date_obj.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'text':
        return new_date_obj.strftime('%A, %B %d, %Y %H:%M:%S')
    elif output_format == 'timestamp':
        return str(int(new_date_obj.timestamp()))
    else:
        return 'Error: Invalid output format specified.'

