def date_digit_sum(date_input, date_format='DD-MM-YYYY', delimiter='-', output_format='integer', calendar_system='gregorian', time_zone='UTC'):
    """
    Calculate the sum of all digits in the components of a date.

    Parameters:
    - date_input (list of str): The dates to be processed, in string format.
    - date_format (str): The format of the input dates. Defaults to 'DD-MM-YYYY'.
    - delimiter (str): The delimiter used in the date strings. Defaults to '-'.
    - output_format (str): The format of the output. Defaults to 'integer'.
    - calendar_system (str): The calendar system used for the input dates. Defaults to 'gregorian'.
    - time_zone (str): The time zone of the input dates. Defaults to 'UTC'.

    Returns:
    - int or str: The sum of the digits, or a detailed breakdown if specified.
    """
    # Error handling for input validation
    if not isinstance(date_input, list) or len(date_input) < 1 or len(date_input) > 10:
        return "Error: 'date_input' must be a list with 1 to 10 date strings."
    if output_format not in ['integer', 'text', 'detailed']:
        return "Error: 'output_format' must be one of ['integer', 'text', 'detailed']."
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return "Error: 'calendar_system' must be one of ['gregorian', 'julian', 'islamic', 'hebrew']."

    # Function logic to calculate digit sum
    total_sum = 0
    for date_str in date_input:
        # Split the date string based on the delimiter
        components = date_str.split(delimiter)
        # Convert each component to its digit sum
        for component in components:
            for char in component:
                if char.isdigit():
                    total_sum += int(char)

    # Return the result based on the output format
    if output_format == 'integer':
        return total_sum
    elif output_format == 'text':
        return f"The sum of digits is {total_sum}."
    elif output_format == 'detailed':
        return {
            'total_sum': total_sum,
            'details': {comp: sum(int(char) for char in comp if char.isdigit()) for comp in components}
        }

