def timezone_converter(input_datetime: str, source_timezone: str, target_timezone: str = None, target_timezone_offset: float = None, output_format: str = 'ISO', adjust_for_dst: bool = True, handle_leap_seconds: bool = False) -> str:
    import pytz
    from datetime import datetime, timedelta

    try:
        # Parse the input datetime
        if 'T' in input_datetime:
            dt = datetime.fromisoformat(input_datetime)
        else:
            try:
                dt = datetime.strptime(input_datetime, '%d %b %Y, %H:%M')
            except ValueError:
                dt = datetime.fromtimestamp(float(input_datetime))

        # Convert input datetime to UTC
        source_tz = pytz.timezone(source_timezone)
        dt = source_tz.localize(dt, is_dst=adjust_for_dst).astimezone(pytz.utc)

        # Apply target timezone offset if provided
        if target_timezone_offset is not None:
            target_dt = dt + timedelta(hours=target_timezone_offset)
        else:
            target_tz = pytz.timezone(target_timezone)
            target_dt = dt.astimezone(target_tz)

        # Format the output
        if output_format == 'ISO':
            return target_dt.isoformat()
        elif output_format == 'RFC2822':
            return target_dt.strftime('%a, %d %b %Y %H:%M:%S %z')
        elif output_format == 'Unix':
            return str(int(target_dt.timestamp()))
        elif output_format == 'custom':
            return target_dt.strftime('%Y-%m-%d %H:%M:%S')
        else:
            raise ValueError('Unsupported output format')
    except Exception as e:
        return f'Error: {str(e)}'

