def date_digit_sum_enhanced(date, date_format='DD MM YYYY', ignore_non_digits=True, time_included=False, digit_sum_type='all'):
    """
    Calculate the sum of digits in the day, month, and year of a given date.

    Parameters:
    - date (str): The date input in a recognized format.
    - date_format (str): The format of the input date.
    - ignore_non_digits (bool): Whether to ignore non-digit characters.
    - time_included (bool): Whether the input includes time components.
    - digit_sum_type (str): Specifies which digits to sum: all, even, or odd.

    Returns:
    - int: The sum of the specified digits.
    """
    import re
    from datetime import datetime

    # Define a helper function to sum digits based on the type
    def sum_digits(digits, digit_sum_type):
        if digit_sum_type == 'all':
            return sum(digits)
        elif digit_sum_type == 'even':
            return sum(d for d in digits if d % 2 == 0)
        elif digit_sum_type == 'odd':
            return sum(d for d in digits if d % 2 != 0)
        else:
            raise ValueError("Invalid digit_sum_type")

    # Parse the date based on the format
    try:
        if date_format == 'DD MM YYYY':
            parsed_date = datetime.strptime(date, '%d %m %Y')
        elif date_format == 'YYYY-MM-DD':
            parsed_date = datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            parsed_date = datetime.strptime(date, '%m/%d/%Y')
        elif date_format == 'DD-MM-YYYY HH:MM':
            parsed_date = datetime.strptime(date, '%d-%m-%Y %H:%M')
        elif date_format == 'YYYY/MM/DD HH:MM:SS':
            parsed_date = datetime.strptime(date, '%Y/%m/%d %H:%M:%S')
        else:
            raise ValueError("Unsupported date format")
    except ValueError as e:
        return str(e)

    # Extract digits from the date components
    date_str = parsed_date.strftime('%d%m%Y')
    if time_included:
        date_str += parsed_date.strftime('%H%M%S')

    if ignore_non_digits:
        digits = [int(d) for d in re.findall(r'\d', date_str)]
    else:
        digits = [int(d) for d in date_str if d.isdigit()]

    # Calculate the sum of the specified digits
    return sum_digits(digits, digit_sum_type)

