def date_calculator(start_date: str, years: int, months: int = 0, days: int = 0, output_format: str = 'date', calendar_system: str = 'gregorian', time_zone: str = 'UTC') -> str:
    """
    Calculate a new date by adjusting the start_date by a specified number of years, months, and days.
    """
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid date format. Please use YYYY-MM-DD.'

    # Adjust the date
    try:
        adjusted_date = date_obj + relativedelta(years=years, months=months, days=days)
    except Exception as e:
        return f'Error: {str(e)}'

    # Convert to the specified time zone
    try:
        tz = pytz.timezone(time_zone)
        adjusted_date = tz.localize(adjusted_date)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Format the output
    if output_format == 'date':
        return adjusted_date.strftime('%Y-%m-%d')
    elif output_format == 'text':
        return adjusted_date.strftime('%A, %d %B %Y')
    elif output_format == 'timestamp':
        return str(int(adjusted_date.timestamp()))
    elif output_format == 'iso':
        return adjusted_date.isoformat()
    else:
        return 'Error: Unsupported output format.'

