def ascii_lookup(characters, output_format='integer', case_sensitive=True, include_non_printable=False):
    # Validate input parameters
    if not isinstance(characters, list) or not (1 <= len(characters) <= 100):
        return {'error': 'Invalid characters input. Must be a list with 1 to 100 single-character strings.'}
    if output_format not in ['integer', 'hex', 'binary', 'octal', 'unicode']:
        return {'error': 'Invalid output format. Supported formats are integer, hex, binary, octal, unicode.'}

    # Initialize result list
    result = []

    # Process each character
    for char in characters:
        if not isinstance(char, str) or len(char) != 1:
            return {'error': f'Invalid character: {char}. Each item must be a single character string.'}

        # Handle case sensitivity
        if not case_sensitive:
            char = char.lower()

        # Get ASCII code
        ascii_code = ord(char)

        # Check for non-printable characters
        if not include_non_printable and (ascii_code < 32 or ascii_code > 126):
            continue

        # Convert ASCII code to the specified format
        if output_format == 'integer':
            formatted_code = ascii_code
        elif output_format == 'hex':
            formatted_code = hex(ascii_code)
        elif output_format == 'binary':
            formatted_code = bin(ascii_code)
        elif output_format == 'octal':
            formatted_code = oct(ascii_code)
        elif output_format == 'unicode':
            formatted_code = f'U+{ascii_code:04X}'

        # Append formatted code to result
        result.append(formatted_code)

    return {'ascii_codes': result}

