def char_to_binary(characters: str, output_format: str = 'binary_string', delimiter: str = ' ', pad_length: int = 8):
    """
    Convert characters to their binary representation.

    :param characters: The characters to be converted to binary.
    :param output_format: The format of the output ('binary_string', 'binary_integer', 'binary_list').
    :param delimiter: A string used to separate binary representations in the output.
    :param pad_length: The length to which each binary representation should be padded.
    :return: Binary representation of the input characters.
    """
    if not isinstance(characters, str) or not characters:
        return {'error': 'Invalid input: characters must be a non-empty string.'}

    if output_format not in ['binary_string', 'binary_integer', 'binary_list']:
        return {'error': 'Invalid output format specified.'}

    try:
        binary_representations = [format(ord(char), f'0{pad_length}b') for char in characters]
    except Exception as e:
        return {'error': f'Error during conversion: {str(e)}'}

    if output_format == 'binary_string':
        return delimiter.join(binary_representations)
    elif output_format == 'binary_list':
        return binary_representations
    elif output_format == 'binary_integer':
        return [int(b, 2) for b in binary_representations]

