def extract_last_name(full_name: str, delimiter: str = ' ', ignore_suffixes: bool = True, ignore_prefixes: bool = False, handle_middle_names: bool = True, case_sensitive: bool = False, special_character_handling: str = 'include') -> str:
    # Validate input parameters
    if not isinstance(full_name, str) or not full_name.strip():
        raise ValueError('full_name must be a non-empty string.')
    if not isinstance(delimiter, str):
        raise ValueError('delimiter must be a string.')
    if not isinstance(ignore_suffixes, bool):
        raise ValueError('ignore_suffixes must be a boolean.')
    if not isinstance(ignore_prefixes, bool):
        raise ValueError('ignore_prefixes must be a boolean.')
    if not isinstance(handle_middle_names, bool):
        raise ValueError('handle_middle_names must be a boolean.')
    if not isinstance(case_sensitive, bool):
        raise ValueError('case_sensitive must be a boolean.')
    if special_character_handling not in ['ignore', 'include', 'replace']:
        raise ValueError("special_character_handling must be 'ignore', 'include', or 'replace'.")

    # Split the full name into parts
    name_parts = full_name.split(delimiter)

    # Handle prefixes
    if ignore_prefixes:
        prefixes = ['Dr.', 'Mr.', 'Mrs.', 'Ms.']
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes
    if ignore_suffixes:
        suffixes = ['Jr.', 'Sr.', 'II', 'III']
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle middle names
    if not handle_middle_names and len(name_parts) > 2:
        name_parts = [name_parts[0], name_parts[-1]]

    # Handle special characters
    if special_character_handling == 'ignore':
        name_parts = [''.join(filter(str.isalnum, part)) for part in name_parts]
    elif special_character_handling == 'replace':
        name_parts = [part.replace('-', ' ').replace('_', ' ') for part in name_parts]

    # Extract the last name
    last_name = name_parts[-1] if name_parts else ''

    # Handle case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    return last_name

