def get_last_letter(input, output_format='character', encoding='UTF-8', handle_special_characters=False):
    # Validate input
    if not isinstance(input, list) or len(input) < 1:
        return {'error': 'Input must be a non-empty list of strings.'}
    if output_format not in ['character', 'text', 'position', 'full_word']:
        return {'error': 'Invalid output format specified.'}
    if encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return {'error': 'Unsupported encoding specified.'}

    # Process each string in the input list
    results = []
    for string in input:
        if not isinstance(string, str):
            results.append({'error': 'All items in input must be strings.'})
            continue

        # Handle special characters if specified
        if handle_special_characters:
            string = ''.join(filter(str.isalnum, string))

        # Extract the last letter
        if len(string) == 0:
            results.append({'error': 'String is empty after filtering special characters.'})
            continue

        last_letter = string[-1]
        if output_format == 'character':
            results.append(last_letter)
        elif output_format == 'text':
            results.append(str(last_letter))
        elif output_format == 'position':
            results.append(len(string) - 1)
        elif output_format == 'full_word':
            results.append(string)

    return results

