def character_to_binary(input: str, encoding: str = 'ASCII', output_format: str = 'binary_string', delimiter: str = '', padding: bool = True):
    # Error handling for unsupported encodings
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16', 'UTF-32', 'ISO-8859-1']:
        return {'error': 'Unsupported encoding specified.'}

    # Error handling for unsupported output formats
    if output_format not in ['binary_string', 'binary_list', 'binary_dict']:
        return {'error': 'Unsupported output format specified.'}

    try:
        # Convert input to bytes using the specified encoding
        byte_data = input.encode(encoding)

        # Convert bytes to binary representation
        binary_data = [format(byte, '08b') if padding else bin(byte)[2:] for byte in byte_data]

        # Format the output based on the specified output_format
        if output_format == 'binary_string':
            result = delimiter.join(binary_data)
        elif output_format == 'binary_list':
            result = binary_data
        elif output_format == 'binary_dict':
            result = {char: format(ord(char), '08b') if padding else bin(ord(char))[2:] for char in input}

        return result
    except Exception as e:
        return {'error': str(e)}

