def date_calculator(start_date, years_to_add=0, years_to_subtract=0, months_to_add=0, months_to_subtract=0, days_to_add=0, days_to_subtract=0, output_format='YYYY-MM-DD', calendar_system='Gregorian'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Adjust for calendar system
    if calendar_system == 'Julian':
        # Adjust the start_date for Julian calendar if needed
        # Note: Python's datetime does not natively support Julian calendar,
        # so this would require additional logic or a library that supports it.
        pass

    # Calculate the new date
    new_date = start_date_obj + relativedelta(years=years_to_add - years_to_subtract,
                                              months=months_to_add - months_to_subtract,
                                              days=days_to_add - days_to_subtract)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO-8601':
        formatted_date = new_date.isoformat()
    else:
        return {'error': 'Invalid output_format specified.'}

    return {'result': formatted_date}

