def extract_name_component(full_name, delimiter=' ', case_sensitive=True, component='first_name', handle_prefixes=False, cultural_format='western'):
    """
    Extracts a specific component from a full name string.

    Parameters:
    - full_name (str): The full name from which the name component is to be extracted.
    - delimiter (str): The character used to separate names in the full name string. Defaults to a space.
    - case_sensitive (bool): Whether the extraction should be case-sensitive. Defaults to true.
    - component (str): Specifies which component of the name to extract. Options are 'first_name', 'middle_name', or 'last_name'. Defaults to 'first_name'.
    - handle_prefixes (bool): Whether to consider prefixes (e.g., Mr., Dr.) in the name extraction process. Defaults to false.
    - cultural_format (str): Specifies the cultural format of the name. Options are 'western', 'eastern', or 'custom'. Defaults to 'western'.

    Returns:
    - str: The extracted name component.
    """
    if not isinstance(full_name, str) or not full_name:
        return "Error: 'full_name' must be a non-empty string."

    if component not in ['first_name', 'middle_name', 'last_name']:
        return "Error: 'component' must be one of 'first_name', 'middle_name', or 'last_name'."

    if cultural_format not in ['western', 'eastern', 'custom']:
        return "Error: 'cultural_format' must be one of 'western', 'eastern', or 'custom'."

    # Handle prefixes if specified
    if handle_prefixes:
        prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.']
        parts = full_name.split(delimiter)
        if parts[0] in prefixes:
            parts = parts[1:]
    else:
        parts = full_name.split(delimiter)

    # Extract component based on cultural format
    if cultural_format == 'western':
        if component == 'first_name':
            return parts[0]
        elif component == 'middle_name':
            return parts[1] if len(parts) > 2 else ''
        elif component == 'last_name':
            return parts[-1]
    elif cultural_format == 'eastern':
        if component == 'first_name':
            return parts[-1]
        elif component == 'middle_name':
            return parts[1] if len(parts) > 2 else ''
        elif component == 'last_name':
            return parts[0]
    elif cultural_format == 'custom':
        # Custom logic can be implemented here
        pass

    return "Error: Unable to extract the specified component."

