def ascii_converter(characters, output_format='list', case_conversion='none', filter_non_ascii=False):
    # Validate characters parameter
    if not isinstance(characters, list) or len(characters) < 1 or len(characters) > 100:
        return {'error': 'Invalid characters input. Must be a list with 1 to 100 single-character strings.'}
    for char in characters:
        if not isinstance(char, str) or len(char) != 1:
            return {'error': 'Each item in characters must be a single-character string.'}

    # Validate output_format
    if output_format not in ['list', 'dictionary', 'json', 'csv']:
        return {'error': 'Invalid output_format. Must be one of: list, dictionary, json, csv.'}

    # Validate case_conversion
    if case_conversion not in ['none', 'uppercase', 'lowercase']:
        return {'error': 'Invalid case_conversion. Must be one of: none, uppercase, lowercase.'}

    # Apply case conversion
    if case_conversion == 'uppercase':
        characters = [char.upper() for char in characters]
    elif case_conversion == 'lowercase':
        characters = [char.lower() for char in characters]

    # Filter non-ASCII characters if required
    if filter_non_ascii:
        characters = [char for char in characters if ord(char) < 128]

    # Convert characters to ASCII
    ascii_codes = [ord(char) for char in characters]

    # Format output
    if output_format == 'list':
        return ascii_codes
    elif output_format == 'dictionary':
        return {char: ord(char) for char in characters}
    elif output_format == 'json':
        import json
        return json.dumps({char: ord(char) for char in characters})
    elif output_format == 'csv':
        return ','.join(str(ord(char)) for char in characters)

    return {'error': 'Unexpected error occurred.'}

