def extract_last_character(input, case_sensitive=True, number_of_characters=1, output_format='array'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(s, str) and s for s in input):
        raise ValueError('Input must be a non-empty list of non-empty strings.')
    if not isinstance(number_of_characters, int) or number_of_characters < 1:
        raise ValueError('Number of characters must be a positive integer.')
    if output_format not in ['string', 'array']:
        raise ValueError("Output format must be either 'string' or 'array'.")

    # Extract last character(s)
    extracted = []
    for s in input:
        if not case_sensitive:
            s = s.lower()
        extracted.append(s[-number_of_characters:])

    # Return based on output format
    if output_format == 'string':
        return ''.join(extracted)
    return extracted

