def character_counter(input: str, characters_to_count=['a', 'e', 'i', 'o', 'u'], case_sensitive=False, count_sequences=False, character_set='all', detailed_statistics=False):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate characters_to_count
    if not all(isinstance(char, str) for char in characters_to_count):
        return {'error': 'All items in characters_to_count must be strings.'}

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        characters_to_count = [char.lower() for char in characters_to_count]

    # Initialize count dictionary
    count_dict = {char: 0 for char in characters_to_count}

    # Count characters or sequences
    if count_sequences:
        for char in characters_to_count:
            count_dict[char] = input.count(char)
    else:
        for char in input:
            if char in count_dict:
                count_dict[char] += 1

    # Prepare detailed statistics if required
    if detailed_statistics:
        total_count = sum(count_dict.values())
        statistics = {char: {'count': count, 'percentage': (count / total_count) * 100 if total_count > 0 else 0} for char, count in count_dict.items()}
        return {'counts': count_dict, 'statistics': statistics}

    return {'counts': count_dict}

