def consonant_counter(input, case_sensitive=False, include_accented=True, custom_consonants=None, language='en', exclude_characters=None, output_format='count'):
    # Define standard consonants for English
    standard_consonants = 'bcdfghjklmnpqrstvwxyz'
    accented_consonants = 'çñ'

    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if custom_consonants and not all(isinstance(c, str) for c in custom_consonants):
        return {'error': 'Custom consonants must be a list of strings.'}
    if exclude_characters and not all(isinstance(c, str) for c in exclude_characters):
        return {'error': 'Exclude characters must be a list of strings.'}

    # Determine consonants to use
    consonants = custom_consonants if custom_consonants else list(standard_consonants)
    if include_accented:
        consonants.extend(accented_consonants)

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        consonants = [c.lower() for c in consonants]

    # Exclude specified characters
    if exclude_characters:
        consonants = [c for c in consonants if c not in exclude_characters]

    # Count consonants
    consonant_count = {c: 0 for c in consonants}
    for char in input:
        if char in consonants:
            consonant_count[char] += 1

