def extract_last_letter(names, ignore_special_characters=False, output_format='character', case_sensitive=True, multi_word_handling='last_word'):
    # Validate input parameters
    if not isinstance(names, list) or not all(isinstance(name, str) and name for name in names):
        raise ValueError('Invalid input: names must be a non-empty list of non-empty strings.')
    if output_format not in ['character', 'text', 'json', 'xml']:
        raise ValueError('Invalid output format.')
    if multi_word_handling not in ['last_word', 'first_word', 'all_words']:
        raise ValueError('Invalid multi_word_handling option.')

    def get_last_letter(name):
        # Handle multi-word names
        if multi_word_handling == 'last_word':
            words = name.split()
            target_word = words[-1]
        elif multi_word_handling == 'first_word':
            words = name.split()
            target_word = words[0]
        else:  # all_words
            target_word = name

        # Extract the last letter
        if ignore_special_characters:
            target_word = ''.join(filter(str.isalnum, target_word))

        if not target_word:
            return ''

        last_letter = target_word[-1]
        return last_letter if case_sensitive else last_letter.lower()

    # Process each name and collect results
    results = [get_last_letter(name) for name in names]

    # Format the output
    if output_format == 'character':
        return results[0] if len(results) == 1 else results
    elif output_format == 'text':
        return ' '.join(results)
    elif output_format == 'json':
        import json
        return json.dumps(results)
    elif output_format == 'xml':
        return '<results>' + ''.join(f'<name>{result}</name>' for result in results) + '</results>'

