def extract_last_name(full_name, delimiter=' ', output_format='string', handle_prefixes=False, handle_suffixes=False, special_character_handling='ignore'):
    # Error handling for required parameter
    if not full_name or not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Validate output_format
    if output_format not in ['string', 'array', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: string, array, detailed.'}

    # Validate special_character_handling
    if special_character_handling not in ['ignore', 'include', 'sanitize']:
        return {'error': 'Invalid special_character_handling. Must be one of: ignore, include, sanitize.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle prefixes if required
    if handle_prefixes:
        prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.']
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes if required
    if handle_suffixes:
        suffixes = ['Jr.', 'Sr.', 'II', 'III']
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle special characters
    if special_character_handling == 'sanitize':
        name_parts = [''.join(filter(str.isalnum, part)) for part in name_parts]
    elif special_character_handling == 'ignore':
        name_parts = [''.join(filter(lambda x: x.isalnum() or x.isspace(), part)) for part in name_parts]

    # Extract the last name
    last_name = name_parts[-1] if name_parts else ''

    # Format the output
    if output_format == 'array':
        return list(last_name)
    elif output_format == 'detailed':
        return {'last_name': last_name, 'components': name_parts}
    else:  # Default to 'string'
        return last_name

