def advanced_consonant_counter(input: str, case_sensitive: bool = False, include_special_characters: bool = False, output_format: str = 'integer', language_support: str = 'en', ignore_whitespace: bool = True):
    # Define consonants based on the language support
    consonants = 'bcdfghjklmnpqrstvwxyz'
    if language_support in ['es', 'fr', 'de', 'multi']:
        # Extend consonants for multilingual support if needed
        consonants += 'ñçß'
    if not case_sensitive:
        consonants += consonants.upper()

    # Initialize consonant count
    consonant_count = 0

    # Iterate over each character in the input
    for char in input:
        if ignore_whitespace and char.isspace():
            continue
        if char in consonants:
            consonant_count += 1
        elif include_special_characters and not char.isalnum():
            consonant_count += 1

    # Format the output based on the specified output_format
    if output_format == 'integer':
        return consonant_count
    elif output_format == 'text':
        return f'There are {consonant_count} consonants.'
    elif output_format == 'json':
        return {'consonant_count': consonant_count}
    elif output_format == 'detailed':
        # Detailed breakdown could include counts of each consonant type
        detailed_count = {consonant: input.lower().count(consonant) for consonant in consonants if consonant in input.lower()}
        return {'total': consonant_count, 'breakdown': detailed_count}
    else:
        raise ValueError('Invalid output format specified.')

