    date_formats = {
        'YYYY-MM-DD': '%Y-%m-%d',
        'DD-MM-YYYY': '%d-%m-%Y',
        'MM-DD-YYYY': '%m-%d-%Y',
        'YYYY/MM/DD': '%Y/%m/%d',
        'DD/MM/YYYY': '%d/%m/%Y'
    }

    if date_format not in date_formats:
        return 'Error: Unsupported date format.'

    # Parse the date
    try:
        parsed_date = datetime.strptime(date, date_formats[date_format])
    except ValueError:
        return 'Error: Invalid date.'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        localized_date = tz.localize(parsed_date)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Calculate day of the week
    if calendar_system == 'Gregorian':
        day_of_week = localized_date.strftime('%A')
    else:
        return 'Error: Unsupported calendar system.'

    # Return in the requested format
    if output_format == 'abbreviated':
        return day_of_week[:3]
    elif output_format == 'full':
