import datetime
import pytz
from dateutil.relativedelta import relativedelta


def date_calculator(start_date: str, duration: int, unit: str = 'days', output_format: str = 'YYYY-MM-DD', timezone: str = 'UTC') -> str:
    """
    Calculate a future or past date based on a given start date and a specified duration.
    """
    # Define valid units and formats
    valid_units = ['minutes', 'hours', 'days', 'weeks', 'months', 'years']
    valid_formats = ['YYYY-MM-DD', 'MM-DD-YYYY', 'DD-MM-YYYY', 'YYYY-MM-DDTHH:MM:SS', 'MM-DD-YYYY HH:MM', 'DD-MM-YYYY HH:MM']

    # Validate unit
    if unit not in valid_units:
        raise ValueError(f"Invalid unit: {unit}. Must be one of {valid_units}.")

    # Validate output format
    if output_format not in valid_formats:
        raise ValueError(f"Invalid output format: {output_format}. Must be one of {valid_formats}.")

    # Parse the start date
    try:
        start_date_obj = datetime.datetime.fromisoformat(start_date)
    except ValueError:
        raise ValueError("Invalid start date format. Must be in ISO 8601 format.")

    # Adjust for timezone
    try:
        tz = pytz.timezone(timezone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        raise ValueError("Invalid timezone specified.")

    # Calculate the new date
    if unit == 'minutes':
        new_date = start_date_obj + datetime.timedelta(minutes=duration)
    elif unit == 'hours':
        new_date = start_date_obj + datetime.timedelta(hours=duration)
    elif unit == 'days':
        new_date = start_date_obj + datetime.timedelta(days=duration)
    elif unit == 'weeks':
        new_date = start_date_obj + datetime.timedelta(weeks=duration)
    elif unit == 'months':
        new_date = start_date_obj + relativedelta(months=duration)
    elif unit == 'years':
        new_date = start_date_obj + relativedelta(years=duration)

    # Format the output
    if output_format == 'YYYY-MM-DD':
        return new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return new_date.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        return new_date.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'MM-DD-YYYY HH:MM':
        return new_date.strftime('%m-%d-%Y %H:%M')
    elif output_format == 'DD-MM-YYYY HH:MM':
        return new_date.strftime('%d-%m-%Y %H:%M')

