    # Validate input
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}
    if not name:
        return {'error': 'Invalid input: name cannot be empty.'}

    # Prepare character set based on case sensitivity
    if not case_sensitive:
        character_set = character_set.lower()
        name = name.lower()

    # Iterate over characters in the name
    for char in name:
        # Ignore leading whitespace if specified
        if ignore_whitespace and char.isspace():
            continue
        # Ignore non-alphabetic characters if specified
        if ignore_non_alphabetic and char not in character_set:
            continue
        # Return the first valid character
        if char in character_set:
            return {'first_letter': char}

