def extract_last_name(full_name, delimiters=[' '], handle_hyphenated=True, ignore_suffix=True, custom_suffixes=None, middle_name_handling=False, last_name_position=-1):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(delimiters, list) or not all(isinstance(d, str) for d in delimiters):
        return {'error': 'Invalid input: delimiters must be a list of strings.'}
    if not isinstance(handle_hyphenated, bool):
        return {'error': 'Invalid input: handle_hyphenated must be a boolean.'}
    if not isinstance(ignore_suffix, bool):
        return {'error': 'Invalid input: ignore_suffix must be a boolean.'}
    if custom_suffixes is not None and (not isinstance(custom_suffixes, list) or not all(isinstance(s, str) for s in custom_suffixes)):
        return {'error': 'Invalid input: custom_suffixes must be a list of strings or None.'}
    if not isinstance(middle_name_handling, bool):
        return {'error': 'Invalid input: middle_name_handling must be a boolean.'}
    if not isinstance(last_name_position, int):
        return {'error': 'Invalid input: last_name_position must be an integer.'}

    # Split the full name using the provided delimiters
    import re
    delimiters_regex = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(delimiters_regex, full_name)

    # Handle hyphenated names
    if handle_hyphenated:
        name_parts = [part for part in name_parts if part]
        if '-' in name_parts[-1]:
            last_name = name_parts[-1]
        else:
            last_name = name_parts[last_name_position]
    else:
        last_name = name_parts[last_name_position]

    # Ignore suffixes
    suffixes = ['Jr.', 'Sr.', 'III', 'IV'] if ignore_suffix else []
    if custom_suffixes:
        suffixes.extend(custom_suffixes)
    if last_name in suffixes:
        last_name = name_parts[last_name_position - 1]

    return last_name

