def get_last_letter(input: str, ignore_whitespace: bool = True, valid_characters: str = '', case_sensitive: bool = False, handle_empty: str = 'return_empty') -> str:
    # Error handling for invalid 'handle_empty' option
    if handle_empty not in ['return_empty', 'return_null', 'error']:
        raise ValueError("Invalid value for 'handle_empty'. Must be 'return_empty', 'return_null', or 'error'.")

    # Handle empty input based on 'handle_empty' parameter
    if not input:
        if handle_empty == 'return_empty':
            return ''
        elif handle_empty == 'return_null':
            return None
        elif handle_empty == 'error':
            raise ValueError('Input string is empty.')

    # Ignore trailing whitespace if 'ignore_whitespace' is True
    if ignore_whitespace:
        input = input.rstrip()

    # If 'valid_characters' is specified, filter the input
    if valid_characters:
        if not case_sensitive:
            valid_characters = valid_characters.lower()
            input = input.lower()
        input = ''.join([char for char in input if char in valid_characters])

    # Return the last character if input is not empty after filtering
    if input:
        return input[-1]
    else:
        if handle_empty == 'return_empty':
            return ''
        elif handle_empty == 'return_null':
            return None
        elif handle_empty == 'error':
            raise ValueError('No valid characters found in input.')

