def distinct_combinations(input, combination_length=2, output_format='count', case_sensitive=False, include_non_alphabetic=False, filter='none'):
    from itertools import combinations
    import re

    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'Combination length must be a positive integer.'}
    if output_format not in ['list', 'count', 'detailed']:
        return {'error': 'Invalid output format.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if not isinstance(include_non_alphabetic, bool):
        return {'error': 'Include non-alphabetic must be a boolean.'}
    if filter not in ['none', 'vowels', 'consonants', 'digits']:
        return {'error': 'Invalid filter type.'}

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter input based on non-alphabetic inclusion
    if not include_non_alphabetic:
        input = re.sub(r'[^a-zA-Z]', '', input)

    # Apply character type filter
    if filter == 'vowels':
        input = ''.join([c for c in input if c in 'aeiouAEIOU'])
    elif filter == 'consonants':
        input = ''.join([c for c in input if c in 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'])
    elif filter == 'digits':
        input = ''.join([c for c in input if c.isdigit()])

    # Generate combinations
    comb_set = set(combinations(input, combination_length))
    distinct_combinations = {''.join(comb) for comb in comb_set}

    # Return based on output format
    if output_format == 'list':
        return {'result': list(distinct_combinations)}
    elif output_format == 'count':
        return {'result': len(distinct_combinations)}
    elif output_format == 'detailed':
        return {'result': {'combinations': list(distinct_combinations), 'count': len(distinct_combinations)}}

