        elif operation == 'exponentiate':
            result = operands[0]
            for num in operands[1:]:
                result **= num
        elif operation == 'root':
            degree = operands[0]
            if degree == 0:
                if error_handling == 'strict':
                    raise ValueError('Root degree cannot be zero.')
                elif error_handling == 'warn':
                    print('Warning: Root degree cannot be zero. Skipping operation.')
                    return None
                else:  # ignore
                    return None
            result = operands[1] ** (1 / degree)
        else:
