def distinct_combinations(input_string, combination_length=2, combination_length_range=None, case_sensitive=True, include_special_characters=False, character_set=None, sort_output=False, max_combinations=None):
    import itertools

    # Error handling for input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string.'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be a positive integer.'}
    if combination_length_range:
        if (not isinstance(combination_length_range, list) or len(combination_length_range) != 2 
                or not all(isinstance(i, int) for i in combination_length_range)):
            return {'error': 'combination_length_range must be a list of two integers.'}

    # Adjust input string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Filter input string if character_set is provided
    if character_set:
        if character_set.startswith('-'):
            exclude_chars = set(character_set[1:])
            input_string = ''.join(c for c in input_string if c not in exclude_chars)
        else:
            include_chars = set(character_set)
            input_string = ''.join(c for c in input_string if c in include_chars)

    # Generate combinations
    if combination_length_range:
        min_len, max_len = combination_length_range
        combinations = set()
        for length in range(min_len, max_len + 1):
            combinations.update(itertools.combinations(input_string, length))
    else:
        combinations = set(itertools.combinations(input_string, combination_length))

    # Convert combinations to strings
    combinations = {''.join(comb) for comb in combinations}

    # Sort combinations if required
    if sort_output:
        combinations = sorted(combinations)

    # Limit number of combinations if max_combinations is set
    if max_combinations is not None:
        combinations = list(combinations)[:max_combinations]

    return {'combinations': combinations}

