def date_calculator(base_date: str, time_unit: str, amount: int, calendar_system: str = 'Gregorian', time_zone: str = 'UTC', calculate_difference: bool = False, target_date: str = None):
    from datetime import datetime, timedelta
    import pytz

    # Validate base_date format
    try:
        base_date_obj = datetime.strptime(base_date, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        return {'error': 'Invalid base_date format. Expected YYYY-MM-DDTHH:MM:SSZ.'}

    # Validate time_unit
    if time_unit not in ['seconds', 'minutes', 'hours', 'days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid time_unit. Must be one of seconds, minutes, hours, days, weeks, months, years.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        base_date_obj = base_date_obj.replace(tzinfo=pytz.utc).astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time_zone. Please provide a valid IANA time zone.'}

    # Perform date arithmetic
    if time_unit == 'weeks':
        delta = timedelta(weeks=amount)
    elif time_unit == 'days':
        delta = timedelta(days=amount)
    elif time_unit == 'hours':
        delta = timedelta(hours=amount)
    elif time_unit == 'minutes':
        delta = timedelta(minutes=amount)
    elif time_unit == 'seconds':
        delta = timedelta(seconds=amount)
    else:
        return {'error': 'Unsupported time_unit for arithmetic. Only weeks, days, hours, minutes, and seconds are supported.'}

    result_date = base_date_obj + delta

    # Return result in the same format
    return {'result_date': result_date.strftime('%Y-%m-%d')}

