def extract_first_name(full_name, delimiters=[' '], ignore_prefixes=False, ignore_suffixes=False, ignore_middle_names=False, case_sensitive=False, locale='en'):
    """
    Extracts the first name from a full name string based on specified parameters.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name:
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Split the full name using the provided delimiters
    import re
    pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(pattern, full_name)

    # Remove prefixes if specified
    if ignore_prefixes:
        prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.', 'Miss', 'Sir']  # Example prefixes
        name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes if specified
    if ignore_suffixes:
        suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV']  # Example suffixes
        name_parts = [part for part in name_parts if part not in suffixes]

    # Remove middle names if specified
    if ignore_middle_names and len(name_parts) > 1:
        name_parts = [name_parts[0]]

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.lower() for part in name_parts]

    # Locale-specific handling could be added here
    # For now, we assume 'en' locale does not require special handling

    # Return the first name
    if name_parts:
        return {'first_name': name_parts[0].capitalize() if not case_sensitive else name_parts[0]}
    else:
        return {'error': 'Unable to extract first name.'}

