def distinct_combinations(input_data, combination_length=2, unique_only=True, output_format='array', case_sensitive=False, exclude_characters=''):
    import itertools

    # Error handling for input_data length
    if len(input_data) < 2:
        return {'error': 'input_data must contain at least two characters.'}

    # Error handling for combination_length
    if combination_length < 2:
        return {'error': 'combination_length must be at least 2.'}

    # Error handling for output_format
    if output_format not in ['array', 'text', 'json']:
        return {'error': 'Invalid output_format. Must be one of array, text, json.'}

    # Adjust for case sensitivity
    if not case_sensitive:
        input_data = input_data.lower()
        exclude_characters = exclude_characters.lower()

    # Filter out excluded characters
    input_data = ''.join([char for char in input_data if char not in exclude_characters])

    # Generate combinations
    combinations = itertools.combinations(input_data, combination_length)

    # Convert combinations to a list of strings
    combinations = [''.join(comb) for comb in combinations]

    # Filter for unique combinations if required
    if unique_only:
        combinations = list(set(combinations))

    # Format output
    if output_format == 'array':
        return combinations
    elif output_format == 'text':
        return ', '.join(combinations)
    elif output_format == 'json':
        import json
        return json.dumps(combinations)

