def date_calculator(start_date: str, weeks_to_subtract: int = 0, days_to_add: int = 0, months_to_add: int = 0, years_to_add: int = 0, calendar_system: str = 'Gregorian', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for date format
    try:
        date_format = '%Y-%m-%d'
        date_obj = datetime.strptime(start_date, date_format)
    except ValueError:
        return 'Error: Invalid start_date format. Please use YYYY-MM-DD.'

    # Error handling for calendar system
    if calendar_system not in ['Gregorian', 'Julian']:
        return 'Error: Invalid calendar system. Choose either Gregorian or Julian.'

    # Subtract weeks
    date_obj -= timedelta(weeks=weeks_to_subtract)

    # Add days
    date_obj += timedelta(days=days_to_add)

    # Add months
    date_obj += relativedelta(months=months_to_add)

    # Add years
    date_obj += relativedelta(years=years_to_add)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return date_obj.strftime('%d-%m-%Y')
    else:
        return 'Error: Invalid output format. Choose from YYYY-MM-DD, MM-DD-YYYY, DD-MM-YYYY.'

