def advanced_character_counter(input_string, characters_to_count, case_sensitive=True, output_format='integer', ignore_whitespace=False, count_mode='individual'):
    # Validate required parameters
    if not isinstance(input_string, str):
        return {'error': 'Invalid input: input_string must be a string.'}
    if not isinstance(characters_to_count, list) or len(characters_to_count) < 1:
        return {'error': 'Invalid input: characters_to_count must be a non-empty list.'}

    # Prepare the input string based on options
    if ignore_whitespace:
        input_string = input_string.replace(' ', '')
    if not case_sensitive:
        input_string = input_string.lower()
        characters_to_count = [char.lower() for char in characters_to_count]

    # Count occurrences
    counts = {}
    for char in characters_to_count:
        if count_mode == 'individual':
            counts[char] = input_string.count(char)
        elif count_mode == 'cumulative':
            counts['total'] = counts.get('total', 0) + input_string.count(char)

    # Format the output
    if output_format == 'integer':
