def date_calculator(start_date: str, offset: int, unit: str, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', business_days_only: bool = False, holiday_calendar: str = 'standard') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate input parameters
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DD.'

    if unit not in ['days', 'weeks', 'months', 'years']:
        return 'Error: Invalid unit. Must be one of days, weeks, months, years.'

    # Calculate the new date based on the unit
    if unit == 'days':
        delta = timedelta(days=offset)
    elif unit == 'weeks':
        delta = timedelta(weeks=offset)
    elif unit == 'months':
        # Approximate month calculation
        month = start_date_obj.month - 1 + offset
        year = start_date_obj.year + month // 12
        month = month % 12 + 1
        day = min(start_date_obj.day, [31, 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month-1])
        new_date = datetime(year, month, day)
        delta = new_date - start_date_obj
    elif unit == 'years':
        try:
            new_date = start_date_obj.replace(year=start_date_obj.year + offset)
            delta = new_date - start_date_obj
        except ValueError:
            return 'Error: Invalid date calculation due to leap year.'

    # Apply the delta to the start date
    result_date = start_date_obj + delta

    # Format the result date
    if output_format == 'YYYY-MM-DD':
        formatted_date = result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = result_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = result_date.strftime('%d-%m-%Y')
    else:
        return 'Error: Invalid output_format. Must be one of YYYY-MM-DD, MM-DD-YYYY, DD-MM-YYYY.'

    return formatted_date

