def character_counter(strings, characters, case_sensitive=True, index_range=None, output_format='integer'):
    # Validate input types
    if not isinstance(strings, list) or not all(isinstance(s, str) for s in strings):
        return {'error': 'Invalid input: strings must be a list of strings.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: characters must be a list of single-character strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if index_range is not None:
        if not (isinstance(index_range, list) and len(index_range) == 2 and all(isinstance(i, int) for i in index_range)):
            return {'error': 'Invalid input: index_range must be a list of two integers.'}

    # Prepare for counting
    results = []
    for string in strings:
        # Apply index range if specified
        if index_range:
            start, end = index_range
            string = string[start:end]
        # Initialize count dictionary
        count_dict = {char: 0 for char in characters}
        # Count occurrences
        for char in string:
            if not case_sensitive:
                char = char.lower()
            for target_char in characters:
                if not case_sensitive:
                    target_char = target_char.lower()
                if char == target_char:
                    count_dict[target_char] += 1
        results.append(count_dict)

    # Format output
    if output_format == 'integer':
        return sum(sum(counts.values()) for counts in results)
    elif output_format == 'text':
        return ', '.join(f"'{char}': {count}" for counts in results for char, count in counts.items())
    elif output_format == 'detailed':
        return results
    else:
        return {'error': 'Invalid output format specified.'}

