        return {'error': 'Invalid specific_consonants type. Must be a list of strings.'}

    # Define consonants based on language
    consonants = 'bcdfghjklmnpqrstvwxyz'
    if language == 'en':
        consonants = 'bcdfghjklmnpqrstvwxyz'
    # Add more language-specific consonants if needed

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        consonants = consonants.lower()
        ignore_characters = [char.lower() for char in ignore_characters]
        specific_consonants = [consonant.lower() for consonant in specific_consonants]

