def enhanced_alphabetical_sorter(input, case_sensitive=False, ignore_non_alphabetic=False, sort_order='ascending', output_format='array', group_by_case=False):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if sort_order not in ['ascending', 'descending']:
        return {'error': 'Invalid sort_order: must be either "ascending" or "descending".'}
    if output_format not in ['array', 'string', 'json']:
        return {'error': 'Invalid output_format: must be "array", "string", or "json".'}

    # Process each string in the input list
    sorted_results = []
    for string in input:
        # Filter non-alphabetic characters if required
        if ignore_non_alphabetic:
            string = ''.join(filter(str.isalpha, string))

        # Sort the string
        if case_sensitive:
            sorted_string = sorted(string)
        else:
            sorted_string = sorted(string, key=lambda c: (c.lower(), c))

        # Group by case if required
        if group_by_case:
            sorted_string = sorted(sorted_string, key=lambda c: (c.islower(), c))

        # Reverse order if descending
        if sort_order == 'descending':
            sorted_string.reverse()

        # Format output
        if output_format == 'array':
            sorted_results.append(sorted_string)
        elif output_format == 'string':
            sorted_results.append(''.join(sorted_string))
        elif output_format == 'json':
            sorted_results.append({'sorted': ''.join(sorted_string)})

    # Return results
    if output_format == 'json':
        return {'results': sorted_results}
    return sorted_results

