def character_counter(input, ignore_characters=[], ignore_position=[], case_sensitive=False, count_types=[], output_format='integer'):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize variables
    total_count = 0
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Iterate over the string
    for index, char in enumerate(input):
        # Check if character should be ignored
        if char in ignore_characters:
            continue

        # Check if position should be ignored
        if ('first' in ignore_position and index == 0) or \
           ('last' in ignore_position and index == len(input) - 1) or \
           ('even' in ignore_position and index % 2 == 0) or \
           ('odd' in ignore_position and index % 2 != 0):
            continue

        # Count the character if it is a letter
        if char.isalpha():
            total_count += 1

    # Prepare output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'The total number of letters is {total_count}.'
    elif output_format == 'detailed':
        return {
            'total_letters': total_count,
            'details': {
                'vowels': sum(1 for char in input if char in vowels),
                'consonants': sum(1 for char in input if char in consonants)
            }
        }
    else:
        return {'error': 'Invalid output format specified.'}

