def extract_last_name(full_name, delimiter=' ', case_sensitive=True, output_format='string', include_middle_names=False, handle_suffixes=False, cultural_convention='western'):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle suffixes if required
    if handle_suffixes and name_parts[-1] in ['Jr.', 'Sr.', 'III']:
        name_parts = name_parts[:-1]

    # Determine the last name based on cultural convention
    if cultural_convention == 'western':
        last_name = name_parts[-1]
    elif cultural_convention == 'eastern':
        last_name = name_parts[0]
    else:
        return {'error': 'Invalid cultural_convention value.'}

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        last_name = delimiter.join(name_parts[1:])

