def string_length_counter(input: str, ignore_characters: list = None, ignore_position: list = None, case_sensitive: bool = False, character_type: list = None, multi_byte_handling: str = 'count_as_one', output_format: str = 'integer') -> int:
    """
    Counts the number of characters in the input string based on specified parameters.
    """
    if not isinstance(input, str):
        raise ValueError('Input must be a string.')
    if ignore_characters and not all(isinstance(c, str) for c in ignore_characters):
        raise ValueError('All ignore_characters must be strings.')
    if ignore_position and not all(pos in ['first', 'last', 'even', 'odd'] for pos in ignore_position):
        raise ValueError('Invalid ignore_position value.')
    if character_type and not all(ct in ['alphabetic', 'numeric', 'whitespace', 'punctuation'] for ct in character_type):
        raise ValueError('Invalid character_type value.')
    if multi_byte_handling not in ['count_as_one', 'count_as_individual']:
        raise ValueError('Invalid multi_byte_handling value.')
    if output_format not in ['integer', 'text', 'detailed_report']:
        raise ValueError('Invalid output_format value.')

    # Initialize character count
    count = 0

    # Convert input to lowercase if case insensitive
    if not case_sensitive:
        input = input.lower()

    # Filter characters based on ignore_characters
    if ignore_characters:
        input = ''.join(c for c in input if c not in ignore_characters)

    # Filter positions
    if ignore_position:
        if 'first' in ignore_position:
            input = input[1:]
        if 'last' in ignore_position:
            input = input[:-1]
        if 'even' in ignore_position:
            input = ''.join(c for i, c in enumerate(input) if i % 2 != 0)
        if 'odd' in ignore_position:
            input = ''.join(c for i, c in enumerate(input) if i % 2 == 0)

    # Filter character types
    if character_type:
        allowed_types = set(character_type)
        input = ''.join(c for c in input if (
            ('alphabetic' in allowed_types and c.isalpha()) or
            ('numeric' in allowed_types and c.isdigit()) or
            ('whitespace' in allowed_types and c.isspace()) or
            ('punctuation' in allowed_types and not c.isalnum() and not c.isspace())
        ))

    # Handle multi-byte characters
    if multi_byte_handling == 'count_as_one':
        count = len(input)
    else:  # count_as_individual
        count = sum(1 for c in input)

    # Return output in specified format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The count is {count}.'
    elif output_format == 'detailed_report':
        return {
            'total_count': count,
            'original_length': len(input),
            'ignored_characters': ignore_characters,
            'ignored_positions': ignore_position,
            'character_types_included': character_type
        }

