    """
    Perform arithmetic operations between numbers or arrays of numbers.

    Parameters:
    - number1: The first number or array of numbers in the operation.
    - number2: The second number or array of numbers to be used in the operation.
    - operation: The arithmetic operation to perform. Defaults to 'subtract'.
    - output_format: The format of the output. Defaults to 'integer'.

    Returns:
    - The result of the arithmetic operation in the specified format.
    """
    # Error handling for unsupported operations
    if operation not in ['subtract', 'add', 'multiply', 'divide']:
        return {'error': 'Unsupported operation'}

    # Error handling for unsupported output formats
    if output_format not in ['integer', 'text', 'json', 'detailed_text']:
        return {'error': 'Unsupported output format'}

    try:
        # Perform the operation
        if operation == 'subtract':
            result = number1 - number2
        elif operation == 'add':
            result = number1 + number2
        elif operation == 'multiply':
            result = number1 * number2
        elif operation == 'divide':
            if number2 == 0:
                return {'error': 'Division by zero'}
            result = number1 / number2

        # Format the output
        if output_format == 'integer':
            return int(result)
        elif output_format == 'text':
            return str(result)
        elif output_format == 'json':
            return {'result': result}
        elif output_format == 'detailed_text':
            return f'The result of {operation} between {number1} and {number2} is {result}.'

