def calculate_difference(value1, value2, absolute=False, output_format='integer', precision=2, rounding='nearest'):
    """
    Calculate the difference between two numerical values or arrays of numbers.
    Parameters:
    - value1: The first numerical value or array of numbers.
    - value2: The second numerical value or array of numbers.
    - absolute: Whether to return the absolute difference.
    - output_format: The format of the output ('integer', 'float', 'text').
    - precision: The number of decimal places for float output.
    - rounding: The rounding method ('up', 'down', 'nearest').
    """
    # Error handling for input types
    if not (isinstance(value1, (int, float, list)) and isinstance(value2, (int, float, list))):
        return {'error': 'Invalid input types. value1 and value2 must be numbers or arrays of numbers.'}

    # Calculate difference
    if isinstance(value1, list) and isinstance(value2, list):
        if len(value1) != len(value2):
            return {'error': 'Arrays must be of the same length.'}
        differences = [v1 - v2 for v1, v2 in zip(value1, value2)]
    elif isinstance(value1, list):
        differences = [v1 - value2 for v1 in value1]
    elif isinstance(value2, list):
        differences = [value1 - v2 for v2 in value2]
    else:
        differences = [value1 - value2]

    # Apply absolute value if needed
    if absolute:
        differences = [abs(diff) for diff in differences]

    # Determine output format
    if output_format == 'integer':
        differences = [int(diff) for diff in differences]
    elif output_format == 'float':
        if rounding == 'up':
            differences = [round(diff + 0.5 * 10**(-precision), precision) for diff in differences]
        elif rounding == 'down':
            differences = [round(diff - 0.5 * 10**(-precision), precision) for diff in differences]
        else:  # rounding == 'nearest'
            differences = [round(diff, precision) for diff in differences]
    elif output_format == 'text':
        differences = [str(diff) for diff in differences]

    # Return single value or list
    return differences[0] if len(differences) == 1 else differences

