    if not isinstance(ignore_prefixes, bool):
        return {'error': 'Invalid ignore_prefixes. It must be a boolean.'}
    if not isinstance(ignore_suffixes, bool):
        return {'error': 'Invalid ignore_suffixes. It must be a boolean.'}
    if custom_prefixes is not None and not all(isinstance(p, str) for p in custom_prefixes):
