    # Define default prefixes and suffixes
    default_prefixes = ['Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.']
    default_suffixes = ['Jr.', 'Sr.', 'II', 'III']

    # Use custom prefixes/suffixes if provided
    prefixes = custom_prefixes if custom_prefixes is not None else default_prefixes
    suffixes = custom_suffixes if custom_suffixes is not None else default_suffixes

    # Split the full name
    parts = full_name.split(delimiter)

