def character_counter(input, characters, case_sensitive=True, output_format='integer', ignore_whitespace=False):
    # Validate input parameters
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input) or len(input) < 1:
        return {'error': 'Invalid input: input must be a list of at least one string.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters) or len(characters) < 1:
        return {'error': 'Invalid characters: characters must be a list of single-character strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive: must be a boolean value.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, detailed.'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'Invalid ignore_whitespace: must be a boolean value.'}

    # Initialize count dictionary
    counts = {char: 0 for char in characters}

    # Process each string in input
    for string in input:
        # Optionally ignore whitespace
        if ignore_whitespace:
            string = ''.join(string.split())

        # Count characters
        for char in string:
            if not case_sensitive:
                char = char.lower()
            for target_char in characters:
                if not case_sensitive:
                    target_char = target_char.lower()
                if char == target_char:
                    counts[target_char] += 1

    # Format output
    if output_format == 'integer':
        total_count = sum(counts.values())
        return total_count
    elif output_format == 'text':
        return f"Total count: {sum(counts.values())}"
    elif output_format == 'detailed':
        return counts

