def date_incrementer(start_date, months_to_add=1, weeks_to_add=0, days_to_add=0, business_days_only=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Calculate the new date
    try:
        # Add months
        new_date = start_date_obj + relativedelta(months=months_to_add)
        # Add weeks
        new_date += timedelta(weeks=weeks_to_add)
        # Add days
        new_date += timedelta(days=days_to_add)

        # Adjust for business days if required
        if business_days_only:
            while new_date.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
                new_date += timedelta(days=1)

        return {'new_date': new_date.strftime('%Y-%m-%d')}
    except Exception as e:
        return {'error': str(e)}

