    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if name_format not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid input: name_format must be one of ["western", "eastern", "custom"].'}
    if custom_delimiter is not None and not isinstance(custom_delimiter, str):
        return {'error': 'Invalid input: custom_delimiter must be a string if provided.'}
    if not isinstance(include_middle_names, bool):
        return {'error': 'Invalid input: include_middle_names must be a boolean.'}
    if not isinstance(handle_suffixes, bool):
        return {'error': 'Invalid input: handle_suffixes must be a boolean.'}
    if title_handling not in ['ignore', 'include', 'separate']:
        return {'error': 'Invalid input: title_handling must be one of ["ignore", "include", "separate"].'}

    # Split the full name based on the format
    if name_format == 'western':
        parts = full_name.split()
    elif name_format == 'eastern':
        parts = full_name.split()
        parts.reverse()  # Reverse for eastern format
    elif name_format == 'custom' and custom_delimiter:
        parts = full_name.split(custom_delimiter)
    else:
        return {'error': 'Invalid input: custom_delimiter must be provided for custom name_format.'}

    # Handle titles
    if title_handling == 'ignore':
        titles = ['Dr.', 'Mr.', 'Ms.', 'Mrs.']
        parts = [part for part in parts if part not in titles]
    elif title_handling == 'separate':
        titles = ['Dr.', 'Mr.', 'Ms.', 'Mrs.']
        parts = [part for part in parts if part not in titles]

    # Handle suffixes
    if handle_suffixes:
        suffixes = ['Jr.', 'Sr.', 'III']
        parts = [part for part in parts if part not in suffixes]

    # Extract last name
    if include_middle_names:
        last_name = ' '.join(parts[1:]) if len(parts) > 1 else parts[0]
    else:
        last_name = parts[-1] if parts else ''

