def enhanced_ascii_converter(characters, output_format='integer', case_sensitive=True, delimiter=','):
    # Validate 'characters' parameter
    if not isinstance(characters, list) or not (1 <= len(characters) <= 100):
        return {'error': 'Invalid characters input. Must be a list with 1 to 100 single-character strings.'}

    # Validate each character in the list
    for char in characters:
        if not isinstance(char, str) or len(char) != 1:
            return {'error': 'Each item in characters must be a single-character string.'}

    # Validate 'output_format' parameter
    if output_format not in ['integer', 'text', 'hexadecimal', 'binary']:
        return {'error': 'Invalid output_format. Must be one of: integer, text, hexadecimal, binary.'}

    # Convert characters to ASCII codes
    ascii_codes = []
    for char in characters:
        if not case_sensitive:
            char = char.lower()
        ascii_code = ord(char)
        if output_format == 'integer':
            ascii_codes.append(str(ascii_code))
        elif output_format == 'text':
            ascii_codes.append(chr(ascii_code))
        elif output_format == 'hexadecimal':
            ascii_codes.append(hex(ascii_code)[2:])
        elif output_format == 'binary':
            ascii_codes.append(bin(ascii_code)[2:])

    # Join ASCII codes with the specified delimiter
    result = delimiter.join(ascii_codes)
    return {'result': result}

