def enhanced_unique_letter_counter(input: str, case_sensitive: bool = False, ignore_non_alphabetic: bool = True, language: str = 'en', handle_diacritics: bool = False, detailed_output: bool = False):
    import unicodedata
    from collections import Counter

    # Error handling for input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Normalize input for diacritic handling
    if not handle_diacritics:
        input = unicodedata.normalize('NFD', input)
        input = ''.join(c for c in input if unicodedata.category(c) != 'Mn')

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter non-alphabetic characters if required
    if ignore_non_alphabetic:
        input = ''.join(filter(str.isalpha, input))

    # Count unique letters
    unique_letters = set(input)

    # Prepare detailed output if required
    if detailed_output:
        letter_counts = Counter(input)
        detailed_report = {letter: letter_counts[letter] for letter in unique_letters}
        return {'unique_count': len(unique_letters), 'details': detailed_report}

    return {'unique_count': len(unique_letters)}

