def extract_last_name(full_name, delimiter=[' '], name_format='first_last', handle_suffix=False, handle_prefix=False):
    """
    Extracts the last name from a full name string based on the specified parameters.

    :param full_name: The full name from which to extract the last name.
    :param delimiter: The delimiters used to separate names, default is a space.
    :param name_format: The format of the name, default is first_last.
    :param handle_suffix: Indicates whether to handle suffixes in the name.
    :param handle_prefix: Indicates whether to handle prefixes in the name.
    :return: The extracted last name or an error message.
    """
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name parameter. It must be a non-empty string.'}

    if not isinstance(delimiter, list) or not all(isinstance(d, str) for d in delimiter):
        return {'error': 'Invalid delimiter parameter. It must be a list of strings.'}

    if name_format not in ['first_last', 'first_middle_last', 'last_first', 'prefix_first_last', 'first_last_suffix', 'compound_last']:
        return {'error': 'Invalid name_format parameter. Unsupported format.'}

    # Split the full name using the provided delimiters
    import re
    pattern = '|'.join(map(re.escape, delimiter))
    name_parts = re.split(pattern, full_name)

    # Handle different name formats
    last_name = ''
    if name_format == 'first_last':
        if len(name_parts) >= 2:
            last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        if len(name_parts) >= 3:
            last_name = name_parts[-1]
    elif name_format == 'last_first':
        if len(name_parts) >= 2:
            last_name = name_parts[0]
    elif name_format == 'prefix_first_last':
        if handle_prefix and len(name_parts) >= 3:
            last_name = name_parts[-1]
        elif len(name_parts) >= 2:
            last_name = name_parts[-1]
    elif name_format == 'first_last_suffix':
        if handle_suffix and len(name_parts) >= 3:
            last_name = name_parts[-2]
        elif len(name_parts) >= 2:
            last_name = name_parts[-1]
    elif name_format == 'compound_last':
        if len(name_parts) >= 2:
            last_name = ' '.join(name_parts[1:])

    if not last_name:
        return {'error': 'Unable to extract last name with the given parameters.'}

    return {'last_name': last_name.strip()}

