    if max_unique_count is not None and not isinstance(max_unique_count, int):
        return {'error': 'max_unique_count must be an integer or None.'}

    # Filter input based on character set
    if character_set == 'alphabet':
        valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    else:
        return {'error': 'Unsupported character set.'}

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()
        valid_chars = set('abcdefghijklmnopqrstuvwxyz')

    # Remove ignored characters
    input = ''.join(c for c in input if c not in ignore_characters)

    # Count unique letters
    unique_letters = set(c for c in input if c in valid_chars)

    # Apply max unique count limit
    if max_unique_count is not None:
        unique_letters = set(list(unique_letters)[:max_unique_count])

    # Return result based on output format
    if output_format == 'count':
        return len(unique_letters)
    elif output_format == 'list':
        return list(unique_letters)
    else:
        return {'error': 'Unsupported output format.'}

