def ascii_converter(characters, output_format='list', handle_non_ascii='error', custom_placeholder='?', include_metadata=False):
    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'string', 'json', 'csv']:
        raise ValueError("'output_format' must be one of 'list', 'string', 'json', 'csv'.")
    if handle_non_ascii not in ['error', 'ignore', 'replace', 'custom_replace']:
        raise ValueError("'handle_non_ascii' must be one of 'error', 'ignore', 'replace', 'custom_replace'.")

    # Initialize result list
    result = []

    # Process each character
    for i, char in enumerate(characters):
        try:
            ascii_code = ord(char)
            if ascii_code > 127:
                raise ValueError("Non-ASCII character detected.")
            entry = {'character': char, 'ascii': ascii_code} if include_metadata else ascii_code
            result.append(entry)
        except ValueError:
            if handle_non_ascii == 'error':
                raise
            elif handle_non_ascii == 'ignore':
                continue
            elif handle_non_ascii == 'replace':
                entry = {'character': char, 'ascii': ord('?')} if include_metadata else ord('?')
                result.append(entry)
            elif handle_non_ascii == 'custom_replace':
                entry = {'character': char, 'ascii': ord(custom_placeholder)} if include_metadata else ord(custom_placeholder)
                result.append(entry)

    # Format the result based on output_format
    if output_format == 'list':
        return result
    elif output_format == 'string':
        return ''.join(chr(r['ascii'] if include_metadata else r) for r in result)
    elif output_format == 'json':
        import json
        return json.dumps(result)
    elif output_format == 'csv':
        return ','.join(str(r['ascii'] if include_metadata else r) for r in result)

