        return {'error': 'Input must be a string.'}

    # Error handling for output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format specified.'}

    # Initialize counts
    total_count = 0
    vowel_count = 0
    consonant_count = 0
    digit_count = 0
    special_character_count = 0

    # Define vowels
    vowels = 'aeiouAEIOU' if case_sensitive else 'aeiou'

    # Iterate over each character in the input string
    for char in input:
        if char.isalpha():
            total_count += 1
            if count_vowels and char in vowels:
                vowel_count += 1
            elif count_consonants and char not in vowels:
                consonant_count += 1
        elif char.isdigit() and count_digits:
            digit_count += 1
        elif not char.isalnum() and count_special_characters:
            special_character_count += 1
        elif char.isspace() and include_spaces:
            total_count += 1

    # Prepare the output based on the specified format
    if output_format == 'integer':
        return {'count': total_count}
    elif output_format == 'text':
        return {'count': f'The total number of characters is {total_count}.'}
