def character_counter(input, characters_to_count=['a', 'e', 'i', 'o', 'u'], ignore_characters=None, ignore_position=None, output_format='integer'):
    # Error handling for input validation
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if not isinstance(characters_to_count, list) or not all(isinstance(c, str) for c in characters_to_count):
        return {'error': 'Invalid characters_to_count: must be a list of strings.'}
    if ignore_characters and (not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters)):
        return {'error': 'Invalid ignore_characters: must be a list of strings.'}
    if ignore_position and (not isinstance(ignore_position, list) or not all(p in ['first', 'last', 'even', 'odd'] for p in ignore_position)):
        return {'error': 'Invalid ignore_position: must be a list with allowed values.'}
    if output_format not in ['integer', 'text', 'detailed_report']:
        return {'error': 'Invalid output_format: must be one of integer, text, detailed_report.'}

    # Initialize count
    total_count = 0
    detailed_counts = {char: 0 for char in characters_to_count}

    # Iterate over each string in input
    for string in input:
        for index, char in enumerate(string):
            # Check ignore conditions
            if ignore_characters and char in ignore_characters:
                continue
            if ignore_position:
                if 'first' in ignore_position and index == 0:
                    continue
                if 'last' in ignore_position and index == len(string) - 1:
                    continue
                if 'even' in ignore_position and index % 2 == 0:
                    continue
                if 'odd' in ignore_position and index % 2 != 0:
                    continue
            # Count characters
            if char in characters_to_count:
                total_count += 1
                detailed_counts[char] += 1

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total count of specified characters: {total_count}'
    elif output_format == 'detailed_report':
