def date_calculator(input_date, operation, years=0, months=0, days=0, hours=0, minutes=0, seconds=0, second_date=None, output_format='YYYY-MM-DD', timezone='UTC'):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Error handling for input_date format
    try:
        input_date_obj = datetime.strptime(input_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return {'error': 'Invalid input_date format. Expected YYYY-MM-DDTHH:MM:SS.'}

    # Set timezone
    try:
        tz = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid timezone specified.'}
    input_date_obj = tz.localize(input_date_obj)

    # Perform operation
    if operation == 'subtract':
        result_date = input_date_obj - relativedelta(years=years, months=months, days=days, hours=hours, minutes=minutes, seconds=seconds)
    elif operation == 'add':
        result_date = input_date_obj + relativedelta(years=years, months=months, days=days, hours=hours, minutes=minutes, seconds=seconds)
    elif operation == 'difference':
        if not second_date:
            return {'error': 'second_date is required for difference operation.'}
        try:
            second_date_obj = datetime.strptime(second_date, '%Y-%m-%dT%H:%M:%S')
            second_date_obj = tz.localize(second_date_obj)
        except ValueError:
            return {'error': 'Invalid second_date format. Expected YYYY-MM-DDTHH:MM:SS.'}
        delta = input_date_obj - second_date_obj
        return {'result': str(delta)}
    else:
        return {'error': 'Invalid operation specified. Choose from add, subtract, or difference.'}

    # Format output
    if output_format == 'YYYY-MM-DD':
        formatted_result = result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_result = result_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_result = result_date.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        formatted_result = result_date.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return {'error': 'Invalid output_format specified.'}

    return {'result': formatted_result}

