def vowel_counter(input, case_sensitive=False, language='English', output_format='count', vowels_to_count=None, exclude_characters=None):
    # Define default vowels for English
    default_vowels = 'aeiou'
    if language == 'Spanish':
        default_vowels += 'áéíóúü'
    elif language == 'French':
        default_vowels += 'àâæçéèêëîïôœùûüÿ'
    elif language == 'German':
        default_vowels += 'äöüß'
    elif language == 'Italian':
        default_vowels += 'àèéìîòóù'

    # Use specified vowels or default
    vowels = vowels_to_count if vowels_to_count else list(default_vowels)

    # Adjust for case sensitivity
    if not case_sensitive:
        vowels = [v.lower() for v in vowels]

    # Initialize count
    total_vowels = 0
    vowels_found = []
    detailed_count = {v: 0 for v in vowels}

    # Process each string
    for string in input:
        # Exclude specified characters
        if exclude_characters:
            for char in exclude_characters:
                string = string.replace(char, '')

        # Count vowels
        for char in string:
            char_to_check = char if case_sensitive else char.lower()
            if char_to_check in vowels:
                total_vowels += 1
                vowels_found.append(char)
                detailed_count[char_to_check] += 1

    # Return based on output format
    if output_format == 'count':
        return total_vowels
    elif output_format == 'list':
        return vowels_found
    elif output_format == 'detailed':
        return detailed_count
    else:
        raise ValueError('Invalid output format specified.')

