def date_calculator(input_date: str, operation: str, years: int = 0, months: int = 0, days: int = 0, second_date: str = None, time_zone: str = 'UTC', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate input_date format
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid input_date format. Expected YYYY-MM-DD.'

    # Perform the specified operation
    if operation == 'subtract':
        # Subtract years, months, and days
        result_date = date_obj - relativedelta(years=years, months=months, days=days)
    else:
        return 'Error: Unsupported operation. Only subtract operation is implemented for this example.'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        return result_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        return result_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO8601':
        return result_date.isoformat()
    else:
        return 'Error: Unsupported output_format.'

