def enhanced_letter_extractor(names, ignore_non_alphabetic=True, case_sensitive=False, alphabet_type='latin', extract_mode='first_letter', prefix_length=1, suffix_length=1):
    # Validate input parameters
    if not isinstance(names, list) or not all(isinstance(name, str) and name for name in names):
        return {'error': 'Invalid input: names must be a non-empty list of non-empty strings.'}
    if extract_mode not in ['first_letter', 'prefix', 'suffix']:
        return {'error': 'Invalid extract_mode. Must be one of: first_letter, prefix, suffix.'}

    # Helper function to extract based on mode
    def extract(name):
        if extract_mode == 'first_letter':
            for char in name:
                if ignore_non_alphabetic and not char.isalpha():
                    continue
                return char if case_sensitive else char.lower()
        elif extract_mode == 'prefix':
            return name[:prefix_length]
        elif extract_mode == 'suffix':
            return name[-suffix_length:]
        return ''

    # Process each name
    results = [extract(name) for name in names]
    return {'results': results}

