    # Validate input types
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        raise ValueError("'names' must be a list of strings.")
    if case_format not in ['uppercase', 'lowercase', 'original', 'capitalize']:
        raise ValueError("'case_format' must be one of 'uppercase', 'lowercase', 'original', 'capitalize'.")
    if non_alpha_handling not in ['skip', 'include', 'default']:
        raise ValueError("'non_alpha_handling' must be one of 'skip', 'include', 'default'.")
    if not isinstance(default_character, str) or len(default_character) > 1:
        raise ValueError("'default_character' must be a single character string.")
    if empty_string_handling not in ['ignore', 'default']:
        raise ValueError("'empty_string_handling' must be one of 'ignore', 'default'.")

    result = []
    for name in names:
        if not name:  # Handle empty strings
            if empty_string_handling == 'default':
                result.append(default_character)
            continue

        first_char = name[0]
        if not first_char.isalpha():  # Handle non-alphabetic characters
            if non_alpha_handling == 'skip':
                continue
            elif non_alpha_handling == 'default':
                first_char = default_character

        # Apply case formatting
        if case_format == 'uppercase':
            first_char = first_char.upper()
        elif case_format == 'lowercase':
            first_char = first_char.lower()
        elif case_format == 'capitalize':
            first_char = first_char.upper() if first_char.isalpha() else first_char

        result.append(first_char)

    return result

