def enhanced_combined_length_calculator(input, ignore_characters=[], ignore_position=[], case_sensitive=False, trim_whitespace=True, output_format='integer'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if len(input) < 1 or len(input) > 20:
        return {'error': 'Invalid input: input list must contain between 1 and 20 strings.'}

    # Process each string
    total_length = 0
    details = []
    for s in input:
        original = s
        if trim_whitespace:
            s = s.strip()
        if not case_sensitive:
            s = s.lower()
        if 'first' in ignore_position and len(s) > 0:
            s = s[1:]
        if 'last' in ignore_position and len(s) > 0:
            s = s[:-1]
        if 'middle' in ignore_position and len(s) > 2:
            s = s[0] + s[2:]
        for char in ignore_characters:
            s = s.replace(char, '')
        length = len(s)
        total_length += length
        details.append({'string': original, 'processed': s, 'length': length})

    # Format output
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'The combined length of the strings is {total_length}.'
    elif output_format == 'detailed':
        return {'total_length': total_length, 'details': details}
    else:
        return {'error': 'Invalid output format specified.'}

