def enhanced_unique_letter_counter(input_string, case_sensitive=False, ignore_non_alphabetic=True, include_characters='', exclude_characters='', count_digits_separately=False, detailed_output=False):
    # Validate input_string
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}

    # Initialize sets for unique characters
    unique_letters = set()
    unique_digits = set() if count_digits_separately else None

    # Normalize input based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        include_characters = include_characters.lower()
        exclude_characters = exclude_characters.lower()

    # Iterate over each character in the input string
    for char in input_string:
        # Check if character should be included
        if include_characters and char in include_characters:
            unique_letters.add(char)
            continue

        # Exclude specified characters
        if char in exclude_characters:
            continue

        # Handle alphabetic characters
        if char.isalpha():
            unique_letters.add(char)
        elif char.isdigit() and count_digits_separately:
            unique_digits.add(char)
        elif not ignore_non_alphabetic:
            unique_letters.add(char)

    # Prepare the result
    result = {'unique_letter_count': len(unique_letters)}
    if count_digits_separately:
        result['unique_digit_count'] = len(unique_digits)
    if detailed_output:
        result['unique_letters'] = list(unique_letters)
        if count_digits_separately:
            result['unique_digits'] = list(unique_digits)

    return result

