def extract_first_name(full_name, delimiter='space', ignore_prefixes=True, output_format='string', cultural_context='western', custom_delimiters=None):
    # Define common prefixes to ignore
    prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.', 'Prof.'] if ignore_prefixes else []

    # Handle delimiter
    if delimiter == 'space':
        delimiters = [' ']
    elif delimiter == 'hyphen':
        delimiters = ['-']
    elif delimiter == 'comma':
        delimiters = [',']
    elif delimiter == 'dot':
        delimiters = ['.']
    elif delimiter == 'semicolon':
        delimiters = [';']
    elif delimiter == 'slash':
        delimiters = ['/']
    elif delimiter == 'custom' and custom_delimiters:
        delimiters = custom_delimiters
    else:
        raise ValueError('Invalid delimiter or custom delimiters not provided')

    # Split the full name based on the delimiters
    import re
    regex_pattern = '|'.join(map(re.escape, delimiters))
    parts = re.split(regex_pattern, full_name)

    # Remove any prefixes
    parts = [part for part in parts if part not in prefixes]

    # Extract the first name based on cultural context
    if cultural_context == 'western':
        first_name = parts[0] if parts else ''
    elif cultural_context == 'eastern':
        first_name = parts[-1] if parts else ''
    elif cultural_context == 'arabic':
        first_name = parts[0] if parts else ''
    elif cultural_context == 'hispanic':
        first_name = parts[0] if parts else ''
    elif cultural_context == 'custom':
        first_name = parts[0] if parts else ''
    else:
        raise ValueError('Invalid cultural context')

    # Prepare the output
    if output_format == 'string':
        return first_name
    elif output_format == 'json':
        return {'first_name': first_name}
    elif output_format == 'detailed_json':
        return {
            'first_name': first_name,
            'full_name': full_name,
            'delimiter_used': delimiter,
            'cultural_context': cultural_context
        }
    else:
        raise ValueError('Invalid output format')

