        result_date = date_obj + timedelta(days=days_offset)
    elif operation == 'difference_in_days':
        # This operation would require a second date input, not applicable here
        return {'error': 'Operation not applicable'}
    else:
        return {'error': 'Unsupported operation'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = result_date.strftime('%Y-%m-%d')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = result_date.strftime('%d-%m-%Y')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = result_date.strftime('%m-%d-%Y')
    elif output_format == 'custom':
        # Custom output format handling can be added here
        return {'error': 'Unsupported output format'}
    else:
        return {'error': 'Unsupported output format'}

    return {'result': formatted_date}

