def extract_date_component(date_input, component, date_format='DD MM YYYY', error_handling='strict', timezone='UTC'):
    from datetime import datetime
    import pytz

    # Define supported formats
    format_mappings = {
        'DD MM YYYY': '%d %m %Y',
        'MM/DD/YYYY': '%m/%d/%Y',
        'YYYY-MM-DD': '%Y-%m-%d',
        'DD-MM-YYYY': '%d-%m-%Y',
        'YYYY/MM/DD': '%Y/%m/%d'
    }

    # Check if the date_format is supported
    if date_format not in format_mappings:
        if error_handling == 'strict':
            raise ValueError(f"Unsupported date format: {date_format}")
        elif error_handling == 'lenient':
            date_format = 'DD MM YYYY'  # Default to a common format

    # Parse the date
    try:
        date_obj = datetime.strptime(date_input, format_mappings[date_format])
    except ValueError as e:
        if error_handling == 'strict':
            raise ValueError(f"Error parsing date: {e}")
        elif error_handling == 'lenient':
            # Attempt to parse with a default format
            try:
                date_obj = datetime.strptime(date_input, '%d %m %Y')
            except ValueError:
                return "Invalid date format"

    # Handle timezone
    if timezone != 'UTC':
        try:
            tz = pytz.timezone(timezone)
            date_obj = date_obj.astimezone(tz)
        except Exception as e:
            if error_handling == 'strict':
                raise ValueError(f"Timezone error: {e}")

