def date_calculator(input_date: str, days_offset: int, calendar_system: str = 'Gregorian', time_zone: str = 'UTC', output_format: str = 'date_only') -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil import parser

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'Hebrew', 'Islamic']:
        return 'Error: Unsupported calendar system.'

    # Validate output format
    if output_format not in ['date_only', 'date_and_day_of_week']:
        return 'Error: Unsupported output format.'

    try:
        # Parse the input date
        base_date = parser.parse(input_date)

        # Adjust for calendar system if necessary
        if calendar_system == 'Julian':
            # Convert to Julian date
            base_date = base_date - timedelta(days=13)  # Rough adjustment for Julian

        # Apply the days offset
        result_date = base_date + timedelta(days=days_offset)

        # Adjust for time zone
        if time_zone != 'UTC':
            try:
                tz = pytz.timezone(time_zone)
                result_date = result_date.astimezone(tz)
            except pytz.UnknownTimeZoneError:
                return 'Error: Unknown time zone.'

        # Format the output
        if output_format == 'date_only':
            return result_date.strftime('%Y-%m-%d')
        elif output_format == 'date_and_day_of_week':
            return result_date.strftime('%Y-%m-%d (%A)')

    except Exception as e:
        return f'Error: {str(e)}'

