def date_parser(date_string, output_component, date_format=None, output_format='numeric'):
    from datetime import datetime
    import calendar

    # Define possible date formats
    possible_formats = [
        '%d %b %Y',  # '14 May 1790'
        '%m/%d/%Y',  # '05/14/1790'
        '%Y-%m-%d',  # '1790-05-14'
        '%d-%m-%Y',  # '14-05-1790'
    ]

    # If date_format is provided, use it directly
    if date_format:
        possible_formats = [date_format]

    # Try parsing the date string with the provided or inferred formats
    parsed_date = None
    for fmt in possible_formats:
        try:
            parsed_date = datetime.strptime(date_string, fmt)
            break
        except ValueError:
            continue

    # If parsing failed, return an error
    if not parsed_date:
        return {'error': 'Invalid date format or date string could not be parsed.'}

    # Extract the requested component
    if output_component == 'month_number':
        result = parsed_date.month
    elif output_component == 'day':
        result = parsed_date.day
    elif output_component == 'year':
        result = parsed_date.year
    elif output_component == 'day_of_week':
        if output_format == 'textual':
            result = calendar.day_name[parsed_date.weekday()]
        else:
            result = parsed_date.weekday()  # Monday is 0
    else:
        return {'error': 'Invalid output component specified.'}

    # Return the result
    return {'result': result}

