def enhanced_unique_letter_counter(input, ignore_case=True, ignore_characters=[], consider_positions=['all'], position_range=[0, 0], pattern='', output_statistics=False):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Normalize case if ignore_case is True
    if ignore_case:
        input = input.lower()

    # Apply ignore_characters
    for char in ignore_characters:
        input = input.replace(char, '')

    # Consider positions
    if 'range' in consider_positions:
        start, end = position_range
        input = input[start:end]
    elif 'first' in consider_positions:
        input = input[0]
    elif 'last' in consider_positions:
        input = input[-1]
    elif 'middle' in consider_positions:
        mid = len(input) // 2
        input = input[mid]
    # 'all' is default, so no change needed

    # Apply pattern if provided
    if pattern:
        import re
        matches = re.findall(pattern, input)
        input = ''.join(matches)

    # Count unique letters
    unique_letters = set(input)
    unique_letters = {char for char in unique_letters if char.isalpha()}

    # Prepare output
    result = {'unique_count': len(unique_letters)}

    # Add statistics if requested
    if output_statistics:
        from collections import Counter
        letter_counts = Counter(input)
        result['statistics'] = {char: count for char, count in letter_counts.items() if char.isalpha()}

    return result

