def extract_month_number(date_string, date_format=None, error_handling='raise', default_value=1, locale=None, ambiguity_resolution='first'):
    """
    Extracts the month number from a given date string.

    Parameters:
    - date_string (str): The date string from which to extract the month number.
    - date_format (str, optional): The expected format of the date string.
    - error_handling (str): How to handle errors ('ignore', 'raise', 'default', 'log').
    - default_value (int): The default month number to return if the date is invalid.
    - locale (str, optional): The locale for month extraction.
    - ambiguity_resolution (str): How to resolve ambiguous dates ('first', 'last', 'average').

    Returns:
    - int: The month number extracted from the date string.
    """
    from datetime import datetime
    import locale as loc

    # Set locale if provided
    if locale:
        try:
            loc.setlocale(loc.LC_TIME, locale)
        except Exception as e:
            if error_handling == 'raise':
                raise ValueError(f"Invalid locale: {locale}") from e
            elif error_handling == 'log':
                print(f"Error setting locale: {e}")

    try:
        # Parse the date string
        if date_format:
            date_obj = datetime.strptime(date_string, date_format)
        else:
            date_obj = datetime.fromisoformat(date_string)

        # Extract the month number
        month_number = date_obj.month
        return month_number

    except ValueError as e:
        if error_handling == 'raise':
            raise ValueError(f"Invalid date string: {date_string}") from e
        elif error_handling == 'default':
            return default_value
        elif error_handling == 'log':
            print(f"Error parsing date: {e}")
            return None
        elif error_handling == 'ignore':
            return None

    except Exception as e:
        if error_handling == 'raise':
            raise e
        elif error_handling == 'log':
            print(f"Unexpected error: {e}")
            return None
        elif error_handling == 'ignore':
            return None

