def date_calculator(start_date: str, days_to_add: int = 0, end_date: str = None, date_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz

    try:
        # Parse the start date
        if date_format == 'YYYY-MM-DD':
            date_obj = datetime.strptime(start_date, '%Y-%m-%d')
        else:
            raise ValueError('Unsupported date format')

        # Adjust for timezone
        timezone = pytz.timezone(time_zone)
        date_obj = timezone.localize(date_obj)

        # Calculate the new date
        if end_date:
            if date_format == 'YYYY-MM-DD':
                end_date_obj = datetime.strptime(end_date, '%Y-%m-%d')
                end_date_obj = timezone.localize(end_date_obj)
                delta = (end_date_obj - date_obj).days
                return str(delta)
            else:
                raise ValueError('Unsupported date format for end_date')
        else:
            new_date_obj = date_obj + timedelta(days=days_to_add)
            return new_date_obj.strftime('%Y-%m-%d')

    except Exception as e:
        return f'Error: {str(e)}'

