def extract_month(date_string, date_format='DD-MM-YYYY', custom_format=None, output_format='numeric', error_handling='strict'):
    from datetime import datetime
    import calendar

    # Define a helper function to parse the date
    def parse_date(date_str, fmt):
        try:
            return datetime.strptime(date_str, fmt)
        except ValueError:
            if error_handling == 'strict':
                raise ValueError(f"Date string '{date_str}' does not match format '{fmt}'")
            elif error_handling == 'lenient':
                # Attempt common formats
                for common_fmt in ['%d-%m-%Y', '%m/%d/%Y', '%Y.%m.%d', '%Y-%m-%d']:
                    try:
                        return datetime.strptime(date_str, common_fmt)
                    except ValueError:
                        continue
                raise ValueError(f"Date string '{date_str}' could not be parsed with common formats")

    # Determine the format to use
    if date_format == 'custom' and custom_format:
        date_obj = parse_date(date_string, custom_format)
    elif date_format == 'DD-MM-YYYY':
        date_obj = parse_date(date_string, '%d-%m-%Y')
    elif date_format == 'MM/DD/YYYY':
        date_obj = parse_date(date_string, '%m/%d/%Y')
    elif date_format == 'YYYY.MM.DD':
        date_obj = parse_date(date_string, '%Y.%m.%d')
    elif date_format == 'YYYY-MM-DD':
        date_obj = parse_date(date_string, '%Y-%m-%d')
    else:
        raise ValueError("Invalid date format specified")

    # Extract the month
    month_number = date_obj.month

    # Return the month in the requested format
    if output_format == 'numeric':
        return month_number
    elif output_format == 'full_name':
        return calendar.month_name[month_number]
    elif output_format == 'abbreviated':
        return calendar.month_abbr[month_number]
    else:
        raise ValueError("Invalid output format specified")

