def date_calculator(start_date, duration, output_format='YYYY-MM-DDTHH:MM:SS', timezone='UTC', business_days=False):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate and parse the start_date
    try:
        start_dt = datetime.fromisoformat(start_date)
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS.'}

    # Adjust for timezone
    try:
        tz = pytz.timezone(timezone)
        start_dt = start_dt.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid timezone specified.'}

    # Parse duration
    duration_value = duration.get('value')
    duration_unit = duration.get('unit')
    if not duration_value or not duration_unit:
        return {'error': 'Duration must include both value and unit.'}

    # Calculate the new date
    try:
        if duration_unit == 'weeks':
            delta = timedelta(weeks=int(duration_value.split()[0]))
        elif duration_unit == 'days':
            delta = timedelta(days=int(duration_value.split()[0]))
        elif duration_unit == 'hours':
            delta = timedelta(hours=int(duration_value.split()[0]))
        elif duration_unit == 'minutes':
            delta = timedelta(minutes=int(duration_value.split()[0]))
        elif duration_unit == 'seconds':
            delta = timedelta(seconds=int(duration_value.split()[0]))
        elif duration_unit == 'months':
            delta = relativedelta(months=int(duration_value.split()[0]))
        elif duration_unit == 'years':
            delta = relativedelta(years=int(duration_value.split()[0]))
        else:
            return {'error': 'Unsupported duration unit.'}

        new_date = start_dt + delta
    except Exception as e:
        return {'error': str(e)}

    # Format the output
    if output_format == 'YYYY-MM-DDTHH:MM:SS':
        formatted_date = new_date.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'MM/DD/YYYY HH:MM:SS':
        formatted_date = new_date.strftime('%m/%d/%Y %H:%M:%S')
    elif output_format == 'DD-MM-YYYY HH:MM:SS':
        formatted_date = new_date.strftime('%d-%m-%Y %H:%M:%S')
    else:
        return {'error': 'Unsupported output format.'}

    return {'result': formatted_date}

