    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Error handling for name_format
    if name_format not in ['western', 'eastern', 'custom', 'arabic', 'hispanic']:
        return {'error': 'Invalid name_format. Must be one of the specified formats.'}

    # Handle prefixes if ignore_prefixes is True
    if ignore_prefixes:
        prefixes = ['Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Prof.']
        for prefix in prefixes:
            if full_name.startswith(prefix):
                full_name = full_name[len(prefix):].strip()
                break

    # Split the name based on the specified format
    if custom_delimiter:
        name_parts = full_name.split(custom_delimiter)
    else:
        name_parts = full_name.split()

    # Handle suffixes if handle_suffixes is True
    if handle_suffixes:
        suffixes = ['Jr.', 'Sr.', 'III']
        if name_parts[-1] in suffixes:
            name_parts = name_parts[:-1]

    # Determine last name based on name_format
    if name_format == 'western':
        last_name = name_parts[-1]
    elif name_format == 'eastern':
        last_name = name_parts[0]
    elif name_format == 'arabic':
        last_name = name_parts[-1]
    elif name_format == 'hispanic':
        last_name = name_parts[-1]
    elif name_format == 'custom':
        last_name = name_parts[-1]

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        last_name = ' '.join(name_parts[1:])

    # Handle title based on title_handling
    if title_handling == 'include':
        last_name = ' '.join(name_parts)
    elif title_handling == 'separate':
        last_name = ' '.join(name_parts[1:])

    return {'last_name': last_name}

