def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', character_set: str = 'alphabetic', exclude_characters: str = '') -> str:
    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return 'Error: Invalid output_format. Choose from integer, text, detailed.'

    # Validate character_set
    if character_set not in ['alphabetic', 'alphanumeric', 'custom']:
        return 'Error: Invalid character_set. Choose from alphabetic, alphanumeric, custom.'

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        exclude_characters = exclude_characters.lower()

    # Define the character set
    if character_set == 'alphabetic':
        valid_chars = set('abcdefghijklmnopqrstuvwxyz')
    elif character_set == 'alphanumeric':
        valid_chars = set('abcdefghijklmnopqrstuvwxyz0123456789')
    elif character_set == 'custom':
        valid_chars = set(input)  # Assume custom means all characters in input

    # Exclude specified characters
    valid_chars -= set(exclude_characters)

    # Count repeated letters
    from collections import Counter
    letter_counts = Counter(c for c in input if c in valid_chars)
    repeated_letters = {char: count for char, count in letter_counts.items() if count > 1}

    # Format the output
    if output_format == 'integer':
        return str(len(repeated_letters))
    elif output_format == 'text':
        return f"There are {len(repeated_letters)} repeated letters."
    elif output_format == 'detailed':
        details = ', '.join(f"'{char}': {count}" for char, count in repeated_letters.items())
        return f"Detailed count: {details}" if details else 'No repeated letters.'

