def reverse_number(number: str, output_format: str = 'string', numeral_system: str = 'decimal', reverse_range: dict = None) -> str:
    # Validate numeral system
    if numeral_system not in ['decimal', 'binary', 'hexadecimal']:
        return 'Error: Unsupported numeral system.'

    # Validate output format
    if output_format not in ['string', 'integer', 'formatted_string']:
        return 'Error: Unsupported output format.'

    # Handle numeral system conversion if necessary
    if numeral_system == 'binary':
        try:
            number = str(int(number, 2))
        except ValueError:
            return 'Error: Invalid binary number.'
    elif numeral_system == 'hexadecimal':
        try:
            number = str(int(number, 16))
        except ValueError:
            return 'Error: Invalid hexadecimal number.'

    # Determine the range to reverse
    start = 0
    end = len(number)
    if reverse_range:
        start = reverse_range.get('start', 0)
        end = reverse_range.get('end', len(number))
        if start < 0 or end > len(number) or start >= end:
            return 'Error: Invalid reverse range.'

    # Reverse the specified range
    reversed_part = number[start:end][::-1]
    reversed_number = number[:start] + reversed_part + number[end:]

    # Format the output
    if output_format == 'integer':
        return str(int(reversed_number))
    elif output_format == 'formatted_string':
        return f'Reversed: {reversed_number}'
    else:  # Default to 'string'
        return reversed_number

