def reverse_order(input: str, preserve_sign: bool = True, output_format: str = 'string', reverse_segments: bool = False, delimiter: str = '') -> str:
    # Error handling for incorrect input types
    if not isinstance(input, str):
        return 'Error: Input must be a string.'
    if output_format not in ['string', 'integer']:
        return 'Error: Output format must be either "string" or "integer".'

    # Handle negative numbers if preserve_sign is true
    sign = ''
    if preserve_sign and input.startswith('-'):
        sign = '-'
        input = input[1:]

    # Reverse segments if reverse_segments is true
    if reverse_segments:
        segments = input.split(delimiter)
        reversed_segments = [segment[::-1] for segment in segments]
        reversed_input = delimiter.join(reversed_segments)
    else:
        reversed_input = input[::-1]

    # Add sign back if necessary
    if sign:
        reversed_input = sign + reversed_input

    # Convert to integer if output_format is 'integer'
    if output_format == 'integer':
        try:
            return int(reversed_input)
        except ValueError:
            return 'Error: Cannot convert reversed input to integer.'

    return reversed_input

