def date_calculator(start_date, years_to_add, months_to_add=0, days_to_add=0, hours_to_add=0, minutes_to_add=0, seconds_to_add=0, output_format='YYYY-MM-DDTHH:MM:SS'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SS.'}

    # Calculate new date
    try:
        new_date = start_date_obj + relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)
        new_date += timedelta(hours=hours_to_add, minutes=minutes_to_add, seconds=seconds_to_add)
    except Exception as e:
        return {'error': str(e)}

    # Format output
    if output_format == 'YYYY-MM-DD':
        result = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        result = new_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        result = new_date.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        result = new_date.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return {'error': 'Invalid output_format. Supported formats are YYYY-MM-DD, MM/DD/YYYY, DD-MM-YYYY, YYYY-MM-DDTHH:MM:SS.'}

    return {'result': result}

