def character_to_binary(input: str, output_format: str = 'binary_string', encoding: str = 'ASCII', error_handling: str = 'strict') -> str:
    # Validate input
    if not input:
        raise ValueError('Input must be a non-empty string.')
    if output_format not in ['binary_string', 'binary_array', 'formatted_binary']:
        raise ValueError('Invalid output_format. Must be one of: binary_string, binary_array, formatted_binary.')
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16']:
        raise ValueError('Invalid encoding. Must be one of: ASCII, UTF-8, UTF-16.')
    if error_handling not in ['ignore', 'strict']:
        raise ValueError('Invalid error_handling. Must be one of: ignore, strict.')

    # Convert character(s) to binary
    binary_result = []
    for char in input:
        try:
            if encoding == 'ASCII':
                binary = format(ord(char), '08b')
            elif encoding == 'UTF-8':
                binary = ''.join(format(b, '08b') for b in char.encode('utf-8'))
            elif encoding == 'UTF-16':
                binary = ''.join(format(b, '08b') for b in char.encode('utf-16')[2:])  # Skip BOM
            binary_result.append(binary)
        except Exception as e:
            if error_handling == 'strict':
                raise ValueError(f'Error encoding character {char}: {str(e)}')
            elif error_handling == 'ignore':
                continue

    # Format output
    if output_format == 'binary_string':
        return ''.join(binary_result)
    elif output_format == 'binary_array':
        return binary_result
    elif output_format == 'formatted_binary':
        return ' '.join(binary_result)

