def get_last_letter(input: str, output_format: str = 'character', handle_empty: bool = False, special_characters: bool = True):
    # Split the input string by commas to handle multiple strings
    strings = input.split(',')
    results = []

    for s in strings:
        s = s.strip()  # Remove any leading/trailing whitespace
        if not s:
            if handle_empty:
                results.append('Empty string provided')
            else:
                raise ValueError('Empty string encountered')
            continue

        # Determine the last character, considering special characters if allowed
        if special_characters:
            last_char = s[-1]
        else:
            last_char = next((char for char in reversed(s) if char.isalnum()), '')

        if not last_char:
            if handle_empty:
                results.append('No valid last letter found')
            else:
                raise ValueError('No valid last letter found')
            continue

        # Format the output based on the specified output_format
        if output_format == 'character':
            results.append(last_char)
        elif output_format == 'text':
            results.append(f'The last letter is {last_char}')
        elif output_format == 'position':
            results.append(s.rfind(last_char))
        elif output_format == 'list':
            results.append(last_char)
        else:
            raise ValueError('Unsupported output format')

    # If the output format is 'list', return the list of results
    if output_format == 'list':
        return results
    # Otherwise, return the first result (for single input strings)
    return results[0] if results else None

