    if not isinstance(full_name, str):
        return {'error': 'full_name must be a string'}

    # Error handling for output_format
    if output_format not in ['string', 'json']:
        return {'error': 'Invalid output_format. Must be "string" or "json".'}

    # Error handling for suffix_handling
    if suffix_handling not in ['include', 'exclude', 'separate']:
        return {'error': 'Invalid suffix_handling. Must be "include", "exclude", or "separate".'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle case sensitivity
    if ignore_case:
        name_parts = [part.lower() for part in name_parts]

    # Determine the last name and handle suffixes
    last_name = name_parts[-1]
    suffix = ''
    if suffix_handling == 'separate' and len(name_parts) > 1:
        suffix = name_parts[-1]
        last_name = name_parts[-2]
    elif suffix_handling == 'include' and len(name_parts) > 1:
        last_name = name_parts[-2] + delimiter + name_parts[-1]

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        last_name = delimiter.join(name_parts[1:])

    # Prepare the output
    if output_format == 'json':
        return {'last_name': last_name, 'suffix': suffix}
    else:
        return last_name

