    # Validate input type
    if not isinstance(input, str):
        raise ValueError('Input must be a string.')

    # Handle empty input based on 'on_empty_input' parameter
    if input == '':
        if on_empty_input == 'error':
            raise ValueError('Input is empty.')
        elif on_empty_input == 'null':
            return None
        elif on_empty_input == 'default_character':
            return default_character

    # Trim leading spaces if 'trim_spaces' is True
    if trim_spaces:
        input = input.lstrip()

    # Handle special characters if 'handle_special_characters' is True
    if handle_special_characters:
        input = ''.join(filter(str.isalnum, input))

    # Extract the first character
    if not input:
        if on_empty_input == 'default_character':
            return default_character
        raise ValueError('No valid characters found.')

    first_letter = input[0]

    # Format the output based on 'output_format'
    if output_format == 'uppercase':
        return first_letter.upper()
    elif output_format == 'lowercase':
        return first_letter.lower()
    elif output_format == 'ascii':
        return str(ord(first_letter))
    elif output_format == 'unicode':
        return str(ord(first_letter))
    else:
        return first_letter

