def char_to_binary(characters, output_format='binary_string', encoding='ASCII', delimiter='', padding=True):
    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: characters must be a list of single-character strings.'}
    if output_format not in ['binary_string', 'binary_list']:
        return {'error': 'Invalid output_format: must be either binary_string or binary_list.'}
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16']:
        return {'error': 'Invalid encoding: must be ASCII, UTF-8, or UTF-16.'}

    # Function logic
    binary_codes = []
    for char in characters:
        if encoding == 'ASCII':
            binary_code = format(ord(char), '08b' if padding else 'b')
        elif encoding == 'UTF-8':
            binary_code = ''.join(format(byte, '08b') for byte in char.encode('utf-8'))
        elif encoding == 'UTF-16':
            binary_code = ''.join(format(byte, '08b') for byte in char.encode('utf-16')[2:])  # Skip BOM
        binary_codes.append(binary_code)

    # Prepare output
    if output_format == 'binary_string':
        result = delimiter.join(binary_codes)
    else:
        result = binary_codes

    return result

