def advanced_date_calculator(start_datetime, years=0, months=0, days=0, hours=0, minutes=0, seconds=0, output_format='YYYY-MM-DDTHH:MM:SS', time_zone='UTC', handle_leap_years=True):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate and parse the start_datetime
    try:
        start_dt = datetime.fromisoformat(start_datetime)
    except ValueError:
        return {'error': 'Invalid start_datetime format. Must be ISO 8601 format.'}

    # Apply the date and time adjustments
    try:
        adjusted_dt = start_dt + relativedelta(years=years, months=months, days=days, hours=hours, minutes=minutes, seconds=seconds)
    except Exception as e:
        return {'error': f'Error in date calculation: {str(e)}'}

    # Handle time zone conversion
    try:
        tz = pytz.timezone(time_zone)
        adjusted_dt = adjusted_dt.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone specified.'}

    # Format the output
    format_mappings = {
        'YYYY-MM-DD': '%Y-%m-%d',
        'MM-DD-YYYY': '%m-%d-%Y',
        'DD-MM-YYYY': '%d-%m-%Y',
        'YYYY-MM-DDTHH:MM:SS': '%Y-%m-%dT%H:%M:%S',
        'MM-DD-YYYYTHH:MM:SS': '%m-%d-%YT%H:%M:%S',
        'DD-MM-YYYYTHH:MM:SS': '%d-%m-%YT%H:%M:%S'
    }

    if output_format not in format_mappings:
        return {'error': 'Invalid output format specified.'}

    formatted_output = adjusted_dt.strftime(format_mappings[output_format])

    return {'result': formatted_output}

