def extract_last_name(full_name, consider_prefixes=True, consider_suffixes=False, delimiter=' ', handle_middle_names=False, multiple_last_names=False, cultural_order='Western'):
    # Error handling for incorrect input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(consider_prefixes, bool) or not isinstance(consider_suffixes, bool) or not isinstance(handle_middle_names, bool) or not isinstance(multiple_last_names, bool):
        return {'error': 'Invalid input: boolean parameters must be of type bool.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}
    if cultural_order not in ['Western', 'Eastern']:
        return {'error': 'Invalid input: cultural_order must be either "Western" or "Eastern".'}

    # Split the full name into parts based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle different cultural orders
    if cultural_order == 'Western':
        # Western order: First Middle Last
        last_name_index = -1
        if multiple_last_names:
            last_name_index = -2
        last_name = delimiter.join(name_parts[last_name_index:])
    else:
        # Eastern order: Last First Middle
        last_name = name_parts[0]

    # Consider prefixes and suffixes
    if not consider_prefixes:
        # Remove common prefixes
        prefixes = ['de', 'van', 'von', 'd']
        last_name_parts = last_name.split(delimiter)
        if last_name_parts[0].lower() in prefixes:
            last_name_parts.pop(0)
        last_name = delimiter.join(last_name_parts)

    if not consider_suffixes:
        # Remove common suffixes
        suffixes = ['Jr.', 'Sr.', 'II', 'III']
        last_name_parts = last_name.split(delimiter)
        if last_name_parts[-1] in suffixes:
            last_name_parts.pop()
        last_name = delimiter.join(last_name_parts)

    return {'last_name': last_name}

