    if not isinstance(ignore_non_alpha, bool) or not isinstance(case_sensitive, bool) \
       or not isinstance(ignore_digits, bool) or not isinstance(ignore_whitespace, bool) \
       or not isinstance(return_position, bool):
        return {'error': 'Invalid input: All options must be boolean values.'}

    # Initialize variables
    last_letter = None
    position = -1

    # Iterate over the string in reverse
    for i in range(len(input_string) - 1, -1, -1):
        char = input_string[i]

        # Check for whitespace
        if ignore_whitespace and char.isspace():
            continue

        # Check for digits
        if ignore_digits and char.isdigit():
            continue

        # Check for non-alphabetical characters
        if ignore_non_alpha and not char.isalpha():
            continue

        # Handle case sensitivity
        if not case_sensitive:
