def count_characters(input, ignore_characters=None, ignore_position=None, case_sensitive=False, character_types=None, output_format='integer'):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if ignore_characters and not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'All ignore_characters must be strings.'}
    if ignore_position and not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'ignore_position must be either "first" or "last".'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if character_types and not all(ct in ['alphabet', 'digit', 'special'] for ct in character_types):
        return {'error': 'character_types must be "alphabet", "digit", or "special".'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'output_format must be "integer", "text", or "json".'}

    # Initialize character count
    count = 0
    frequency = {}

    # Determine character types to count
    count_alphabet = not character_types or 'alphabet' in character_types
    count_digit = not character_types or 'digit' in character_types
    count_special = not character_types or 'special' in character_types

    # Process input string
    for i, char in enumerate(input):
        # Ignore specified positions
        if ignore_position:
            if 'first' in ignore_position and i == 0:
                continue
            if 'last' in ignore_position and i == len(input) - 1:
                continue

        # Ignore specified characters
        if ignore_characters and char in ignore_characters:
            continue

        # Check character types
        if count_alphabet and char.isalpha():
            if not case_sensitive:
                char = char.lower()
            count += 1
            frequency[char] = frequency.get(char, 0) + 1
        elif count_digit and char.isdigit():
            count += 1
            frequency[char] = frequency.get(char, 0) + 1
        elif count_special and not char.isalnum():
            count += 1
            frequency[char] = frequency.get(char, 0) + 1

    # Return result in specified format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'Total count: {count}'
    elif output_format == 'json':
        return {'total_count': count, 'frequency': frequency}

