def date_calculator(input_date, operation, unit, value, output_format='YYYY-MM-DD', time_zone='UTC', business_days_only=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for input_date
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid input_date format. Expected YYYY-MM-DD.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date_obj = tz.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone specified.'}

    # Perform the operation
    if operation == 'add':
        if unit == 'days':
            date_obj += timedelta(days=value)
        elif unit == 'months':
            date_obj += relativedelta(months=value)
        elif unit == 'years':
            date_obj += relativedelta(years=value)
        else:
            return {'error': 'Invalid unit specified. Must be days, months, or years.'}
    elif operation == 'subtract':
        if unit == 'days':
            date_obj -= timedelta(days=value)
        elif unit == 'months':
            date_obj -= relativedelta(months=value)
        elif unit == 'years':
            date_obj -= relativedelta(years=value)
        else:
            return {'error': 'Invalid unit specified. Must be days, months, or years.'}
    else:
        return {'error': 'Invalid operation specified. Must be add or subtract.'}

    # Handle business days only
    if business_days_only:
        while date_obj.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
            date_obj -= timedelta(days=1)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        result_date = date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        result_date = date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        result_date = date_obj.strftime('%d-%m-%Y')
    elif output_format == 'ISO-8601':
        result_date = date_obj.isoformat()
    else:
        return {'error': 'Invalid output_format specified.'}

    return {'result_date': result_date}

