def string_length_counter(input, include_special_characters=False, output_format='integer', case_sensitive=False, count_words=False):
    """
    Analyzes the composition of a given string, counting letters, words, and special characters.

    Parameters:
    - input (str): The string to be analyzed.
    - include_special_characters (bool): Whether to include special characters in the count.
    - output_format (str): The format of the output ('integer', 'text', 'detailed').
    - case_sensitive (bool): Whether the count should be case-sensitive.
    - count_words (bool): Whether to include a word count in the analysis.

    Returns:
    - Depending on the output_format, returns an integer, text, or detailed breakdown.
    """
    if not isinstance(input, str):
        return "Error: 'input' must be a string."
    if not isinstance(include_special_characters, bool):
        return "Error: 'include_special_characters' must be a boolean."
    if output_format not in ['integer', 'text', 'detailed']:
        return "Error: 'output_format' must be one of ['integer', 'text', 'detailed']."
    if not isinstance(case_sensitive, bool):
        return "Error: 'case_sensitive' must be a boolean."
    if not isinstance(count_words, bool):
        return "Error: 'count_words' must be a boolean."

    # Adjust string based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Initialize counts
    letter_count = 0
    special_char_count = 0
    word_count = 0

    # Count letters and special characters
    for char in input:
        if char.isalpha():
            letter_count += 1
        elif not char.isalnum():
            special_char_count += 1

    # Count words if required
    if count_words:
        word_count = len(input.split())

    # Prepare output based on format
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f"The string contains {letter_count} letters."
    elif output_format == 'detailed':
        details = {
            'letters': letter_count,
            'special_characters': special_char_count if include_special_characters else 0,
            'words': word_count
        }
        return details

