    for string in input:
        for char in string:
            # Handle spaces
            if char == ' ' and not include_spaces:
                continue
            # Handle non-letter characters
            if ignore_non_letters and not char.isalpha():
                continue
            # Handle case sensitivity
            if not case_sensitive:
                char = char.lower()
            # Count the character
            if char in letter_count:
                letter_count[char] += 1
            else:
                letter_count[char] = 1

    # Format output
    if output_format == 'integer':
        return sum(letter_count.values())
    elif output_format == 'text':
