def extract_last_name(full_name, delimiter=[' '], name_format='first_last', handle_special_characters=False, script_type='latin'):
    # Validate required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Validate optional parameters
    if not isinstance(delimiter, list) or not all(isinstance(d, str) for d in delimiter):
        return {'error': 'Invalid delimiter. It must be a list of strings.'}
    if name_format not in ['first_last', 'first_middle_last', 'last_first', 'last_first_middle', 'prefix_first_last', 'first_last_suffix', 'prefix_first_middle_last_suffix']:
        return {'error': 'Invalid name_format. Unsupported format provided.'}
    if not isinstance(handle_special_characters, bool):
        return {'error': 'Invalid handle_special_characters. It must be a boolean.'}
    if script_type not in ['latin', 'non-latin']:
        return {'error': 'Invalid script_type. It must be either "latin" or "non-latin".'}

    # Split the full name using the provided delimiters
    import re
    pattern = '|'.join(map(re.escape, delimiter))
    name_parts = re.split(pattern, full_name)

    # Determine the last name based on the name format
    last_name = ''
    if name_format == 'first_last':
        last_name = name_parts[-1] if len(name_parts) >= 2 else ''
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1] if len(name_parts) >= 3 else ''
    elif name_format == 'last_first':
        last_name = name_parts[0] if len(name_parts) >= 2 else ''
    elif name_format == 'last_first_middle':
        last_name = name_parts[0] if len(name_parts) >= 3 else ''
    elif name_format == 'prefix_first_last':
        last_name = name_parts[-1] if len(name_parts) >= 3 else ''
    elif name_format == 'first_last_suffix':
        last_name = name_parts[-2] if len(name_parts) >= 3 else ''
    elif name_format == 'prefix_first_middle_last_suffix':
        last_name = name_parts[-2] if len(name_parts) >= 5 else ''

    # Handle special characters if required
    if handle_special_characters:
        last_name = re.sub(r'[^\w\s]', '', last_name)

    # Return the extracted last name
    return {'last_name': last_name.strip()}

