    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 20:
        return {'error': 'Input must be a list of 1 to 20 strings.'}
    if ignore_characters and not isinstance(ignore_characters, list):
        return {'error': 'ignore_characters must be a list of strings.'}
    if ignore_position and not all(pos in ['first', 'last', 'middle'] for pos in ignore_position):
        return {'error': 'ignore_position must be a list containing any of ["first", "last", "middle"].'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(ignore_numbers, bool):
        return {'error': 'ignore_numbers must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'output_format must be one of ["integer", "text", "detailed"].'}

    # Initialize count
    total_count = 0
    detailed_counts = []

    # Process each string
    for string in input:
        original_string = string
        if not case_sensitive:
            string = string.lower()
        if ignore_numbers:
            string = ''.join(filter(lambda x: not x.isdigit(), string))
        if ignore_characters:
            string = ''.join(filter(lambda x: x not in ignore_characters, string))
        if ignore_position:
            if 'first' in ignore_position and len(string) > 0:
                string = string[1:]
            if 'last' in ignore_position and len(string) > 0:
                string = string[:-1]
            if 'middle' in ignore_position and len(string) > 2:
                string = string[0] + string[1:-1].replace(string[1:-1], '') + string[-1]

        # Count letters
        count = sum(1 for char in string if char.isalpha())
        total_count += count
        detailed_counts.append({'string': original_string, 'count': count})

    # Return result based on output_format
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total letter count: {total_count}'
