    if ignore_characters is None:
        ignore_characters = []
    if ignore_position is None:
        ignore_position = []
    if ignore_range is None:
        ignore_range = []

    # Validate parameter types
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'Invalid ignore_characters type. Must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last', 'even', 'odd'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position type. Must be a list with valid position strings.'}
    if not isinstance(ignore_range, list) or len(ignore_range) != 2 or not all(isinstance(i, int) for i in ignore_range):
        return {'error': 'Invalid ignore_range type. Must be a list of two integers.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: integer, text, detailed.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

