        return {'error': 'input_date and operation are required parameters.'}

    # Parse the input date
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'input_date must be in YYYY-MM-DD format.'}

    # Adjust for time zone
    try:
        timezone = pytz.timezone(time_zone)
        date_obj = timezone.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone specified.'}

    # Perform the operation
    if operation == 'subtract':
        if not time_unit or not amount:
