        if time_unit == 'days':
            result_date = date_obj - relativedelta(days=amount)
        elif time_unit == 'months':
            result_date = date_obj - relativedelta(months=amount)
        elif time_unit == 'years':
            result_date = date_obj - relativedelta(years=amount)
        else:
            return {'error': 'Invalid time_unit specified.'}
    else:
        return {'error': 'Unsupported operation for this question.'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = result_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = result_date.strftime('%d-%m-%Y')
    elif output_format == 'DD/MM/YYYY':
        formatted_date = result_date.strftime('%d/%m/%Y')
    elif output_format == 'YYYY/MM/DD':
