import pytz

# Function to calculate the adjusted date

def date_calculator(input_date: str, adjustment: dict, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', consider_leap_year: bool = True) -> str:
    try:
        # Parse the input date
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')

        # Handle time zone
        if time_zone:
            try:
                tz = pytz.timezone(time_zone)
                date_obj = tz.localize(date_obj)
            except pytz.UnknownTimeZoneError:
                return 'Error: Unknown time zone specified.'

        # Extract adjustment details
        value = adjustment.get('value')
        unit = adjustment.get('unit')
        business_days_only = adjustment.get('business_days_only', False)

        # Validate adjustment parameters
        if unit not in ['days', 'weeks', 'months', 'years']:
            return 'Error: Invalid unit specified for adjustment.'

        # Perform date adjustment
        if unit == 'days':
            delta = timedelta(days=value)
        elif unit == 'weeks':
            delta = timedelta(weeks=value)
        elif unit == 'months':
            delta = relativedelta(months=value)
        elif unit == 'years':
            delta = relativedelta(years=value)

        # Adjust date
        adjusted_date = date_obj - delta

        # Consider leap year if necessary
        if consider_leap_year and unit == 'years':
            if date_obj.month == 2 and date_obj.day == 29:
                if not (adjusted_date.year % 4 == 0 and (adjusted_date.year % 100 != 0 or adjusted_date.year % 400 == 0)):
                    adjusted_date = adjusted_date.replace(day=28)

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            formatted_date = adjusted_date.strftime('%Y-%m-%d')
        elif output_format == 'MM-DD-YYYY':
            formatted_date = adjusted_date.strftime('%m-%d-%Y')
        elif output_format == 'DD-MM-YYYY':
            formatted_date = adjusted_date.strftime('%d-%m-%Y')
        else:
            return 'Error: Invalid output format specified.'

        return formatted_date

    except ValueError as e:
        return f'Error: {str(e)}'

