def ascii_converter(characters, output_format='integer', error_handling='default'):
    """
    Convert a list of characters to their ASCII codes.

    Parameters:
    - characters (list of str): An array of single characters to be converted.
    - output_format (str): The format of the ASCII code output ('integer', 'hexadecimal', 'binary').
    - error_handling (str): The method for handling invalid inputs ('default', 'error_message', 'ignore_invalid').

    Returns:
    - list: A list of ASCII codes in the specified format or error messages.
    """
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")

    if output_format not in ['integer', 'hexadecimal', 'binary']:
        raise ValueError("'output_format' must be one of 'integer', 'hexadecimal', 'binary'.")

    if error_handling not in ['default', 'error_message', 'ignore_invalid']:
        raise ValueError("'error_handling' must be one of 'default', 'error_message', 'ignore_invalid'.")

    ascii_codes = []
    for char in characters:
        try:
            ascii_code = ord(char)
            if output_format == 'hexadecimal':
                ascii_code = hex(ascii_code)
            elif output_format == 'binary':
                ascii_code = bin(ascii_code)
            ascii_codes.append(ascii_code)
        except Exception as e:
            if error_handling == 'default':
                ascii_codes.append(-1)
            elif error_handling == 'error_message':
                ascii_codes.append(f"Error converting '{char}': {str(e)}")
            elif error_handling == 'ignore_invalid':
                continue
    return ascii_codes

