def extract_first_character(input, ignore_whitespace=True, case_sensitive=True, character_type='letter', handle_empty_input='return_null'):
    # Check for empty input
    if not input:
        if handle_empty_input == 'return_null':
            return None
        elif handle_empty_input == 'return_empty_string':
            return ''
        elif handle_empty_input == 'error':
            raise ValueError('Input cannot be empty')

    # Handle whitespace
    if ignore_whitespace:
        input = input.lstrip()

    # Define character type checks
    def is_letter(char):
        return char.isalpha()

    def is_number(char):
        return char.isdigit()

    def is_symbol(char):
        return not char.isalnum() and not char.isspace()

    # Iterate over characters to find the first matching character
    for char in input:
        if character_type == 'letter' and is_letter(char):
            return char if case_sensitive else char.lower()
        elif character_type == 'number' and is_number(char):
            return char
        elif character_type == 'symbol' and is_symbol(char):
            return char
        elif character_type == 'any':
            return char if case_sensitive else char.lower()

    # If no character is found, return based on handle_empty_input
    if handle_empty_input == 'return_null':
        return None
    elif handle_empty_input == 'return_empty_string':
        return ''
    elif handle_empty_input == 'error':
        raise ValueError('No valid character found')

