def char_to_binary(characters, bit_format='8-bit', output_format='array', encoding='ASCII', delimiter=' '):
    # Validate input parameters
    if not characters or not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid characters input. Must be a list of single-character strings.'}
    if bit_format not in ['8-bit', '16-bit', '32-bit']:
        return {'error': 'Invalid bit_format. Must be one of: 8-bit, 16-bit, 32-bit.'}
    if output_format not in ['string', 'array']:
        return {'error': 'Invalid output_format. Must be one of: string, array.'}
    if encoding not in ['ASCII', 'UTF-8']:
        return {'error': 'Invalid encoding. Must be one of: ASCII, UTF-8.'}

    # Determine the number of bits for the binary format
    bit_length = int(bit_format.split('-')[0])

    # Convert characters to binary
    binary_codes = []
    for char in characters:
        if encoding == 'ASCII':
            binary_code = format(ord(char), f'0{bit_length}b')
        elif encoding == 'UTF-8':
            binary_code = ''.join(format(byte, f'0{bit_length}b') for byte in char.encode('utf-8'))
        binary_codes.append(binary_code)

    # Format the output
    if output_format == 'string':
        return delimiter.join(binary_codes)
    else:
