def advanced_date_calculator(start_date: str, duration: int, unit: str, output_format: str = 'date', business_days_only: bool = False, holidays: list = None, time_zone: str = None):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate unit
    if unit not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid unit. Must be one of days, weeks, months, years.'}

    # Calculate new date based on unit
    if unit == 'days':
        new_date = start_date_obj + timedelta(days=duration)
    elif unit == 'weeks':
        new_date = start_date_obj + timedelta(weeks=duration)
    elif unit == 'months':
        new_date = start_date_obj + relativedelta(months=duration)
    elif unit == 'years':
        new_date = start_date_obj + relativedelta(years=duration)

    # Handle output_format
    if output_format == 'date':
        result = new_date.strftime('%Y-%m-%d')
    elif output_format == 'text':
        result = new_date.strftime('%A, %B %d, %Y')
    elif output_format == 'timestamp':
        result = int(new_date.timestamp())
    else:
        return {'error': 'Invalid output_format. Must be one of date, text, timestamp.'}

    return {'result': result}

