    # Error handling for invalid parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'string', 'json', 'csv']:
        raise ValueError("'output_format' must be one of 'list', 'string', 'json', 'csv'.")
    if handle_non_ascii not in ['ignore', 'replace', 'error']:
        raise ValueError("'handle_non_ascii' must be one of 'ignore', 'replace', 'error'.")

    ascii_codes = []
    for char in characters:
        try:
            ascii_code = ord(char)
            if ascii_code > 127:  # Non-ASCII character
                if handle_non_ascii == 'ignore':
                    continue
                elif handle_non_ascii == 'replace':
                    ascii_code = ord('?')  # Replace with '?' character
                elif handle_non_ascii == 'error':
                    raise ValueError(f"Non-ASCII character found: {char}")
            ascii_codes.append((char, ascii_code))
        except TypeError:
            raise ValueError(f"Invalid character input: {char}")

    # Format the output
    if output_format == 'list':
        return [code for _, code in ascii_codes]
    elif output_format == 'string':
        return ''.join(str(code) for _, code in ascii_codes)
    elif output_format == 'json':
        return {char: code for char, code in ascii_codes}
    elif output_format == 'csv':
        return ','.join(f"{char}:{code}" for char, code in ascii_codes)

