    # Error handling for invalid inputs
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It should be a non-empty string.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid delimiter. It should be a string.'}
    if not isinstance(handle_suffix, bool):
        return {'error': 'Invalid handle_suffix. It should be a boolean.'}
    if not isinstance(handle_middle_names, bool):
        return {'error': 'Invalid handle_middle_names. It should be a boolean.'}
    if not isinstance(cultural_convention, str):
        return {'error': 'Invalid cultural_convention. It should be a string.'}
    if not isinstance(multiple_delimiters, list) or not all(isinstance(d, str) for d in multiple_delimiters):
        return {'error': 'Invalid multiple_delimiters. It should be a list of strings.'}
    if not isinstance(return_structured_name, bool):
        return {'error': 'Invalid return_structured_name. It should be a boolean.'}

    # Determine the delimiters to use
    delimiters = multiple_delimiters if multiple_delimiters else [delimiter]

    # Split the full name using the delimiters
    import re
    regex_pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(regex_pattern, full_name)

    # Handle cultural conventions
    if cultural_convention == 'Western':
        # Western convention: Last name is typically the last part
        last_name = name_parts[-1]
        if handle_suffix and len(name_parts) > 1 and name_parts[-1].lower() in ['jr', 'sr', 'ii', 'iii']:
            last_name = name_parts[-2] + ' ' + name_parts[-1]
    elif cultural_convention == 'Eastern':
        # Eastern convention: Last name is typically the first part
        last_name = name_parts[0]
    else:
        return {'error': 'Unsupported cultural convention.'}

    # Return structured name if requested
    if return_structured_name:
        structured_name = {'first_name': name_parts[0], 'middle_names': name_parts[1:-1], 'last_name': last_name}
        return structured_name

