def character_counter(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, count_types=['alphabets', 'digits', 'special_characters']):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Ignore position must be a list containing "first" or "last".'}
    if output_format not in ['integer', 'text', 'detailed_report']:
        return {'error': 'Output format must be one of "integer", "text", "detailed_report".'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if not isinstance(count_types, list) or not all(ct in ['alphabets', 'digits', 'special_characters'] for ct in count_types):
        return {'error': 'Count types must be a list containing "alphabets", "digits", "special_characters".'}

    # Prepare the input string
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Ignore specified positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]

    # Count characters
    count = 0
    detailed_count = {'alphabets': 0, 'digits': 0, 'special_characters': 0}
    for char in input:
        if char in ignore_characters:
            continue
        if 'alphabets' in count_types and char.isalpha():
            count += 1
            detailed_count['alphabets'] += 1
        elif 'digits' in count_types and char.isdigit():
            count += 1
            detailed_count['digits'] += 1
        elif 'special_characters' in count_types and not char.isalnum():
            count += 1
            detailed_count['special_characters'] += 1

    # Return result based on output format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'Total count: {count}'
    elif output_format == 'detailed_report':
        return detailed_count

