def date_calculator(start_date, duration, calendar_system='gregorian', output_format='YYYY-MM-DD', time_zone='UTC', business_days_only=False):
    from datetime import datetime, timedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate duration
    if not isinstance(duration, dict) or 'value' not in duration or 'unit' not in duration:
        return {'error': 'Invalid duration. Expected a dictionary with keys value and unit.'}

    value = duration['value']
    unit = duration['unit']

    if unit not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid duration unit. Expected one of days, weeks, months, years.'}

    # Calculate new date based on duration
    if unit == 'days':
        delta = timedelta(days=value)
    elif unit == 'weeks':
        delta = timedelta(weeks=value)
    elif unit == 'months':
        # Simplified month calculation
        month = (start_date_obj.month - 1 + value) % 12 + 1
        year = start_date_obj.year + (start_date_obj.month - 1 + value) // 12
        day = min(start_date_obj.day, [31, 29 if year % 4 == 0 and (year % 100 != 0 or year % 400 == 0) else 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month-1])
        new_date = start_date_obj.replace(year=year, month=month, day=day)
        return {'date': new_date.strftime(output_format)}
    elif unit == 'years':
        try:
            new_date = start_date_obj.replace(year=start_date_obj.year + value)
        except ValueError:
            # Handle February 29th for non-leap years
            new_date = start_date_obj.replace(year=start_date_obj.year + value, day=28)
        return {'date': new_date.strftime(output_format)}

    # Apply delta for days and weeks
    new_date = start_date_obj + delta

    # Format the output date
    formatted_date = new_date.strftime(output_format)

    return {'date': formatted_date}

