def string_length_counter(input, ignore_characters=None, ignore_position=None, output_format='integer', case_sensitive=False, character_type='all', language='en'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if len(input) < 1 or len(input) > 10:
        return {'error': 'Invalid input: input list must contain between 1 and 10 strings.'}

    # Initialize count
    total_count = 0
    detailed_count = {'vowels': 0, 'consonants': 0, 'digits': 0, 'special': 0}

    # Define helper functions
    def is_vowel(char):
        return char.lower() in 'aeiou'

    def is_consonant(char):
        return char.isalpha() and not is_vowel(char)

    # Process each string
    for string in input:
        # Apply case sensitivity
        if not case_sensitive:
            string = string.lower()

        # Ignore specified positions
        if ignore_position:
            if 'first' in ignore_position and len(string) > 0:
                string = string[1:]
            if 'last' in ignore_position and len(string) > 0:
                string = string[:-1]

        # Count characters
        for char in string:
            if ignore_characters and char in ignore_characters:
                continue
            if character_type == 'vowels' and not is_vowel(char):
                continue
            if character_type == 'consonants' and not is_consonant(char):
                continue
            if character_type == 'digits' and not char.isdigit():
                continue
            if character_type == 'special' and char.isalnum():
                continue

            total_count += 1
            if output_format == 'detailed':
                if is_vowel(char):
                    detailed_count['vowels'] += 1
                elif is_consonant(char):
                    detailed_count['consonants'] += 1
                elif char.isdigit():
                    detailed_count['digits'] += 1
                else:
                    detailed_count['special'] += 1

    # Return result based on output format
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total count: {total_count}'
    elif output_format == 'detailed':
        return {'total': total_count, 'breakdown': detailed_count}
    else:
        return {'error': 'Invalid output format specified.'}

