def first_letter_extractor_v2(names, case_sensitive=True, output_format='array', error_handling='warn'):
    """
    Extracts the first letter from each name in the provided list of names.

    Parameters:
    - names (list of str): A list of names from which the first letters will be extracted.
    - case_sensitive (bool): Determines if the output should preserve the case of the first letter(s).
    - output_format (str): Specifies the format of the output ('string' or 'array').
    - error_handling (str): Defines how to handle errors ('ignore', 'warn', 'strict').

    Returns:
    - A string or array of first letters based on the output_format.
    """
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        if error_handling == 'strict':
            raise ValueError("All items in 'names' must be non-empty strings.")
        elif error_handling == 'warn':
            print("Warning: Some items in 'names' are not strings.")
        names = [name for name in names if isinstance(name, str)]

    first_letters = []
    for name in names:
        if name:
            first_letter = name[0] if case_sensitive else name[0].lower()
            first_letters.append(first_letter)
        else:
            if error_handling == 'strict':
                raise ValueError("Empty string found in 'names'.")
            elif error_handling == 'warn':
                print("Warning: Empty string found in 'names'.")

    if output_format == 'string':
        return ''.join(first_letters)
    return first_letters

