    """
    Extracts the last digit from a given number with customizable options.
    """
    import re

    # Handle non-numeric characters if specified
    if handle_non_numeric:
        number = ''.join(filter(str.isdigit, number))
        if not number:
            return 'Error: No numeric characters found.'

    # Convert to string if not already
    number_str = str(number)

    # Handle negative sign
    if ignore_negative_sign and number_str.startswith('-'):
        number_str = number_str[1:]

    # Handle decimal points
    if decimal_handling == 'consider' and '.' in number_str:
        number_str = number_str.split('.')[-1]
    elif decimal_handling == 'ignore' and '.' in number_str:
        number_str = number_str.split('.')[0]

    # Extract the last digit
    if not number_str:
        return 'Error: No digits to extract.'
    last_digit = number_str[-1]

    # Format the output
    if output_format == 'integer':
        return int(last_digit)
    elif output_format == 'string':
        return last_digit
    elif output_format == 'character':
        return last_digit
    else:
        return 'Error: Invalid output format.'

