def first_digit_extractor_v2(number: str, ignore_sign: bool = True, ignore_leading_zeros: bool = True, output_format: str = 'string', scientific_notation_support: bool = False, decimal_handling: str = 'ignore'):
    """
    Extracts the first digit from the given number string based on the specified parameters.
    """
    import re

    # Error handling for invalid output_format
    if output_format not in ['integer', 'string', 'json']:
        return {'error': 'Invalid output_format. Must be one of: integer, string, json.'}

    # Error handling for invalid decimal_handling
    if decimal_handling not in ['ignore', 'consider']:
        return {'error': 'Invalid decimal_handling. Must be one of: ignore, consider.'}

    # Handle scientific notation if supported
    if scientific_notation_support:
        try:
            number = f'{float(number):.15g}'  # Convert to standard float representation
        except ValueError:
            return {'error': 'Invalid number format for scientific notation.'}

    # Remove sign if ignore_sign is True
    if ignore_sign:
        number = number.lstrip('-+')

    # Consider decimal handling
    if decimal_handling == 'ignore':
        number = number.split('.')[0]

    # Remove leading zeros if ignore_leading_zeros is True
    if ignore_leading_zeros:
        number = number.lstrip('0')

    # Use regex to find the first digit
    match = re.search(r'\d', number)
    if not match:
        return {'error': 'No digits found in the input.'}

    first_digit = match.group(0)

    # Format the output based on output_format
    if output_format == 'integer':
        return int(first_digit)
    elif output_format == 'json':
        return {'first_digit': first_digit}
    else:
        return first_digit

