def last_digit_extractor(number: str, ignore_sign: bool = True, output_format: str = 'integer', numeral_system: str = 'decimal', decimal_precision: int = 0, validate_input: bool = True):
    """
    Extracts the last digit from a given number based on the specified parameters.
    """
    import re

    # Validate input if required
    if validate_input:
        if numeral_system == 'decimal':
            pattern = r'^-?\d+(\.\d+)?$'
        elif numeral_system == 'binary':
            pattern = r'^-?[01]+(\.[01]+)?$'
        elif numeral_system == 'hexadecimal':
            pattern = r'^-?[0-9a-fA-F]+(\.[0-9a-fA-F]+)?$'
        elif numeral_system == 'octal':
            pattern = r'^-?[0-7]+(\.[0-7]+)?$'
        else:
            return {'error': 'Unsupported numeral system'}

        if not re.match(pattern, number):
            return {'error': 'Invalid number format for the specified numeral system'}

    # Handle sign if ignore_sign is True
    if ignore_sign:
        number = number.lstrip('-')

    # Convert number to integer based on numeral system
    if numeral_system == 'decimal':
        base = 10
    elif numeral_system == 'binary':
        base = 2
    elif numeral_system == 'hexadecimal':
        base = 16
    elif numeral_system == 'octal':
        base = 8
    else:
        return {'error': 'Unsupported numeral system'}

    try:
        # Handle decimal precision
        if '.' in number and decimal_precision > 0:
            integer_part, decimal_part = number.split('.')
            decimal_part = decimal_part[:decimal_precision]
            number = integer_part + decimal_part

        # Convert to integer
        num = int(number, base)
    except ValueError:
        return {'error': 'Error converting number to integer'}

    # Extract last digit
    last_digit = str(num)[-1]

    # Format output
    if output_format == 'integer':
        return int(last_digit)
    elif output_format == 'string':
        return last_digit
    else:
        return {'error': 'Unsupported output format'}

