    # Validate input
    if not isinstance(input, list) or len(input) < 1:
        return 'Error: Input must be a non-empty list.'
    if not all(isinstance(i, (str, int, float)) for i in input):
        return 'Error: All items in input must be strings, integers, or floats.'
    if not isinstance(separator, str):
        return 'Error: Separator must be a string.'
    if output_format != 'string':
        return 'Error: Output format must be "string".'
    if case_transform not in ['none', 'uppercase', 'lowercase']:
        return 'Error: Case transform must be "none", "uppercase", or "lowercase".'
    if not isinstance(trim_whitespace, bool):
        return 'Error: Trim whitespace must be a boolean.'

    # Prepare input values
    processed_input = []
    for item in input:
        if isinstance(item, (int, float)):
            item = str(item)
        if trim_whitespace:
            item = item.strip()
        processed_input.append(item)

    # Concatenate values
    result = separator.join(processed_input)

    # Apply case transformation
    if case_transform == 'uppercase':
        result = result.upper()
    elif case_transform == 'lowercase':
        result = result.lower()

    return result

