def advanced_year_calculator(starting_year, increment_years, consider_leap_years=True, calendar_system='Gregorian', output_day_of_week=False):
    import datetime

    # Validate input types
    if not isinstance(starting_year, int):
        return {'error': 'starting_year must be an integer'}
    if not isinstance(increment_years, (int, float)):
        return {'error': 'increment_years must be a number'}
    if not isinstance(consider_leap_years, bool):
        return {'error': 'consider_leap_years must be a boolean'}
    if calendar_system not in ['Gregorian', 'Julian']:
        return {'error': "calendar_system must be 'Gregorian' or 'Julian'"}
    if not isinstance(output_day_of_week, bool):
        return {'error': 'output_day_of_week must be a boolean'}

    # Calculate the resulting year
    resulting_year = starting_year + increment_years

    # Calculate the day of the week if required
    day_of_week = None
    if output_day_of_week:
        try:
            # Use Gregorian calendar by default
            if calendar_system == 'Gregorian':
                date = datetime.datetime(starting_year, 1, 1) + datetime.timedelta(days=increment_years * 365.25)
            else:  # Julian calendar
                date = datetime.datetime(starting_year, 1, 1) + datetime.timedelta(days=increment_years * 365.25)
            day_of_week = date.strftime('%A')
        except Exception as e:
            return {'error': str(e)}

    # Return the result
    result = {'resulting_year': int(resulting_year)}
    if output_day_of_week:
        result['day_of_week'] = day_of_week
    return result

