            name = name.lstrip(string.punctuation)
        return name[0] if name else None

    results = []
    for name in names:
        if not isinstance(name, str) or (not name and not handle_empty):
            if error_handling == 'raise':
                raise ValueError('Invalid name encountered.')
            elif error_handling == 'skip':
                continue
            elif error_handling == 'default':
                results.append('?')
                continue

        first_char = get_first_valid_char(name)
        if first_char is None:
            if error_handling == 'raise':
                raise ValueError('Empty string encountered.')
            elif error_handling == 'skip':
                continue
            elif error_handling == 'default':
                results.append('?')
                continue

        if output_format == 'uppercase':
            results.append(first_char.upper())
        elif output_format == 'lowercase':
            results.append(first_char.lower())
        elif output_format == 'ascii':
            results.append(ord(first_char))
        elif output_format == 'unicode':
            results.append(f'U+{ord(first_char):04X}')
        else:  # Default to 'character'
