def ascii_converter_v2(characters, handle_non_ascii='error', replacement_character='?', include_extended_info=False):
    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if handle_non_ascii not in ['error', 'ignore', 'message', 'replace']:
        raise ValueError("'handle_non_ascii' must be one of 'error', 'ignore', 'message', 'replace'.")
    if not isinstance(replacement_character, str) or len(replacement_character) != 1:
        raise ValueError("'replacement_character' must be a single character string.")
    if not isinstance(include_extended_info, bool):
        raise ValueError("'include_extended_info' must be a boolean.")

    results = []
    for char in characters:
        ascii_code = ord(char)
        if ascii_code > 127:  # Non-ASCII character
            if handle_non_ascii == 'error':
                raise ValueError(f"Non-ASCII character encountered: {char}")
            elif handle_non_ascii == 'ignore':
                continue
            elif handle_non_ascii == 'message':
                results.append({'character': char, 'message': 'Non-ASCII character'})
                continue
            elif handle_non_ascii == 'replace':
                char = replacement_character
                ascii_code = ord(char)
        result = {'character': char, 'ascii': ascii_code}
        if include_extended_info:
            result.update({
                'binary': bin(ascii_code),
                'hex': hex(ascii_code)
            })
        results.append(result)
    return results

