        if 'punctuation' in ignore_character_classes and not char.isalnum() and not char.isspace():
            return True
        if 'first' in ignore_position and index == 0:
            return True
        if 'last' in ignore_position and index == len(input) - 1:
            return True
        if 'even' in ignore_position and index % 2 == 0:
            return True
        if 'odd' in ignore_position and index % 2 != 0:
            return True
        return False

    # Count characters
    for index, char in enumerate(input):
        if not is_ignored(char, index):
            count += 1
            if output_format == 'detailed':
                if char.isalpha():
                    detailed_count['letters'] += 1
                elif char.isdigit():
                    detailed_count['digits'] += 1
                elif char.isspace():
                    detailed_count['whitespace'] += 1
                else:
                    detailed_count['punctuation'] += 1

    # Return result based on output_format
    if output_format == 'integer':
        return str(count)
    elif output_format == 'text':
        return f'The string contains {count} characters.'
    elif output_format == 'detailed':
        return str(detailed_count)

