def extract_first_name(full_name, naming_convention='western', delimiter=' ', include_middle_name=False, suffix_handling='ignore', custom_convention_pattern=None):
    # Validate the 'full_name' parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name: must be a non-empty string.'}

    # Validate the 'naming_convention' parameter
    if naming_convention not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid naming_convention: must be one of ["western", "eastern", "custom"].'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle different naming conventions
    if naming_convention == 'western':
        # Western convention assumes the first part is the first name
        first_name = name_parts[0]
    elif naming_convention == 'eastern':
        # Eastern convention assumes the last part is the first name
        first_name = name_parts[-1]
    elif naming_convention == 'custom' and custom_convention_pattern:
        import re
        match = re.match(custom_convention_pattern, full_name)
        if match:
            first_name = match.group(1)  # Assuming the first capturing group is the first name
        else:
            return {'error': 'Custom pattern did not match the full name.'}
    else:
        return {'error': 'Custom naming convention requires a valid regex pattern.'}

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + ' '.join(name_parts[1:-1])

    # Handle suffix according to the specified handling
    if suffix_handling == 'include' and len(name_parts) > 1:
        first_name += ' ' + name_parts[-1]
    elif suffix_handling == 'separate' and len(name_parts) > 1:
        suffix = name_parts[-1]
        return {'first_name': first_name, 'suffix': suffix}

    return {'first_name': first_name}

