def character_counter(input, ignore_characters=[], ignore_position=[], ignore_position_range=[], case_sensitive=False, character_types=[], output_format='integer'):
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(p in ['first', 'last', 'even', 'odd', 'range'] for p in ignore_position):
        return {'error': 'Ignore position must be a list containing valid options.'}
    if not isinstance(ignore_position_range, list) or len(ignore_position_range) not in [0, 2] or not all(isinstance(i, int) for i in ignore_position_range):
        return {'error': 'Ignore position range must be a list of two integers.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if not isinstance(character_types, list) or not all(t in ['vowels', 'consonants', 'digits', 'special'] for t in character_types):
        return {'error': 'Character types must be a list containing valid options.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Output format must be one of: integer, text, detailed.'}

    # Normalize case if not case-sensitive
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Filter characters based on ignore_characters
    filtered_input = ''.join(c for c in input if c not in ignore_characters)

    # Filter positions
    if 'first' in ignore_position:
        filtered_input = filtered_input[1:]
    if 'last' in ignore_position:
        filtered_input = filtered_input[:-1]
    if 'even' in ignore_position:
        filtered_input = ''.join(c for i, c in enumerate(filtered_input) if i % 2 != 0)
    if 'odd' in ignore_position:
        filtered_input = ''.join(c for i, c in enumerate(filtered_input) if i % 2 == 0)
    if 'range' in ignore_position and len(ignore_position_range) == 2:
        start, end = ignore_position_range
        filtered_input = filtered_input[:start] + filtered_input[end+1:]

    # Count characters based on character_types
    if character_types:
        count = 0
        for c in filtered_input:
            if ('vowels' in character_types and c in 'aeiou') or \
               ('consonants' in character_types and c.isalpha() and c not in 'aeiou') or \
               ('digits' in character_types and c.isdigit()) or \
               ('special' in character_types and not c.isalnum()):
                count += 1
    else:
        count = len(filtered_input)

    # Return result based on output_format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The string contains {count} characters.'
    elif output_format == 'detailed':
        detail = {'vowels': 0, 'consonants': 0, 'digits': 0, 'special': 0}
        for c in filtered_input:
            if c in 'aeiou':
                detail['vowels'] += 1
            elif c.isalpha():
                detail['consonants'] += 1
            elif c.isdigit():
                detail['digits'] += 1
            else:
                detail['special'] += 1
        return detail

