        name_parts = [part.strip('.,') for part in name_parts]

    # Extract the desired component
    if component == 'first_name':
        if ignore_middle_names:
            return name_parts[0] if name_parts else ''
        else:
            return ' '.join(name_parts[:-1]) if len(name_parts) > 1 else name_parts[0]
    elif component == 'middle_name':
        return ' '.join(name_parts[1:-1]) if len(name_parts) > 2 else ''
    elif component == 'last_name':
        return name_parts[-1] if len(name_parts) > 1 else ''
    elif component == 'prefix':
        return name_parts[0] if len(name_parts) > 1 and name_parts[0].endswith('.') else ''
    elif component == 'suffix':
        return name_parts[-1] if len(name_parts) > 1 and name_parts[-1].endswith('.') else ''
    else:
        return {'error': 'Invalid component specified. Options are first_name, middle_name, last_name, prefix, suffix.'}

