def count_letters(input, ignore_characters=[], ignore_position=[], case_sensitive=False, character_set='alphabetic', custom_character_set=[], output_format='integer'):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Expected a string.'}

    # Validate ignore_characters parameter
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'Invalid ignore_characters type. Expected a list of strings.'}

    # Validate ignore_position parameter
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position value. Expected a list containing "first" or "last".'}

    # Validate case_sensitive parameter
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Expected a boolean.'}

    # Validate character_set parameter
    if character_set not in ['alphabetic', 'alphanumeric', 'custom']:
        return {'error': 'Invalid character_set value. Expected "alphabetic", "alphanumeric", or "custom".'}

    # Validate custom_character_set parameter
    if not isinstance(custom_character_set, list) or not all(isinstance(char, str) for char in custom_character_set):
        return {'error': 'Invalid custom_character_set type. Expected a list of strings.'}

    # Validate output_format parameter
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format value. Expected "integer", "text", or "detailed".'}

    # Prepare the character set
    if character_set == 'alphabetic':
        valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')
    elif character_set == 'alphanumeric':
        valid_chars = set('abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789')
    elif character_set == 'custom':
        valid_chars = set(custom_character_set)

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        valid_chars = set(char.lower() for char in valid_chars)
        ignore_characters = [char.lower() for char in ignore_characters]

    # Remove ignored characters
    input = ''.join(char for char in input if char not in ignore_characters)

    # Remove ignored positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]

    # Count valid characters
    count = 0
    detailed_count = {}
    for char in input:
        if char in valid_chars:
            count += 1
            if output_format == 'detailed':
                if char in detailed_count:
                    detailed_count[char] += 1
                else:
                    detailed_count[char] = 1

    # Prepare output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The count of letters is {count}.'
    elif output_format == 'detailed':
        return detailed_count

