def extract_first_letter(input, output_case='original', ignore_non_alpha=False, language_support='latin', handle_empty_strings=False, output_format='list'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        raise ValueError("Input must be a list of strings.")
    if len(input) < 1:
        raise ValueError("Input list must contain at least one string.")

    # Define a helper function to determine if a character is alphabetic based on language support
    def is_alpha(char, language):
        if language == 'latin':
            return char.isalpha()
        elif language == 'cyrillic':
            return 'А' <= char <= 'я' or 'Ё' <= char <= 'ё'
        elif language == 'greek':
            return 'Α' <= char <= 'ω' or 'ά' <= char <= 'ώ'
        else:
            raise ValueError("Unsupported language script.")

    # Process each string in the input list
    result = []
    for string in input:
        if handle_empty_strings and string == '':
            result.append('_')  # Placeholder for empty strings
            continue

        first_letter = None
        for char in string:
            if ignore_non_alpha and not is_alpha(char, language_support):
                continue
            first_letter = char
            break

        if first_letter is None:
            first_letter = ''

        # Adjust case if needed
        if output_case == 'uppercase':
            first_letter = first_letter.upper()
        elif output_case == 'lowercase':
            first_letter = first_letter.lower()

        result.append(first_letter)

    # Format the output
    if output_format == 'string':
        return ''.join(result)
    return result

