def ascii_lookup_plus(characters, output_format='list', error_handling='ignore'):
    """
    Retrieve ASCII codes for given characters with specified output format and error handling.

    :param characters: List of characters or ranges (e.g., ['a', 'b', 'c-d']).
    :param output_format: Format of the output ('list', 'string', 'json', 'csv').
    :param error_handling: How to handle invalid inputs ('ignore', 'report').
    :return: ASCII codes in the specified format.
    """
    import json

    def get_ascii_code(char):
        if len(char) == 1:
            return ord(char)
        elif '-' in char and len(char) == 3:
            start, end = char.split('-')
            if len(start) == 1 and len(end) == 1:
                return [ord(c) for c in range(ord(start), ord(end) + 1)]
        return None

    ascii_codes = {}
    errors = []

    for char in characters:
        result = get_ascii_code(char)
        if result is None:
            if error_handling == 'report':
                errors.append(f"Invalid character or range: {char}")
            continue
        if isinstance(result, list):
            for c in range(ord(char[0]), ord(char[2]) + 1):
                ascii_codes[chr(c)] = c
        else:
            ascii_codes[char] = result

    if output_format == 'list':
        output = list(ascii_codes.values())
    elif output_format == 'string':
        output = ''.join(map(str, ascii_codes.values()))
    elif output_format == 'json':
        output = json.dumps(ascii_codes)
    elif output_format == 'csv':
        output = ','.join(map(str, ascii_codes.values()))
    else:
        raise ValueError("Invalid output format specified.")

    if error_handling == 'report' and errors:
        return {'output': output, 'errors': errors}
    return output

