def reverse_order(input: str, output_format: str = 'string', handle_negative: bool = True, handle_decimal: bool = False, segment_reversal: list = [], character_encoding: str = 'UTF-8') -> str:
    """
    Reverse the order of characters in the input based on specified parameters.
    """
    # Error handling for unsupported character encoding
    if character_encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return 'Error: Unsupported character encoding.'

    # Handle negative numbers
    negative = ''
    if handle_negative and input.startswith('-'):
        negative = '-'
        input = input[1:]

    # Handle decimal numbers
    if handle_decimal and '.' in input:
        integer_part, decimal_part = input.split('.')
        reversed_input = negative + integer_part[::-1] + '.' + decimal_part[::-1]
    else:
        reversed_input = negative + input[::-1]

    # Handle segment reversal
    if segment_reversal:
        segments = [input[i:j] for i, j in zip([0]+segment_reversal, segment_reversal+[None])]
        reversed_segments = [seg[::-1] for seg in segments]
        reversed_input = ''.join(reversed_segments)

    # Convert to the desired output format
    if output_format == 'number':
        try:
            return float(reversed_input) if '.' in reversed_input else int(reversed_input)
        except ValueError:
            return 'Error: Cannot convert reversed input to number.'
    elif output_format == 'json':
        return {'reversed': reversed_input}
    elif output_format == 'array':
        return list(reversed_input)
    else:
        return reversed_input

