def count_letters(input: str, ignore_characters: list = None, ignore_position: list = None, output_format: str = 'integer', case_sensitive: bool = False, character_type_filter: list = ['all']):
    # Initialize defaults
    if ignore_characters is None:
        ignore_characters = []
    if ignore_position is None:
        ignore_position = []

    # Handle case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Define vowels and consonants
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Filter input based on ignore_characters
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Handle ignore_position
    if 'first' in ignore_position and len(filtered_input) > 0:
        filtered_input = filtered_input[1:]
    if 'last' in ignore_position and len(filtered_input) > 0:
        filtered_input = filtered_input[:-1]

    # Filter by character type
    if 'vowel' in character_type_filter:
        filtered_input = ''.join([char for char in filtered_input if char in vowels])
    elif 'consonant' in character_type_filter:
        filtered_input = ''.join([char for char in filtered_input if char in consonants])

    # Count letters
    letter_count = len(filtered_input)

    # Prepare output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for char in filtered_input if char in vowels)
        consonant_count = sum(1 for char in filtered_input if char in consonants)
        return {
            'total': letter_count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }
    else:
        raise ValueError('Invalid output format specified.')

