def string_length_counter_v2(input, ignore_characters=[], case_sensitive=False, ignore_whitespace=False, output_format='integer'):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 10:
        return {'error': 'Input must be a list with 1 to 10 items.'}

    # Flatten the input if it contains nested arrays
    flat_input = []
    for item in input:
        if isinstance(item, list):
            flat_input.extend(item)
        elif isinstance(item, str):
            flat_input.append(item)
        else:
            return {'error': 'Input items must be strings or arrays of strings.'}

    # Initialize character count
    total_length = 0

    # Process each string in the flattened input
    for string in flat_input:
        if not case_sensitive:
            string = string.lower()
            ignore_characters = [char.lower() for char in ignore_characters]

        if ignore_whitespace:
            string = string.replace(' ', '')

        # Count characters excluding ignored ones
        count = sum(1 for char in string if char not in ignore_characters)
        total_length += count

    # Format output
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'Total character count: {total_length}'
    elif output_format == 'json':
        return {'total_length': total_length}
    elif output_format == 'detailed_report':
        return {
            'total_length': total_length,
            'details': {
                'input': input,
                'ignore_characters': ignore_characters,
                'case_sensitive': case_sensitive,
                'ignore_whitespace': ignore_whitespace
            }
        }
    else:
        return {'error': 'Invalid output format specified.'}

