def advanced_arithmetic_calculator(number1, number2, operation='subtract', precision=None, safe_division=False):
    """
    Perform an arithmetic operation on two numbers with optional precision control and safe division.

    :param number1: The first number in the arithmetic operation, can be an integer or a floating-point.
    :param number2: The second number in the arithmetic operation, can be an integer or a floating-point.
    :param operation: The arithmetic operation to perform. Defaults to 'subtract'.
    :param precision: The number of decimal places to round the result to, applicable for operations involving floating-point numbers.
    :param safe_division: A flag to enable safe division, which returns 'Infinity' or 'NaN' instead of throwing an error when dividing by zero.
    :return: The result of the arithmetic operation, rounded to the specified precision if applicable.
    """
    try:
        if operation == 'subtract':
            result = number1 - number2
        elif operation == 'add':
            result = number1 + number2
        elif operation == 'multiply':
            result = number1 * number2
        elif operation == 'divide':
            if number2 == 0:
                if safe_division:
                    result = float('inf') if number1 != 0 else float('nan')
                else:
                    raise ZeroDivisionError('Division by zero is not allowed.')
            else:
                result = number1 / number2
        elif operation == 'exponentiate':
            result = number1 ** number2
        elif operation == 'modulus':
            if number2 == 0:
                if safe_division:
                    result = float('nan')
                else:
                    raise ZeroDivisionError('Modulus by zero is not allowed.')
            else:
                result = number1 % number2
        else:
            raise ValueError(f"Invalid operation '{operation}'. Supported operations are: subtract, add, multiply, divide, exponentiate, modulus.")

        if precision is not None:
            result = round(result, precision)

        return result
    except Exception as e:
        return str(e)

