def operation_director_lookup(operation_name, dataset, case_sensitive=False, partial_match=True, filter_by_director=None, filter_by_date=None):
    # Validate dataset
    if not isinstance(dataset, list) or not all(isinstance(item, dict) for item in dataset):
        return {'error': 'Invalid dataset format. Dataset must be a list of dictionaries.'}

    # Prepare operation name for search
    search_name = operation_name if case_sensitive else operation_name.lower()

    # Initialize result
    result = None

    # Search through the dataset
    for entry in dataset:
        # Validate required fields
        if 'operation' not in entry or 'director' not in entry:
            return {'error': 'Dataset entries must contain operation and director fields.'}

        # Prepare operation name from dataset
        operation = entry['operation'] if case_sensitive else entry['operation'].lower()

        # Check for partial match or exact match
        if (partial_match and search_name in operation) or (not partial_match and search_name == operation):
            # Apply additional filters
            if filter_by_director and filter_by_director != entry.get('director'):
                continue
            if filter_by_date and filter_by_date != entry.get('operation_date'):
                continue
            # If all conditions are met, set result
            result = entry['director']
            break

    # Return result or error if not found
    if result:
        return {'director': result}
    else:
        return {'error': 'Operation not found or no matching director.'}

