    if special_character_handling == 'replace' and not replacement_character:
        return 'Error: Replacement character must be provided when special_character_handling is set to replace.'

    # Process the input string
    processed_input = input

    # Ignore leading whitespace if specified
    if ignore_whitespace:
        processed_input = processed_input.lstrip()

    # Convert to lowercase if case insensitive
    if not case_sensitive:
        processed_input = processed_input.lower()

    # Iterate over the string to find the first valid character
    for index, char in enumerate(processed_input):
        # Skip ignored positions
        if index in ignore_positions:
            continue

        # Handle special characters
        if not char.isalnum():
            if special_character_handling == 'ignore':
                continue
            elif special_character_handling == 'replace':
                char = replacement_character

        # Skip ignored characters
        if char in ignore_characters:
            continue

        # Return the first valid character
        return char

    # Return an error if no valid character is found
    return 'Error: No valid character found.'

