def extract_last_name(full_name, name_delimiters=[' '], consider_prefixes=True, consider_suffixes=False, output_format='string', handle_single_word_names=True):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(name_delimiters, list) or not all(isinstance(d, str) for d in name_delimiters):
        return {'error': 'Invalid input: name_delimiters must be a list of strings.'}
    if not isinstance(consider_prefixes, bool):
        return {'error': 'Invalid input: consider_prefixes must be a boolean.'}
    if not isinstance(consider_suffixes, bool):
        return {'error': 'Invalid input: consider_suffixes must be a boolean.'}
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid input: output_format must be one of ["string", "array", "json"].'}
    if not isinstance(handle_single_word_names, bool):
        return {'error': 'Invalid input: handle_single_word_names must be a boolean.'}

    # Split the full name using the provided delimiters
    import re
    delimiters_regex = '|'.join(map(re.escape, name_delimiters))
    name_parts = re.split(delimiters_regex, full_name)

    # Handle single-word names
    if len(name_parts) == 1:
        if handle_single_word_names:
            last_name = name_parts[0]
        else:
            return {'error': 'Single-word names are not handled.'}
    else:
        # Consider prefixes and suffixes
        if consider_prefixes:
            last_name = ' '.join(name_parts[-2:]) if len(name_parts) > 1 else name_parts[-1]
        else:
            last_name = name_parts[-1]

        if consider_suffixes:
            # Assuming suffixes are at the end and separated by space
            suffixes = ['Jr.', 'Sr.', 'II', 'III']  # Example suffixes
            if last_name.split()[-1] in suffixes:
                last_name = ' '.join(last_name.split()[:-1])

    # Format the output
    if output_format == 'string':
        return last_name
    elif output_format == 'array':
        return last_name.split()
    elif output_format == 'json':
        return {'last_name': last_name}

