def reverse_number(number: str, output_format: str = 'string', handle_negative: bool = True, handle_decimal: bool = True, error_handling: str = 'warn') -> str:
    """
    Reverses the order of digits in the given number string.

    Parameters:
    - number (str): The number to be reversed.
    - output_format (str): The format of the output ('string', 'integer', 'float').
    - handle_negative (bool): Whether to handle negative numbers.
    - handle_decimal (bool): Whether to handle decimal numbers.
    - error_handling (str): Error handling strategy ('ignore', 'warn', 'strict').

    Returns:
    - str: The reversed number in the specified format.
    """
    try:
        # Check if the number is valid
        if not isinstance(number, str):
            raise ValueError("The number must be provided as a string.")

        # Handle negative numbers
        is_negative = number.startswith('-') and handle_negative
        if is_negative:
            number = number[1:]

        # Handle decimal numbers
        parts = number.split('.') if handle_decimal else [number]

        # Reverse the integer and fractional parts separately
        reversed_parts = [''.join(reversed(part)) for part in parts]
        reversed_number = '.'.join(reversed_parts)

        # Reapply negative sign if necessary
        if is_negative:
            reversed_number = '-' + reversed_number

        # Convert to the desired output format
        if output_format == 'integer':
            return str(int(reversed_number))
        elif output_format == 'float':
            return str(float(reversed_number))
        else:
            return reversed_number

    except Exception as e:
        if error_handling == 'strict':
            raise
        elif error_handling == 'warn':
            print(f"Warning: {e}")
        return ""

