    if output_format not in ['year_only', 'detailed']:
        return {'error': "Invalid output_format. Choose 'year_only' or 'detailed'."}

    # Calculate the resulting year
    result_year = starting_year - years_to_subtract

    # Prepare the output based on the specified format
    if output_format == 'year_only':
        return {'result': result_year}
    elif output_format == 'detailed':
        details = {
            'starting_year': starting_year,
            'years_subtracted': years_to_subtract,
            'result_year': result_year,
