def extract_last_name(full_name: str, output_format: str = 'string', handle_suffix: bool = False, error_handling: str = 'warn') -> str:
    # Split the full name into parts
    name_parts = full_name.split()

    # Determine the last name
    if not name_parts:
        if error_handling == 'strict':
            raise ValueError('The full name provided is empty.')
        elif error_handling == 'warn':
            print('Warning: The full name provided is empty.')
        return ''

    # Handle suffix if required
    if handle_suffix and len(name_parts) > 1 and name_parts[-1] in ['Jr.', 'Sr.', 'II', 'III']:
        last_name = ' '.join(name_parts[-2:])
    else:
        last_name = name_parts[-1]

    # Apply output format
    if output_format == 'uppercase':
        last_name = last_name.upper()
    elif output_format == 'lowercase':
        last_name = last_name.lower()
    elif output_format == 'titlecase':
        last_name = last_name.title()
    # Default is 'string', which means no change

    return last_name

