def advanced_year_calculator(base_year, years_to_add=0, years_to_subtract=0, calendar_system='gregorian', consider_leap_years=True, output_format='integer'):
    """
    Calculate the resulting year based on the given parameters.

    :param base_year: The starting year from which calculations will be made.
    :param years_to_add: The number of years to add to the base year.
    :param years_to_subtract: The number of years to subtract from the base year.
    :param calendar_system: The calendar system to use for calculations.
    :param consider_leap_years: Whether to account for leap years in the calculation.
    :param output_format: The format of the output.
    :return: The calculated year in the specified format.
    """
    # Error handling for invalid inputs
    if not isinstance(base_year, int):
        return {'error': 'Invalid type for base_year. Expected integer.'}
