        return {'error': 'Invalid type for years_to_add or years_to_subtract. Expected integer.'}
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return {'error': 'Unsupported calendar system.'}
    if output_format not in ['integer', 'string', 'detailed']:
        return {'error': 'Unsupported output format.'}

    # Calculate the resulting year
    result_year = base_year + years_to_add - years_to_subtract

    # Consider leap years if necessary (simplified for this example)
    if consider_leap_years and calendar_system == 'gregorian':
        # Simplified leap year consideration
        if (result_year % 4 == 0 and result_year % 100 != 0) or (result_year % 400 == 0):
            leap_year_status = 'Leap year'
        else:
            leap_year_status = 'Non-leap year'
    else:
        leap_year_status = 'Leap year consideration not applied'

    # Format the output based on the specified format
    if output_format == 'integer':
        return result_year
    elif output_format == 'string':
        return f'The calculated year is {result_year}.'
    elif output_format == 'detailed':
        return {
            'year': result_year,
            'leap_year_status': leap_year_status,
            'calendar_system': calendar_system
        }

