        return {'error': 'Input must be a string.'}

    # Initialize variables
    original_length = len(input)
    filtered_string = input

    # Handle ignore_characters
    if ignore_characters:
        for char in ignore_characters:
            filtered_string = filtered_string.replace(char, '')

    # Handle ignore_position
    if 'first' in ignore_position and filtered_string:
        filtered_string = filtered_string[1:]
    if 'last' in ignore_position and filtered_string:
        filtered_string = filtered_string[:-1]

    # Handle case sensitivity
    if not case_sensitive:
        filtered_string = filtered_string.lower()

    # Handle character_types
    if character_types:
        if 'vowels' in character_types:
            filtered_string = ''.join([c for c in filtered_string if c in 'aeiouAEIOU'])
        if 'consonants' in character_types:
            filtered_string = ''.join([c for c in filtered_string if c.isalpha() and c not in 'aeiouAEIOU'])
        if 'digits' in character_types:
            filtered_string = ''.join([c for c in filtered_string if c.isdigit()])
        if 'special' in character_types:
            filtered_string = ''.join([c for c in filtered_string if not c.isalnum()])

    # Calculate final length
    final_length = len(filtered_string)

    # Handle output_format
    if output_format == 'integer':
        return final_length
    elif output_format == 'text':
        return f'The length of the string is {final_length}.'
    elif output_format == 'detailed':
        return {
            'original_length': original_length,
            'filtered_length': final_length,
            'ignored_characters': ignore_characters,
            'ignored_positions': ignore_position,
            'case_sensitive': case_sensitive,
            'character_types': character_types
        }
    else:
        return {'error': 'Invalid output format specified.'}

