def letter_counter(name, ignore_characters=[], ignore_position=[], case_sensitive=False, count_vowels=False, count_consonants=False, frequency_statistics=False):
    # Validate input types
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid input: ignore_characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid input: ignore_position must be a list containing "first" or "last".'}
    if not isinstance(case_sensitive, bool) or not isinstance(count_vowels, bool) or not isinstance(count_consonants, bool) or not isinstance(frequency_statistics, bool):
        return {'error': 'Invalid input: case_sensitive, count_vowels, count_consonants, and frequency_statistics must be booleans.'}

    # Adjust case sensitivity
    if not case_sensitive:
        name = name.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Define vowels and consonants
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Apply ignore positions
    if 'first' in ignore_position and len(name) > 0:
        name = name[1:]
    if 'last' in ignore_position and len(name) > 0:
        name = name[:-1]

    # Filter out ignored characters
    filtered_name = ''.join(c for c in name if c not in ignore_characters)

    # Count letters based on specified criteria
    if count_vowels:
        filtered_name = ''.join(c for c in filtered_name if c in vowels)
    elif count_consonants:
        filtered_name = ''.join(c for c in filtered_name if c in consonants)

    # Calculate frequency statistics if required
    frequency = {}
    if frequency_statistics:
        for char in filtered_name:
            frequency[char] = frequency.get(char, 0) + 1

    # Return results
    result = {'letter_count': len(filtered_name)}
    if frequency_statistics:
        result['frequency_statistics'] = frequency

    return result

