def reverse_order(input: str, output_format: str = 'string', preserve_leading_zeros: bool = True, handle_negative: bool = True, decimal_precision: int = None):
    # Error handling for invalid input
    if not input.replace('-', '').replace('.', '').isdigit():
        return {'error': 'Invalid input: Input must be a numeric string.'}
    if output_format not in ['string', 'integer', 'float']:
        return {'error': 'Invalid output format: Must be string, integer, or float.'}

    # Handle negative numbers
    is_negative = input.startswith('-') and handle_negative
    if is_negative:
        input = input[1:]

    # Reverse the input
    reversed_input = input[::-1]

    # Handle leading zeros
    if not preserve_leading_zeros:
        reversed_input = reversed_input.lstrip('0')

    # Construct the output based on the format
    if output_format == 'integer':
        result = int(reversed_input)
        if is_negative:
            result = -result
    elif output_format == 'float':
        result = float(reversed_input)
        if is_negative:
            result = -result
        if decimal_precision is not None:
            result = round(result, decimal_precision)
    else:  # Default to string
        if is_negative:
            result = '-' + reversed_input
        else:
            result = reversed_input

    return result

