def digit_product_calculator(number, output_format='integer', ignore_zeros=False, precision=2):
    """
    Calculate the product of the digits of a given number.

    Parameters:
    - number (number): The number whose digits will be multiplied.
    - output_format (str): The format of the output. Can be 'integer', 'text', or 'json'.
    - ignore_zeros (bool): Option to ignore zeros in the digit multiplication.
    - precision (int): The number of decimal places to consider for floating-point numbers.

    Returns:
    - The product of the digits in the specified format.
    """
    # Error handling for invalid input types
    if not isinstance(number, (int, float)):
        return {'error': 'Invalid input: number must be an integer or float.'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'Invalid output format. Choose from integer, text, or json.'}
    if not isinstance(ignore_zeros, bool):
        return {'error': 'Invalid input: ignore_zeros must be a boolean.'}
    if not isinstance(precision, int) or precision < 0:
        return {'error': 'Invalid input: precision must be a non-negative integer.'}

    # Convert number to string and handle negative numbers
    number_str = str(abs(number))

    # Initialize product
    product = 1

    # Calculate product of digits
    for char in number_str:
        if char.isdigit():
            digit = int(char)
            if digit == 0 and ignore_zeros:
                continue
            product *= digit

    # Format the output
    if output_format == 'integer':
        return product
    elif output_format == 'text':
        return f'The product of the digits is {product}.'
    elif output_format == 'json':
        return {'product': product}

