def digit_product_calculator(numeric_string, ignore_non_digits=True, output_format='integer', error_handling='strict', numeric_base=10):
    # Validate numeric_base
    if not (2 <= numeric_base <= 36):
        raise ValueError('numeric_base must be between 2 and 36.')

    # Validate numeric_string
    if not isinstance(numeric_string, str) or len(numeric_string) == 0:
        if error_handling == 'strict':
            raise ValueError('numeric_string must be a non-empty string.')
        else:
            return 'Invalid input: numeric_string must be a non-empty string.'

    # Filter digits based on ignore_non_digits
    if ignore_non_digits:
        digits = [char for char in numeric_string if char.isdigit()]
    else:
        digits = list(numeric_string)

    # Convert digits to the specified numeric base
    try:
        digits = [int(char, numeric_base) for char in digits]
    except ValueError:
        if error_handling == 'strict':
            raise ValueError('Invalid character for the specified numeric base.')
        else:
            return 'Invalid character for the specified numeric base.'

    # Calculate the product of digits
    product = 1
    for digit in digits:
        product *= digit

    # Return the result based on output_format
    if output_format == 'integer':
        return product
    elif output_format == 'text':
        return f'The product of the digits is {product}.'
    elif output_format == 'detailed':
        return {
            'digits': digits,
            'product': product,
            'calculation': ' * '.join(map(str, digits)) + f' = {product}'
        }
    else:
        if error_handling == 'strict':
            raise ValueError('Invalid output_format specified.')
        else:
            return 'Invalid output_format specified.'

