def reverse_number(input_number: str, preserve_sign: bool = True, reverse_decimal: bool = False, output_format: str = 'string', digits_to_reverse: int = None):
    # Validate input_number is a valid number string
    try:
        float(input_number)  # Check if input_number can be converted to a float
    except ValueError:
        return {'error': 'Invalid input_number. Must be a valid number string.'}

    # Handle negative sign preservation
    sign = ''
    if input_number.startswith('-'):
        sign = '-' if preserve_sign else ''
        input_number = input_number[1:]

    # Split integer and decimal parts if necessary
    if '.' in input_number:
        integer_part, decimal_part = input_number.split('.')
    else:
        integer_part, decimal_part = input_number, ''

    # Reverse the integer part
    if digits_to_reverse is None:
        reversed_integer = integer_part[::-1]
    else:
        reversed_integer = integer_part[:digits_to_reverse][::-1] + integer_part[digits_to_reverse:]

    # Reverse the decimal part if required
    if reverse_decimal and decimal_part:
        reversed_decimal = decimal_part[::-1]
    else:
        reversed_decimal = decimal_part

    # Construct the reversed number
    if reversed_decimal:
        reversed_number = f'{reversed_integer}.{reversed_decimal}'
    else:
        reversed_number = reversed_integer

    # Apply the sign
    reversed_number = sign + reversed_number

    # Format the output
    if output_format == 'number':
        try:
            return {'result': float(reversed_number)}
        except ValueError:
            return {'error': 'Reversed number cannot be converted to a float.'}
    else:
        return {'result': reversed_number}

