def digit_sum_calculator(year: str, output_format: str = 'integer', operation: str = 'sum', include_negative: bool = False):
    # Validate the 'year' parameter
    if not isinstance(year, str) or not year.lstrip('-').isdigit():
        return {'error': 'Invalid year format. Year must be a string representing an integer.'}

    # Convert year to an integer for processing
    year_int = int(year)

    # Handle negative years based on 'include_negative' parameter
    if include_negative and year_int < 0:
        digits = [int(d) for d in str(year_int)]  # Include the negative sign
    else:
        digits = [int(d) for d in str(abs(year_int))]  # Ignore the negative sign

    # Perform the specified operation
    if operation == 'sum':
        result = sum(digits)
    elif operation == 'product':
        result = 1
        for d in digits:
            result *= d
    else:
        return {'error': 'Unsupported operation. Choose either "sum" or "product".'}

    # Format the output based on 'output_format'
    if output_format == 'integer':
        return result
    elif output_format == 'text':
        return str(result)
    elif output_format == 'json':
        return {'result': result}
    elif output_format == 'xml':
        return f'<result>{result}</result>'
    else:
        return {'error': 'Unsupported output format. Choose from "integer", "text", "json", or "xml".'}

