def character_counter(input, ignore_characters=[], ignore_position=[], case_sensitive=False, character_types=['letters', 'digits', 'symbols', 'whitespace'], output_format='integer'):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last', 'even', 'odd'] for pos in ignore_position):
        return {'error': 'Ignore position must be a list containing any of ["first", "last", "even", "odd"].'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if not isinstance(character_types, list) or not all(ct in ['letters', 'digits', 'symbols', 'whitespace'] for ct in character_types):
        return {'error': 'Character types must be a list containing any of ["letters", "digits", "symbols", "whitespace"].'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Output format must be one of ["integer", "text", "detailed"].'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Filter characters based on ignore_characters
    filtered_input = ''.join(c for c in input if c not in ignore_characters)

    # Filter characters based on ignore_position
    if 'first' in ignore_position:
        filtered_input = filtered_input[1:]
    if 'last' in ignore_position:
        filtered_input = filtered_input[:-1]
    if 'even' in ignore_position:
        filtered_input = ''.join(c for i, c in enumerate(filtered_input) if i % 2 != 0)
    if 'odd' in ignore_position:
        filtered_input = ''.join(c for i, c in enumerate(filtered_input) if i % 2 == 0)

    # Count characters based on character_types
    count = 0
    for c in filtered_input:
        if 'letters' in character_types and c.isalpha():
            count += 1
        elif 'digits' in character_types and c.isdigit():
            count += 1
        elif 'symbols' in character_types and not c.isalnum() and not c.isspace():
            count += 1
        elif 'whitespace' in character_types and c.isspace():
            count += 1

    # Format the output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The count is {count}.'
    elif output_format == 'detailed':
        return {
            'total_count': count,
            'details': {
                'letters': sum(1 for c in filtered_input if c.isalpha()),
                'digits': sum(1 for c in filtered_input if c.isdigit()),
                'symbols': sum(1 for c in filtered_input if not c.isalnum() and not c.isspace()),
                'whitespace': sum(1 for c in filtered_input if c.isspace())
            }
        }

