def sum_of_digits_extended(input_number: str, output_format: str = 'integer', detailed_output: bool = False):
    # Validate input_number
    if not isinstance(input_number, str) or not input_number.replace('.', '', 1).isdigit():
        return {'error': 'Invalid input_number. It must be a numeric string.'}

    # Validate output_format
    if output_format not in ['integer', 'text', 'binary', 'hexadecimal']:
        return {'error': 'Invalid output_format. Must be one of integer, text, binary, or hexadecimal.'}

    # Calculate the sum of digits
    sum_digits = sum(int(char) for char in input_number if char.isdigit())

    # Format the result based on output_format
    if output_format == 'integer':
        result = sum_digits
    elif output_format == 'text':
        result = str(sum_digits)
    elif output_format == 'binary':
        result = bin(sum_digits)[2:]
    elif output_format == 'hexadecimal':
        result = hex(sum_digits)[2:]

    # Prepare detailed output if requested
    if detailed_output:
        breakdown = ' + '.join(char for char in input_number if char.isdigit())
        detailed_result = f"Sum of digits: {breakdown} = {sum_digits}"
        return {'result': result, 'details': detailed_result}

    return {'result': result}

