    def parse_complex_number(base_str):
        try:
            return complex(base_str.replace('i', 'j'))
        except ValueError:
            raise ValueError('Invalid complex number format.')

    try:
        if isinstance(base, str):
            base = parse_complex_number(base)
        result = base ** exponent

        if output_format == 'number':
            return round(result, precision)
        elif output_format == 'string':
            return str(round(result, precision))
        elif output_format == 'json':
            return json.dumps({'result': round(result, precision)})
        elif output_format == 'scientific':
            return f'{result:.{precision}e}'
        else:
            raise ValueError('Invalid output format specified.')

    except Exception as e:
        if error_handling == 'strict':
            raise e
        elif error_handling == 'lenient':
            return 'An error occurred, but lenient mode is enabled.'
