            extracted_digits.append(number[pos])
        except IndexError:
            if error_handling == 'raise':
                raise ValueError(f"Position {pos + 1} is out of range for the number {number}.")
            elif error_handling == 'default':
                extracted_digits.append('0')  # Default value
            # 'ignore' does nothing
    # Format the output based on the specified output format
    if output_format == 'integer':
        return int(''.join(extracted_digits))
    elif output_format == 'array':
        return extracted_digits
    else:  # Default to 'string'
        return ''.join(extracted_digits)

