def digit_extractor_v2(number, position, output_format='integer', default_value='', error_handling='strict'):
    # Convert the number to a string to handle both integer and float cases uniformly
    number_str = str(number)
    # Remove the decimal point for easier indexing
    number_str = number_str.replace('.', '')

    # Check if the position is valid
    if position < 1 or position > len(number_str):
        if error_handling == 'strict':
            raise ValueError('Position exceeds the number of digits in the number.')
        elif error_handling == 'warn':
            print('Warning: Position exceeds the number of digits in the number.')
        return default_value

    # Extract the digit
    digit = number_str[position - 1]

    # Format the output based on the specified output_format
    if output_format == 'integer':
        return int(digit)
    elif output_format == 'string':
        return digit
    elif output_format == 'json':
        return {
            'digit': int(digit),
            'position': position,
            'number': number
        }
    else:
        raise ValueError('Invalid output format specified.')

