def extract_first_name(names, ignore_prefixes=True, output_format='array', cultural_naming_conventions='western', custom_rules=None):
    # Error handling for required parameters
    if not isinstance(names, list) or len(names) < 1:
        return {'error': 'The parameter "names" must be a non-empty list of strings.'}

    # Validate output_format
    if output_format not in ['array', 'string', 'json']:
        return {'error': 'Invalid output_format. Must be one of: array, string, json.'}

    # Validate cultural_naming_conventions
    if cultural_naming_conventions not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid cultural_naming_conventions. Must be one of: western, eastern, custom.'}

    # Validate custom_rules if cultural_naming_conventions is 'custom'
    if cultural_naming_conventions == 'custom':
        if not custom_rules or 'delimiter' not in custom_rules or 'first_name_position' not in custom_rules:
            return {'error': 'Custom rules must include "delimiter" and "first_name_position" when using custom cultural naming conventions.'}

    # Define common prefixes to ignore
    prefixes = ['Mr.', 'Ms.', 'Dr.', 'Mrs.']

    # Function to extract first name based on convention
    def get_first_name(full_name):
        # Split the name based on spaces or custom delimiter
        if cultural_naming_conventions == 'custom':
            parts = full_name.split(custom_rules['delimiter'])
            position = custom_rules['first_name_position']
        else:
            parts = full_name.split()
            position = 0 if cultural_naming_conventions == 'western' else -1

        # Remove prefixes if needed
        if ignore_prefixes:
            parts = [part for part in parts if part not in prefixes]

        # Return the first name based on the position
        if 0 <= position < len(parts):
            return parts[position]
        else:
            return ''

    # Extract first names
    first_names = [get_first_name(name) for name in names]

    # Format the output
    if output_format == 'array':
        return first_names
    elif output_format == 'string':
        return ' '.join(first_names)
    elif output_format == 'json':
        return {name: first_name for name, first_name in zip(names, first_names)}

def count_letters(input, ignore_characters=[], ignore_position=[], case_sensitive=False, character_type='all', output_format='integer'):
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Initialize variables
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Apply ignore positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]

    # Filter characters based on ignore list
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Count characters based on type
    if character_type == 'vowels':
        count = sum(1 for char in filtered_input if char in vowels)
    elif character_type == 'consonants':
        count = sum(1 for char in filtered_input if char in consonants)
    else:
        count = len(filtered_input)

    # Format output
    if output_format == 'text':
        return f'The count is {count}.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for char in filtered_input if char in vowels)
        consonant_count = sum(1 for char in filtered_input if char in consonants)
        return {
            'total': count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }
    else:
        return count

