def count_letters_advanced(input, ignore_characters=[], ignore_position=[], case_sensitive=False, output_format='integer'):
    """
    Count the number of letters in the given input string with options to ignore specific characters,
    positions, and case sensitivity. Returns the count in the specified output format.
    """
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize variables
    filtered_input = input

    # Handle case sensitivity
    if not case_sensitive:
        filtered_input = filtered_input.lower()

    # Ignore specified characters
    if ignore_characters:
        for char in ignore_characters:
            filtered_input = filtered_input.replace(char, '')

    # Ignore specified positions
    if ignore_position:
        filtered_input = ''.join(
            char for idx, char in enumerate(filtered_input)
            if not (
                ('first' in ignore_position and idx == 0) or
                ('last' in ignore_position and idx == len(filtered_input) - 1) or
                ('even' in ignore_position and idx % 2 == 0) or
                ('odd' in ignore_position and idx % 2 != 0)
            )
        )

    # Count letters
    letter_count = sum(char.isalpha() for char in filtered_input)

    # Format output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed':
        from collections import Counter
        detailed_count = Counter(filtered_input)
        return dict(detailed_count)
    else:
        return {'error': 'Invalid output format specified.'}

