def letter_counter(input: str, ignore_non_letters: bool = True, output_format: str = 'integer', case_sensitive: bool = False, target_letters: list = []):
    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Choose from integer, text, or detailed.'}

    # Validate target_letters
    if not all(isinstance(letter, str) and len(letter) == 1 for letter in target_letters):
        return {'error': 'Each target letter must be a single character string.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        target_letters = [letter.lower() for letter in target_letters]

    # Count letters
    letter_count = {}
    for char in input:
        if ignore_non_letters and not char.isalpha():
            continue
        if target_letters and char not in target_letters:
            continue
        letter_count[char] = letter_count.get(char, 0) + 1

    # Format the output
    if output_format == 'integer':
        return sum(letter_count.values())
    elif output_format == 'text':
        return f"Total letters: {sum(letter_count.values())}"
    elif output_format == 'detailed':
        return letter_count

