def string_length_counter(input, ignore_characters=[], ignore_case_sensitive=False, ignore_position=[], ignore_ranges=[], output_format='integer'):
    """
    Counts the number of characters in a string, with options to ignore specified characters, positions, or ranges.
    """
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if not isinstance(ignore_case_sensitive, bool):
        return {'error': 'Ignore case sensitive must be a boolean.'}
    if not isinstance(ignore_position, list) or not all(p in ['first', 'last'] for p in ignore_position):
        return {'error': 'Ignore position must be a list containing "first" or "last".'}
    if not isinstance(ignore_ranges, list) or not all(isinstance(r, dict) and 'start' in r and 'end' in r for r in ignore_ranges):
        return {'error': 'Ignore ranges must be a list of dictionaries with "start" and "end" keys.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Output format must be "integer", "text", or "detailed".'}

    # Prepare the string for counting
    filtered_input = input

    # Apply ignore characters
    if ignore_characters:
        for char in ignore_characters:
            if ignore_case_sensitive:
                filtered_input = filtered_input.replace(char, '')
            else:
                filtered_input = filtered_input.replace(char.lower(), '').replace(char.upper(), '')

    # Apply ignore positions
    if 'first' in ignore_position and filtered_input:
        filtered_input = filtered_input[1:]
    if 'last' in ignore_position and filtered_input:
        filtered_input = filtered_input[:-1]

    # Apply ignore ranges
    for range_ in ignore_ranges:
        start, end = range_['start'], range_['end']
        if 0 <= start < len(filtered_input) and 0 <= end < len(filtered_input):
            filtered_input = filtered_input[:start] + filtered_input[end+1:]

    # Calculate the length
    length = len(filtered_input)

    # Prepare the output
    if output_format == 'integer':
        return length
    elif output_format == 'text':
        return f'The length of the string is {length}.'
    elif output_format == 'detailed':
        ignored_details = {
            'ignored_characters': ignore_characters,
            'ignored_positions': ignore_position,
            'ignored_ranges': ignore_ranges
        }
        return {
            'length': length,
            'details': ignored_details
        }

