    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return 'Error: Invalid date format. Expected YYYY-MM-DDTHH:MM:SS.'

    # Calculate the new date
    new_date = start_date_obj + relativedelta(months=months_to_add) + timedelta(days=days_to_add, hours=hours_to_add, minutes=minutes_to_add)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return new_date.strftime('%Y-%m-%d')
    elif output_format == 'text':
