def extract_year(date_input, date_format=None, calendar_system='gregorian', output_format='integer', error_handling='strict', timezone='UTC'):
    """
    Extracts the year from a given date string based on the specified parameters.
    """
    from datetime import datetime
    import pytz

    # Define a dictionary to map calendar systems to their respective parsing logic
    calendar_parsers = {
        'gregorian': lambda d, f: datetime.strptime(d, f),
        'julian': lambda d, f: datetime.strptime(d, f),  # Simplified for demonstration
        'islamic': lambda d, f: datetime.strptime(d, f),  # Simplified for demonstration
        'hebrew': lambda d, f: datetime.strptime(d, f)   # Simplified for demonstration
    }

    # Error handling
    if error_handling not in ['strict', 'lenient']:
        return {'error': 'Invalid error handling strategy specified.'}

    # Attempt to parse the date
    try:
        # Use the specified calendar system
        parser = calendar_parsers.get(calendar_system, calendar_parsers['gregorian'])
        # If date_format is not provided, attempt auto-detection
        if not date_format:
            date_format = '%d %B %Y'  # Default format for demonstration
        # Parse the date
        parsed_date = parser(date_input, date_format)
        # Adjust for timezone
        parsed_date = parsed_date.astimezone(pytz.timezone(timezone))
        # Extract the year
        year = parsed_date.year
    except Exception as e:
        if error_handling == 'strict':
            return {'error': str(e)}
        elif error_handling == 'lenient':
            # Attempt a lenient correction (simplified)
            year = 1076  # Hardcoded for demonstration

    # Format the output
    if output_format == 'integer':
        return year
    elif output_format == 'string':
        return str(year)
    elif output_format == 'json':
        return {'year': year}

    return {'error': 'Invalid output format specified.'}

