def consonant_counter(input, consonant_set=None, case_sensitive=False, language='en', count_position='all', detailed_output=False):
    # Default consonant set to English consonants if not provided
    if consonant_set is None:
        consonant_set = ['b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z']

    # Convert input to lowercase if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        consonant_set = [c.lower() for c in consonant_set]

    # Initialize consonant count and frequency dictionary
    consonant_count = 0
    consonant_frequency = {c: 0 for c in consonant_set}

    # Determine the range of input to analyze based on count_position
    if count_position == 'start':
        input_range = input[:1]  # Only the first character
    elif count_position == 'end':
        input_range = input[-1:]  # Only the last character
    elif count_position == 'middle':
        input_range = input[1:-1]  # Exclude first and last characters
    else:
        input_range = input  # Analyze the whole string

    # Count consonants in the specified range
    for char in input_range:
        if char in consonant_set:
            consonant_count += 1
            consonant_frequency[char] += 1

    # Return detailed output if requested
    if detailed_output:
        return {'total_consonants': consonant_count, 'frequency': consonant_frequency}
    else:
        return consonant_count

