def date_calculator(start_date: str, duration: int, time_unit: str = 'days', direction: str = 'after', output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', business_days: bool = False) -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Use YYYY-MM-DD.'

    # Validate time_unit
    if time_unit not in ['days', 'weeks', 'months', 'years']:
        return 'Error: Invalid time_unit. Choose from days, weeks, months, years.'

    # Validate direction
    if direction not in ['before', 'after']:
        return 'Error: Invalid direction. Choose from before, after.'

    # Calculate the new date
    if direction == 'before':
        duration = -duration

    if time_unit == 'days':
        delta = timedelta(days=duration)
    elif time_unit == 'weeks':
        delta = timedelta(weeks=duration)
    elif time_unit == 'months':
        delta = relativedelta(months=duration)
    elif time_unit == 'years':
        delta = relativedelta(years=duration)

    new_date = start_date_obj + delta

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = new_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'DD Month YYYY':
        formatted_date = new_date.strftime('%d %B %Y')
    else:
        return 'Error: Invalid output_format.'

    return formatted_date

