def digit_extractor_plus(number, position, length=1, output_format='integer', numeral_system='decimal'):
    # Convert the number to the specified numeral system
    if numeral_system == 'binary':
        num_str = bin(number)[2:] if number >= 0 else '-' + bin(number)[3:]
    elif numeral_system == 'hexadecimal':
        num_str = hex(number)[2:] if number >= 0 else '-' + hex(number)[3:]
    elif numeral_system == 'decimal':
        num_str = str(number)
    else:
        return {'error': 'Unsupported numeral system'}

    # Handle negative indexing
    if position < 0:
        position = len(num_str) + position + 1

    # Validate position
    if position < 1 or position > len(num_str):
        return {'error': 'Position out of range'}

    # Extract the digits
    start_index = position - 1
    end_index = start_index + length
    extracted_digits = num_str[start_index:end_index]

    # Format the output
    if output_format == 'integer':
        try:
            return int(extracted_digits)
        except ValueError:
            return {'error': 'Invalid extraction for integer conversion'}
    elif output_format == 'string':
        return extracted_digits
    elif output_format == 'list':
        return list(extracted_digits)
    else:
        return {'error': 'Unsupported output format'}

