def digit_extractor(number, position, base=10, handle_out_of_range='error', default_value=0, handle_non_integer='error'):
    # Convert the number to the specified base
    def convert_to_base(n, b):
        if n < 0:
            return '-' + convert_to_base(-n, b)
        elif n == 0:
            return '0'
        digits = ''
        while n:
            digits = str(n % b) + digits
            n //= b
        return digits

    # Handle non-integer numbers
    if not isinstance(number, int):
        if handle_non_integer == 'error':
            raise ValueError("Number must be an integer.")
        elif handle_non_integer == 'round':
            number = round(number)
        elif handle_non_integer == 'truncate':
            number = int(number)

    # Convert number to the specified base
    number_str = convert_to_base(number, base)

    # Adjust position for negative indexing
    if position < 0:
        position = len(number_str) + position + 1

    # Check if position is out of range
    if position < 1 or position > len(number_str):
        if handle_out_of_range == 'error':
            raise IndexError("Position out of range.")
        elif handle_out_of_range == 'null':
            return None
        elif handle_out_of_range == 'default':
            return default_value

    # Extract the digit
    return int(number_str[position - 1])

