def alphabetical_order(input, ignore_case=True, output_format='array', locale='en-US', include_sets=['uppercase', 'lowercase'], language_code='en'):
    import locale as loc
    import re

    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate output_format
    if output_format not in ['array', 'string']:
        return {'error': 'Invalid output_format. Must be "array" or "string".'}

    # Set locale for sorting
    try:
        loc.setlocale(loc.LC_COLLATE, locale)
    except loc.Error:
        return {'error': f'Invalid locale: {locale}'}

    # Extract alphabetical characters
    characters = re.findall(r'[A-Za-z]', input)

    # Filter by include_sets
    if 'uppercase' not in include_sets:
        characters = [c for c in characters if not c.isupper()]
    if 'lowercase' not in include_sets:
        characters = [c for c in characters if not c.islower()]

    # Sort characters
    if ignore_case:
        characters.sort(key=lambda x: x.lower())
    else:
        characters.sort(key=loc.strxfrm)

    # Format output
    if output_format == 'string':
        return ''.join(characters)
    else:
        return characters

