def enhanced_unique_letter_counter(input: str, case_sensitive: bool = False, ignore_characters: list = [], character_set: str = 'alphabet', include_whitespace: bool = False, detailed_output: bool = False):
    # Validate character_set
    if character_set not in ['alphabet', 'numeric', 'alphanumeric', 'all']:
        return {'error': 'Invalid character set specified.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Define character sets
    char_sets = {
        'alphabet': set('abcdefghijklmnopqrstuvwxyz'),
        'numeric': set('0123456789'),
        'alphanumeric': set('abcdefghijklmnopqrstuvwxyz0123456789'),
        'all': set(chr(i) for i in range(32, 127))  # ASCII range
    }

    # Filter characters based on the specified character set
    valid_chars = char_sets[character_set]
    if not include_whitespace:
        valid_chars.discard(' ')

    # Remove ignored characters from valid_chars
    valid_chars -= set(ignore_characters)

    # Count unique characters
    unique_chars = set(c for c in input if c in valid_chars)

    # Prepare the output
    if detailed_output:
        detailed_counts = {char: input.count(char) for char in unique_chars}
        return {'unique_count': len(unique_chars), 'details': detailed_counts}
    else:
        return {'unique_count': len(unique_chars)}

