    # Remove ignored characters using regex
    if ignore_characters:
        ignore_pattern = '[' + ''.join(ignore_characters) + ']'
        input = re.sub(ignore_pattern, '', input)

    # Remove non-letter characters if required
    if ignore_non_letters:
        input = re.sub('[^a-zA-Z]', '', input)

    # Handle position-based ignoring
    filtered_input = ''
    for i, char in enumerate(input):
        if ('first' in ignore_position and i == 0) or \
           ('last' in ignore_position and i == len(input) - 1) or \
           ('even' in ignore_position and i % 2 == 0) or \
