def string_length_counter(input: str, ignore_characters: list = [], case_sensitive: bool = True, output_format: str = 'integer', count_vowels: bool = False, count_consonants: bool = False, count_digits: bool = False, count_whitespace: bool = True):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if output_format not in ['integer', 'text', 'detailed_report']:
        return {'error': 'Invalid output format.'}

    # Prepare the string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Filter out ignored characters
    filtered_input = ''.join(char for char in input if char not in ignore_characters)

    # Count letters
    letter_count = sum(char.isalpha() for char in filtered_input)

    # Prepare additional counts if required
    vowel_count = sum(char in 'aeiouAEIOU' for char in filtered_input) if count_vowels else None
    consonant_count = sum(char.isalpha() and char not in 'aeiouAEIOU' for char in filtered_input) if count_consonants else None
    digit_count = sum(char.isdigit() for char in filtered_input) if count_digits else None
    whitespace_count = sum(char.isspace() for char in filtered_input) if count_whitespace else None

    # Prepare the output based on the format
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The string contains {letter_count} letters.'
    elif output_format == 'detailed_report':
        report = {
            'letters': letter_count,
            'vowels': vowel_count,
            'consonants': consonant_count,
