def date_digit_sum(date: str, date_format: str = 'Month DD, YYYY', output_format: str = 'integer', include_leap_year_check: bool = False, digit_separator: str = 'none') -> str:
    import re
    from datetime import datetime

    # Define a helper function to check for leap year
    def is_leap_year(year: int) -> bool:
        return year % 4 == 0 and (year % 100 != 0 or year % 400 == 0)

    # Attempt to parse the date based on the provided format
    try:
        if date_format == 'YYYY-MM-DD':
            parsed_date = datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'DD-MM-YYYY':
            parsed_date = datetime.strptime(date, '%d-%m-%Y')
        elif date_format == 'Month DD, YYYY':
            parsed_date = datetime.strptime(date, '%B %d, %Y')
        elif date_format == 'MM/DD/YYYY':
            parsed_date = datetime.strptime(date, '%m/%d/%Y')
        elif date_format == 'DD.MM.YYYY':
            parsed_date = datetime.strptime(date, '%d.%m.%Y')
        else:
            return 'Error: Unsupported date format.'
    except ValueError:
        return 'Error: Invalid date or format.'

    # Extract digits from the date
    digits = re.findall(r'\d', date)
    digit_sum = sum(int(digit) for digit in digits)

    # Prepare the output
    if output_format == 'integer':
        result = str(digit_sum)
    elif output_format == 'text':
        separator = '' if digit_separator == 'none' else (',' if digit_separator == 'comma' else ' ')
        result = separator.join(digits)
    elif output_format == 'json':
        result = {'digit_sum': digit_sum, 'digits': digits}
        if include_leap_year_check:
            result['is_leap_year'] = is_leap_year(parsed_date.year)
        result = str(result)
    else:
        return 'Error: Unsupported output format.'

    # Include leap year information if requested
    if include_leap_year_check and output_format != 'json':
        leap_year_info = ' (Leap Year)' if is_leap_year(parsed_date.year) else ' (Not a Leap Year)'
        result += leap_year_info

    return result

