    filtered_parts = [part for part in name_parts if part not in ignore_prefixes]

    # Handle cultural naming conventions
    if cultural_naming_convention == 'Eastern':
        # Eastern convention might have the family name first
        first_name_index = 1 if len(filtered_parts) > 1 else 0
    else:  # Default to Western
        first_name_index = 0

    # Extract the first name
    first_name = filtered_parts[first_name_index] if filtered_parts else ''

    # Include middle name if specified
    if include_middle_name and len(filtered_parts) > first_name_index + 1:
        first_name += ' ' + filtered_parts[first_name_index + 1]

    # Handle suffixes if specified
    if suffix_handling and len(filtered_parts) > first_name_index + 2:
        first_name += ' ' + filtered_parts[first_name_index + 2]

