def string_length_calculator(input, output_format='integer', whitespace_handling='include', case_sensitivity=False, individual_lengths=False):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        raise ValueError('Input must be a list of strings.')
    if output_format not in ['integer', 'text', 'json', 'xml']:
        raise ValueError('Invalid output format.')
    if whitespace_handling not in ['include', 'exclude']:
        raise ValueError('Invalid whitespace handling option.')

    # Calculate lengths
    total_length = 0
    individual_lengths_list = []
    for s in input:
        if not case_sensitivity:
            s = s.lower()
        if whitespace_handling == 'exclude':
            s = s.replace(' ', '')
        length = len(s)
        total_length += length
        if individual_lengths:
            individual_lengths_list.append(length)

    # Prepare output
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'Total length: {total_length}'
    elif output_format == 'json':
        result = {'total_length': total_length}
        if individual_lengths:
            result['individual_lengths'] = individual_lengths_list
        return result
    elif output_format == 'xml':
        xml_result = f'<result><total_length>{total_length}</total_length>'
        if individual_lengths:
            xml_result += '<individual_lengths>' + ''.join(f'<length>{l}</length>' for l in individual_lengths_list) + '</individual_lengths>'
        xml_result += '</result>'
        return xml_result

