def date_calculator(start_date: str, weeks_before: int = 0, days_after: int = 0, months_before: int = 0, years_after: int = 0, calendar_system: str = 'gregorian', time_zone: str = 'UTC', output_format: str = 'date') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for invalid calendar system
    if calendar_system not in ['gregorian', 'julian']:
        return 'Error: Unsupported calendar system.'

    # Error handling for invalid output format
    if output_format not in ['date', 'text', 'timestamp']:
        return 'Error: Unsupported output format.'

    # Parse the start date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start date format.'

    # Adjust for weeks before
    if weeks_before:
        start_date_obj -= timedelta(weeks=weeks_before)

    # Adjust for days after
    if days_after:
        start_date_obj += timedelta(days=days_after)

    # Adjust for months before
    if months_before:
        start_date_obj -= relativedelta(months=months_before)

    # Adjust for years after
    if years_after:
        start_date_obj += relativedelta(years=years_after)

    # Convert to the specified time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = start_date_obj.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Format the output
    if output_format == 'date':
        return start_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'text':
        return start_date_obj.strftime('%A, %B %d, %Y')
    elif output_format == 'timestamp':
        return str(int(start_date_obj.timestamp()))

