def advanced_consonant_counter(input: str, ignore_special_characters: bool = True, case_sensitive: bool = False, output_format: str = 'integer', alphabet: str = 'latin', include_numbers: bool = False):
    # Define consonants for different alphabets
    consonants = {
        'latin': 'bcdfghjklmnpqrstvwxyz',
        'cyrillic': 'бвгджзйклмнпрстфхцчшщ',
        'greek': 'βγδζθκλμνξπρστφχψ'
    }

    # Validate the alphabet
    if alphabet not in consonants:
        raise ValueError(f"Unsupported alphabet: {alphabet}")

    # Select consonants based on the alphabet
    selected_consonants = consonants[alphabet]

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        selected_consonants = selected_consonants.lower()

    # Initialize consonant count
    consonant_count = 0
    consonant_details = {}

    # Count consonants
    for char in input:
        if ignore_special_characters and not char.isalnum():
            continue
        if include_numbers and char.isdigit():
            consonant_count += 1
            continue
        if char in selected_consonants:
            consonant_count += 1
            if output_format == 'detailed':
                if char in consonant_details:
                    consonant_details[char] += 1
                else:
                    consonant_details[char] = 1

    # Format output
    if output_format == 'integer':
        return consonant_count
    elif output_format == 'text':
        return f"The number of consonants is {consonant_count}."
    elif output_format == 'detailed':
        return consonant_details
    else:
        raise ValueError(f"Unsupported output format: {output_format}")

