    # Error handling for required parameter
    if not full_name:
        raise ValueError("The 'full_name' parameter is required.")

    # Trim spaces if required
    if trim_spaces:
        full_name = full_name.strip()

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle case sensitivity
    if ignore_case:
        name_parts = [part.lower() for part in name_parts]

    # Determine last name based on cultural format
    if cultural_format == 'western':
        last_name = name_parts[-1]
    elif cultural_format == 'eastern':
        last_name = name_parts[0]
    elif cultural_format == 'custom':
        if last_name_position is not None and 0 <= last_name_position < len(name_parts):
            last_name = name_parts[last_name_position]
        else:
            raise ValueError("Invalid 'last_name_position' for the given full name.")
    else:
        raise ValueError("Invalid 'cultural_format'. Must be 'western', 'eastern', or 'custom'.")

    # Handle suffixes if required
    if suffix_handling and last_name in ['Jr.', 'Sr.', 'III', 'II']:
        last_name = name_parts[-2] if cultural_format == 'western' else name_parts[1]

    # Include middle names if required
    if include_middle_names and cultural_format == 'western':
