def extract_last_name(full_name: str, delimiter: str = ' ', ignore_middle_names: bool = True, case_sensitive: bool = False, include_suffix: bool = False, include_prefix: bool = False, output_format: str = 'plain') -> str:
    # Error handling for required parameter
