        return 'Error: full_name must be a non-empty string.'

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.lower() for part in name_parts]

    # Determine the last name position
    if ignore_middle_names:
        last_name = name_parts[-1]
    else:
        last_name = name_parts[-1] if len(name_parts) > 1 else name_parts[0]

    # Include suffix if specified
    if include_suffix and len(name_parts) > 1:
        suffixes = ['jr', 'sr', 'iii', 'iv']  # Example suffixes
        if name_parts[-1].lower() in suffixes:
            last_name = name_parts[-2] + ' ' + name_parts[-1]

    # Include prefix if specified
    if include_prefix and len(name_parts) > 1:
        prefixes = ['dr', 'mr', 'ms', 'mrs']  # Example prefixes
        if name_parts[0].lower() in prefixes:
            last_name = name_parts[0] + ' ' + last_name

    # Format the output
    if output_format == 'full':
