def closest_palindrome_finder(number, direction='both', return_type='integer', max_distance=None, multiple_results=False):
    """
    Finds the closest palindrome number to the given integer.

    Parameters:
    - number (int): The integer input for which the closest palindrome is to be found.
    - direction (str): The direction in which to search for the palindrome ('both', 'up', 'down').
    - return_type (str): The format of the output ('integer', 'string', 'detailed').
    - max_distance (int): The maximum distance to search for a palindrome.
    - multiple_results (bool): If true, returns all palindromes found within the specified distance.

    Returns:
    - Depending on 'return_type', returns an integer, string, or detailed object.
    """
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    if not isinstance(number, int):
        raise ValueError("'number' must be an integer.")
    if direction not in ['both', 'up', 'down']:
        raise ValueError("'direction' must be 'both', 'up', or 'down'.")
    if return_type not in ['integer', 'string', 'detailed']:
        raise ValueError("'return_type' must be 'integer', 'string', or 'detailed'.")
    if max_distance is not None and not isinstance(max_distance, int):
        raise ValueError("'max_distance' must be an integer.")
    if not isinstance(multiple_results, bool):
        raise ValueError("'multiple_results' must be a boolean.")

    closest_palindrome = None
    distance = 0
    results = []

    while closest_palindrome is None:
        if max_distance is not None and distance > max_distance:
            break

        if direction in ['both', 'up']:
            if is_palindrome(number + distance):
                results.append((number + distance, distance))
                if not multiple_results:
                    closest_palindrome = number + distance

        if direction in ['both', 'down'] and distance != 0:
            if is_palindrome(number - distance):
                results.append((number - distance, distance))
                if not multiple_results:
                    closest_palindrome = number - distance

        distance += 1

    if not results:
        return None

    if multiple_results:
        if return_type == 'integer':
            return [result[0] for result in results]
        elif return_type == 'string':
            return [str(result[0]) for result in results]
        elif return_type == 'detailed':
            return [{'palindrome': result[0], 'distance': result[1]} for result in results]
    else:
        palindrome, dist = results[0]
        if return_type == 'integer':
            return palindrome
        elif return_type == 'string':
            return str(palindrome)
        elif return_type == 'detailed':
            return {'palindrome': palindrome, 'distance': dist}

