# closest_palindrome_finder(1976) would return 1991 based on the default parameters.

def string_length_counter(input: str, ignore_characters: list = None, ignore_position: list = None, case_sensitive: bool = False, ignore_digits: bool = False, count_types: list = None, output_format: str = 'integer') -> any:
    """
    Count the total number of letters in a given string with options to customize the counting process.
    """
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Initialize default values
    if ignore_characters is None:
        ignore_characters = []
    if ignore_position is None:
        ignore_position = []
    if count_types is None:
        count_types = []

    # Normalize input based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Define helper functions
    def is_vowel(char):
        return char in 'aeiou'

    def is_consonant(char):
        return char.isalpha() and not is_vowel(char)

    def is_special_character(char):
        return not char.isalnum()

    # Initialize counters
    total_count = 0
    vowel_count = 0
    consonant_count = 0
    special_character_count = 0

    # Iterate over the string
    for index, char in enumerate(input):
        # Check for ignored characters
        if char in ignore_characters:
            continue

        # Check for ignored positions
        if ('first' in ignore_position and index == 0) or \
           ('last' in ignore_position and index == len(input) - 1) or \
           ('even' in ignore_position and index % 2 == 0) or \
           ('odd' in ignore_position and index % 2 != 0):
            continue

        # Check for digits
        if ignore_digits and char.isdigit():
            continue

        # Count based on types
        if 'vowels' in count_types and is_vowel(char):
            vowel_count += 1
        elif 'consonants' in count_types and is_consonant(char):
            consonant_count += 1
        elif 'special_characters' in count_types and is_special_character(char):
            special_character_count += 1
        elif not count_types:  # Count all if no specific types are mentioned
            total_count += 1

    # Prepare output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total letters: {total_count}'
    elif output_format == 'detailed':
        return {
            'total': total_count,
            'vowels': vowel_count,
            'consonants': consonant_count,
            'special_characters': special_character_count
        }
    else:
        return {'error': 'Invalid output format specified.'}

