def extract_first_name(full_name, ignore_prefixes=False, ignore_suffixes=False, handle_middle_names=False, handle_initials=False, international_support=False, compound_first_names=False):
    # Error handling for invalid input
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not full_name.strip():
        return {'error': 'Invalid input: full_name cannot be empty.'}

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefixes if required
    if ignore_prefixes:
        prefixes = {'Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss', 'Sir', 'Madam'}
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes if required
    if ignore_suffixes:
        suffixes = {'Jr.', 'Sr.', 'II', 'III', 'IV'}
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle middle names if required
    if handle_middle_names and len(name_parts) > 2:
        name_parts = [name_parts[0]] + name_parts[2:]

    # Handle initials if required
    if handle_initials:
        name_parts = [part for part in name_parts if len(part) > 1 or part.endswith('.')]

    # Handle compound first names
    if compound_first_names and len(name_parts) > 1:
        first_name = name_parts[0]
        if '-' in first_name or ' ' in first_name:
            return first_name
        return ' '.join(name_parts[:2])

    # Default behavior: return the first part as the first name
    return name_parts[0] if name_parts else {'error': 'Unable to extract first name.'}

