def string_length_counter_v2(input: str, ignore_characters: list = [], ignore_character_types: list = [], ignore_position: list = [], case_sensitive: bool = True, output_format: str = 'integer'):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a valid UTF-8 string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Ignore characters must be a list of strings.'}
    if not isinstance(ignore_character_types, list) or not all(c in ['digits', 'punctuation', 'whitespace'] for c in ignore_character_types):
        return {'error': 'Ignore character types must be a list containing only digits, punctuation, or whitespace.'}
    if not isinstance(ignore_position, list) or not all(c in ['first', 'last', 'even', 'odd'] for c in ignore_position):
        return {'error': 'Ignore position must be a list containing only first, last, even, or odd.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'Output format must be one of integer, text, or json.'}

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Filter input based on ignore parameters
    filtered_input = ''
    for i, char in enumerate(input):
        if char in ignore_characters:
            continue
        if 'digits' in ignore_character_types and char.isdigit():
            continue
        if 'punctuation' in ignore_character_types and not char.isalnum():
            continue
        if 'whitespace' in ignore_character_types and char.isspace():
            continue
        if 'first' in ignore_position and i == 0:
            continue
        if 'last' in ignore_position and i == len(input) - 1:
            continue
        if 'even' in ignore_position and i % 2 == 0:
            continue
        if 'odd' in ignore_position and i % 2 != 0:
            continue
        filtered_input += char

    # Calculate length
    length = len(filtered_input)

    # Format output
    if output_format == 'integer':
        return length
    elif output_format == 'text':
        return f'The total number of characters is {length}.'
    elif output_format == 'json':
        return {'length': length}

# Example usage based on the question
