def timezone_converter(input_datetime, input_timezone_offset=None, output_timezone_offset=None, input_timezone_name=None, output_timezone_name=None, output_format='formatted_string', locale='en-US', adjust_for_dst=True):
    from datetime import datetime
    import pytz
    from pytz import timezone

    # Error handling for input_datetime
    try:
        dt = datetime.fromisoformat(input_datetime)
    except ValueError:
        return {'error': 'Invalid input_datetime format. Must be ISO 8601.'}

    # Determine input time zone
    if input_timezone_name:
        try:
            input_tz = timezone(input_timezone_name)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown input_timezone_name.'}
    elif input_timezone_offset is not None:
        input_tz = pytz.FixedOffset(int(input_timezone_offset * 60))
    else:
        return {'error': 'Either input_timezone_name or input_timezone_offset must be provided.'}

    # Determine output time zone
    if output_timezone_name:
        try:
            output_tz = timezone(output_timezone_name)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown output_timezone_name.'}
    elif output_timezone_offset is not None:
        output_tz = pytz.FixedOffset(int(output_timezone_offset * 60))
    else:
        return {'error': 'Either output_timezone_name or output_timezone_offset must be provided.'}

    # Convert input datetime to input time zone
    dt = input_tz.localize(dt, is_dst=adjust_for_dst)

    # Convert to output time zone
    dt = dt.astimezone(output_tz)

    # Format output
    if output_format == 'timestamp':
        result = dt.timestamp()
    elif output_format == 'iso_string':
        result = dt.isoformat()
    else:  # formatted_string
        result = dt.strftime('%Y-%m-%d %H:%M')

    return {'converted_datetime': result}

