def date_digit_sum(date, date_format='Month DD, YYYY', handle_invalid='error', output_format='integer', exclude_components=[], digit_transformation='none'):
    from datetime import datetime
    import json

    # Helper function to transform digits
    def transform_digit(digit, transformation):
        if transformation == 'square':
            return digit ** 2
        elif transformation == 'cube':
            return digit ** 3
        return digit

    # Parse the date based on the provided format
    try:
        if date_format == 'YYYY-MM-DD':
            parsed_date = datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            parsed_date = datetime.strptime(date, '%m/%d/%Y')
        elif date_format == 'Month DD, YYYY':
            parsed_date = datetime.strptime(date, '%B %d, %Y')
        elif date_format == 'DD-MM-YYYY':
            parsed_date = datetime.strptime(date, '%d-%m-%Y')
        elif date_format == 'YYYY/MM/DD':
            parsed_date = datetime.strptime(date, '%Y/%m/%d')
        else:
            raise ValueError('Unsupported date format')
    except ValueError as e:
        if handle_invalid == 'error':
            raise e
        elif handle_invalid == 'default':
            parsed_date = datetime(2000, 1, 1)  # Default date
        else:
            return None

    # Extract components
    components = {'day': parsed_date.day, 'month': parsed_date.month, 'year': parsed_date.year}

    # Exclude specified components
    for component in exclude_components:
        components.pop(component, None)

    # Sum the digits
    digit_sum = 0
    digit_details = {}
    for component, value in components.items():
        digits = [int(d) for d in str(value)]
        transformed_digits = [transform_digit(d, digit_transformation) for d in digits]
        component_sum = sum(transformed_digits)
        digit_sum += component_sum
        digit_details[component] = {'digits': digits, 'transformed': transformed_digits, 'sum': component_sum}

    # Return the result in the specified format
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of digits is {digit_sum}.'
    elif output_format == 'json':
        return json.dumps({'total_sum': digit_sum, 'details': digit_details})
    else:
        raise ValueError('Unsupported output format')

# Example usage
result = date_digit_sum('September 25, 2017', date_format='Month DD, YYYY')
print(result)  # Output: 26

