def date_calculator(start_date, months_to_add=0, weeks_to_add=0, days_to_add=0, output_format='YYYY-MM-DD', time_zone='UTC', return_day_of_week=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate time zone
    if time_zone not in pytz.all_timezones:
        return {'error': 'Invalid time zone.'}

    # Adjust for time zone
    tz = pytz.timezone(time_zone)
    start_date_obj = tz.localize(start_date_obj)

    # Calculate the new date
    new_date = start_date_obj + relativedelta(months=months_to_add) + timedelta(weeks=weeks_to_add, days=days_to_add)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = new_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'DD/MM/YYYY':
        formatted_date = new_date.strftime('%d/%m/%Y')
    elif output_format == 'YYYY/MM/DD':
        formatted_date = new_date.strftime('%Y/%m/%d')
    else:
        return {'error': 'Invalid output format.'}

    # Determine the day of the week if requested
    day_of_week = new_date.strftime('%A') if return_day_of_week else None

    # Return the result
    result = {'calculated_date': formatted_date}
    if return_day_of_week:
        result['day_of_week'] = day_of_week

    return result

