def date_digit_sum(date: str, date_format: str = 'DD MM YYYY', handle_invalid: str = 'error', digit_sum_type: str = 'total') -> int:
    """
    Calculate the sum of all digits in the day, month, and year of a given date.

    Parameters:
    - date (str): The date input in a recognized format.
    - date_format (str): The format of the input date. Defaults to 'DD MM YYYY'.
    - handle_invalid (str): Specifies how to handle invalid date inputs. Defaults to 'error'.
    - digit_sum_type (str): Specifies the type of digit sum calculation. Defaults to 'total'.

    Returns:
    - int: The sum of the digits as specified by the digit_sum_type.
    """
    import datetime

    # Define a helper function to calculate the digit sum
    def calculate_digit_sum(numbers):
        return sum(int(digit) for number in numbers for digit in str(number) if digit.isdigit())

    # Parse the date according to the specified format
    try:
        if date_format == 'DD MM YYYY':
            parsed_date = datetime.datetime.strptime(date, '%d %m %Y')
        elif date_format == 'MM/DD/YYYY':
            parsed_date = datetime.datetime.strptime(date, '%m/%d/%Y')
        elif date_format == 'YYYY-MM-DD':
            parsed_date = datetime.datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'DD-MM-YYYY':
            parsed_date = datetime.datetime.strptime(date, '%d-%m-%Y')
        elif date_format == 'YYYY/MM/DD':
            parsed_date = datetime.datetime.strptime(date, '%Y/%m/%d')
        else:
            raise ValueError('Unsupported date format')
    except ValueError as e:
        if handle_invalid == 'error':
            raise e
        elif handle_invalid == 'warn':
            print(f"Warning: {e}")
            return 0
        elif handle_invalid == 'ignore':
            return 0

    # Extract day, month, and year
    day, month, year = parsed_date.day, parsed_date.month, parsed_date.year

    # Calculate the digit sum
    if digit_sum_type == 'total':
        return calculate_digit_sum([day, month, year])
    elif digit_sum_type == 'separate':
        return {
            'day_sum': calculate_digit_sum([day]),
            'month_sum': calculate_digit_sum([month]),
            'year_sum': calculate_digit_sum([year])
        }

