def extract_first_name(full_name, delimiter=' ', ignore_prefixes=False, ignore_suffixes=False, include_middle_initial=False, cultural_name_handling='Western'):
    # Error handling for invalid inputs
    if not full_name or not isinstance(full_name, str):
        return {'error': 'Invalid full name provided.'}
    if not isinstance(delimiter, str) or len(delimiter) == 0:
        return {'error': 'Invalid delimiter provided.'}

    # Define common prefixes and suffixes
    prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.'] if ignore_prefixes else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if ignore_suffixes else []

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes
    if ignore_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle cultural naming conventions
    if cultural_name_handling == 'Eastern':
        # In some Eastern cultures, the family name comes first
        first_name_index = 1 if len(name_parts) > 1 else 0
    else:
        # Default to Western naming convention
        first_name_index = 0

    # Extract the first name
    first_name = name_parts[first_name_index]

    # Include middle initial if required
    if include_middle_initial and len(name_parts) > first_name_index + 1:
        middle_initial = name_parts[first_name_index + 1][0] + '.'
        first_name += ' ' + middle_initial

    return {'first_name': first_name}

