def char_to_binary(input, output_format='binary_string', bit_length=8, include_spaces=False):
    # Validate input
    if not isinstance(input, str) or len(input) == 0:
        return {'error': 'Input must be a non-empty string.'}
    if output_format not in ['binary_string', 'binary_list']:
        return {'error': "Output format must be 'binary_string' or 'binary_list'."}
    if bit_length not in [7, 8, 16]:
        return {'error': 'Bit length must be one of 7, 8, or 16.'}

    # Convert each character to binary
    binary_codes = []
    for char in input:
        binary_code = format(ord(char), f'0{bit_length}b')
        binary_codes.append(binary_code)

    # Format output
    if output_format == 'binary_string':
        if include_spaces:
            result = ' '.join(binary_codes)
        else:
            result = ''.join(binary_codes)
    elif output_format == 'binary_list':
        result = binary_codes

    return {'result': result}

