def alphabetical_sorter(input: str, case_sensitive: bool = False, ignore_non_alpha: bool = True, sort_order: str = 'ascending', output_format: str = 'string', return_indices: bool = False):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Validate sort_order parameter
    if sort_order not in ['ascending', 'descending']:
        return {'error': 'Invalid sort_order. Must be either "ascending" or "descending".'}

    # Validate output_format parameter
    if output_format not in ['string', 'array', 'json', 'csv']:
        return {'error': 'Invalid output_format. Must be one of "string", "array", "json", "csv".'}

    # Filter non-alphabetic characters if ignore_non_alpha is True
    if ignore_non_alpha:
        input = ''.join(filter(str.isalpha, input))

    # Sort the characters
    if not case_sensitive:
        input = input.lower()
    sorted_chars = sorted(input, reverse=(sort_order == 'descending'))

    # Prepare the output
    if output_format == 'string':
        result = ''.join(sorted_chars)
    elif output_format == 'array':
        result = sorted_chars
    elif output_format == 'json':
        result = {'sorted': sorted_chars}
    elif output_format == 'csv':
        result = ','.join(sorted_chars)

    # Return indices if requested
    if return_indices:
        indices = [input.index(char) for char in sorted_chars]
        return {'result': result, 'indices': indices}

    return {'result': result}

