def combined_length_calculator_v2(input, ignore_characters=[], ignore_position=[], case_sensitive=False, output_format='integer', delimiter=','):
    # Validate input
    if not isinstance(input, list) or len(input) < 2:
        raise ValueError('Input must be a list of at least two strings.')

    # Initialize total length
    total_length = 0

    # Process each string
    for string in input:
        # Apply case sensitivity
        if not case_sensitive:
            string = string.lower()
            ignore_characters = [char.lower() for char in ignore_characters]

        # Remove ignored characters
        for char in ignore_characters:
            string = string.replace(char, '')

        # Remove ignored positions
        if 'first' in ignore_position and len(string) > 0:
            string = string[1:]
        if 'last' in ignore_position and len(string) > 0:
            string = string[:-1]
        if 'middle' in ignore_position and len(string) > 2:
            string = string[0] + string[-1]

        # Add to total length
        total_length += len(string)

    # Format output
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return delimiter.join(input)
    elif output_format == 'detailed_report':
        report = f"Combined Length: {total_length}{delimiter}Strings: {delimiter.join(input)}"
        return report
    else:
        raise ValueError('Unsupported output format.')

