    from datetime import datetime
    import pytz
    import calendar

    # Validate date format
    try:
        date_obj = datetime.strptime(date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid date format. Please use YYYY-MM-DD.'

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'Hebrew', 'Islamic']:
        return 'Error: Unsupported calendar system. Supported systems are Gregorian, Julian, Hebrew, and Islamic.'

    # Validate time zone
    try:
        tz = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone. Please use a valid IANA time zone format.'

    # Adjust date for time zone
    date_obj = tz.localize(date_obj)

    # Calculate day of the week
    if calendar_system == 'Gregorian':
        day_index = date_obj.weekday()
    elif calendar_system == 'Julian':
        # Julian calendar logic (simplified)
        day_index = (date_obj.toordinal() + 1) % 7
    elif calendar_system == 'Hebrew':
        # Placeholder for Hebrew calendar logic
        day_index = (date_obj.toordinal() + 2) % 7
    elif calendar_system == 'Islamic':
        # Placeholder for Islamic calendar logic
        day_index = (date_obj.toordinal() + 3) % 7

    # Days of the week
    days_full = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    days_abbr = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']

    # Determine output format
    if output_format == 'full':
        return days_full[day_index]
