def prime_factorizer(number, include_multiplicity=False, output_format='list', max_factor_limit=None, performance_mode='standard', error_handling='strict'):
    # Validate input
    if not isinstance(number, int) or number == 0:
        if error_handling == 'strict':
            raise ValueError('Number must be a non-zero integer.')
        elif error_handling == 'lenient':
            return []

    # Initialize variables
    n = abs(number)
    factors = []
    multiplicity = {}

    # Function to find prime factors
    def find_factors(n):
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                factors.append(d)
                multiplicity[d] = multiplicity.get(d, 0) + 1
                n //= d
            d += 1
        if n > 1:
            factors.append(n)
            multiplicity[n] = multiplicity.get(n, 0) + 1

    # Find prime factors
    find_factors(n)

    # Apply max_factor_limit if specified
    if max_factor_limit is not None:
        factors = factors[:max_factor_limit]

    # Prepare output based on format
    if output_format == 'list':
        return factors
    elif output_format == 'dictionary':
        return multiplicity
    elif output_format == 'string':
        if include_multiplicity:
            return ', '.join([f'{p}^{multiplicity[p]}' for p in multiplicity])
        else:
            return ', '.join(map(str, factors))
    elif output_format == 'json':
        import json
        if include_multiplicity:
            return json.dumps(multiplicity)
        else:
            return json.dumps(factors)

