def reverse_string(input: str, ignore_characters: list = None, ignore_position: list = None, ignore_ranges: list = None, case_sensitive: bool = True, output_format: str = 'string'):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if ignore_characters and not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'All ignore_characters must be strings.'}
    if ignore_position and not all(p in ['first', 'last'] for p in ignore_position):
        return {'error': 'Ignore_position must contain only "first" or "last".'}
    if ignore_ranges:
        for r in ignore_ranges:
            if not isinstance(r, dict) or 'start' not in r or 'end' not in r:
                return {'error': 'Each ignore_range must be a dictionary with "start" and "end" keys.'}
            if not (isinstance(r['start'], int) and isinstance(r['end'], int)):
                return {'error': 'Start and end in ignore_ranges must be integers.'}
            if r['start'] < 0 or r['end'] >= len(input):
                return {'error': 'Ignore range indices out of bounds.'}

    # Prepare the string for reversal
    chars = list(input)
    if not case_sensitive:
        chars = [c.lower() for c in chars]

    # Apply ignore rules
    ignore_indices = set()
    if ignore_characters:
        ignore_indices.update(i for i, c in enumerate(chars) if c in ignore_characters)
    if ignore_position:
        if 'first' in ignore_position:
            ignore_indices.add(0)
        if 'last' in ignore_position:
            ignore_indices.add(len(chars) - 1)
    if ignore_ranges:
        for r in ignore_ranges:
            ignore_indices.update(range(r['start'], r['end'] + 1))

    # Reverse the string considering ignore indices
    reversed_chars = [chars[i] for i in range(len(chars)) if i not in ignore_indices]
    reversed_chars.reverse()
    for i in ignore_indices:
        reversed_chars.insert(i, chars[i])

    # Format the output
    if output_format == 'array':
        return reversed_chars
    elif output_format == 'json':
        return {'reversed': ''.join(reversed_chars)}
    else:
        return ''.join(reversed_chars)

