def closest_palindrome_finder(year, direction='both', output_format='integer', search_range=100, return_multiple=False):
    """
    Finds the closest palindrome number to a given year.

    Parameters:
    - year (int): The year to find the closest palindrome number for.
    - direction (str): The direction to search for palindrome numbers ('both', 'past', 'future').
    - output_format (str): The format of the output ('integer', 'text', 'detailed').
    - search_range (int): The maximum range (in years) to search for palindrome numbers.
    - return_multiple (bool): Whether to return multiple closest palindromes if they exist at the same distance.

    Returns:
    - The closest palindrome number or detailed information based on the output format.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    closest_palindromes = []
    min_distance = float('inf')

    # Search for palindromes in the specified direction
    if direction in ['both', 'past']:
        for y in range(year, year - search_range - 1, -1):
            if is_palindrome(y):
                distance = abs(year - y)
                if distance < min_distance:
                    closest_palindromes = [y]
                    min_distance = distance
                elif distance == min_distance and return_multiple:
                    closest_palindromes.append(y)

    if direction in ['both', 'future']:
        for y in range(year, year + search_range + 1):
            if is_palindrome(y):
                distance = abs(year - y)
                if distance < min_distance:
                    closest_palindromes = [y]
                    min_distance = distance
                elif distance == min_distance and return_multiple:
                    closest_palindromes.append(y)

    # Format the output based on the output_format parameter
    if output_format == 'integer':
        return closest_palindromes[0] if closest_palindromes else None
    elif output_format == 'text':
        return f"The closest palindrome year to {year} is {closest_palindromes[0]}"
    elif output_format == 'detailed':
        return {
            'year': year,
            'closest_palindromes': closest_palindromes,
            'search_range': search_range,
            'direction': direction,
            'output_format': output_format
        }
    else:
        raise ValueError("Invalid output_format specified.")

