def extract_character(input, position, custom_index=None, range_start=None, range_end=None):
    """
    Extracts specific characters or sequences from strings based on the given position or range.
    Parameters:
    - input (list of str): The strings from which characters or sequences will be extracted.
    - position (str): The position or range of characters to extract ('first', 'last', 'custom', 'range').
    - custom_index (int, optional): The custom index for character extraction, used only if position is 'custom'.
    - range_start (int, optional): The starting index for range extraction, used only if position is 'range'.
    - range_end (int, optional): The ending index for range extraction, used only if position is 'range'.
    Returns:
    - list of str: Extracted characters or sequences from each input string.
    """
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return "Error: 'input' must be a list of strings."
    if position not in ['first', 'last', 'custom', 'range']:
        return "Error: 'position' must be one of 'first', 'last', 'custom', 'range'."
    results = []
    for string in input:
        if position == 'first':
            results.append(string[0] if string else '')
        elif position == 'last':
            results.append(string[-1] if string else '')
        elif position == 'custom':
            if custom_index is None:
                return "Error: 'custom_index' must be provided for 'custom' position."
            try:
                results.append(string[custom_index])
            except IndexError:
                results.append('')
        elif position == 'range':
            if range_start is None or range_end is None:
                return "Error: 'range_start' and 'range_end' must be provided for 'range' position."
            results.append(string[range_start:range_end])
    return results

