def digit_extractor(number, position, output_format='integer', extract_multiple=False, error_handling='strict'):
    # Convert the number to a string to facilitate digit extraction
    num_str = str(abs(number)).replace('.', '')  # Remove decimal point for uniformity
    num_len = len(num_str)

    # Adjust position for negative indexing
    if position < 0:
        position = num_len + position + 1

    # Check if position is valid
    if position < 1 or position > num_len:
        if error_handling == 'ignore':
            return None
        elif error_handling == 'warn':
            print('Warning: Position out of range.')
            return None
        elif error_handling == 'strict':
            raise ValueError('Position out of range.')

    # Extract digits
    if extract_multiple:
        extracted = num_str[position-1:]
    else:
        extracted = num_str[position-1]

    # Format the output
    if output_format == 'integer':
        return int(extracted) if not extract_multiple else [int(d) for d in extracted]
    elif output_format == 'string':
        return extracted
    elif output_format == 'list':
        return [int(d) for d in extracted]

