def digit_extractor(number, position, length=1, output_format='integer', error_handling='raise'):
    # Convert the number to a string to facilitate digit extraction
    number_str = str(number).replace('.', '')  # Remove decimal point for simplicity
    num_digits = len(number_str)

    # Adjust position for negative indexing
    if position < 0:
        position = num_digits + position + 1

    # Validate position
    if position < 1 or position > num_digits:
        if error_handling == 'ignore':
            return None
        elif error_handling == 'default':
            return 0  # Default value
        else:
            raise ValueError('Position out of range')

    # Extract digits
    start_index = position - 1
    end_index = start_index + length
    extracted_digits = number_str[start_index:end_index]

    # Format output
    if output_format == 'integer':
        return int(extracted_digits)
    elif output_format == 'string':
        return extracted_digits
    elif output_format == 'list':
        return [int(digit) for digit in extracted_digits]
    else:
        raise ValueError('Invalid output format')

