def advanced_concatenation_tool(params):
    # Extract parameters with defaults
    inputs = params.get('inputs', [])
    separator_config = params.get('separator', {'default': ''})
    output_format = params.get('output_format', 'string')
    prefix = params.get('prefix', '')
    suffix = params.get('suffix', '')

    # Error handling for minimum items
    if len(inputs) < 2:
        return 'Error: At least two items are required for concatenation.'

    # Flatten nested arrays
    def flatten(items):
        for item in items:
            if isinstance(item, list):
                yield from flatten(item)
            else:
                yield item

    flat_inputs = list(flatten(inputs))

    # Determine separators
    default_separator = separator_config.get('default', '')
    string_separator = separator_config.get('type_specific', {}).get('string', default_separator)
    number_separator = separator_config.get('type_specific', {}).get('number', default_separator)

    # Concatenate items with appropriate separators
    result_parts = []
    for item in flat_inputs:
        if isinstance(item, str):
            result_parts.append(item)
        elif isinstance(item, (int, float)):
            result_parts.append(str(item))

    # Join parts with separators
    result = ''
    for i, part in enumerate(result_parts):
        if i > 0:
            if part.isdigit():
                result += number_separator
            else:
                result += string_separator
        result += part

    # Add prefix and suffix
    result = f'{prefix}{result}{suffix}'

    # Convert to number if required
    if output_format == 'number':
        try:
            result = float(result) if '.' in result else int(result)
        except ValueError:
            return 'Error: Cannot convert result to number.'

    return result

