def date_calculator(input_date: str, operation: str = 'subtract', days: int = 1, second_date: str = None, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate input_date format
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid input_date format. Expected YYYY-MM-DD.'

    # Validate operation
    if operation not in ['add', 'subtract', 'difference']:
        return 'Error: Invalid operation. Must be add, subtract, or difference.'

    # Handle time zone
    try:
        tz = pytz.timezone(time_zone)
        date_obj = tz.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Invalid time zone.'

    # Perform the operation
    if operation == 'subtract':
        result_date = date_obj - timedelta(days=days)
    elif operation == 'add':
        result_date = date_obj + timedelta(days=days)
    elif operation == 'difference':
        if not second_date:
            return 'Error: second_date is required for difference operation.'
        try:
            second_date_obj = datetime.strptime(second_date, '%Y-%m-%d')
            second_date_obj = tz.localize(second_date_obj)
        except ValueError:
            return 'Error: Invalid second_date format. Expected YYYY-MM-DD.'
        result_date = abs((date_obj - second_date_obj).days)
        return str(result_date)

    # Format the output
    if output_format == 'YYYY-MM-DD':
        return result_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return result_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return result_date.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DD HH:MM:SS':
        return result_date.strftime('%Y-%m-%d %H:%M:%S')
    elif output_format == 'MM-DD-YYYY HH:MM:SS':
        return result_date.strftime('%m-%d-%Y %H:%M:%S')
    elif output_format == 'DD-MM-YYYY HH:MM:SS':
        return result_date.strftime('%d-%m-%Y %H:%M:%S')
    else:
        return 'Error: Invalid output_format.'

