def date_calculator(input_date: str, days_to_add: int = 0, days_to_subtract: int = 0, months_to_add: int = 0, months_to_subtract: int = 0, years_to_add: int = 0, years_to_subtract: int = 0, calculate_difference: bool = False, second_date: str = None, output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import re

    # Validate input_date format
    date_format = '%Y-%m-%d'
    try:
        date_obj = datetime.strptime(input_date, date_format)
    except ValueError:
        return 'Error: input_date must be in YYYY-MM-DD format.'

    # Validate second_date if calculate_difference is True
    if calculate_difference:
        if not second_date:
            return 'Error: second_date is required when calculate_difference is True.'
        try:
            second_date_obj = datetime.strptime(second_date, date_format)
        except ValueError:
            return 'Error: second_date must be in YYYY-MM-DD format.'

    # Calculate new date
    if not calculate_difference:
        # Adjust date by adding/subtracting days, months, years
        date_obj += timedelta(days=days_to_add - days_to_subtract)
        date_obj += relativedelta(months=months_to_add - months_to_subtract)
        date_obj += relativedelta(years=years_to_add - years_to_subtract)

        # Format output date
        if output_format == 'YYYY-MM-DD':
            return date_obj.strftime('%Y-%m-%d')
        elif output_format == 'MM/DD/YYYY':
            return date_obj.strftime('%m/%d/%Y')
        elif output_format == 'DD-MM-YYYY':
            return date_obj.strftime('%d-%m-%Y')
        elif output_format == 'timestamp':
            return str(int(date_obj.timestamp()))
        else:
            return 'Error: Invalid output_format specified.'
    else:
        # Calculate difference between dates
        difference = second_date_obj - date_obj
        return str(difference.days) + ' days'

# Example usage based on the question
