def closest_palindrome_finder(year, year_range=None, direction='both', include_current=True, return_distance=False, multiple_closest=False):
    """
    Find the closest palindrome number to a given year or within a range of years.
    """
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    if not isinstance(year, int):
        return {'error': 'Invalid input: year must be an integer.'}

    if year_range:
        if not (isinstance(year_range, list) and len(year_range) == 2 and all(isinstance(y, int) for y in year_range)):
            return {'error': 'Invalid input: year_range must be a list of two integers.'}

    closest_palindrome = None
    min_distance = float('inf')
    results = []

    # Check if the current year is a palindrome
    if include_current and is_palindrome(year):
        closest_palindrome = year
        min_distance = 0
        results.append(year)

    # Search for the closest palindrome
    for offset in range(1, 10000):  # Arbitrary large range to find palindromes
        if direction in ['both', 'next']:
            next_year = year + offset
            if is_palindrome(next_year):
                if offset < min_distance:
                    closest_palindrome = next_year
                    min_distance = offset
                    results = [next_year]
                elif offset == min_distance and multiple_closest:
                    results.append(next_year)

        if direction in ['both', 'previous']:
            prev_year = year - offset
            if prev_year > 0 and is_palindrome(prev_year):
                if offset < min_distance:
                    closest_palindrome = prev_year
                    min_distance = offset
                    results = [prev_year]
                elif offset == min_distance and multiple_closest:
                    results.append(prev_year)

        if closest_palindrome is not None and not multiple_closest:
            break

    result = {'closest_palindrome': closest_palindrome}
    if return_distance:
        result['distance'] = min_distance
    if multiple_closest:
        result['all_closest_palindromes'] = results

    return result

# Example usage based on the question
result = closest_palindrome_finder(1864)
print(result)  # Expected output: {'closest_palindrome': 1881}

