# What is the square of 18?
# Answer: 324.0
result = advanced_math_operations(operation='square', numbers=[18])
print(result)  # Output should be 324.0

def music_tour_partner_finder(artist_name: str, partner_origin: str = '', music_genre: str = '', tour_location: str = '', tour_date_range: dict = {}, partner_popularity: int = 0, collaboration_history: bool = False):
