    :param partner_popularity: A threshold for the popularity of the tour partner.
    :param collaboration_history: Whether to filter partners based on previous collaborations.
    :return: The name of the tour partner that matches the criteria.
    """
    # Error handling for required parameter
    if not artist_name:
        return {'error': 'artist_name is required'}

    # Error handling for date range
    if 'start_date' in tour_date_range and 'end_date' in tour_date_range:
        try:
            start_date = datetime.strptime(tour_date_range['start_date'], '%Y-%m-%d')
            end_date = datetime.strptime(tour_date_range['end_date'], '%Y-%m-%d')
            if start_date > end_date:
                return {'error': 'start_date must be before end_date'}
        except ValueError:
            return {'error': 'Invalid date format, should be YYYY-MM-DD'}

    # Error handling for partner_popularity
    if partner_popularity < 0:
        return {'error': 'partner_popularity must be a non-negative integer'}

    # Simulated database of tour partners
    tour_partners = [
        {'name': 'Blood on the Dance Floor', 'origin': 'Orlando, Florida', 'genre': 'Electronic', 'location': 'United States', 'popularity': 50000, 'collaborated': True},
        # Additional simulated entries could be added here
    ]

    # Filter logic based on provided parameters
    for partner in tour_partners:
        if partner['name'] == 'Blood on the Dance Floor' and \
           partner['origin'] == partner_origin and \
           partner['genre'] == music_genre and \
           partner['location'] == tour_location and \
           partner['popularity'] >= partner_popularity and \
           (not collaboration_history or partner['collaborated']):
            return {'partner': partner['name']}

    return {'error': 'No matching tour partner found'}

