def year_difference_calculator(start_year, end_year, absolute_difference=False, output_format='integer', allow_non_integer=False, contextual_info=False):
    # Error handling for non-integer inputs
    if not allow_non_integer:
        if not isinstance(start_year, int) or not isinstance(end_year, int):
            return 'Error: Non-integer inputs are not allowed.'
    else:
        try:
            start_year = int(start_year)
            end_year = int(end_year)
        except ValueError:
            return 'Error: Inputs must be convertible to integers.'

    # Calculate the difference
    difference = end_year - start_year
    if absolute_difference:
        difference = abs(difference)

    # Handle output format
    if output_format == 'integer':
        return difference
    elif output_format == 'text':
        return f'The difference is {difference} years.'
    elif output_format == 'detailed_text':
        detailed_output = f'The difference between {start_year} and {end_year} is {difference} years.'
        if contextual_info:
            detailed_output += ' This period includes significant historical events.'
        return detailed_output
    else:
        return 'Error: Invalid output format specified.'

