def digit_sum_calculator_v2(year: str, ignore_non_numeric: bool = True, output_format: str = 'integer', numeral_system: str = 'decimal', include_digit_count: bool = False, separate_even_odd_sum: bool = False):
    # Validate numeral system
    if numeral_system not in ['decimal', 'binary', 'hexadecimal']:
        return {'error': 'Invalid numeral system specified.'}

    # Convert input to the specified numeral system
    try:
        if numeral_system == 'binary':
            numeric_value = int(year, 2)
        elif numeral_system == 'hexadecimal':
            numeric_value = int(year, 16)
        else:
            numeric_value = int(year)
    except ValueError:
        return {'error': 'Invalid input for the specified numeral system.'}

    # Filter out non-numeric characters if needed
    if ignore_non_numeric:
        year = ''.join(filter(str.isdigit, year))

    # Calculate the sum of digits
    digit_sum = sum(int(digit) for digit in year)
    even_sum = sum(int(digit) for digit in year if int(digit) % 2 == 0)
    odd_sum = sum(int(digit) for digit in year if int(digit) % 2 != 0)
    digit_count = len(year)

    # Prepare the output based on the specified format
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of the digits is {digit_sum}.'
    elif output_format == 'detailed':
        details = {
            'digit_sum': digit_sum,
            'digit_count': digit_count if include_digit_count else None,
            'even_sum': even_sum if separate_even_odd_sum else None,
            'odd_sum': odd_sum if separate_even_odd_sum else None
        }
        # Remove None values
        return {k: v for k, v in details.items() if v is not None}
    else:
        return {'error': 'Invalid output format specified.'}

