def sum_of_digits(numbers, output_format='integer', base=10, digit_filter=None):
    """
    Calculate the sum of the digits of given numbers.

    Parameters:
    - numbers (list of int): The numbers whose digits are to be summed.
    - output_format (str): The format of the output ('integer', 'text', 'detailed').
    - base (int): The numerical base for digit extraction.
    - digit_filter (list of int): Digits to include in the summation.

    Returns:
    - int or str: The sum of the digits in the specified format.
    """
    if not isinstance(numbers, list) or not all(isinstance(n, int) for n in numbers):
        raise ValueError("'numbers' must be a list of integers.")
    if output_format not in ['integer', 'text', 'detailed']:
        raise ValueError("'output_format' must be one of 'integer', 'text', 'detailed'.")
    if not isinstance(base, int) or base <= 1:
        raise ValueError("'base' must be an integer greater than 1.")
    if digit_filter is not None and (not isinstance(digit_filter, list) or not all(isinstance(d, int) for d in digit_filter)):
        raise ValueError("'digit_filter' must be a list of integers.")

    def sum_digits(number):
        digits = []
        while number > 0:
            digits.append(number % base)
            number //= base
        if digit_filter is not None:
            digits = [d for d in digits if d in digit_filter]
        return sum(digits)

    results = [sum_digits(num) for num in numbers]
    total_sum = sum(results)

    if output_format == 'integer':
        return total_sum
    elif output_format == 'text':
        return f"The sum of the digits is {total_sum}."
    elif output_format == 'detailed':
        detailed_result = ""
        for num, result in zip(numbers, results):
            detailed_result += f"Number: {num}, Sum of digits: {result}\n"
        detailed_result += f"Total sum: {total_sum}"
        return detailed_result

