def date_difference_calculator(start_date, end_date, calendar_system='gregorian', output_format='integer', include_time=False, business_days_only=False, holidays=[]):
    from datetime import datetime, timedelta
    import calendar

    # Helper function to parse date strings
    def parse_date(date_str):
        try:
            return datetime.strptime(date_str, '%Y-%m-%d')
        except ValueError:
            raise ValueError('Invalid date format. Please use YYYY-MM-DD.')

    # Parse the start and end dates
    start = parse_date(start_date)
    end = parse_date(end_date)

    # Validate date range
    if start > end:
        raise ValueError('Start date must be before end date.')

    # Calculate the difference in days
    delta = end - start
    days_difference = delta.days

    # Handle business days calculation if needed
    if business_days_only:
        current_date = start
        business_days = 0
        while current_date <= end:
            if current_date.weekday() < 5 and current_date.strftime('%Y-%m-%d') not in holidays:
                business_days += 1
            current_date += timedelta(days=1)
        days_difference = business_days

    # Return the result based on the output format
    if output_format == 'integer':
        return days_difference
    elif output_format == 'text':
        return f'The number of days between {start_date} and {end_date} is {days_difference} days.'
    elif output_format == 'detailed':
        years, remainder = divmod(days_difference, 365)
        months, days = divmod(remainder, 30)  # Simplified calculation
        return f'{years} years, {months} months, and {days} days'
    else:
        raise ValueError('Invalid output format specified.')

