def extract_first_name(full_name: str, case_sensitive: bool = False, output_format: str = 'string', include_middle_name: bool = False, prefix_handling: str = 'ignore', suffix_handling: str = 'ignore') -> str:
    # Validate input types
    if not isinstance(full_name, str):
        return 'Error: full_name must be a string.'
    if not isinstance(case_sensitive, bool):
        return 'Error: case_sensitive must be a boolean.'
    if output_format not in ['string', 'json', 'xml']:
        return 'Error: output_format must be one of ["string", "json", "xml"].'
    if not isinstance(include_middle_name, bool):
        return 'Error: include_middle_name must be a boolean.'
    if prefix_handling not in ['ignore', 'include', 'separate']:
        return 'Error: prefix_handling must be one of ["ignore", "include", "separate"].'
    if suffix_handling not in ['ignore', 'include', 'separate']:
        return 'Error: suffix_handling must be one of ["ignore", "include", "separate"].'

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefix
    if prefix_handling == 'include' and len(name_parts) > 1:
        first_name = name_parts[0] + ' ' + name_parts[1]
    else:
        first_name = name_parts[0]

    # Handle middle name inclusion
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + name_parts[1]

    # Handle suffix
    if suffix_handling == 'include' and len(name_parts) > 2:
        first_name += ' ' + name_parts[-1]

    # Adjust case sensitivity
    if not case_sensitive:
        first_name = first_name.lower().capitalize()

    # Format output
    if output_format == 'json':
        return {'first_name': first_name}
    elif output_format == 'xml':
        return f'<first_name>{first_name}</first_name>'
    else:
        return first_name

