def distinct_combinations(input_string, combination_length=2, output_format='array', case_sensitive=True, character_type_filter='all', max_combinations=None):
    import itertools

    # Validate input_string
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string.'}

    # Validate combination_length
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be a positive integer.'}

    # Validate output_format
    if output_format not in ['array', 'string']:
        return {'error': "output_format must be either 'array' or 'string'."}

    # Validate character_type_filter
    if character_type_filter not in ['all', 'letters', 'digits', 'symbols']:
        return {'error': "character_type_filter must be one of 'all', 'letters', 'digits', 'symbols'."}

    # Filter input_string based on character_type_filter
    if character_type_filter == 'letters':
        input_string = ''.join(filter(str.isalpha, input_string))
    elif character_type_filter == 'digits':
        input_string = ''.join(filter(str.isdigit, input_string))
    elif character_type_filter == 'symbols':
        input_string = ''.join(filter(lambda c: not c.isalnum(), input_string))

    # Adjust for case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Generate combinations
    combinations = set(itertools.combinations(input_string, combination_length))

    # Limit the number of combinations if max_combinations is set
    if max_combinations is not None:
        combinations = list(combinations)[:max_combinations]

    # Format output
    if output_format == 'string':
        return ''.join([''.join(comb) for comb in combinations])
    else:
        return [''.join(comb) for comb in combinations]

