def reverse_number(number, output_as_string=True, preserve_sign=True, decimal_precision=None):
    """
    Reverses the digits of the given number.

    Parameters:
    - number (int or float): The number to be reversed.
    - output_as_string (bool): Whether to output the reversed number as a string. Defaults to True.
    - preserve_sign (bool): Whether to preserve the sign of the number when reversing. Defaults to True.
    - decimal_precision (int): Specifies the number of decimal places to include in the output if the input is a float.

    Returns:
    - Reversed number as a string or number based on the parameters.
    """
    try:
        # Check if the number is an integer or float
        if not isinstance(number, (int, float)):
            raise ValueError("The 'number' parameter must be an integer or float.")

        # Convert number to string and handle negative sign
        num_str = str(number)
        if preserve_sign and number < 0:
            num_str = num_str[1:]
            reversed_str = '-' + num_str[::-1]
        else:
            reversed_str = num_str[::-1]

        # Handle decimal precision for floats
        if '.' in num_str and decimal_precision is not None:
            integer_part, decimal_part = reversed_str.split('.')
            decimal_part = decimal_part[:decimal_precision]
            reversed_str = integer_part + '.' + decimal_part

        # Convert to number if output_as_string is False
        if not output_as_string:
            if '.' in reversed_str:
                return float(reversed_str)
            else:
                return int(reversed_str)

        return reversed_str
    except Exception as e:
        return f"Error: {str(e)}"

