def extract_first_name(full_name, delimiter=' ', ignore_prefixes=True, custom_prefixes=None, include_middle_name=False, case_sensitive=False, ignore_suffixes=True):
    # Validate full_name parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name parameter. It must be a non-empty string.'}

    # Default prefixes and suffixes
    default_prefixes = ['Mr.', 'Ms.', 'Dr.']
    default_suffixes = ['Jr.', 'Sr.', 'III']

    # Combine default and custom prefixes
    prefixes = default_prefixes if ignore_prefixes else []
    if custom_prefixes:
        prefixes.extend(custom_prefixes)

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Remove prefixes
    if ignore_prefixes or custom_prefixes:
        name_parts = [part for part in name_parts if part not in prefixes]

    # Remove suffixes
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in default_suffixes]

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.capitalize() for part in name_parts]

    # Extract first name and optionally middle name
    if include_middle_name and len(name_parts) > 1:
        return {'first_name': ' '.join(name_parts[:2])}
    elif name_parts:
        return {'first_name': name_parts[0]}
    else:
        return {'error': 'Unable to extract first name from the provided full_name.'}

