def extract_character(input: str, position: str, custom_index: int = None, output_format: str = 'character', error_handling: str = 'strict'):
    # Error handling for empty input string
    if not input:
        if error_handling == 'warn':
            print('Warning: Input string is empty.')
        elif error_handling == 'strict':
            raise ValueError('Input string must be non-empty.')
        return None

    # Determine the index based on the position
    if position == 'first':
        index = 0
    elif position == 'last':
        index = len(input) - 1
    elif position == 'middle':
        index = len(input) // 2
    elif position == 'custom':
        if custom_index is None or custom_index < 0 or custom_index >= len(input):
            if error_handling == 'warn':
                print('Warning: Custom index is out of bounds.')
            elif error_handling == 'strict':
                raise ValueError('Custom index is out of bounds.')
            return None
        index = custom_index
    else:
        if error_handling == 'warn':
            print('Warning: Invalid position specified.')
        elif error_handling == 'strict':
            raise ValueError('Invalid position specified.')
        return None

    # Extract the character
    character = input[index]

    # Format the output
    if output_format == 'character':
        return character
    elif output_format == 'ascii':
        return ord(character)
    elif output_format == 'unicode':
        return ord(character)
    else:
        if error_handling == 'warn':
            print('Warning: Invalid output format specified.')
        elif error_handling == 'strict':
            raise ValueError('Invalid output format specified.')
        return None

