def ascii_converter(characters, output_format='integer', case_sensitive=True, delimiter=','):
    """
    Convert characters to their ASCII codes based on the specified format.
    :param characters: List of single-character strings to convert.
    :param output_format: The format for ASCII output ('integer', 'hexadecimal', 'binary', 'octal').
    :param case_sensitive: Boolean indicating if conversion is case-sensitive.
    :param delimiter: String used to separate ASCII codes in the output.
    :return: ASCII codes in the specified format, separated by the delimiter.
    """
    # Validate input
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: characters must be a list of single-character strings.'}
    if output_format not in ['integer', 'hexadecimal', 'binary', 'octal']:
        return {'error': 'Invalid output format. Choose from integer, hexadecimal, binary, octal.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}

    # Convert characters to ASCII codes
    ascii_codes = []
    for char in characters:
        if not case_sensitive:
            char = char.lower()
        ascii_code = ord(char)
        if output_format == 'hexadecimal':
            ascii_codes.append(hex(ascii_code)[2:])
        elif output_format == 'binary':
            ascii_codes.append(bin(ascii_code)[2:])
        elif output_format == 'octal':
            ascii_codes.append(oct(ascii_code)[2:])
        else:  # default to integer
            ascii_codes.append(str(ascii_code))

    # Join ASCII codes with the specified delimiter
    return delimiter.join(ascii_codes)

