def distinct_combinations(input_string, combination_length=2, case_sensitive=True, output_format='integer', include_characters='', exclude_characters='', character_type_filter='all'):
    import itertools
    import string

    # Error handling for input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be a positive integer'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if output_format not in ['integer', 'list']:
        return {'error': "output_format must be 'integer' or 'list'"}
    if character_type_filter not in ['all', 'alphabetic', 'numeric', 'alphanumeric']:
        return {'error': "character_type_filter must be 'all', 'alphabetic', 'numeric', or 'alphanumeric'"}

    # Adjust input string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        include_characters = include_characters.lower()
        exclude_characters = exclude_characters.lower()

    # Filter input string based on character type
    if character_type_filter == 'alphabetic':
        input_string = ''.join(filter(str.isalpha, input_string))
    elif character_type_filter == 'numeric':
        input_string = ''.join(filter(str.isdigit, input_string))
    elif character_type_filter == 'alphanumeric':
        input_string = ''.join(filter(lambda c: c.isalpha() or c.isdigit(), input_string))

    # Exclude specified characters
    if exclude_characters:
        input_string = ''.join(c for c in input_string if c not in exclude_characters)

    # Generate combinations
    combinations = set(itertools.combinations(input_string, combination_length))

    # Include specified characters
    if include_characters:
        combinations = {combo for combo in combinations if all(char in combo for char in include_characters)}

    # Return result based on output format
    if output_format == 'integer':
        return len(combinations)
    else:
        return [''.join(combo) for combo in combinations]

