def extract_last_name(full_name, ignore_prefixes=True, handle_hyphenated=True, output_format='string', handle_middle_names=False, handle_suffixes=True, cultural_naming_conventions='western'):
    # Error handling for full_name
    if not full_name or not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Validate output_format
    if output_format not in ['string', 'array', 'json']:
        return {'error': 'Invalid output_format. Must be one of: string, array, json.'}

    # Validate cultural_naming_conventions
    if cultural_naming_conventions not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid cultural_naming_conventions. Must be one of: western, eastern, custom.'}

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefixes if needed
    if ignore_prefixes:
        prefixes = ['Mr.', 'Mrs.', 'Ms.', 'Dr.']
        name_parts = [part for part in name_parts if part not in prefixes]

    # Handle suffixes if needed
    if handle_suffixes:
        suffixes = ['Jr.', 'Sr.', 'II', 'III']
        name_parts = [part for part in name_parts if part not in suffixes]

    # Determine last name based on cultural conventions
    last_name = ''
    if cultural_naming_conventions == 'western':
        last_name = name_parts[-1] if name_parts else ''
    elif cultural_naming_conventions == 'eastern':
        last_name = name_parts[0] if name_parts else ''
    elif cultural_naming_conventions == 'custom':
        # Custom logic can be implemented here
        last_name = name_parts[-1] if name_parts else ''

    # Handle hyphenated names
    if handle_hyphenated and '-' in last_name:
        last_name = last_name.replace('-', ' ')

    # Format the output
    if output_format == 'string':
        return last_name
    elif output_format == 'array':
        return [last_name]
    elif output_format == 'json':
        return {'last_name': last_name}

    return {'error': 'Unexpected error occurred.'}

