def consonant_counter(input: str, case_sensitive: bool = False, output_format: str = 'integer', consonants_to_count: list = [], ignore_special_characters: bool = True):
    # Validate parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'output_format must be one of ["integer", "text", "detailed"].'}
    if not isinstance(consonants_to_count, list) or not all(isinstance(c, str) and len(c) == 1 for c in consonants_to_count):
        return {'error': 'consonants_to_count must be a list of single-character strings.'}
    if not isinstance(ignore_special_characters, bool):
        return {'error': 'ignore_special_characters must be a boolean.'}

    # Define consonants
    all_consonants = 'bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ'
    consonants = consonants_to_count if consonants_to_count else all_consonants

    # Prepare input
    if not case_sensitive:
        input = input.lower()
        consonants = [c.lower() for c in consonants]

    # Count consonants
    consonant_count = {}
    for char in input:
        if ignore_special_characters and not char.isalpha():
            continue
        if char in consonants:
            consonant_count[char] = consonant_count.get(char, 0) + 1

    # Prepare output
    if output_format == 'integer':
        return sum(consonant_count.values())
    elif output_format == 'text':
        return f"Total consonants: {sum(consonant_count.values())}"
    elif output_format == 'detailed':
        return consonant_count

