def advanced_year_calculator(base_year, year_difference, output_format='integer', calendar_system='Gregorian', include_leap_year_info=False):
    # Validate input types
    if not isinstance(base_year, int) or not isinstance(year_difference, int):
        return {'error': 'base_year and year_difference must be integers'}
    if output_format not in ['integer', 'string', 'detailed']:
