    if calendar_system not in ['Gregorian', 'Julian', 'Islamic', 'Hebrew']:
        return {'error': 'Invalid calendar_system. Choose from Gregorian, Julian, Islamic, Hebrew.'}

    # Calculate the target year
    target_year = base_year + year_difference

    # Prepare the output based on the format
    if output_format == 'integer':
        return target_year
    elif output_format == 'string':
        return str(target_year)
    elif output_format == 'detailed':
        # Simulate detailed output with additional context
        detailed_info = f"Year: {target_year}, Calendar: {calendar_system}"
        if include_leap_year_info:
            # Simplified leap year check for Gregorian calendar
            is_leap = (target_year % 4 == 0 and (target_year % 100 != 0 or target_year % 400 == 0))
            detailed_info += f", Leap Year: {'Yes' if is_leap else 'No'}"
        return detailed_info

    # Default return in case of unexpected behavior
    return {'error': 'Unexpected error occurred.'}

