            return {'error': 'year_range must be a list of two integers [start_year, end_year].'}
        if not all(isinstance(year, int) for year in year_range):
            return {'error': 'year_range must contain integers.'}

    # Validate recipient_type
    if recipient_type not in ['individual', 'work']:
        return {'error': "recipient_type must be either 'individual' or 'work'."}

    # Perform the search
    key = (award_name, recipient_name)
