def date_calculator(start_date: str, time_unit: str, amount: int, output_format: str = 'date', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        date = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Use YYYY-MM-DD.'

    # Validate time_unit
    if time_unit not in ['days', 'weeks', 'months', 'years', 'business_days']:
        return 'Error: Invalid time_unit. Must be one of days, weeks, months, years, business_days.'

    # Validate time_zone
    try:
        tz = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return 'Error: Invalid time_zone. Use a valid IANA time zone.'

    # Adjust date based on time_unit
    if time_unit == 'days':
        date += timedelta(days=amount)
    elif time_unit == 'weeks':
        date += timedelta(weeks=amount)
    elif time_unit == 'months':
        date += relativedelta(months=amount)
    elif time_unit == 'years':
        date += relativedelta(years=amount)
    elif time_unit == 'business_days':
        days_added = 0
        while days_added < abs(amount):
            date += timedelta(days=1 if amount > 0 else -1)
            if date.weekday() < 5:  # Monday to Friday are business days
                days_added += 1

    # Convert date to specified time zone
    date = date.astimezone(tz)

