    name_parts = full_name.split()

    # Logic for extracting last name based on the format
    if name_format == 'western':
        # Assume the last name is the last part
        last_name = name_parts[-1]

        # Handle compound last names
        if handle_compound_last_names and len(name_parts) > 1:
            # Check for common compound last name indicators
            compound_indicators = ['de', 'la', 'van', 'von']
            for i in range(len(name_parts) - 2, -1, -1):
                if name_parts[i].lower() in compound_indicators:
                    last_name = ' '.join(name_parts[i:])
                    break

        # Include suffix if required
        if include_suffix and len(name_parts) > 1:
            suffixes = ['Jr.', 'Sr.', 'II', 'III']
            if name_parts[-1] in suffixes:
                last_name += ' ' + name_parts[-1]

        # Include middle name if required
        if include_middle_name and len(name_parts) > 2:
            last_name = ' '.join(name_parts[1:])

    # Additional logic for other name formats can be implemented here
    else:
        # Default to western logic for simplicity in this example
