def character_lookup(actor_name, movie_title, case_sensitive=False, exact_match=True, release_year=None, partial_match=False, multiple_actors=None, multiple_movies=None):
    """
    Retrieve character names portrayed by actors in specific movies.

    Parameters:
    - actor_name (str): The name of the actor whose character name is to be retrieved.
    - movie_title (str): The title of the movie in which the actor's character name is to be retrieved.
    - case_sensitive (bool): Whether the search should be case-sensitive. Defaults to false.
    - exact_match (bool): Whether to match the actor name and movie title exactly. Defaults to true.
    - release_year (int, optional): The year of the movie's release to narrow down the search.
    - partial_match (bool): Whether to allow partial matches for actor names and movie titles. Defaults to false.
    - multiple_actors (list of str, optional): A list of actor names for multiple actor queries.
    - multiple_movies (list of str, optional): A list of movie titles for multiple movie queries.

    Returns:
    - str: The character name or an error message.
    """
    # Error handling for required parameters
    if not actor_name or not movie_title:
        return "Error: 'actor_name' and 'movie_title' are required parameters."

    # Simulated database of movies and characters
    database = {
        ('Anna Camp', 'Pitch Perfect 2'): 'Aubrey Posen',
        # Additional entries can be added here
    }

    # Normalize input based on case sensitivity
    if not case_sensitive:
        actor_name = actor_name.lower()
        movie_title = movie_title.lower()
        database = {(k[0].lower(), k[1].lower()): v for k, v in database.items()}

    # Check for multiple actors or movies
    if multiple_actors:
        results = {}
        for actor in multiple_actors:
            key = (actor.lower() if not case_sensitive else actor, movie_title)
            results[actor] = database.get(key, "Character not found")
        return results

    if multiple_movies:
        results = {}
        for movie in multiple_movies:
            key = (actor_name, movie.lower() if not case_sensitive else movie)
            results[movie] = database.get(key, "Character not found")
        return results

    # Exact or partial match logic
    if exact_match:
        key = (actor_name, movie_title)
        return database.get(key, "Character not found")
    else:
        for (actor, movie), character in database.items():
            if (partial_match and actor_name in actor and movie_title in movie) or (actor_name == actor and movie_title == movie):
                return character
        return "Character not found"

def first_letter_extractor_v2(input: str, output_format: str = 'character', encoding: str = 'UTF-8', include_whitespace: bool = False):
    # Validate encoding
    if encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return {'error': 'Unsupported encoding type'}

    # Validate output_format
    if output_format not in ['character', 'position_info', 'all_first_letters']:
        return {'error': 'Invalid output format'}

    # Handle empty input
    if not input:
        return {'error': 'Input string is empty'}

    # Extract first letter based on output_format
    if output_format == 'character':
        # Consider whitespace if include_whitespace is True
        if include_whitespace:
            return {'result': input[0]}
        else:
            for char in input:
                if not char.isspace():
                    return {'result': char}
    elif output_format == 'position_info':
        for index, char in enumerate(input):
            if not char.isspace() or include_whitespace:
                return {'result': {'character': char, 'position': index}}
    elif output_format == 'all_first_letters':
        words = input.split()
        first_letters = [word[0] for word in words]
        return {'result': first_letters}

    return {'error': 'Unexpected error occurred'}

