def enhanced_consonant_counter(input: str, vowels=['a', 'e', 'i', 'o', 'u'], consonant_groups=[], case_sensitive=False, output_format='integer', include_non_alpha=False):
    # Ensure input is a string
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Normalize case if not case-sensitive
    if not case_sensitive:
        input = input.lower()
        vowels = [v.lower() for v in vowels]
        consonant_groups = [c.lower() for c in consonant_groups]

    # Define consonants
    consonants = set('abcdefghijklmnopqrstuvwxyz') - set(vowels)

    # Count consonants
    consonant_count = 0
    consonant_details = {}
    for char in input:
        if char.isalpha() or include_non_alpha:
            if char in consonants:
                consonant_count += 1
                if output_format == 'detailed_report':
                    consonant_details[char] = consonant_details.get(char, 0) + 1

    # Prepare output
    if output_format == 'integer':
        return consonant_count
    elif output_format == 'text':
        return f'There are {consonant_count} consonants in the input.'
    elif output_format == 'detailed_report':
        return {'total_consonants': consonant_count, 'details': consonant_details}
    else:
        return {'error': 'Invalid output format specified.'}

