def date_calculator(input_date: str, increment: dict, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Parse the input date
    try:
        input_datetime = datetime.strptime(input_date, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        try:
            input_datetime = datetime.strptime(input_date, '%Y-%m-%d')
        except ValueError:
            return 'Error: Invalid input date format.'

    # Apply time zone
    try:
        tz = pytz.timezone(time_zone)
        input_datetime = tz.localize(input_datetime)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Calculate the new date with increments
    try:
        years = increment.get('years', 0)
        months = increment.get('months', 0)
        weeks = increment.get('weeks', 0)
        days = increment.get('days', 0)
        hours = increment.get('hours', 0)
        minutes = increment.get('minutes', 0)

        new_datetime = input_datetime + relativedelta(years=years, months=months)
        new_datetime += timedelta(weeks=weeks, days=days, hours=hours, minutes=minutes)
    except Exception as e:
        return f'Error: {str(e)}'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return new_datetime.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        return new_datetime.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        return new_datetime.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        return new_datetime.strftime('%Y-%m-%dT%H:%M:%S')
    else:
        return 'Error: Unsupported output format.'

