def date_parser(date_input, output_format='number', delimiter=' ', date_format='DMY', time_included=False, error_handling='strict'):
    """
    Parses a date string and extracts specific components based on the provided parameters.

    :param date_input: The date string to be parsed.
    :param output_format: The format of the output ('number', 'name', 'full_date', 'day_of_week', 'quarter').
    :param delimiter: The delimiter used in the date string.
    :param date_format: The format of the date string ('DMY', 'MDY', 'YMD', 'YDM').
    :param time_included: Indicates whether the time component is included in the date string.
    :param error_handling: The error handling mode ('strict', 'lenient').
    :return: The extracted date component based on the output_format.
    """
    import datetime
    from dateutil import parser

    try:
        # Replace delimiter with space for uniform parsing
        date_input = date_input.replace(delimiter, ' ')

        # Parse the date
        if date_format == 'DMY':
            parsed_date = datetime.datetime.strptime(date_input, '%d %B %Y')
        elif date_format == 'MDY':
            parsed_date = datetime.datetime.strptime(date_input, '%B %d %Y')
        elif date_format == 'YMD':
            parsed_date = datetime.datetime.strptime(date_input, '%Y %B %d')
        elif date_format == 'YDM':
            parsed_date = datetime.datetime.strptime(date_input, '%Y %d %B')
        else:
            if error_handling == 'strict':
                raise ValueError('Invalid date format specified.')
            else:
                parsed_date = parser.parse(date_input)

        # Extract the required component
        if output_format == 'number':
            return parsed_date.month
        elif output_format == 'name':
            return parsed_date.strftime('%B')
        elif output_format == 'full_date':
            return parsed_date.strftime('%Y-%m-%d')
        elif output_format == 'day_of_week':
            return parsed_date.strftime('%A')
        elif output_format == 'quarter':
            return (parsed_date.month - 1) // 3 + 1
        else:
            if error_handling == 'strict':
                raise ValueError('Invalid output format specified.')
            else:
                return None

    except Exception as e:
        if error_handling == 'strict':
            raise e
        else:
            return str(e)

# Example usage
result = date_parser('7 October 1978', output_format='number')
print(result)  # Output: 10

