def date_incrementer(start_date, months_to_add=1, days_to_add=0, years_to_add=0, date_format='YYYY-MM-DD'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Add years, months, and days
    try:
        date_obj += relativedelta(years=years_to_add)
        date_obj += relativedelta(months=months_to_add)
        date_obj += timedelta(days=days_to_add)
    except Exception as e:
        return {'error': str(e)}

    # Format the output date
    try:
        if date_format == 'YYYY-MM-DD':
            return {'result': date_obj.strftime('%Y-%m-%d')}
        else:
            return {'error': 'Unsupported date format.'}
    except Exception as e:
        return {'error': str(e)}

