    Retrieve comprehensive biographical information about individuals in the film industry.

    Parameters:
    - role (str): The role of the individual in the film industry, e.g., director, actor.
    - work_title (str): The title of the work associated with the individual.
    - output_fields (list): The fields of information to be retrieved about the individual.
    - contextual_data (dict, optional): Additional contextual data such as active years and notable collaborations.

    Returns:
    - dict: A dictionary containing the requested biographical information.
    """
    # Simulated database of biographical data
    database = {
        ('director', 'Maniac'): {
            'birth_year': 1986,
            'birth_date': 'June 11, 1986',
            'full_name': 'Cary Joji Fukunaga',
            'nationality': 'American',
            'awards': ['Primetime Emmy Award'],
            'filmography': ['Maniac', 'True Detective']
        }
    }

    # Validate required parameters
    if not role or not work_title or not output_fields:
        return {'error': 'Missing required parameters: role, work_title, and output_fields are required.'}

    # Validate output_fields
    valid_fields = {'birth_year', 'birth_date', 'full_name', 'nationality', 'awards', 'filmography'}
    if not all(field in valid_fields for field in output_fields):
        return {'error': 'Invalid output_fields specified. Valid fields are: birth_year, birth_date, full_name, nationality, awards, filmography.'}

    # Retrieve data from the simulated database
    key = (role, work_title)
    if key not in database:
        return {'error': 'No data found for the specified role and work_title.'}

    # Extract the requested information
    data = database[key]
    result = {field: data[field] for field in output_fields if field in data}

    return result

# Example usage
result = biographical_data_query('director', 'Maniac', ['birth_date'])
print(result)  # Output: {'birth_date': 'June 11, 1986'}

def advanced_date_calculator(input_date_time, operation, unit, value=None, second_date_time=None, output_format='YYYY-MM-DDTHH:MM:SS', time_zone='UTC'):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate required parameters
    if not input_date_time or not operation or not unit or not output_format:
        return {'error': 'Missing required parameters.'}

    # Validate operation
    if operation not in ['add', 'subtract', 'difference']:
        return {'error': 'Invalid operation.'}

    # Validate unit
    if unit not in ['days', 'months', 'years', 'hours', 'minutes', 'seconds']:
        return {'error': 'Invalid unit.'}

    # Parse input date
    try:
        input_date = datetime.fromisoformat(input_date_time)
    except ValueError:
        return {'error': 'Invalid input_date_time format.'}

    # Handle time zone
    try:
        tz = pytz.timezone(time_zone)
        input_date = input_date.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone.'}

    # Perform operation
    if operation == 'subtract':
        if unit == 'days':
            result_date = input_date - timedelta(days=value)
        elif unit == 'months':
            result_date = input_date - relativedelta(months=value)
        elif unit == 'years':
            result_date = input_date - relativedelta(years=value)
        elif unit == 'hours':
            result_date = input_date - timedelta(hours=value)
        elif unit == 'minutes':
            result_date = input_date - timedelta(minutes=value)
        elif unit == 'seconds':
            result_date = input_date - timedelta(seconds=value)
    else:
        return {'error': 'Operation not supported in this context.'}

    # Format output date
    if output_format == 'YYYY-MM-DDTHH:MM:SS':
        formatted_date = result_date.strftime('%Y-%m-%dT%H:%M:%S')
    elif output_format == 'MM-DD-YYYY HH:MM:SS':
        formatted_date = result_date.strftime('%m-%d-%Y %H:%M:%S')
    elif output_format == 'DD-MM-YYYY HH:MM:SS':
        formatted_date = result_date.strftime('%d-%m-%Y %H:%M:%S')
    else:
        return {'error': 'Invalid output format.'}

    return {'result': formatted_date}

