def date_calculator(start_date: str, interval: int, unit: str = 'days', output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', consider_holidays: bool = False) -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DD.'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Invalid time zone specified.'

    # Calculate new date based on unit
    if unit == 'days':
        new_date_obj = start_date_obj + timedelta(days=interval)
    elif unit == 'weeks':
        new_date_obj = start_date_obj + timedelta(weeks=interval)
    elif unit == 'months':
        new_date_obj = start_date_obj + relativedelta(months=interval)
    elif unit == 'business_days':
        # Simplified business day calculation (excluding weekends)
        days_added = 0
        while days_added < abs(interval):
            start_date_obj += timedelta(days=1 if interval > 0 else -1)
            if start_date_obj.weekday() < 5:  # Monday to Friday
                days_added += 1
        new_date_obj = start_date_obj
    else:
        return 'Error: Invalid unit specified.'

    # Format output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date_obj.strftime('%d-%m-%Y')
    elif output_format == 'ISO-8601':
        formatted_date = new_date_obj.isoformat()
    else:
        return 'Error: Invalid output format specified.'

    return formatted_date

