def date_calculator(start_date: str, duration: int, unit: str, operation: str, time_zone: str = 'UTC', business_days_only: bool = False, calendar_system: str = 'gregorian') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate input parameters
    try:
        # Parse the start date
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%SZ')
        # Apply the time zone
        start_date_obj = pytz.timezone(time_zone).localize(start_date_obj)
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SSZ.'
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Validate unit
    if unit not in ['minutes', 'hours', 'days', 'weeks', 'months', 'years']:
        return 'Error: Invalid unit. Must be one of minutes, hours, days, weeks, months, years.'

    # Validate operation
    if operation not in ['add', 'subtract']:
        return 'Error: Invalid operation. Must be add or subtract.'

    # Validate calendar system
    if calendar_system not in ['gregorian', 'julian']:
        return 'Error: Invalid calendar system. Must be gregorian or julian.'

    # Perform the date calculation
    if unit == 'days':
        delta = timedelta(days=duration)
    elif unit == 'weeks':
        delta = timedelta(weeks=duration)
    elif unit == 'hours':
        delta = timedelta(hours=duration)
    elif unit == 'minutes':
        delta = timedelta(minutes=duration)
    else:
        return 'Error: Unsupported unit for this implementation.'

    if operation == 'subtract':
        delta = -delta

    # Calculate the new date
    new_date_obj = start_date_obj + delta

    # Return the result in the specified format
    return new_date_obj.strftime('%Y-%m-%d')

