def actor_role_identifier(actor_name: str = '', role_name: str = '', show_title: str = '', additional_filters: dict = None) -> dict:
    """
    Identifies actors based on their roles in TV shows and movies.
    :param actor_name: The name of the actor or actress, if known.
    :param role_name: The name of the character or role played by the actor or actress.
    :param show_title: The title of the television show or movie in which the role is featured.
    :param additional_filters: Additional filters such as genre, year, director_name, award_wins, and language.
    :return: A dictionary containing the search results or error messages.
    """
    if not role_name or not show_title:
        return {'error': 'Both role_name and show_title are required parameters.'}

    if additional_filters is None:
        additional_filters = {}

    # Simulate a database search with the given parameters
    # For demonstration, we assume the database contains a record for Gina in Brooklyn Nine-Nine
    database = [
        {'actor_name': 'Chelsea Peretti', 'role_name': 'Gina Linetti', 'show_title': 'Brooklyn Nine-Nine',
         'additional_filters': {'genre': 'Comedy', 'year': 2013, 'director_name': 'Michael Schur',
                                'award_wins': 0, 'language': 'English'}}
    ]

    # Search logic
    results = []
    for entry in database:
        if (role_name.lower() in entry['role_name'].lower() and
                show_title.lower() in entry['show_title'].lower()):
            # Check additional filters
            match = True
            for key, value in additional_filters.items():
                if key in entry['additional_filters'] and entry['additional_filters'][key] != value:
                    match = False
                    break
            if match:
                results.append(entry)

    if results:
        return {'results': results}
    else:
        return {'error': 'No matching records found.'}

