def date_calculator(start_date: str, days_difference: int = 0, weeks_difference: int = 0, months_difference: int = 0, output_format: str = 'YYYY-MM-DD', custom_format: str = '', time_zone: str = 'UTC', include_day_of_week: bool = False, business_days_only: bool = False) -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta
    import calendar

    # Error handling for date format
    try:
        date = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Use YYYY-MM-DD.'

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date = tz.localize(date)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Calculate total days difference
    total_days = days_difference + weeks_difference * 7

    # Adjust for business days only
    if business_days_only:
        while total_days != 0:
            date += timedelta(days=1 if total_days > 0 else -1)
            if date.weekday() < 5:  # Monday to Friday are business days
                total_days -= 1 if total_days > 0 else -1
    else:
        date += timedelta(days=total_days)

    # Adjust for months difference
    date += relativedelta(months=months_difference)

    # Format the output date
    if output_format == 'custom' and custom_format:
        formatted_date = date.strftime(custom_format)
    elif output_format == 'YYYY-MM-DD':
        formatted_date = date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
