def date_calculator(start_date: str, interval: dict, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', handle_leap_years: bool = True, adjust_for_dst: bool = True) -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate and parse the start_date
    try:
        start_date_dt = datetime.fromisoformat(start_date.replace('Z', '+00:00'))
    except ValueError:
        return 'Error: Invalid start_date format. Expected ISO 8601 format.'

    # Validate interval
    if 'value' not in interval or 'unit' not in interval:
        return 'Error: Interval must include both value and unit.'

    value = interval['value']
    unit = interval['unit']

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_dt = start_date_dt.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone specified.'

    # Calculate the new date based on the interval
    if unit == 'months':
        new_date_dt = start_date_dt - relativedelta(months=value)
    elif unit == 'years':
        new_date_dt = start_date_dt - relativedelta(years=value)
    elif unit == 'weeks':
        new_date_dt = start_date_dt - timedelta(weeks=value)
    elif unit == 'days':
        new_date_dt = start_date_dt - timedelta(days=value)
    elif unit == 'hours':
        new_date_dt = start_date_dt - timedelta(hours=value)
    elif unit == 'minutes':
        new_date_dt = start_date_dt - timedelta(minutes=value)
    elif unit == 'seconds':
        new_date_dt = start_date_dt - timedelta(seconds=value)
    else:
        return 'Error: Unsupported interval unit.'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return new_date_dt.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return new_date_dt.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return new_date_dt.strftime('%d-%m-%Y')
    elif output_format == 'YYYY-MM-DDTHH:MM:SSZ':
        return new_date_dt.strftime('%Y-%m-%dT%H:%M:%SZ')
    else:
        return 'Error: Unsupported output format.'

