def parole_eligibility_calculator(conviction_date, sentence_length, jurisdiction, good_behavior_reduction, parole_law_version, prior_convictions, crime_severity, rehabilitation_programs):
    from datetime import datetime, timedelta

    # Validate conviction_date format
    try:
        conviction_date_obj = datetime.strptime(conviction_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format for conviction_date. Expected YYYY-MM-DD.'}

    # Validate sentence_length
    if 'years' not in sentence_length:
        return {'error': 'sentence_length must include at least the number of years.'}

    # Calculate total sentence duration in days
    total_days = sentence_length.get('years', 0) * 365 + sentence_length.get('months', 0) * 30 + sentence_length.get('days', 0)

    # Apply good behavior reduction if applicable
    if good_behavior_reduction:
        total_days *= 0.85  # Assuming a 15% reduction for good behavior

    # Adjust for jurisdiction-specific parole laws
    # This is a placeholder for jurisdiction-specific logic
    if jurisdiction == 'example_jurisdiction':
        total_days *= 0.9  # Example adjustment

    # Adjust based on prior convictions and crime severity
    if prior_convictions > 0:
        total_days *= 1.1  # Increase by 10% for prior convictions
    if crime_severity == 'high':
        total_days *= 1.2  # Increase by 20% for high severity crimes

    # Consider rehabilitation programs
    if 'anger_management' in rehabilitation_programs:
        total_days *= 0.95  # 5% reduction for completing anger management

    # Calculate parole eligibility date
    parole_eligibility_date = conviction_date_obj + timedelta(days=total_days)

