def date_calculator(base_date: str, years_to_add: int = 0, months_to_add: int = 0, days_to_add: int = 0, output_format: str = 'string', validate_input: bool = True):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import re

    # Helper function to validate date format
    def validate_date_format(date_str):
        # Simple regex to match YYYY-MM-DD format
        return bool(re.match(r'^\d{4}-\d{2}-\d{2}$', date_str))

    # Validate input if required
    if validate_input:
        if not validate_date_format(base_date):
            return {'error': 'Invalid date format. Expected YYYY-MM-DD.'}
        if output_format not in ['string', 'timestamp', 'ISO8601', 'RFC2822']:
            return {'error': 'Unsupported output format.'}

    try:
        # Parse the base date
        date_obj = datetime.strptime(base_date, '%Y-%m-%d')

        # Add years, months, and days
        date_obj += relativedelta(years=years_to_add, months=months_to_add)
        date_obj += timedelta(days=days_to_add)

        # Format the output
        if output_format == 'string':
            return {'result': date_obj.strftime('%Y-%m-%d')}
        elif output_format == 'timestamp':
            return {'result': int(date_obj.timestamp())}
        elif output_format == 'ISO8601':
            return {'result': date_obj.isoformat()}
        elif output_format == 'RFC2822':
            return {'result': date_obj.strftime('%a, %d %b %Y %H:%M:%S +0000')}
    except Exception as e:
        return {'error': str(e)}

