def tv_show_character_lookup(actor_name, character_name, output_format='text', include_details=False, max_results=1):
    # Validate input types
    if not isinstance(actor_name, list) or not all(isinstance(name, str) for name in actor_name):
        return {'error': 'Invalid actor_name format. Must be a list of strings.'}
    if not isinstance(character_name, list) or not all(isinstance(name, str) for name in character_name):
        return {'error': 'Invalid character_name format. Must be a list of strings.'}
    if output_format not in ['text', 'json', 'xml']:
        return {'error': 'Invalid output_format. Must be one of: text, json, xml.'}
    if not isinstance(include_details, bool):
        return {'error': 'Invalid include_details format. Must be a boolean.'}
    if not isinstance(max_results, int) or max_results < 1:
        return {'error': 'Invalid max_results. Must be a positive integer.'}

    # Simulated database of TV shows
    tv_show_database = {
        ('Charlie McDermott', 'Axl Heck'): {
            'show_name': 'The Middle',
            'details': {
                'genre': 'Sitcom',
                'release_year': 2009,
                'episode_count': 215
            }
        }
    }

    # Find the TV show based on actor and character
    results = []
    for actor, character in zip(actor_name, character_name):
        key = (actor, character)
        if key in tv_show_database:
            show_info = tv_show_database[key]
            if include_details:
                result = show_info
            else:
                result = {'show_name': show_info['show_name']}
            results.append(result)

    # Limit results to max_results
    results = results[:max_results]

    # Format output
    if output_format == 'json':
        return {'results': results}
    elif output_format == 'xml':
        # Simulate XML output
        xml_results = '<results>'
        for result in results:
            xml_results += f"<show><name>{result['show_name']}</name>"
            if include_details:
                xml_results += f"<genre>{result['details']['genre']}</genre>"
                xml_results += f"<release_year>{result['details']['release_year']}</release_year>"
                xml_results += f"<episode_count>{result['details']['episode_count']}</episode_count>"
            xml_results += '</show>'
        xml_results += '</results>'
        return {'results': xml_results}
    else:  # Default to text
