def date_subtractor(input_date: str, years_to_subtract: int = 1, months_to_subtract: int = 0, days_to_subtract: int = 0, output_format: str = 'string'):
    from datetime import datetime
    from dateutil.relativedelta import relativedelta

    # Supported date formats
    date_formats = ['%Y-%m-%d', '%m/%d/%Y']

    # Attempt to parse the input date
    parsed_date = None
    for fmt in date_formats:
        try:
            parsed_date = datetime.strptime(input_date, fmt)
            break
        except ValueError:
            continue

    if not parsed_date:
        return {'error': 'Invalid date format. Supported formats are YYYY-MM-DD and MM/DD/YYYY.'}

    # Subtract the specified years, months, and days
    result_date = parsed_date - relativedelta(years=years_to_subtract, months=months_to_subtract, days=days_to_subtract)

    # Format the output based on the specified output format
    if output_format == 'string':
        return result_date.strftime('%Y-%m-%d')
    elif output_format == 'date_object':
        return result_date
    elif output_format == 'timestamp':
        return int(result_date.timestamp())
    else:
        return {'error': 'Invalid output format. Supported formats are string, date_object, and timestamp.'}

