def date_calculator(start_date, days_to_add=0, weeks_to_add=0, months_to_add=0, output_format='YYYY-MM-DD', time_zone='UTC'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate and parse the start_date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Apply time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone specified.'}

    # Calculate the new date
    try:
        # Add days and weeks
        delta_days = timedelta(days=days_to_add + weeks_to_add * 7)
        new_date_obj = start_date_obj + delta_days

        # Add months
        new_date_obj = new_date_obj + relativedelta(months=months_to_add)
    except Exception as e:
        return {'error': f'Error in date calculation: {str(e)}'}

    # Format the output date
    try:
        if output_format == 'YYYY-MM-DD':
            formatted_date = new_date_obj.strftime('%Y-%m-%d')
        elif output_format == 'MM/DD/YYYY':
            formatted_date = new_date_obj.strftime('%m/%d/%Y')
        elif output_format == 'DD-MM-YYYY':
            formatted_date = new_date_obj.strftime('%d-%m-%Y')
        elif output_format == 'YYYY/MM/DD':
            formatted_date = new_date_obj.strftime('%Y/%m/%d')
        else:
            return {'error': 'Invalid output_format specified.'}
    except Exception as e:
        return {'error': f'Error in formatting date: {str(e)}'}

    return {'result': formatted_date}

