def date_calculator_plus(start_date: str, days_to_add: int, hours_to_add: int = 0, minutes_to_add: int = 0, time_zone: str = 'UTC', output_format: str = 'YYYY-MM-DDTHH:MM:SS') -> str:
    """
    Calculate a new date and time by adding or subtracting days, hours, and minutes from a given start date.

    :param start_date: The starting date and time in 'YYYY-MM-DDTHH:MM:SS' format.
    :param days_to_add: The number of days to add (or subtract if negative).
    :param hours_to_add: The number of hours to add (or subtract if negative).
    :param minutes_to_add: The number of minutes to add (or subtract if negative).
    :param time_zone: The time zone of the start date, specified in IANA format.
    :param output_format: The format of the output date and time.
    :return: The calculated date and time in the specified format.
    """
    try:
        # Parse the start date
        start_dt = datetime.datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%S')

        # Apply the time zone
        tz = pytz.timezone(time_zone)
        start_dt = tz.localize(start_dt)

        # Calculate the new date and time
        delta = datetime.timedelta(days=days_to_add, hours=hours_to_add, minutes=minutes_to_add)
        new_dt = start_dt + delta

        # Format the output
        if output_format == 'YYYY-MM-DD':
            return new_dt.strftime('%Y-%m-%d')
        elif output_format == 'MM/DD/YYYY':
            return new_dt.strftime('%m/%d/%Y')
        elif output_format == 'DD-MM-YYYY':
            return new_dt.strftime('%d-%m-%Y')
        elif output_format == 'YYYY-MM-DDTHH:MM:SS':
            return new_dt.strftime('%Y-%m-%dT%H:%M:%S')
        elif output_format == 'MM/DD/YYYY HH:MM':
            return new_dt.strftime('%m/%d/%Y %H:%M')
        elif output_format == 'DD-MM-YYYY HH:MM':
            return new_dt.strftime('%d-%m-%Y %H:%M')
        else:
            raise ValueError('Invalid output format specified.')

    except Exception as e:
        return f'Error: {str(e)}'

