def consonant_counter(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        raise ValueError('Input must be a list of strings.')
    if len(input) < 1 or len(input) > 20:
        raise ValueError('Input list must contain between 1 and 20 strings.')

    # Define consonants
    consonants = 'bcdfghjklmnpqrstvwxyz'
    if not case_sensitive:
        consonants += consonants.upper()

    # Initialize result
    result = []

    # Process each string
    for string in input:
        count = 0
        for i, char in enumerate(string):
            # Check ignore positions
            if ('first' in ignore_position and i == 0) or \
               ('last' in ignore_position and i == len(string) - 1) or \
               ('even' in ignore_position and i % 2 == 0) or \
               ('odd' in ignore_position and i % 2 != 0):
                continue

            # Check ignore characters
            if any(re.search(pattern, char) for pattern in ignore_characters):
                continue

            # Count consonants
            if char in consonants:
                count += 1

        # Append result based on output format
        if output_format == 'detailed':
            result.append({'string': string, 'consonant_count': count})
        else:
            result.append(count)

    # Format final output
    if output_format == 'integer':
        return sum(result)
    elif output_format == 'text':
        return f'Total consonants: {sum(result)}'
    elif output_format == 'detailed':
        return result
    else:
        raise ValueError('Unsupported output format.')

