def alphabetical_sorter(input_string: str, ignore_case: bool = True, remove_non_alpha: bool = True, output_format: str = 'array', sort_direction: str = 'ascending', handle_diacritics: bool = False, character_set: str = 'latin') -> list or str:
    # Validate parameters
    if not isinstance(input_string, str):
        raise ValueError('input_string must be a string')
    if not isinstance(ignore_case, bool):
        raise ValueError('ignore_case must be a boolean')
    if not isinstance(remove_non_alpha, bool):
        raise ValueError('remove_non_alpha must be a boolean')
    if output_format not in ['array', 'string']:
        raise ValueError('output_format must be either "array" or "string"')
    if sort_direction not in ['ascending', 'descending']:
        raise ValueError('sort_direction must be either "ascending" or "descending"')
    if not isinstance(handle_diacritics, bool):
        raise ValueError('handle_diacritics must be a boolean')
    if character_set not in ['latin', 'cyrillic', 'greek', 'all']:
        raise ValueError('character_set must be one of "latin", "cyrillic", "greek", "all"')

    # Process input string
    if remove_non_alpha:
        input_string = ''.join(filter(str.isalpha, input_string))

    if ignore_case:
        input_string = input_string.lower()

    # Sort the characters
    sorted_chars = sorted(input_string, reverse=(sort_direction == 'descending'))

    # Return in the specified format
    if output_format == 'string':
        return ''.join(sorted_chars)
    return sorted_chars

