def reverse_string(input, case_format='original', trim_whitespace=False, reverse_word_order=False):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 20:
        return {'error': 'Input must be a list of 1 to 20 strings.'}
    if case_format not in ['original', 'uppercase', 'lowercase', 'capitalize']:
        return {'error': 'Invalid case_format. Must be one of: original, uppercase, lowercase, capitalize.'}

    # Process each string in the input list
    results = []
    for string in input:
        # Trim whitespace if required
        if trim_whitespace:
            string = string.strip()

        # Reverse the string
        reversed_string = string[::-1]

        # Reverse word order if required
        if reverse_word_order:
            words = reversed_string.split()
            reversed_string = ' '.join(words[::-1])

        # Apply case formatting
        if case_format == 'uppercase':
            reversed_string = reversed_string.upper()
        elif case_format == 'lowercase':
            reversed_string = reversed_string.lower()
        elif case_format == 'capitalize':
            reversed_string = reversed_string.capitalize()

        results.append(reversed_string)

    return {'result': results}

