def actor_program_lookup(actor_name: str, media_type: str = 'both', year_range: list = None, genre: str = None, director: str = None, output_format: str = 'list', max_results: int = None):
    """
    An advanced tool for identifying television programs, movies, or other media associated with a given actor.

    Parameters:
    - actor_name (str): The name of the actor whose associated program is to be identified.
    - media_type (str): The type of media to search for. Defaults to 'both'.
    - year_range (list): The range of years to consider for the actor's work. Defaults to all years.
    - genre (str): The genre of the media to filter results by. Optional.
    - director (str): The name of the director to filter results by. Optional.
    - output_format (str): The format of the output. Defaults to 'list'.
    - max_results (int): The maximum number of results to return. Optional.

    Returns:
    - A list of media titles associated with the actor, formatted according to 'output_format'.
    """
    # Simulated database of actor programs
    database = {
        'Luke Null': [
            {'title': 'Saturday Night Live (season 43)', 'media_type': 'television', 'year': 2017, 'genre': 'comedy', 'director': None},
            # Additional entries could be added here
        ]
    }

    # Error handling for required parameter
    if not actor_name:
        return {'error': 'actor_name is required'}

    # Retrieve actor's programs from the database
    actor_programs = database.get(actor_name, [])

    # Filter by media_type
    if media_type != 'both':
        actor_programs = [program for program in actor_programs if program['media_type'] == media_type]

    # Filter by year_range
    if year_range:
        actor_programs = [program for program in actor_programs if year_range[0] <= program['year'] <= year_range[1]]

    # Filter by genre
    if genre:
        actor_programs = [program for program in actor_programs if program['genre'] == genre]

    # Filter by director
    if director:
        actor_programs = [program for program in actor_programs if program['director'] == director]

    # Limit results
    if max_results:
        actor_programs = actor_programs[:max_results]

    # Format output
    if output_format == 'list':
        return [program['title'] for program in actor_programs]
    elif output_format == 'detailed':
        return actor_programs
    elif output_format == 'sorted':
        return sorted(actor_programs, key=lambda x: x['year'])
    elif output_format == 'limited':
        return [program['title'] for program in actor_programs[:10]]
    else:
        return {'error': 'Invalid output_format specified'}

