    name_parts = full_name.split()

    # Extract the first name based on the specified name format
    if name_format in ['first_last', 'first_middle_last', 'first_initial_last', 'first_last_suffix']:
        first_name = name_parts[0]
    elif name_format == 'prefix_first_last':
        first_name = name_parts[1] if len(name_parts) > 1 else ''
    else:
