def extract_last_letter(input, ignore_empty=True, output_format='character', case_sensitive=False, encoding='UTF-8'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if len(input) < 1 or len(input) > 10:
        return {'error': 'Invalid input: input list must contain between 1 and 10 strings.'}
    if output_format not in ['character', 'text', 'unicode', 'ascii']:
        return {'error': 'Invalid output format.'}
    if encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return {'error': 'Invalid encoding.'}

    # Process each string in the input list
    results = []
    for string in input:
        if ignore_empty and not string:
            continue
        last_letter = string[-1] if string else ''
        if not case_sensitive:
            last_letter = last_letter.lower()

        # Format the output
        if output_format == 'text':
            results.append(last_letter)
        elif output_format == 'unicode':
            results.append(ord(last_letter))
        elif output_format == 'ascii':
            results.append(ascii(last_letter))
        else:  # Default to 'character'
            results.append(last_letter)

    return results

