def digit_sum_calculator(number, output_format='integer', include_decimal=False, base=10):
    # Validate the 'number' parameter
    if not isinstance(number, (int, float)):
        return {'error': 'Invalid number type. Must be an integer or float.'}

    # Validate the 'output_format' parameter
    if output_format not in ['integer', 'text', 'json', 'binary']:
        return {'error': 'Invalid output format. Must be one of integer, text, json, binary.'}

    # Validate the 'base' parameter
    if base not in [2, 8, 10, 16]:
        return {'error': 'Invalid base. Must be one of 2, 8, 10, 16.'}

    # Convert number to string and handle decimal point if needed
    number_str = str(number)
    if not include_decimal:
        number_str = number_str.split('.')[0]

    # Calculate the sum of digits
    digit_sum = 0
    for char in number_str:
        if char.isdigit():
            digit_sum += int(char)

    # Format the output based on 'output_format'
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of digits is {digit_sum}'
    elif output_format == 'json':
        return {'digit_sum': digit_sum}
    elif output_format == 'binary':
        return bin(digit_sum)

