def prime_factorizer(number, output_format='list', optimization_level='none', include_negative=False):
    # Error handling for invalid inputs
    if not isinstance(number, int) or number <= 1:
        return {'error': 'Invalid input: number must be an integer greater than 1.'}

    # Convert negative numbers to positive if include_negative is True
    if number < 0 and include_negative:
        number = abs(number)

    # Helper function to check if a number is prime
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    # If the number is prime, return it directly
    if is_prime(number):
        if output_format == 'list':
            return [number]
        elif output_format == 'text':
            return f'The number {number} is prime.'
        elif output_format == 'detailed':
            return {number: 1}

    # Factorization logic
    factors = []
    # Optimization level handling (not implemented in detail here)
    # Basic factorization logic
    def factorize(n):
        d = 2
        while d * d <= n:
            while (n % d) == 0:
                factors.append(d)
                n //= d
            d += 1
        if n > 1:
            factors.append(n)

    factorize(number)

    # Format output based on output_format
    if output_format == 'list':
        return factors
    elif output_format == 'text':
        return 'Prime factors: ' + ', '.join(map(str, factors))
    elif output_format == 'detailed':
        from collections import Counter
        return dict(Counter(factors))

    return {'error': 'Invalid output format specified.'}

# Example usage
