print(result)  # Output: [2003]

def sum_calculator(numbers, output_format='number', precision=2, ignore_nan=True):
    """
    Calculate the sum of numbers in an array with specified output format and precision.

    :param numbers: List of numbers to sum.
    :param output_format: Format of the output ('number', 'text', 'json', 'xml').
    :param precision: Number of decimal places to round the sum to.
    :param ignore_nan: Whether to ignore NaN values.
    :return: Sum of numbers in the specified format.
    """
    import math
    import json

    if not isinstance(numbers, list):
        return {'error': 'Invalid input: numbers must be a list.'}

    if not all(isinstance(n, (int, float)) for n in numbers):
        return {'error': 'Invalid input: all items in numbers must be numeric.'}

    # Handle NaN values
    if ignore_nan:
        numbers = [n for n in numbers if not math.isnan(n)]

    # Calculate the sum
    total = sum(numbers)

    # Handle precision
    total = round(total, precision)

    # Format the output
    if output_format == 'number':
        return total
    elif output_format == 'text':
        return f'The sum is {total}'
    elif output_format == 'json':
        return json.dumps({'sum': total})
    elif output_format == 'xml':
        return f'<sum>{total}</sum>'
    else:
        return {'error': 'Invalid output format specified.'}

