    # Error handling for required 'input' parameter
    if input is None:
        return {'error': 'Input is required.'}

    # Helper function to extract the first letter from a single string
    def extract_first_letter(s):
        if ignore_whitespace:
            s = s.lstrip()
        if ignore_special_characters:
            s = ''.join(filter(str.isalnum, s))
        if not s:
            return ''
        return s[0] if case_sensitive else s[0].lower()

    # If input is a string, process it directly
    if isinstance(input, str):
        return {'result': extract_first_letter(input)}

    # If input is a list, process each element if extract_multiple is True
    elif isinstance(input, list):
        if extract_multiple:
            return {'result': [extract_first_letter(item) for item in input]}
        else:
            return {'error': 'extract_multiple must be True to process a list of strings.'}

    # Error handling for invalid input types
    else:
        return {'error': 'Invalid input type. Must be a string or list of strings.'}

