def advanced_character_counter(input, ignore_characters=None, ignore_position=None, output_format='integer', case_sensitive=False, count_types=None, regex_pattern=None, detailed_statistics=False):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize character count
    character_count = 0

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Handle ignore positions
    if ignore_position:
        if 'first' in ignore_position:
            input = input[1:]
        if 'last' in ignore_position:
            input = input[:-1]

    # Count characters based on count_types
    if count_types:
        for char in input:
            if 'vowels' in count_types and char in 'aeiou':
                character_count += 1
            elif 'consonants' in count_types and char.isalpha() and char not in 'aeiou':
                character_count += 1
            elif 'digits' in count_types and char.isdigit():
                character_count += 1
            elif 'special' in count_types and not char.isalnum():
                character_count += 1
    else:
        # Default to counting all letters
        character_count = sum(1 for char in input if char.isalpha())

    # Handle ignore characters
    if ignore_characters:
        character_count -= sum(1 for char in input if char in ignore_characters)

    # Handle regex pattern
    if regex_pattern:
        import re
        matches = re.findall(regex_pattern, input)
        character_count = len(matches)

    # Handle output format
    if output_format == 'text':
        return f'The number of characters is {character_count}.'
    elif output_format == 'json':
        return {'character_count': character_count}
    elif output_format == 'integer':
        return character_count
    else:
        return {'error': 'Invalid output format specified.'}

    # Handle detailed statistics
    if detailed_statistics:
        from collections import Counter
        frequency = Counter(input)
        return {'character_count': character_count, 'frequency': frequency}

    return character_count

