def reverse_number(number: str, preserve_sign: bool = True, remove_leading_zeros: bool = True, numerical_base: int = 10, handle_decimal: bool = False, handle_scientific_notation: bool = False) -> str:
    # Error handling for invalid numerical base
    if numerical_base < 2 or numerical_base > 36:
        return 'Error: Unsupported numerical base. Please use a base between 2 and 36.'

    # Handle scientific notation if required
    if handle_scientific_notation and 'e' in number.lower():
        try:
            num = float(number)
            number = f'{num:.10f}'.rstrip('0').rstrip('.')  # Convert to decimal form
        except ValueError:
            return 'Error: Invalid scientific notation.'

    # Handle decimal numbers if required
    if handle_decimal and '.' in number:
        integer_part, decimal_part = number.split('.')
        reversed_number = integer_part[::-1] + '.' + decimal_part[::-1]
    else:
        reversed_number = number[::-1]

    # Preserve sign if required
    if preserve_sign and reversed_number[-1] in '+-':
        reversed_number = reversed_number[-1] + reversed_number[:-1]

    # Remove leading zeros if required
    if remove_leading_zeros:
        reversed_number = reversed_number.lstrip('0')
        if reversed_number == '':
            reversed_number = '0'

    return reversed_number

