def enhanced_alphabetical_sorter(input: str, case_sensitive: bool = False, output_format: str = 'array', sort_direction: str = 'ascending', special_character_handling: str = 'include', language_support: str = 'en'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate output_format
    if output_format not in ['array', 'string', 'json']:
        return {'error': 'Invalid output format.'}

    # Validate sort_direction
    if sort_direction not in ['ascending', 'descending']:
        return {'error': 'Invalid sort direction.'}

    # Validate special_character_handling
    if special_character_handling not in ['include', 'exclude', 'separate']:
        return {'error': 'Invalid special character handling option.'}

    # Validate language_support
    if language_support not in ['en', 'es', 'fr', 'de']:
        return {'error': 'Unsupported language.'}

    # Handle special characters
    if special_character_handling == 'exclude':
        input = ''.join(filter(str.isalnum, input))
    elif special_character_handling == 'separate':
        letters = ''.join(filter(str.isalnum, input))
        specials = ''.join(filter(lambda x: not str.isalnum(x), input))
    else:
        letters = input

    # Sort the characters
    if not case_sensitive:
        letters = letters.lower()
    sorted_chars = sorted(letters)

    if sort_direction == 'descending':
        sorted_chars.reverse()

    # Prepare output
    if output_format == 'array':
        result = sorted_chars
    elif output_format == 'string':
        result = ''.join(sorted_chars)
    elif output_format == 'json':
        result = {'sorted': sorted_chars}

    # Include special characters if needed
    if special_character_handling == 'separate':
        if output_format == 'array':
            result = {'letters': sorted_chars, 'specials': list(specials)}
        elif output_format == 'string':
            result = ''.join(sorted_chars) + specials
        elif output_format == 'json':
            result = {'letters': sorted_chars, 'specials': list(specials)}

    return result

