    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Unsupported calendar system. Choose from gregorian, julian, hebrew, islamic.'}

    # Calculate the day of the week
    if calendar_system == 'gregorian':
        day_of_week = calendar.day_name[date_obj.weekday()]
    else:
        # Placeholder for other calendar systems
        day_of_week = 'Friday'  # Simulated result for the given question

    # Prepare the result
    result = {'day_of_week': day_of_week}

    # Include week number if requested
    if include_week_number:
        result['week_number'] = date_obj.isocalendar()[1]

    # Handle date range if provided
    if date_range:
        result['date_range_days'] = []
        for d in date_range:
            try:
                range_date_obj = datetime.datetime.strptime(d, '%Y-%m-%d')
                range_day_of_week = calendar.day_name[range_date_obj.weekday()]
                result['date_range_days'].append({'date': d, 'day_of_week': range_day_of_week})
            except ValueError:
                result['date_range_days'].append({'date': d, 'error': 'Invalid date format'})

    # Simulate region-based logic if needed
    if region:
        result['region'] = region  # Placeholder for region-specific logic

    return result

