def next_year_calculator(year, output_format='integer', calendar_system='gregorian', include_leap_year_info=False):
    # Validate input parameters
    if not isinstance(year, int):
        return {'error': 'Invalid input: year must be an integer.'}
    if output_format not in ['integer', 'string', 'roman', 'binary']:
        return {'error': 'Invalid input: output_format must be one of integer, string, roman, binary.'}
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Invalid input: calendar_system must be one of gregorian, julian, hebrew, islamic.'}

    # Calculate the next year
    next_year = year + 1

    # Determine if the next year is a leap year (only for Gregorian calendar)
    is_leap_year = False
    if calendar_system == 'gregorian':
        is_leap_year = (next_year % 4 == 0 and (next_year % 100 != 0 or next_year % 400 == 0))

    # Format the output
    if output_format == 'string':
        result = str(next_year)
    elif output_format == 'roman':
        # Simple Roman numeral conversion for demonstration
        roman_numerals = {1000: 'M', 900: 'CM', 500: 'D', 400: 'CD', 100: 'C', 90: 'XC', 50: 'L', 40: 'XL', 10: 'X', 9: 'IX', 5: 'V', 4: 'IV', 1: 'I'}
        num = next_year
        result = ''
        for value, numeral in roman_numerals.items():
            while num >= value:
                result += numeral
                num -= value
    elif output_format == 'binary':
        result = bin(next_year)[2:]
    else:
        result = next_year

    # Include leap year information if requested
    if include_leap_year_info:
        return {'next_year': result, 'is_leap_year': is_leap_year}
    else:
        return {'next_year': result}

