def reverse_number(input: str, output_format: str = 'string', precision: int = None, reverse_length: int = None):
    """
    Reverses the order of digits in the input number.

    Parameters:
    - input (str): The number to be reversed, provided as a string.
    - output_format (str): The format of the output ('string', 'integer', 'float').
    - precision (int): The number of decimal places to preserve.
    - reverse_length (int): The number of digits to reverse from the end.

    Returns:
    - Reversed number in the specified format.
    """
    try:
        # Validate output_format
        if output_format not in ['string', 'integer', 'float']:
            raise ValueError("Invalid output_format. Must be 'string', 'integer', or 'float'.")

        # Determine the part of the number to reverse
        if reverse_length is None:
            reverse_length = len(input)

        # Reverse the specified length of the number
        reversed_part = input[-reverse_length:][::-1]
        remaining_part = input[:-reverse_length]
        reversed_number = remaining_part + reversed_part

        # Handle precision for float output
        if '.' in reversed_number and precision is not None:
            integer_part, decimal_part = reversed_number.split('.')
            decimal_part = decimal_part[:precision]
            reversed_number = f"{integer_part}.{decimal_part}"

        # Convert to the specified output format
        if output_format == 'integer':
            return int(reversed_number)
        elif output_format == 'float':
            return float(reversed_number)
        else:
            return reversed_number

    except Exception as e:
        return str(e)

