def date_calculator(input_date: str, days_to_add: int, output_format: str = 'YYYY-MM-DD', calculate_difference: bool = False, second_date: str = None, time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Error handling for input_date
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid input_date format. Expected YYYY-MM-DD.'

    # Error handling for days_to_add
    if not isinstance(days_to_add, int):
        return 'Error: days_to_add must be an integer.'

    # Calculate the new date
    new_date = date_obj + timedelta(days=days_to_add)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO-8601':
        formatted_date = new_date.isoformat()
    else:
        return 'Error: Invalid output_format.'

    # Handle calculate_difference
    if calculate_difference:
        if not second_date:
            return 'Error: second_date is required when calculate_difference is true.'
        try:
            second_date_obj = datetime.strptime(second_date, '%Y-%m-%d')
        except ValueError:
            return 'Error: Invalid second_date format. Expected YYYY-MM-DD.'
        difference = (second_date_obj - date_obj).days
        return f'Difference: {difference} days'

    return formatted_date

