def unique_letter_counter(input: str, case_sensitive: bool = False, ignore_non_alpha: bool = True, alphabet: str = 'latin', custom_characters: str = None, detailed_statistics: bool = False):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(ignore_non_alpha, bool):
        return {'error': 'ignore_non_alpha must be a boolean.'}
    if not isinstance(detailed_statistics, bool):
        return {'error': 'detailed_statistics must be a boolean.'}
    if alphabet not in ['latin', 'cyrillic', 'greek']:
        return {'error': 'Unsupported alphabet specified.'}

    # Determine the character set to use
    if custom_characters:
        char_set = set(custom_characters)
    else:
        if alphabet == 'latin':
            char_set = set('abcdefghijklmnopqrstuvwxyz')
        elif alphabet == 'cyrillic':
            char_set = set('абвгдежзийклмнопрстуфхцчшщъыьэюя')
        elif alphabet == 'greek':
            char_set = set('αβγδεζηθικλμνξοπρστυφχψω')

    # Process the input string
    if not case_sensitive:
        input = input.lower()

    # Filter characters based on ignore_non_alpha
    if ignore_non_alpha:
        input = ''.join(filter(str.isalpha, input))

    # Count unique letters
    unique_letters = set(input) & char_set
    unique_count = len(unique_letters)

    # Prepare detailed statistics if requested
    if detailed_statistics:
        frequency = {char: input.count(char) for char in unique_letters}
        return {'unique_count': unique_count, 'frequency': frequency}

    return {'unique_count': unique_count}

