def digit_product_calculator_v2(year, output_format='integer', handle_zeros=False, error_handling='strict'):
    # Convert year to string if it's an integer
    if isinstance(year, int):
        year = str(year)

    # Validate year input
    if not year.isdigit() or int(year) <= 0:
        if error_handling == 'strict':
            raise ValueError('Year must be a positive integer or a string representing a positive integer.')
        elif error_handling == 'lenient':
            year = ''.join(filter(str.isdigit, year)) or '1'

    # Calculate the product of digits
    product = 1
    for char in year:
        digit = int(char)
        if digit == 0 and not handle_zeros:
            return 0
        elif digit != 0 or handle_zeros:
            product *= digit

    # Format the output
    if output_format == 'integer':
        return product
    elif output_format == 'text':
        return f'The product of the digits of the year {year} is {product}.'
    elif output_format == 'json':
        return {
            'year': year,
            'product': product
        }

