def enhanced_ascii_converter(characters, output_format='list', handle_non_ascii='error'):
    """
    Convert characters to their ASCII codes with enhanced options.

    :param characters: List of single-character strings to convert.
    :param output_format: Format of the output ('list', 'dictionary', 'json', 'csv').
    :param handle_non_ascii: How to handle non-ASCII characters ('ignore', 'replace', 'error').
    :return: ASCII codes in the specified format.
    :raises ValueError: If non-ASCII characters are found and 'error' is specified.
    """
    import json
    import csv
    from io import StringIO

    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'dictionary', 'json', 'csv']:
        raise ValueError("Invalid 'output_format'. Must be one of: 'list', 'dictionary', 'json', 'csv'.")
    if handle_non_ascii not in ['ignore', 'replace', 'error']:
        raise ValueError("Invalid 'handle_non_ascii'. Must be one of: 'ignore', 'replace', 'error'.")

    # Placeholder for non-ASCII characters
    placeholder = '?'  # Can be customized

    # Convert characters to ASCII codes
    ascii_codes = {}
    for char in characters:
        try:
            ascii_code = ord(char)
            if ascii_code > 127 and handle_non_ascii == 'error':
                raise ValueError(f"Non-ASCII character found: {char}")
            elif ascii_code > 127 and handle_non_ascii == 'replace':
                ascii_codes[char] = ord(placeholder)
            else:
                ascii_codes[char] = ascii_code
        except TypeError:
            if handle_non_ascii == 'ignore':
                continue
            elif handle_non_ascii == 'replace':
                ascii_codes[char] = ord(placeholder)
            else:
                raise ValueError(f"Non-ASCII character found: {char}")

    # Format output
    if output_format == 'list':
        return list(ascii_codes.values())
    elif output_format == 'dictionary':
        return ascii_codes
    elif output_format == 'json':
        return json.dumps(ascii_codes)
    elif output_format == 'csv':
        output = StringIO()
        writer = csv.writer(output)
        writer.writerow(['Character', 'ASCII'])
        for char, code in ascii_codes.items():
            writer.writerow([char, code])
        return output.getvalue().strip()

