    def parse_date(date_str, date_format):
        try:
            if date_format == 'YYYY-MM-DD':
                return datetime.datetime.strptime(date_str, '%Y-%m-%d')
            elif date_format == 'DD-MM-YYYY':
                return datetime.datetime.strptime(date_str, '%d-%m-%Y')
            elif date_format == 'MM-DD-YYYY':
                return datetime.datetime.strptime(date_str, '%m-%d-%Y')
            elif date_format == 'YYYY/MM/DD':
                return datetime.datetime.strptime(date_str, '%Y/%m/%d')
            elif date_format == 'DD/MM/YYYY':
                return datetime.datetime.strptime(date_str, '%d/%m/%Y')
            elif date_format == 'MM/DD/YYYY':
                return datetime.datetime.strptime(date_str, '%m/%d/%Y')
        except ValueError as e:
            if error_handling == 'strict':
                raise ValueError(f"Invalid date format: {e}")
            elif error_handling == 'lenient':
                # Attempt to parse using a generic parser
                return parser.parse(date_str)

    # Parse the date
    try:
        date_obj = parse_date(date, date_format)
    except Exception as e:
        return str(e)

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        date_obj = tz.localize(date_obj)
    except Exception as e:
        if error_handling == 'strict':
            return f"Invalid time zone: {e}"
        elif error_handling == 'lenient':
            date_obj = date_obj.astimezone(pytz.UTC)

    # Calculate the day of the week
    if calendar_system == 'Gregorian':
        day_of_week = date_obj.strftime('%A')
    elif calendar_system == 'Julian':
        # Convert to Julian date and calculate
        julian_date = date_obj.toordinal() + 1721424.5
        day_of_week = datetime.datetime.fromordinal(int(julian_date)).strftime('%A')

    # Format the output
