def day_of_week_calculator(date: str, calendar: str = 'gregorian', output_format: str = 'text', timezone: str = 'UTC') -> str:
    import datetime
    import pytz
    from dateutil import parser

    # Error handling for date parsing
    try:
        # Parse the date string into a datetime object
        parsed_date = parser.parse(date, dayfirst=True)
    except ValueError:
        return 'Error: Invalid date format. Please use YYYY-MM-DD, DD-MM-YYYY, or MM-DD-YYYY.'

    # Error handling for calendar system
    if calendar not in ['gregorian', 'julian', 'iso_week_date']:
        return 'Error: Unsupported calendar system. Choose from gregorian, julian, or iso_week_date.'

    # Error handling for output format
    if output_format not in ['text', 'numeric', 'abbreviated']:
        return 'Error: Unsupported output format. Choose from text, numeric, or abbreviated.'

    # Error handling for timezone
    try:
        timezone_obj = pytz.timezone(timezone)
    except pytz.UnknownTimeZoneError:
        return 'Error: Invalid timezone. Please use a valid IANA timezone format.'

    # Convert the date to the specified timezone
    localized_date = timezone_obj.localize(parsed_date)

    # Calculate the day of the week based on the calendar system
    if calendar == 'gregorian':
        day_of_week = localized_date.weekday()  # Monday is 0 and Sunday is 6
    elif calendar == 'julian':
        # Julian calendar calculation
        julian_date = localized_date.toordinal() + 2  # Adjust for Julian calendar
        day_of_week = julian_date % 7
    elif calendar == 'iso_week_date':
        # ISO week date calculation
        day_of_week = localized_date.isoweekday() % 7  # ISO: Monday is 1 and Sunday is 7

    # Format the output based on the specified output format
    if output_format == 'text':
        days_text = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday']
        return days_text[day_of_week]
    elif output_format == 'numeric':
        return str(day_of_week)
    elif output_format == 'abbreviated':
        days_abbr = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
        return days_abbr[day_of_week]

