def timezone_difference_calculator(location_1: str, location_2: str, date: str, time_of_day: str = '00:00', date_range: list = None, output_format: str = 'hours') -> dict:
    import pytz
    from datetime import datetime

    try:
        # Validate date format
        datetime.strptime(date, '%Y-%m-%d')
        if date_range:
            for d in date_range:
                datetime.strptime(d, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format. Use YYYY-MM-DD.'}

    # Validate output format
    if output_format not in ['hours', 'detailed', 'local_times']:
        return {'error': 'Invalid output format. Choose from hours, detailed, local_times.'}

    # Define time zones
    try:
        tz1 = pytz.timezone(location_1)
        tz2 = pytz.timezone(location_2)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown timezone. Please provide a valid location.'}

    # Calculate time difference
    try:
        date_time = datetime.strptime(date + ' ' + time_of_day, '%Y-%m-%d %H:%M')
        local_time_1 = tz1.localize(date_time)
        local_time_2 = tz2.localize(date_time)
        time_difference = (local_time_1 - local_time_2).total_seconds() / 3600
    except Exception as e:
        return {'error': str(e)}

    # Prepare output
    if output_format == 'hours':
        return {'time_difference': time_difference}
    elif output_format == 'detailed':
        return {'detailed': f'The time difference between {location_1} and {location_2} on {date} at {time_of_day} is {time_difference} hours.'}
    elif output_format == 'local_times':
        return {'local_times': {'location_1': local_time_1.strftime('%Y-%m-%d %H:%M:%S'), 'location_2': local_time_2.strftime('%Y-%m-%d %H:%M:%S')}}

    return {'error': 'An unexpected error occurred.'}

