def closest_palindrome_finder(input_number, search_range=1000, return_type='closest', priority='none'):
    """
    Finds the closest palindrome to the given input number.

    Parameters:
    - input_number (int): The integer number for which the closest palindrome is to be found.
    - search_range (int, optional): The range within which to search for the closest palindrome.
    - return_type (str, optional): Specifies the type of return value.
    - priority (str, optional): Specifies priority for smaller or larger palindromes when equidistant.

    Returns:
    - Depending on return_type, returns the closest palindrome, all palindromes within range, or the distance to the closest palindrome.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    if not isinstance(input_number, int):
        raise ValueError("input_number must be an integer.")
    if not isinstance(search_range, int) or search_range < 0:
        raise ValueError("search_range must be a non-negative integer.")
    if return_type not in ['closest', 'all_within_range', 'distance_to_closest']:
        raise ValueError("return_type must be one of 'closest', 'all_within_range', 'distance_to_closest'.")
    if priority not in ['smaller', 'larger', 'none']:
        raise ValueError("priority must be one of 'smaller', 'larger', 'none'.")

    closest_palindrome = None
    min_distance = float('inf')
    palindromes_within_range = []

    for i in range(search_range + 1):
        for candidate in [input_number - i, input_number + i]:
            if candidate >= 0 and is_palindrome(candidate):
                distance = abs(input_number - candidate)
                if return_type == 'all_within_range':
                    palindromes_within_range.append(candidate)
                elif distance < min_distance:
                    closest_palindrome = candidate
                    min_distance = distance
                elif distance == min_distance:
                    if priority == 'smaller' and candidate < closest_palindrome:
                        closest_palindrome = candidate
                    elif priority == 'larger' and candidate > closest_palindrome:
                        closest_palindrome = candidate

    if return_type == 'closest':
        return closest_palindrome
    elif return_type == 'all_within_range':
        return palindromes_within_range
    elif return_type == 'distance_to_closest':
        return min_distance

# Example usage
result = closest_palindrome_finder(1972)
print(result)  # Expected output: 1991

