def enhanced_combined_length_calculator(names, normalize={'remove_accents': False, 'remove_special_characters': False}, output_format='integer', encoding='UTF-8'):
    import unicodedata
    import re

    # Error handling for required 'names' parameter
    if not isinstance(names, list) or len(names) == 0:
        return {'error': 'The names parameter must be a non-empty list of strings.'}

    # Validate encoding
    if encoding not in ['UTF-8', 'ASCII', 'ISO-8859-1']:
        return {'error': 'Invalid encoding specified.'}

    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format specified.'}

    # Normalize names if required
    def normalize_string(s):
        if normalize.get('remove_accents', False):
            s = ''.join(c for c in unicodedata.normalize('NFD', s) if unicodedata.category(c) != 'Mn')
        if normalize.get('remove_special_characters', False):
            s = re.sub(r'[^\w\s]', '', s)
        return s

    normalized_names = [normalize_string(name) for name in names]

    # Calculate combined length
    combined_length = sum(len(name.encode(encoding)) for name in normalized_names)

    # Return result based on output_format
    if output_format == 'integer':
        return combined_length
    elif output_format == 'text':
        return f'The combined length of the names is {combined_length} characters.'
    elif output_format == 'detailed':
        details = {name: len(name.encode(encoding)) for name in normalized_names}
        return {'total_length': combined_length, 'details': details}

