def date_digit_sum(date, date_format=None, delimiter=None, output_format='integer', exclude_components=None, date_range=None):
    import datetime
    from dateutil import parser

    # Error handling for required 'date' parameter
    if not date:
        return {'error': 'The date parameter is required.'}

    # Parse the date using the provided format or default parser
    try:
        if date_format:
            parsed_date = datetime.datetime.strptime(date, date_format)
        else:
            parsed_date = parser.parse(date)
    except ValueError as e:
        return {'error': f'Invalid date format: {str(e)}'}

    # Extract components
    day, month, year = parsed_date.day, parsed_date.month, parsed_date.year

    # Convert components to strings and exclude if necessary
    components = {'day': str(day), 'month': str(month), 'year': str(year)}
    if exclude_components:
        for component in exclude_components:
            components[component] = ''

    # Calculate digit sum
    digit_sum = sum(int(digit) for component in components.values() for digit in component if digit.isdigit())

    # Return result based on output_format
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of the digits is {digit_sum}.'
    elif output_format == 'detailed':
        return {
            'day_sum': sum(int(d) for d in components['day'] if d.isdigit()),
            'month_sum': sum(int(d) for d in components['month'] if d.isdigit()),
            'year_sum': sum(int(d) for d in components['year'] if d.isdigit()),
            'total_sum': digit_sum
        }
    else:
        return {'error': 'Invalid output format specified.'}

