def extract_first_name(full_name: str, name_format: str = 'western', include_middle_initial: bool = False, include_nickname: bool = False, custom_delimiter: str = ' ', handle_compound_first_names: bool = True) -> str:
    """
    Extracts the first name from a full name string based on the specified name format and options.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name:
        return 'Error: full_name must be a non-empty string.'

    # Error handling for name_format
    if name_format not in ['western', 'eastern', 'custom', 'arabic', 'hispanic']:
        return 'Error: Invalid name_format. Must be one of [western, eastern, custom, arabic, hispanic].'

    # Split the full name based on the custom delimiter
    name_parts = full_name.split(custom_delimiter)

    # Logic to extract the first name based on the name format
    if name_format == 'western':
        first_name = name_parts[0]
    elif name_format == 'eastern':
        first_name = name_parts[-1]
    elif name_format == 'custom':
        first_name = name_parts[0]
    elif name_format == 'arabic':
        first_name = name_parts[0]
    elif name_format == 'hispanic':
        first_name = name_parts[0]

    # Handle compound first names
    if handle_compound_first_names and len(name_parts) > 1:
        if name_parts[1].lower() in ['ann', 'lee', 'jo']:
            first_name += ' ' + name_parts[1]

    # Include middle initial if requested
    if include_middle_initial and len(name_parts) > 2:
        first_name += ' ' + name_parts[1][0] + '.'

    # Include nickname if requested
    if include_nickname and '(' in full_name and ')' in full_name:
        nickname_start = full_name.find('(') + 1
        nickname_end = full_name.find(')')
        nickname = full_name[nickname_start:nickname_end]
        first_name += ' (' + nickname + ')'

    return first_name

