def extract_last_name(full_name, delimiter=' ', handle_hyphenated=True, output_format='string', case_sensitive=False, include_suffix=False):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Split the full name using the provided delimiters
    delimiters = delimiter.split('|')
    import re
    pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(pattern, full_name)

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.lower() for part in name_parts]

    # Handle hyphenated names
    if handle_hyphenated:
        last_name_candidates = [part for part in name_parts if '-' in part or part.isalpha()]
    else:
        last_name_candidates = [part for part in name_parts if part.isalpha()]

    # Determine the last name
    if not last_name_candidates:
        return {'error': 'No valid last name found.'}

    last_name = last_name_candidates[-1]

    # Include suffix if required
    if include_suffix and len(name_parts) > 1:
        suffixes = ['Jr', 'Sr', 'II', 'III', 'IV']  # Example suffixes
        if name_parts[-1] in suffixes:
            last_name = f'{last_name} {name_parts[-1]}'

    # Format the output
    if output_format == 'array':
        return {'last_name': last_name.split()}
    elif output_format == 'object':
        return {'last_name': last_name, 'metadata': {'original_name': full_name, 'delimiter_used': delimiter}}
    else:  # Default to 'string'
        return {'last_name': last_name}

