def sum_string_lengths_v2(strings, output_format='integer', encoding='utf-8', include_whitespace=True):
    # Validate input parameters
    if not isinstance(strings, list) or len(strings) < 1:
        return {'error': 'Invalid input: strings must be a non-empty list of strings.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, or detailed.'}
    if encoding not in ['utf-8', 'ascii', 'latin-1']:
        return {'error': 'Invalid encoding: must be one of utf-8, ascii, or latin-1.'}
    if not isinstance(include_whitespace, bool):
        return {'error': 'Invalid include_whitespace: must be a boolean value.'}

    # Calculate the combined length of strings
    total_length = 0
    for s in strings:
        if not include_whitespace:
            s = ''.join(s.split())  # Remove whitespace if not included
        try:
            total_length += len(s.encode(encoding))
        except UnicodeEncodeError:
            return {'error': f'Encoding error: string {s} cannot be encoded with {encoding}.'}

    # Format the output based on the output_format parameter
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'The combined length of the strings is {total_length}.'
    elif output_format == 'detailed':
        return {
            'total_length': total_length,
            'string_count': len(strings),
            'average_length': total_length / len(strings) if strings else 0,
            'encoding_used': encoding,
            'whitespace_included': include_whitespace
        }

