    if not isinstance(international_support, bool):
        return {'error': 'international_support must be a boolean'}

    # Split the full name using the provided delimiters
    import re
    delimiter_pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(delimiter_pattern, full_name)

    # Logic to extract the first name
    first_name = None
    for part in name_parts:
        # Skip titles if include_titles is False
        if not include_titles and part.lower() in ['mr', 'mrs', 'ms', 'dr', 'prof']:
