def extract_last_name(full_name: str, name_format: str = 'first_last', handle_hyphenated: bool = True, handle_special_characters: bool = True, include_suffix: bool = False, output_format: str = 'string'):
    """
    Extracts the last name from a full name string based on the specified parameters.

    Parameters:
    - full_name (str): The full name from which to extract the last name.
    - name_format (str): The format of the name provided. Defaults to 'first_last'.
    - handle_hyphenated (bool): Whether to handle hyphenated last names as a single entity. Defaults to true.
    - handle_special_characters (bool): Whether to handle special characters in names. Defaults to true.
    - include_suffix (bool): Whether to include suffixes in the extraction. Defaults to false.
    - output_format (str): The format of the output. Defaults to 'string'.

    Returns:
    - The extracted last name in the specified format.
    """
    # Error handling for required parameter
    if not full_name:
        return {'error': 'The full_name parameter is required.'}

    # Split the full name based on spaces
    name_parts = full_name.split()

    # Determine the last name based on the name format
    if name_format == 'first_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first':
        last_name = name_parts[0]
    elif name_format == 'title_first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first_middle':
        last_name = name_parts[0]
    elif name_format == 'title_first_middle_last':
        last_name = name_parts[-1]
    else:
        return {'error': 'Unsupported name format.'}

    # Handle hyphenated last names
    if handle_hyphenated and '-' in last_name:
        last_name = last_name.replace('-', ' ')

    # Handle special characters
    if not handle_special_characters:
        last_name = ''.join(e for e in last_name if e.isalnum())

    # Include suffix if specified
    if include_suffix and len(name_parts) > 1 and name_parts[-1] in ['Jr.', 'Sr.', 'III']:
        last_name += ' ' + name_parts[-1]

    # Format the output
    if output_format == 'array':
        return [last_name]
    elif output_format == 'object':
        return {'last_name': last_name}
    else:
        return last_name

