def extract_character(input: str, position: str = 'last', nth_value: int = None, range: dict = None, pattern: str = None, ignore_case: bool = False):
    # Validate input
    if not input:
        return {'error': 'Input string is empty.'}

    # Extract based on position
    if position == 'first':
        return {'result': input[0] if input else ''}
    elif position == 'last':
        return {'result': input[-1] if input else ''}
    elif position == 'nth':
        if nth_value is None or nth_value < 1 or nth_value > len(input):
            return {'error': 'Invalid nth_value provided.'}
        return {'result': input[nth_value - 1]}

    # Extract based on range
    if range:
        start = range.get('start', 0)
        end = range.get('end', len(input))
        if start < 0 or end > len(input) or start > end:
            return {'error': 'Invalid range specified.'}
        return {'result': input[start:end]}

    # Extract based on pattern
    if pattern:
        import re
        flags = re.IGNORECASE if ignore_case else 0
        match = re.search(pattern, input, flags)
        if match:
            return {'result': match.group(0)}
        else:
            return {'error': 'Pattern not found in input string.'}

    # Default case if no valid extraction method is specified
    return {'error': 'No valid extraction method specified.'}

