    titles = {'Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss', 'Mx.'}
    suffixes = {'Jr.', 'Sr.', 'II', 'III', 'IV'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Filter out titles if ignore_titles is True
    if ignore_titles:
        name_parts = [part for part in name_parts if part not in titles]

    # Filter out suffixes if ignore_suffixes is True
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle middle names if handle_middle_names is True
    if handle_middle_names:
        # Return the first part as the first name
        return ' '.join(name_parts[:2]) if len(name_parts) > 1 else name_parts[0]
    else:
        # Return only the first part as the first name
        return name_parts[0] if name_parts else ''

    # Error handling for incorrect input
    if not isinstance(full_name, str):
        raise ValueError('full_name must be a string')
    if not isinstance(delimiter, str):
        raise ValueError('delimiter must be a string')
    if not isinstance(ignore_titles, bool):
        raise ValueError('ignore_titles must be a boolean')
    if not isinstance(ignore_suffixes, bool):
        raise ValueError('ignore_suffixes must be a boolean')
    if not isinstance(handle_middle_names, bool):
        raise ValueError('handle_middle_names must be a boolean')
    if not isinstance(locale, str):
        raise ValueError('locale must be a string')

# Example usage
first_name = extract_first_name('Senakhtenre Ahmose')
print(first_name)  # Output: 'Senakhtenre'

def first_letter_extractor_v2(input: str, ignore_non_alphabetic: bool = False, case_sensitive: bool = True, language: str = 'en', character_set: str = 'alphabetic', handle_empty_string: str = 'return_empty') -> str:
    # Error handling for incorrect input types
    if not isinstance(input, str):
        raise ValueError('Input must be a string.')
    if handle_empty_string not in ['return_empty', 'return_null', 'error']:
        raise ValueError('Invalid value for handle_empty_string.')

    # Handle empty string based on the specified behavior
    if input == '':
        if handle_empty_string == 'return_empty':
            return ''
        elif handle_empty_string == 'return_null':
            return None
        elif handle_empty_string == 'error':
            raise ValueError('Input string is empty.')

    # Iterate over the string to find the first valid character
    for char in input:
        if character_set == 'alphabetic' and char.isalpha():
            if ignore_non_alphabetic and not char.isalpha():
                continue
            return char if case_sensitive else char.lower()
        # Additional character set handling can be implemented here

    # If no valid character is found, return based on empty string handling
    return '' if handle_empty_string == 'return_empty' else None

