def extract_last_name(full_name, delimiter=[' '], ignore_titles=True, naming_convention='western', include_middle_names=False, error_handling='warn'):
    # Define common titles to ignore
    titles = {'Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss', 'Sir', 'Dame'}

    # Split the full name using the provided delimiters
    import re
    pattern = '|'.join(map(re.escape, delimiter))
    parts = re.split(pattern, full_name)

    # Remove titles if ignore_titles is True
    if ignore_titles:
        parts = [part for part in parts if part not in titles]

    # Determine the last name based on the naming convention
    try:
        if naming_convention == 'western':
            last_name = parts[-1]
        elif naming_convention == 'eastern':
            last_name = parts[0]
        else:
            # Custom logic can be implemented here
            last_name = parts[-1]  # Default to western for simplicity

        # Include middle names if specified
        if include_middle_names and len(parts) > 2:
            last_name = ' '.join(parts[1:]) if naming_convention == 'western' else ' '.join(parts[:-1])

        return last_name
    except IndexError:
        if error_handling == 'warn':
            print('Warning: Unable to extract last name due to insufficient parts.')
            return None
        elif error_handling == 'strict':
            raise ValueError('Error: Unable to extract last name due to insufficient parts.')
        else:
            return None

