def date_calculator(base_date_time, years_to_add=0, years_to_subtract=0, months_to_add=0, months_to_subtract=0, days_to_add=0, days_to_subtract=0, hours_to_add=0, hours_to_subtract=0, minutes_to_add=0, minutes_to_subtract=0, seconds_to_add=0, seconds_to_subtract=0, output_format='YYYY-MM-DDTHH:MM:SS'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Validate base_date_time format
    try:
        base_date = datetime.strptime(base_date_time, '%Y-%m-%dT%H:%M:%S')
    except ValueError:
        return {'error': 'Invalid base_date_time format. Expected format: YYYY-MM-DDTHH:MM:SS'}

    # Validate output_format
    valid_formats = ['YYYY-MM-DD', 'MM/DD/YYYY', 'DD-MM-YYYY', 'YYYY-MM-DDTHH:MM:SS', 'MM/DD/YYYY HH:MM:SS', 'DD-MM-YYYY HH:MM:SS']
    if output_format not in valid_formats:
        return {'error': 'Invalid output_format. Must be one of: ' + ', '.join(valid_formats)}

    # Perform date calculations
    result_date = base_date + relativedelta(years=years_to_add - years_to_subtract,
                                            months=months_to_add - months_to_subtract,
                                            days=days_to_add - days_to_subtract)
    result_date += timedelta(hours=hours_to_add - hours_to_subtract,
                             minutes=minutes_to_add - minutes_to_subtract,
                             seconds=seconds_to_add - seconds_to_subtract)

    # Format the result date
    if output_format == 'YYYY-MM-DD':
        return {'result': result_date.strftime('%Y-%m-%d')}
    elif output_format == 'MM/DD/YYYY':
        return {'result': result_date.strftime('%m/%d/%Y')}
    elif output_format == 'DD-MM-YYYY':
        return {'result': result_date.strftime('%d-%m-%Y')}
    elif output_format == 'YYYY-MM-DDTHH:MM:SS':
        return {'result': result_date.strftime('%Y-%m-%dT%H:%M:%S')}
    elif output_format == 'MM/DD/YYYY HH:MM:SS':
        return {'result': result_date.strftime('%m/%d/%Y %H:%M:%S')}
    elif output_format == 'DD-MM-YYYY HH:MM:SS':
        return {'result': result_date.strftime('%d-%m-%Y %H:%M:%S')}

