def count_letters(input, ignore_characters=None, ignore_position=None, case_sensitive=False, character_type='all', output_format='integer'):
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Default values for optional parameters
    if ignore_characters is None:
        ignore_characters = []
    if ignore_position is None:
        ignore_position = []

    # Validate parameter types
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid ignore_characters type. Must be a list of strings.'}
    if not isinstance(ignore_position, list) or not all(p in ['first', 'last', 'even', 'odd'] for p in ignore_position):
        return {'error': 'Invalid ignore_position type. Must be a list with specific values.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Must be a boolean.'}
    if character_type not in ['all', 'vowels', 'consonants']:
        return {'error': 'Invalid character_type. Must be one of all, vowels, consonants.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of integer, text, detailed.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Define vowels and consonants
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Filter input based on ignore_characters
    filtered_input = ''.join([c for c in input if c not in ignore_characters])

    # Filter input based on ignore_position
    if 'first' in ignore_position and len(filtered_input) > 0:
        filtered_input = filtered_input[1:]
    if 'last' in ignore_position and len(filtered_input) > 0:
        filtered_input = filtered_input[:-1]
    if 'even' in ignore_position:
        filtered_input = ''.join([c for i, c in enumerate(filtered_input) if i % 2 != 0])
    if 'odd' in ignore_position:
        filtered_input = ''.join([c for i, c in enumerate(filtered_input) if i % 2 == 0])

    # Filter input based on character_type
    if character_type == 'vowels':
        filtered_input = ''.join([c for c in filtered_input if c in vowels])
    elif character_type == 'consonants':
        filtered_input = ''.join([c for c in filtered_input if c in consonants])

    # Count the letters
    letter_count = len(filtered_input)

    # Format the output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for c in filtered_input if c in vowels)
        consonant_count = sum(1 for c in filtered_input if c in consonants)
        return {
            'total': letter_count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }

# Example usage based on the question
result = count_letters('Maureen')
print(result)  # Expected output: 5

