def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DD', output_format='integer', time_zone='UTC', validate_date_range=True):
    from datetime import datetime
    import pytz

    # Helper function to parse date
    def parse_date(date_str, date_format):
        try:
            if 'T' in date_format:
                return datetime.strptime(date_str, date_format).replace(tzinfo=pytz.timezone(time_zone))
            else:
                return datetime.strptime(date_str, date_format)
        except ValueError:
            raise ValueError(f"Date '{date_str}' does not match format '{date_format}'")

    # Parse the start and end dates
    try:
        start = parse_date(start_date, date_format)
        end = parse_date(end_date, date_format)
    except ValueError as e:
        return {'error': str(e)}

    # Validate date range
    if validate_date_range and start > end:
        return {'error': 'End date must be after start date.'}

    # Calculate the difference
    delta = end - start

    # Format the output
    if output_format == 'integer':
        return {'result': delta.days}
    elif output_format == 'text':
        return {'result': f"{delta.days} days"}
    elif output_format == 'weeks':
        return {'result': delta.days // 7}
    elif output_format == 'months':
        return {'result': delta.days // 30}
    else:
        return {'error': 'Invalid output format specified.'}

# Example usage
