    from datetime import datetime, timedelta
    import pytz

    # Validate and parse the start date
    try:
        if calendar_system == 'Julian':
            # Use a library or custom logic for Julian calendar conversion
            start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
        else:
            start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        raise ValueError('Invalid start date format. Expected format is YYYY-MM-DD.')

    # Add days
    result_date_obj = start_date_obj + timedelta(days=days_to_add)

    # Format the result date
    if date_format == 'YYYY-MM-DD':
        result_date = result_date_obj.strftime('%Y-%m-%d')
    elif date_format == 'DD-MM-YYYY':
        result_date = result_date_obj.strftime('%d-%m-%Y')
    elif date_format == 'MM/DD/YYYY':
