def extract_last_name(full_name, delimiters=[' '], handle_hyphenated=True, ignore_titles=True, handle_middle_names=False, ignore_suffixes=True, cultural_naming_conventions='Western'):
    # Error handling for incorrect input types
    if not isinstance(full_name, str) or not full_name.strip():
        return 'Error: full_name must be a non-empty string.'
    if not isinstance(delimiters, list) or not all(isinstance(d, str) for d in delimiters):
        return 'Error: delimiters must be a list of strings.'
    if not isinstance(handle_hyphenated, bool):
        return 'Error: handle_hyphenated must be a boolean.'
    if not isinstance(ignore_titles, bool):
        return 'Error: ignore_titles must be a boolean.'
    if not isinstance(handle_middle_names, bool):
        return 'Error: handle_middle_names must be a boolean.'
    if not isinstance(ignore_suffixes, bool):
        return 'Error: ignore_suffixes must be a boolean.'
    if not isinstance(cultural_naming_conventions, str):
        return 'Error: cultural_naming_conventions must be a string.'

    # Titles and suffixes to ignore
    titles = ['Mr.', 'Mrs.', 'Ms.', 'Dr.'] if ignore_titles else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if ignore_suffixes else []

    # Remove titles and suffixes
    name_parts = full_name.split()
    name_parts = [part for part in name_parts if part not in titles + suffixes]

    # Handle hyphenated names
    if handle_hyphenated:
        last_name_candidates = [part for part in name_parts if '-' in part]
        if last_name_candidates:
            return last_name_candidates[-1]

    # Determine last name based on cultural naming conventions
    if cultural_naming_conventions == 'Western':
        # Western convention: last part is the last name
        last_name = name_parts[-1] if name_parts else ''
    else:
        # Other conventions can be added here
        last_name = name_parts[-1] if name_parts else ''

    return last_name

