def date_calculator(start_date: str, duration: dict, operation: str, time_zone: str = None, business_days_only: bool = False):
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Parse the start_date
    try:
        start_dt = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DDTHH:MM:SSZ.'}

    # Adjust for time zone if provided
    if time_zone:
        try:
            tz = pytz.timezone(time_zone)
            start_dt = start_dt.astimezone(tz)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown time zone specified.'}

    # Calculate the total duration
    days = duration.get('days', 0)
    weeks = duration.get('weeks', 0)
    months = duration.get('months', 0)
    years = duration.get('years', 0)
    hours = duration.get('hours', 0)
    minutes = duration.get('minutes', 0)

    # Create a timedelta and relativedelta object
    delta = timedelta(days=days + weeks * 7, hours=hours, minutes=minutes)
    relative_delta = relativedelta(months=months, years=years)

    # Perform the operation
    if operation == 'add':
        result_dt = start_dt + delta + relative_delta
    elif operation == 'subtract':
        result_dt = start_dt - delta - relative_delta
    else:
        return {'error': 'Invalid operation. Use add or subtract.'}

    # Consider business days only if specified
    if business_days_only:
        # Simple business day adjustment (ignoring holidays)
        while result_dt.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
            result_dt += timedelta(days=1 if operation == 'add' else -1)

    # Return the result in the specified format
    return {'result_date': result_dt.strftime('%Y-%m-%d')}

