def date_difference_calculator(start_date, end_date, date_format='YYYY-MM-DDTHH:MM:SS', calendar_system='gregorian', output_unit='days'):
    import datetime
    from dateutil import parser

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return {'error': 'Unsupported calendar system'}

    # Error handling for unsupported output units
    if output_unit not in ['days', 'weeks', 'months']:
        return {'error': 'Unsupported output unit'}

    try:
        # Parse the start and end dates
        start = parser.parse(start_date)
        end = parser.parse(end_date)
    except ValueError:
        return {'error': 'Invalid date format'}

    # Calculate the difference in days
    delta = end - start
    days_difference = delta.days

    # Convert the difference to the desired output unit
    if output_unit == 'weeks':
        result = days_difference / 7
    elif output_unit == 'months':
        result = days_difference / 30.44  # Approximate average month length
    else:
        result = days_difference

    return {'difference': result}

