def timezone_converter(input_datetime, input_timezone, output_timezone, output_format='ISO 8601', custom_format=None, batch_processing=None, recurring_conversion=None, historical_data=False):
    from datetime import datetime
    import pytz

    try:
        # Parse the input datetime
        input_dt = datetime.fromisoformat(input_datetime)

        # Set the input timezone
        if input_timezone.startswith(('+', '-')):
            input_tz = pytz.FixedOffset(int(input_timezone))
        else:
            input_tz = pytz.timezone(input_timezone)

        # Localize the input datetime
        localized_dt = input_tz.localize(input_dt)

        # Set the output timezone
        if output_timezone.startswith(('+', '-')):
            output_tz = pytz.FixedOffset(int(output_timezone))
        else:
            output_tz = pytz.timezone(output_timezone)

        # Convert to the output timezone
        converted_dt = localized_dt.astimezone(output_tz)

        # Format the output
        if output_format == 'ISO 8601':
            return converted_dt.isoformat()
        elif output_format == 'RFC 2822':
            return converted_dt.strftime('%a, %d %b %Y %H:%M:%S %z')
        elif output_format == 'custom' and custom_format:
            return converted_dt.strftime(custom_format)
        else:
            raise ValueError('Invalid output format or missing custom format string.')
    except Exception as e:
        return f'Error: {str(e)}'

