    if ignore_position and not all(pos in ['first', 'last'] for pos in ignore_position):
        raise ValueError("'ignore_position' must be a list containing 'first' and/or 'last'.")
    if output_format not in ['integer', 'text', 'json']:
        raise ValueError("'output_format' must be 'integer', 'text', or 'json'.")
    if character_type not in ['all', 'vowels', 'consonants']:
        raise ValueError("'character_type' must be 'all', 'vowels', or 'consonants'.")

    # Helper function to determine if a character is a vowel
    def is_vowel(char):
        return char.lower() in 'aeiou'

    # Helper function to determine if a character is a consonant
    def is_consonant(char):
        return char.isalpha() and not is_vowel(char)

    # Initialize total count
    total_count = 0
    detailed_counts = []

    # Process each string
    for string in input:
        # Apply case sensitivity
        if not case_sensitive:
            string = string.lower()

        # Initialize count for this string
        count = 0

        # Iterate over characters in the string
        for i, char in enumerate(string):
            # Check if character should be ignored
            if ignore_characters and char in ignore_characters:
                continue
            if ignore_position:
                if 'first' in ignore_position and i == 0:
                    continue
                if 'last' in ignore_position and i == len(string) - 1:
                    continue
            # Check character type
            if character_type == 'vowels' and not is_vowel(char):
                continue
            if character_type == 'consonants' and not is_consonant(char):
                continue
            # Increment count
            if char.isalpha():
                count += 1

        # Add to total count
        total_count += count
        # Add to detailed counts if needed
        if detailed_output:
            detailed_counts.append({string: count})

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f"Total letter count: {total_count}"
    elif output_format == 'json':
        result = {'total_count': total_count}
        if detailed_output:
            result['detailed_counts'] = detailed_counts
        return result

