from datetime import datetime, timedelta
from dateutil.relativedelta import relativedelta
import pytz


def date_calculator(input_date: str, operation: str, time_unit: str, amount: int, output_format: str = 'YYYY-MM-DD', custom_format: str = '', time_zone: str = 'UTC', business_days: bool = False) -> str:
    try:
        # Parse the input date
        date = datetime.strptime(input_date, '%Y-%m-%dT%H:%M:%S')

        # Adjust for time zone if specified
        if time_zone:
            tz = pytz.timezone(time_zone)
            date = tz.localize(date)

        # Perform the operation
        if operation == 'add':
            if time_unit == 'days':
                date += timedelta(days=amount)
            elif time_unit == 'months':
                date += relativedelta(months=amount)
            elif time_unit == 'years':
                date += relativedelta(years=amount)
            elif time_unit == 'hours':
                date += timedelta(hours=amount)
            elif time_unit == 'minutes':
                date += timedelta(minutes=amount)
            elif time_unit == 'seconds':
                date += timedelta(seconds=amount)
            else:
                raise ValueError('Invalid time unit')
        elif operation == 'subtract':
            if time_unit == 'days':
                date -= timedelta(days=amount)
            elif time_unit == 'months':
                date -= relativedelta(months=amount)
            elif time_unit == 'years':
                date -= relativedelta(years=amount)
            elif time_unit == 'hours':
                date -= timedelta(hours=amount)
            elif time_unit == 'minutes':
                date -= timedelta(minutes=amount)
            elif time_unit == 'seconds':
                date -= timedelta(seconds=amount)
            else:
                raise ValueError('Invalid time unit')
        else:
            raise ValueError('Invalid operation')

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            return date.strftime('%Y-%m-%d')
        elif output_format == 'MM/DD/YYYY':
            return date.strftime('%m/%d/%Y')
        elif output_format == 'DD-MM-YYYY':
            return date.strftime('%d-%m-%Y')
        elif output_format == 'custom':
            if not custom_format:
                raise ValueError('Custom format must be provided when output_format is set to custom')
            return date.strftime(custom_format)
        else:
            raise ValueError('Invalid output format')

    except Exception as e:
        return str(e)

