def extract_first_name(names, delimiter=' ', ignore_titles=True, include_middle_names=False, name_order='first_last', custom_titles=[]):
    # Validate input parameters
    if not isinstance(names, list) or len(names) == 0:
        return {'error': 'The names parameter must be a non-empty list of strings.'}
    if name_order not in ['first_last', 'last_first']:
        return {'error': 'The name_order parameter must be either "first_last" or "last_first".'}

    # Common titles to ignore
    common_titles = ['Mr.', 'Mrs.', 'Dr.', 'Ms.', 'Miss', 'Mx.']
    titles_to_ignore = common_titles + custom_titles if ignore_titles else custom_titles

    # Function to extract first name from a single full name
    def extract_from_single_name(full_name):
        # Split the name using the specified delimiter
        parts = full_name.split(delimiter)

        # Remove any titles from the name parts
        parts = [part for part in parts if part not in titles_to_ignore]

        # Determine the index of the first name based on the name order
        if name_order == 'first_last':
            first_name_index = 0
        else:  # 'last_first'
            first_name_index = 1 if len(parts) > 1 else 0

        # Extract the first name
        if include_middle_names:
            return ' '.join(parts[first_name_index:])
        else:
            return parts[first_name_index] if parts else ''

    # Apply the extraction function to each name in the list
    first_names = [extract_from_single_name(name) for name in names]

    return {'first_names': first_names}

