def string_length_calculator(input, ignore_characters=None, ignore_spaces=False, ignore_substrings=None, case_sensitive=True, character_types=['letters'], output_format='integer'):
    """
    Calculate the total number of letters in the given string with various customization options.
    """
    # Error handling for required parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize the count
    count = 0

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Remove ignored substrings
    if ignore_substrings:
        for substring in ignore_substrings:
            input = input.replace(substring, '')

    # Count letters
    for char in input:
        if ignore_spaces and char == ' ':
            continue
        if ignore_characters and char in ignore_characters:
            continue
        if 'letters' in character_types and char.isalpha():
            count += 1

    # Format the output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The total number of letters is {count}.'
    elif output_format == 'json':
        return {'count': count}
    else:
        return {'error': 'Invalid output format specified.'}

