    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate input parameters
    try:
        # Parse the input date
        input_date = datetime.strptime(input_date, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        return 'Error: Invalid input_date format. Expected ISO 8601 format.'

    # Handle timezone
    try:
        tz = pytz.timezone(timezone)
        input_date = tz.localize(input_date)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown timezone specified.'

    # Perform the operation
    if operation == 'subtract':
        if unit == 'months':
            result_date = input_date - relativedelta(months=value)
        else:
            return 'Error: Unsupported unit for subtraction.'
    else:
        return 'Error: Unsupported operation.'

    # Format the result date
    result_date_str = result_date.strftime('%Y-%m-%d')

    return result_date_str

