def count_total_letters(names, ignore_characters=None, output_format='integer', case_sensitive=False, character_types=['all']):
    # Validate input types
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        return {'error': 'Invalid input: names must be a list of strings.'}
    if ignore_characters and not isinstance(ignore_characters, list):
        return {'error': 'Invalid input: ignore_characters must be a list of strings.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid input: output_format must be one of integer, text, detailed.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(character_types, list) or not all(ct in ['vowels', 'consonants', 'all'] for ct in character_types):
        return {'error': 'Invalid input: character_types must be a list containing vowels, consonants, or all.'}

    # Define helper functions
    def is_vowel(char):
        return char.lower() in 'aeiou'

    def is_consonant(char):
        return char.isalpha() and not is_vowel(char)

    # Initialize count
    total_count = 0
    detailed_count = {'vowels': 0, 'consonants': 0}

    # Process each name
    for name in names:
        for char in name:
            # Apply case sensitivity
            if not case_sensitive:
                char = char.lower()

            # Skip ignored characters
            if ignore_characters and char in ignore_characters:
                continue

            # Count based on character types
            if 'all' in character_types or ('vowels' in character_types and is_vowel(char)) or ('consonants' in character_types and is_consonant(char)):
                total_count += 1
                if is_vowel(char):
                    detailed_count['vowels'] += 1
                elif is_consonant(char):
                    detailed_count['consonants'] += 1

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total letters: {total_count}'
    elif output_format == 'detailed':
        return {'total': total_count, 'breakdown': detailed_count}

