def extract_last_name(full_name, delimiter=' ', output_format='string', include_middle_names=False, handle_suffixes=False, handle_prefixes=False):
    # Validate the full_name parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle prefixes if specified
    if handle_prefixes and name_parts[0].lower() in ['mr', 'mrs', 'ms', 'dr']:
        name_parts = name_parts[1:]

    # Handle suffixes if specified
    if handle_suffixes and name_parts[-1].lower() in ['jr', 'sr', 'ii', 'iii']:
        suffix = name_parts.pop()
    else:
        suffix = None

    # Extract the last name
    last_name = name_parts[-1]

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        middle_names = name_parts[1:-1]
        last_name = ' '.join(middle_names + [last_name])

    # Format the output based on the specified output_format
    if output_format == 'array':
        result = [last_name]
        if suffix:
            result.append(suffix)
    elif output_format == 'json':
        result = {'last_name': last_name}
        if suffix:
            result['suffix'] = suffix
    else:  # Default to 'string'
        result = last_name
        if suffix:
            result += f' {suffix}'

    return result

