def vowel_counter(input: str, vowels: list = ['a', 'e', 'i', 'o', 'u'], case_sensitive: bool = False, output_format: str = 'integer', count_consonants: bool = False, language: str = 'en'):
    # Error handling for incorrect input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(vowels, list) or not all(isinstance(v, str) for v in vowels):
        return {'error': 'Vowels must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case_sensitive must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Output_format must be one of ["integer", "text", "detailed"].'}
    if not isinstance(count_consonants, bool):
        return {'error': 'Count_consonants must be a boolean.'}
    if not isinstance(language, str):
        return {'error': 'Language must be a string.'}

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()
        vowels = [v.lower() for v in vowels]

    # Initialize counts
    vowel_count = 0
    consonant_count = 0

    # Count vowels and consonants
    for char in input:
        if char in vowels:
            vowel_count += 1
        elif char.isalpha():
            consonant_count += 1

    # Prepare output based on format
    if output_format == 'integer':
        return vowel_count
    elif output_format == 'text':
        return f'There are {vowel_count} vowels in the input.'
    elif output_format == 'detailed':
        return {
            'vowel_count': vowel_count,
            'consonant_count': consonant_count if count_consonants else 'N/A',
            'details': {v: input.count(v) for v in vowels}
        }

