def extract_last_name(full_name, ignore_prefixes=[], ignore_suffixes=[], case_sensitive=False, locale='en', compound_last_name_handling=True, delimiter=' '):
    # Error handling for incorrect input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(ignore_prefixes, list) or not all(isinstance(p, str) for p in ignore_prefixes):
        return {'error': 'Invalid input: ignore_prefixes must be a list of strings.'}
    if not isinstance(ignore_suffixes, list) or not all(isinstance(s, str) for s in ignore_suffixes):
        return {'error': 'Invalid input: ignore_suffixes must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(locale, str):
        return {'error': 'Invalid input: locale must be a string.'}
    if not isinstance(compound_last_name_handling, bool):
        return {'error': 'Invalid input: compound_last_name_handling must be a boolean.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}

    # Split the full name using the specified delimiter
    names = full_name.split(delimiter)

    # Remove prefixes and suffixes if specified
    if not case_sensitive:
        names = [name.lower() for name in names]
        ignore_prefixes = [prefix.lower() for prefix in ignore_prefixes]
        ignore_suffixes = [suffix.lower() for suffix in ignore_suffixes]

    # Filter out ignored prefixes
    names = [name for name in names if name not in ignore_prefixes]

    # Handle compound last names
    if compound_last_name_handling:
        last_name = names[-1]
        if '-' in last_name or ' ' in last_name:
            return {'last_name': last_name}

    # Filter out ignored suffixes
    last_name = names[-1]
    if last_name in ignore_suffixes:
        return {'error': 'The last name is a suffix that should be ignored.'}

    return {'last_name': last_name}

