def extract_name_component(full_name, component='first', delimiter=' ', case_sensitive=True, cultural_format='Western'):
    """
    Extracts a specific component from a full name string based on the given parameters.

    :param full_name: The full name from which the name component will be extracted.
    :param component: The name component to extract (e.g., 'first', 'middle', 'last', 'prefix', 'suffix').
    :param delimiter: The character used to separate the parts of the name, default is space.
    :param case_sensitive: Whether the extraction should be case-sensitive, default is true.
    :param cultural_format: The cultural naming format to consider (e.g., 'Western', 'Eastern', 'Latin').
    :return: The extracted name component or an error message if extraction fails.
    """
    # Error handling for required parameter
    if not full_name:
        return {'error': 'The full_name parameter is required.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Determine the index based on the component and cultural format
    index_map = {
        'Western': {'first': 0, 'middle': 1, 'last': -1},
        'Eastern': {'first': -1, 'middle': 1, 'last': 0},
        'Latin': {'first': 0, 'middle': 1, 'last': -1}
    }

    if cultural_format not in index_map:
        return {'error': 'Invalid cultural_format specified.'}

    if component not in index_map[cultural_format]:
        return {'error': 'Invalid component specified.'}

    index = index_map[cultural_format][component]

    # Handle case sensitivity
    if not case_sensitive:
        name_parts = [part.lower() for part in name_parts]

    # Extract the component
    try:
        extracted_component = name_parts[index]
    except IndexError:
        return {'error': 'The specified component could not be extracted due to insufficient name parts.'}

    return {'component': extracted_component}

