def reverse_string(input, reverse_partial=None, case_sensitive=True, output_format='string', whitespace_handling='preserve', character_set=None, delimiter=', '):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 10:
        return {'error': 'Input must be an array of 1 to 10 strings.'}
    for s in input:
        if not isinstance(s, str):
            return {'error': 'All items in input must be strings.'}

    # Process each string in the input list
    results = []
    for s in input:
        # Handle whitespace
        if whitespace_handling == 'trim':
            s = s.strip()
        elif whitespace_handling == 'remove':
            s = ''.join(s.split())

        # Determine the range for reversal
        start, end = 0, len(s)
        if reverse_partial:
            start = reverse_partial.get('start', 0)
            end = reverse_partial.get('end', len(s))

        # Reverse the specified portion of the string
        if character_set:
            # Reverse only specified characters
            reversed_part = ''.join([c if c not in character_set else '' for c in s[start:end]])[::-1]
            s = s[:start] + reversed_part + s[end:]
        else:
            # Reverse all characters
            reversed_part = s[start:end][::-1]
            s = s[:start] + reversed_part + s[end:]

        # Add to results
        results.append(s)

    # Format the output
    if output_format == 'array':
        return {'result': delimiter.join(results)}
    else:
        return {'result': ''.join(results)}

