def date_calculator(start_date, years_to_add, months_to_add=0, days_to_add=0, output_format='YYYY-MM-DD', time_zone='UTC'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Error handling for date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Error handling for time zone
    try:
        tz = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone.'}

    # Calculate the new date
    try:
        new_date = start_date_obj + relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)
    except Exception as e:
        return {'error': str(e)}

    # Convert to the specified time zone
    new_date = tz.localize(new_date)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'ISO-8601':
        formatted_date = new_date.isoformat()
    else:
        return {'error': 'Invalid output format.'}

    return {'date': formatted_date}

