def extract_last_name(full_name, delimiter=' ', last_name_position='last', custom_index=0, handle_middle_names=False, case_sensitive=False, multiple_last_names=False, suffix_handling=False, inconsistent_delimiters=False):
    # Error handling for required parameter
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}

    # Handle inconsistent delimiters
    if inconsistent_delimiters:
        import re
        parts = re.split(r'\s+', full_name.strip())
    else:
        parts = full_name.split(delimiter)

    # Error handling for custom index
    if last_name_position == 'custom' and (custom_index < 0 or custom_index >= len(parts)):
        return {'error': 'Invalid custom_index: out of range.'}

    # Determine the last name based on position
    if last_name_position == 'last':
        last_name = parts[-1]
    elif last_name_position == 'first':
        last_name = parts[0]
    elif last_name_position == 'custom':
        last_name = parts[custom_index]
    else:
        return {'error': 'Invalid last_name_position: must be "last", "first", or "custom".'}

    # Handle case sensitivity
    if not case_sensitive:
        last_name = last_name.lower()

    # Handle multiple last names
    if multiple_last_names and last_name_position == 'last':
        last_name = ' '.join(parts[-2:]) if len(parts) > 1 else last_name

    # Handle suffixes
    if suffix_handling and last_name_position == 'last':
        suffixes = ['Jr', 'Sr', 'II', 'III', 'IV']
        if len(parts) > 1 and parts[-1].strip('.') in suffixes:
            last_name = ' '.join(parts[-2:])

    return {'last_name': last_name}

def enhanced_unique_letter_counter(input: str, case_sensitive: bool = False, include_non_alpha: bool = False, character_set: str = 'ASCII', ignore_characters: str = '', return_statistics: bool = False):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a valid string.'}

    # Normalize case if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        ignore_characters = ignore_characters.lower()

    # Filter out ignored characters
    filtered_input = ''.join(ch for ch in input if ch not in ignore_characters)

    # Determine character set
    if character_set == 'ASCII':
        valid_chars = set(chr(i) for i in range(128))
    elif character_set == 'Unicode':
        valid_chars = set(chr(i) for i in range(65536))
    else:
        return {'error': 'Unsupported character set specified.'}

    # Filter out non-alphabetic characters if include_non_alpha is False
    if not include_non_alpha:
        filtered_input = ''.join(ch for ch in filtered_input if ch.isalpha())

    # Count unique letters
    unique_letters = set(ch for ch in filtered_input if ch in valid_chars)
    count = len(unique_letters)

    # Prepare statistics if required
    statistics = {}
    if return_statistics:
        for letter in unique_letters:
            statistics[letter] = filtered_input.count(letter)

    # Return result
    result = {'unique_count': count}
    if return_statistics:
        result['statistics'] = statistics
    return result

