def character_counter(input_string, characters_to_count, case_sensitive=False, ignore_whitespace=False, alphabetic_only=False, detailed_report=False):
    # Validate input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(characters_to_count, list) or not all(isinstance(c, str) for c in characters_to_count):
        return {'error': 'characters_to_count must be a list of strings'}
    if not characters_to_count:
        return {'error': 'characters_to_count must contain at least one character'}

    # Prepare the input string based on options
    if not case_sensitive:
        input_string = input_string.lower()
        characters_to_count = [c.lower() for c in characters_to_count]
    if ignore_whitespace:
        input_string = input_string.replace(' ', '')
    if alphabetic_only:
        input_string = ''.join(filter(str.isalpha, input_string))

    # Count occurrences
    counts = {char: 0 for char in characters_to_count}
    for char in input_string:
        if char in counts:
            counts[char] += 1

    # Prepare the result
    if detailed_report:
        return {'detailed_report': counts}
    else:
        total_count = sum(counts.values())
        return {'total_count': total_count}

