def date_calculator(input_date, years_offset=0, months_offset=0, days_offset=0, calendar_system='Gregorian', output_format='YYYY-MM-DD', include_time=False):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Error handling for unsupported calendar systems
    if calendar_system not in ['Gregorian', 'Julian', 'Islamic', 'Hebrew']:
        return {'error': 'Unsupported calendar system'}

    # Error handling for unsupported output formats
    if output_format not in ['YYYY-MM-DD', 'DD-MM-YYYY', 'MM-DD-YYYY', 'ISO 8601']:
        return {'error': 'Unsupported output format'}

    try:
        # Parse the input date
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')

        # Apply the date offsets
        date_obj += relativedelta(years=years_offset, months=months_offset, days=days_offset)

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            result_date = date_obj.strftime('%Y-%m-%d')
        elif output_format == 'DD-MM-YYYY':
            result_date = date_obj.strftime('%d-%m-%Y')
        elif output_format == 'MM-DD-YYYY':
            result_date = date_obj.strftime('%m-%d-%Y')
        elif output_format == 'ISO 8601':
            result_date = date_obj.isoformat()

        # Include time if specified
        if include_time:
            result_date += ' ' + date_obj.strftime('%H:%M:%S')

        return {'result': result_date}
    except ValueError as e:
        return {'error': str(e)}

