def date_subtractor(input_date: str, years_to_subtract: int = 0, months_to_subtract: int = 0, days_to_subtract: int = 0, calendar_system: str = 'Gregorian', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'ISO8601']:
        return 'Error: Unsupported calendar system.'

    # Validate output format
    if output_format not in ['YYYY-MM-DD', 'MM-DD-YYYY', 'DD-MM-YYYY']:
        return 'Error: Unsupported output format.'

    try:
        # Parse the input date
        date = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid date format. Please use YYYY-MM-DD.'

    # Subtract years, months, and days
    try:
        new_date = date - relativedelta(years=years_to_subtract, months=months_to_subtract, days=days_to_subtract)
    except Exception as e:
        return f'Error: {str(e)}'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        return new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        return new_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        return new_date.strftime('%d-%m-%Y')

