def first_letter_extractor(names, case_sensitive=True, output_format='list', handle_non_alphabetic=False, default_character=''):
    # Validate input types
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        return {'error': 'Invalid input: names must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if output_format not in ['single', 'list', 'concatenated']:
        return {'error': 'Invalid input: output_format must be one of ["single", "list", "concatenated"].'}
    if not isinstance(handle_non_alphabetic, bool):
        return {'error': 'Invalid input: handle_non_alphabetic must be a boolean.'}
    if not isinstance(default_character, str):
        return {'error': 'Invalid input: default_character must be a string.'}

    # Extract first letters
    first_letters = []
    for name in names:
        if name:
            first_char = name[0]
            if not first_char.isalpha() and not handle_non_alphabetic:
                first_char = default_character
            elif not case_sensitive:
                first_char = first_char.lower()
        else:
            first_char = default_character
        first_letters.append(first_char)

    # Format output
    if output_format == 'single':
        return first_letters[0] if first_letters else default_character
    elif output_format == 'concatenated':
        return ''.join(first_letters)
    else:  # 'list'
        return first_letters

