def enhanced_ascii_converter(input: str, mode: str, encoding: str = 'UTF-8') -> dict:
    """
    Convert characters to ASCII codes or ASCII codes to characters.

    Parameters:
    - input (str): A string of characters or ASCII codes.
    - mode (str): The mode of conversion ('to_ascii' or 'from_ascii').
    - encoding (str): The character encoding format (default is 'UTF-8').

    Returns:
    - dict: A dictionary with the conversion result or an error message.
    """
    try:
        if mode not in ['to_ascii', 'from_ascii']:
            return {'error': 'Invalid mode. Choose either "to_ascii" or "from_ascii".'}

        if mode == 'to_ascii':
            # Convert characters to ASCII codes
            ascii_codes = [ord(char) for char in input]
            return {'result': ascii_codes}

        elif mode == 'from_ascii':
            # Convert ASCII codes to characters
            try:
                ascii_values = map(int, input.split())
                characters = ''.join(chr(value) for value in ascii_values)
                return {'result': characters}
            except ValueError:
                return {'error': 'Invalid input for ASCII conversion. Ensure input is a space-separated string of numbers.'}

    except Exception as e:
        return {'error': str(e)}

