def date_calculator(start_date, days_to_add=0, months_to_add=0, years_to_add=0, output_format='YYYY-MM-DD', time_zone='UTC', adjust_for_dst=False):
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Adjust date based on input parameters
    try:
        new_date = date_obj + relativedelta(days=days_to_add, months=months_to_add, years=years_to_add)
    except Exception as e:
        return {'error': str(e)}

    # Handle time zone adjustment
    if time_zone != 'UTC':
        try:
            tz = pytz.timezone(time_zone)
            new_date = new_date.astimezone(tz)
        except pytz.UnknownTimeZoneError:
            return {'error': 'Unknown time zone specified.'}

    # Adjust for daylight saving time if required
    if adjust_for_dst:
        new_date = new_date + relativedelta(hours=1) if new_date.dst() else new_date

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = new_date.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date.strftime('%d-%m-%Y')
    elif output_format == 'DD/MM/YYYY':
        formatted_date = new_date.strftime('%d/%m/%Y')
    elif output_format == 'YYYY/MM/DD':
        formatted_date = new_date.strftime('%Y/%m/%d')
    else:
        return {'error': 'Invalid output format specified.'}

    return {'result': formatted_date}

