def enhanced_ascii_code_finder(characters, output_format='integer', handle_non_ascii=True, error_message='Non-ASCII character detected.'):
    """
    Find ASCII or Unicode codes for a list of characters.

    Parameters:
    characters (list of str): The characters for which ASCII or Unicode codes are to be found.
    output_format (str): The format of the output code. Defaults to 'integer'.
    handle_non_ascii (bool): Whether to handle non-ASCII characters by returning a specific error message or their Unicode code point.
    error_message (str): Custom error message for non-ASCII characters when 'handle_non_ascii' is false.

    Returns:
    dict: A dictionary with characters as keys and their corresponding codes as values.
    """
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['integer', 'hex', 'binary', 'unicode']:
        raise ValueError("'output_format' must be one of ['integer', 'hex', 'binary', 'unicode'].")

    result = {}
    for char in characters:
        code_point = ord(char)
        if code_point > 127 and not handle_non_ascii:
            result[char] = error_message
        else:
            if output_format == 'integer':
                result[char] = code_point
            elif output_format == 'hex':
                result[char] = hex(code_point)
            elif output_format == 'binary':
                result[char] = bin(code_point)
            elif output_format == 'unicode':
                result[char] = f'U+{code_point:04X}'
    return result

