def extract_last_letter(input: str, ignore_special_characters: bool = False, output_format: str = 'character', case_sensitive: bool = True, consider_multibyte: bool = True, letter_range: str = '[a-zA-Z]') -> str:
    import re

    # Validate output_format
    if output_format not in ['character', 'ascii', 'unicode', 'hex']:
        raise ValueError('Invalid output format specified.')

    # Handle multi-byte characters
    if consider_multibyte:
        input = input.encode('utf-8').decode('utf-8')

    # Define the regex pattern for letters
    pattern = re.compile(letter_range)

    # Reverse the string to find the last letter
    for char in reversed(input):
        if ignore_special_characters and not pattern.match(char):
            continue
        if pattern.match(char):
            last_letter = char
            break
    else:
        raise ValueError('No valid letter found in the input string.')

    # Convert the last letter to the desired format
    if output_format == 'ascii':
        return str(ord(last_letter))
    elif output_format == 'unicode':
        return f'U+{ord(last_letter):04X}'
    elif output_format == 'hex':
        return hex(ord(last_letter))
    else:  # Default to 'character'
        return last_letter

