def extract_last_name(full_name, name_format='western', custom_delimiter=' ', include_middle_names=False, handle_suffixes=True, handle_prefixes=True, special_character_handling='ignore'):
    """
    Extracts the last name from a full name string based on the specified naming convention and parameters.
    """
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid full_name. It must be a non-empty string.'}

    # Handle special characters based on the specified option
    if special_character_handling == 'remove':
        import re
        full_name = re.sub(r'[^\w\s]', '', full_name)
    elif special_character_handling == 'include':
        pass  # Include special characters as they are
    # 'ignore' option does nothing

    # Split the name based on the format
    if name_format == 'western':
        parts = full_name.split()
    elif name_format == 'eastern':
        parts = full_name.split()
        parts.reverse()  # Reverse for eastern naming convention
    elif name_format == 'custom':
        parts = full_name.split(custom_delimiter)
    else:
        return {'error': 'Unsupported name_format.'}

    # Handle prefixes
    if handle_prefixes:
        prefixes = ['Dr.', 'Mr.', 'Ms.', 'Mrs.']  # Example prefixes
        parts = [part for part in parts if part not in prefixes]

    # Handle suffixes
    if handle_suffixes:
        suffixes = ['Jr.', 'Sr.', 'III']  # Example suffixes
        if parts[-1] in suffixes:
            parts.pop()

    # Determine the last name
    if include_middle_names:
        last_name = ' '.join(parts[1:]) if len(parts) > 1 else parts[0]
    else:
        last_name = parts[-1] if parts else ''

    return {'last_name': last_name}

