def first_letter_extractor(input: str, case_sensitive: bool = True, output_format: str = 'character', ignore_whitespace: bool = False, handle_non_alpha: str = 'ignore') -> str:
    """
    Extracts the first letter from the given input string based on specified parameters.

    :param input: The string from which the first letter will be extracted.
    :param case_sensitive: If True, maintains the case of the first letter.
    :param output_format: The format of the output ('character', 'ascii', 'unicode', 'hex').
    :param ignore_whitespace: If True, ignores leading whitespace.
    :param handle_non_alpha: Specifies how to handle non-alphabetic characters ('ignore', 'extract', 'error').
    :return: The first letter in the specified format.
    :raises ValueError: If non-alphabetic characters are encountered and 'handle_non_alpha' is set to 'error'.
    """
    # Handle leading whitespace
    if ignore_whitespace:
        input = input.lstrip()

    # Iterate over the string to find the first valid character
    for char in input:
        if char.isalpha():
            # Handle case sensitivity
            if not case_sensitive:
                char = char.lower()

            # Return the character in the specified format
            if output_format == 'character':
                return char
            elif output_format == 'ascii':
                return str(ord(char))
            elif output_format == 'unicode':
                return f'U+{ord(char):04X}'
            elif output_format == 'hex':
                return hex(ord(char))

        elif handle_non_alpha == 'extract':
            # Return non-alphabetic character in the specified format
            if output_format == 'character':
                return char
            elif output_format == 'ascii':
                return str(ord(char))
            elif output_format == 'unicode':
                return f'U+{ord(char):04X}'
            elif output_format == 'hex':
                return hex(ord(char))

        elif handle_non_alpha == 'error':
            raise ValueError('Non-alphabetic character encountered at the start of the string.')

    # If no valid character is found, return an empty string or handle as needed
    return ''

