def extract_last_letter(input: str, ignore_whitespace: bool = True, case_sensitive: bool = True, ignore_punctuation: bool = False, character_set: str = 'all', extract_count: int = 1, output_details: bool = False):
    import string

    # Error handling for invalid inputs
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(extract_count, int) or extract_count < 1:
        return {'error': 'Extract count must be a positive integer.'}

    # Handle whitespace
    if ignore_whitespace:
        input = input.rstrip()

    # Handle punctuation
    if ignore_punctuation:
        input = input.rstrip(string.punctuation)

    # Handle character set
    if character_set != 'all':
        input = ''.join([char for char in input if char in character_set])

    # Extract last letter(s)
    if len(input) < extract_count:
        return {'error': 'Not enough characters to extract.'}
    extracted = input[-extract_count:]

    # Handle case sensitivity
    if not case_sensitive:
        extracted = extracted.lower()

    # Prepare output
    result = {'last_letter': extracted}
    if output_details:
        result['position'] = len(input) - extract_count

    return result

