    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize variables
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'
    letters = input

    # Apply case sensitivity
    if not case_sensitive:
        letters = letters.lower()

    # Ignore specified positions
    if 'first' in ignore_position and len(letters) > 0:
        letters = letters[1:]
    if 'last' in ignore_position and len(letters) > 0:
        letters = letters[:-1]

    # Ignore specified characters
    for char in ignore_characters:
        letters = letters.replace(char, '')

    # Filter by character type
    if character_type == 'vowels':
        letters = ''.join([char for char in letters if char in vowels])
    elif character_type == 'consonants':
        letters = ''.join([char for char in letters if char in consonants])

    # Count letters
    letter_count = len(letters)

    # Format output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed_json':
        from collections import Counter
        return {'total_count': letter_count, 'breakdown': dict(Counter(letters))}
    else:
        return {'error': 'Invalid output format specified.'}

