def date_calculator(start_date, end_date=None, days_offset=None, input_format='YYYY-MM-DD', output_format='YYYY-MM-DD', time_zone='UTC', operation='add_subtract_days'):
    from datetime import datetime, timedelta
    import pytz

    # Helper function to parse date based on input format
    def parse_date(date_str, date_format):
        try:
            if date_format == 'YYYY-MM-DD':
                return datetime.strptime(date_str, '%Y-%m-%d')
            elif date_format == 'MM/DD/YYYY':
                return datetime.strptime(date_str, '%m/%d/%Y')
            elif date_format == 'DD-MM-YYYY':
                return datetime.strptime(date_str, '%d-%m-%Y')
        except ValueError:
            raise ValueError(f"Invalid date format for {date_str} with format {date_format}")

    # Helper function to format date based on output format
    def format_date(date_obj, date_format):
        if date_format == 'YYYY-MM-DD':
            return date_obj.strftime('%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            return date_obj.strftime('%m/%d/%Y')
        elif date_format == 'DD-MM-YYYY':
            return date_obj.strftime('%d-%m-%Y')

    # Validate required parameters
    if not start_date or not operation:
        raise ValueError("'start_date' and 'operation' are required parameters.")

    # Parse the start date
    start_date_obj = parse_date(start_date, input_format)

    # Adjust for timezone
    tz = pytz.timezone(time_zone)
    start_date_obj = tz.localize(start_date_obj)

    if operation == 'add_subtract_days':
        if days_offset is None:
            raise ValueError("'days_offset' is required for add_subtract_days operation.")
        # Perform the date arithmetic
        result_date_obj = start_date_obj + timedelta(days=days_offset)
        # Format the result date
        result_date_str = format_date(result_date_obj, output_format)
        return result_date_str
    elif operation == 'calculate_difference':
        if not end_date:
            raise ValueError("'end_date' is required for calculate_difference operation.")
        # Parse the end date
        end_date_obj = parse_date(end_date, input_format)
        end_date_obj = tz.localize(end_date_obj)
        # Calculate the difference
        difference = (end_date_obj - start_date_obj).days
        return difference
    else:
        raise ValueError(f"Unsupported operation: {operation}")

