def operation_director_lookup(operation_name: str, dataset: list, case_sensitive: bool = False, partial_match: bool = True, filter_by_status: str = None):
    """
    Searches for the director of a specified operation in the dataset.

    Parameters:
    - operation_name (str): The name of the operation to search for.
    - dataset (list): A list of dictionaries, each containing 'operation', 'director', and optional 'metadata'.
    - case_sensitive (bool): Whether the search should be case-sensitive. Defaults to False.
    - partial_match (bool): Whether to allow partial matches. Defaults to True.
    - filter_by_status (str): Optional status to filter operations.

    Returns:
    - str: The name of the director if found, or an error message.
    """
    try:
        if not isinstance(operation_name, str) or not isinstance(dataset, list):
            raise ValueError("Invalid input types.")

        for entry in dataset:
            if 'operation' not in entry or 'director' not in entry:
                raise ValueError("Dataset entries must contain 'operation' and 'director'.")

            operation = entry['operation']
            director = entry['director']
            metadata = entry.get('metadata', {})
            status = metadata.get('status', None)

            if filter_by_status and status != filter_by_status:
                continue

            if partial_match:
                match = operation_name in operation if not case_sensitive else operation_name.lower() in operation.lower()
            else:
                match = operation_name == operation if not case_sensitive else operation_name.lower() == operation.lower()

            if match:
                return director

        return "No matching operation found."

    except Exception as e:
        return str(e)

