def first_letter_extractor_plus(input, ignore_whitespace=True, case_sensitive=True, character_type='letter', language_script='any'):
    import re

    # Define regex patterns for different character types
    patterns = {
        'letter': r'[A-Za-z]',
        'number': r'[0-9]',
        'symbol': r'[!@#$%^&*(),.?":{}|<>]',
        'any': r'.'
    }

    # Validate character_type
    if character_type not in patterns:
        raise ValueError("Invalid character_type. Must be one of 'letter', 'number', 'symbol', or 'any'.")

    # Function to extract first character based on parameters
    def extract_first_char(s):
        if ignore_whitespace:
            s = s.lstrip()
        pattern = patterns[character_type]
        match = re.search(pattern, s)
        if match:
            char = match.group(0)
            if not case_sensitive:
                char = char.lower()
            return char
        return None

    # Handle input being a string or a list of strings
    if isinstance(input, str):
        return extract_first_char(input)
    elif isinstance(input, list):
        return [extract_first_char(item) for item in input if isinstance(item, str)]
    else:
        raise TypeError("Input must be a string or a list of strings.")

