def count_repeated_letters(input, case_sensitive=False, output_format='integer', ignore_characters=[], consecutive_only=False):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format. Must be one of: integer, text, detailed.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Initialize a dictionary to count repeated letters
    repeated_counts = {}

    # Iterate over the string to count repeated letters
    i = 0
    while i < len(input):
        char = input[i]
        if char in ignore_characters:
            i += 1
            continue
        count = 1
        while i + 1 < len(input) and input[i + 1] == char:
            count += 1
            i += 1
        if count > 1:
            if consecutive_only:
                repeated_counts[char] = repeated_counts.get(char, 0) + 1
            else:
                repeated_counts[char] = repeated_counts.get(char, 0) + count
        i += 1

    # Format the output based on the specified output format
    if output_format == 'integer':
        return sum(repeated_counts.values())
    elif output_format == 'text':
        return f"Total repeated letters: {sum(repeated_counts.values())}"
    elif output_format == 'detailed':
        return {char: count for char, count in repeated_counts.items()}

