def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', min_repetition: int = 2, ignore_non_alpha: bool = True):
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': "output_format must be one of ['integer', 'list', 'detailed']."}
    if not isinstance(min_repetition, int) or min_repetition < 1:
        return {'error': 'min_repetition must be a positive integer.'}
    if not isinstance(ignore_non_alpha, bool):
        return {'error': 'ignore_non_alpha must be a boolean.'}

    # Prepare the input string based on the parameters
    if ignore_non_alpha:
        input = ''.join(filter(str.isalpha, input))
    if not case_sensitive:
        input = input.lower()

    # Count occurrences of each letter
    from collections import Counter
    letter_counts = Counter(input)

    # Filter letters based on the repetition criteria
    repeated_letters = {letter: count for letter, count in letter_counts.items() if count >= min_repetition}

    # Generate output based on the specified format
    if output_format == 'integer':
        return len(repeated_letters)
    elif output_format == 'list':
        return list(repeated_letters.keys())
    elif output_format == 'detailed':
        return [{'letter': letter, 'count': count, 'positions': [i for i, l in enumerate(input) if l == letter]} for letter, count in repeated_letters.items()]

