def get_last_letter(names, output_format='character', ignore_empty=False):
    # Validate input types
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        raise ValueError("'names' must be a list of strings.")
    if output_format not in ['character', 'text', 'json']:
        raise ValueError("'output_format' must be one of 'character', 'text', or 'json'.")
    if not isinstance(ignore_empty, bool):
        raise ValueError("'ignore_empty' must be a boolean.")

    # Process names to get last letters
    last_letters = {}
    for name in names:
        if name == "" and ignore_empty:
            continue
        last_letter = name[-1] if name else ""
        last_letters[name] = last_letter

    # Format output based on 'output_format'
    if output_format == 'character':
        return [last_letters[name] for name in names if name or not ignore_empty]
    elif output_format == 'text':
        return ''.join(last_letters[name] for name in names if name or not ignore_empty)
    elif output_format == 'json':
        return last_letters

