def consonant_counter(input: str, case_sensitive: bool = False, ignore_non_alpha: bool = True, language: str = 'english', custom_consonants: list = None, detailed_count: bool = False):
    # Define consonants for supported languages
    language_consonants = {
        'english': 'bcdfghjklmnpqrstvwxyz',
        'spanish': 'bcdfghjklmnñpqrstvwxyz',
        'french': 'bcdfghjklmnpqrstvwxz',
        'german': 'bcdfghjklmnpqrstvwxyz'
    }

    # Use custom consonants if provided, otherwise use language-specific consonants
    consonants = custom_consonants if custom_consonants else list(language_consonants.get(language, ''))

    # Convert consonants to the appropriate case if case sensitivity is not required
    if not case_sensitive:
        consonants = [c.lower() for c in consonants]
        input = input.lower()

    # Initialize consonant count
    consonant_count = 0
    detailed_counts = {}

    # Iterate over each character in the input string
    for char in input:
        # Skip non-alphabetic characters if ignore_non_alpha is True
        if ignore_non_alpha and not char.isalpha():
            continue

        # Check if the character is a consonant
        if char in consonants:
            consonant_count += 1
            if detailed_count:
                if char in detailed_counts:
                    detailed_counts[char] += 1
                else:
                    detailed_counts[char] = 1

    # Return detailed counts if requested
    if detailed_count:
        return {'total': consonant_count, 'details': detailed_counts}
    else:
        return consonant_count

