    if relationship_type not in database[individual_name]:
        return {'error': 'Invalid relationship type for the given individual.'}

    # Retrieve results
    results = database[individual_name][relationship_type][:max_results]

    # Format results
    if output_format == 'list':
        return results
    elif output_format == 'text':
        return ', '.join(results)
    elif output_format == 'json':
        import json
