def consonant_counter(input, case_sensitive=False, output_format='integer', language='en', exclude_consonants=[]):
    # Define consonants for supported languages
    consonants = {
        'en': 'bcdfghjklmnpqrstvwxyz',
        'es': 'bcdfghjklmnñpqrstvwxyz',
        'fr': 'bcdfghjklmnpqrstvwxyz'
    }

    # Validate input
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if language not in consonants:
        return {'error': f'Unsupported language: {language}'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': f'Unsupported output format: {output_format}'}

    # Prepare consonant set
    consonant_set = set(consonants[language]) - set(exclude_consonants)
    if not case_sensitive:
        consonant_set = consonant_set.union(set(c.upper() for c in consonant_set))

    # Count consonants
    total_count = 0
    detailed_counts = []
    for string in input:
        count = sum(1 for char in string if char in consonant_set)
        total_count += count
        detailed_counts.append({'string': string, 'count': count})

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total consonants: {total_count}'
    elif output_format == 'detailed':
        return detailed_counts

