def advanced_consonant_counter(input, case_sensitive=False, output_format='integer', exclude_characters=None, language='en'):
    # Define consonants for each supported language
    consonants = {
        'en': 'bcdfghjklmnpqrstvwxyz',
        'es': 'bcdfghjklmnñpqrstvwxyz',
        'fr': 'bcdfghjklmnpqrstvwxyz'
    }

    # Validate language
    if language not in consonants:
        return {'error': 'Unsupported language'}

    # Validate output format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format'}

    # Prepare consonant set
    consonant_set = set(consonants[language])

    # Apply case sensitivity
    if not case_sensitive:
        consonant_set = consonant_set.union(set(c.upper() for c in consonant_set))

    # Exclude characters if provided
    if exclude_characters:
        consonant_set = consonant_set.difference(set(exclude_characters))

    # Initialize result
    result = []

    # Count consonants in each string
    for string in input:
        count = sum(1 for char in string if char in consonant_set)
        if output_format == 'detailed':
            result.append({'string': string, 'count': count})
        else:
            result.append(count)

    # Format output
    if output_format == 'integer':
        return sum(result)
    elif output_format == 'text':
        return ', '.join(str(count) for count in result)
    elif output_format == 'detailed':
        return result

