def reverse_order(input, output_format='string', case_sensitive=True, ignore_whitespace=False, reverse_sections=None):
    """
    Reverses the order of characters in the given input.

    Parameters:
    - input (str): The input string, number, or list to be reversed.
    - output_format (str): The format of the output. Defaults to 'string'.
    - case_sensitive (bool): Determines if the reversal should maintain case sensitivity. Defaults to True.
    - ignore_whitespace (bool): If true, whitespace will be ignored during reversal. Defaults to False.
    - reverse_sections (list): An array of indices specifying sections of the input to reverse individually.

    Returns:
    - Reversed input in the specified format.
    """
    # Error handling for invalid input types
    if not isinstance(input, (str, int, list)):
        return "Error: Invalid input type. Must be a string, number, or list."

    # Convert input to string if it is a number
    if isinstance(input, int):
        input = str(input)

    # Handle whitespace ignoring
    if ignore_whitespace:
        input = ''.join(input.split())

    # Reverse the input
    reversed_input = input[::-1]

    # Handle case sensitivity
    if not case_sensitive:
        reversed_input = reversed_input.lower()

    # Convert to the specified output format
    if output_format == 'string':
        return reversed_input
    elif output_format == 'number':
        try:
            return int(reversed_input)
        except ValueError:
            return "Error: Cannot convert reversed input to number."
    elif output_format == 'list':
        return list(reversed_input)
    else:
        return "Error: Invalid output format specified."

