    # Validate the full_name parameter
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}

    # Validate the name_position parameter
    if not isinstance(name_position, int) or name_position < 0:
        return {'error': 'Invalid input: name_position must be a non-negative integer.'}

    # Split the full name using the provided delimiters
    import re
    delimiters_regex = '|'.join(map(re.escape, name_delimiters))
    name_parts = re.split(delimiters_regex, full_name)

    # Handle special characters if required
    if handle_special_characters:
        name_parts = [re.sub(r'[^\w\s]', '', part) for part in name_parts]

    # Normalize names if required
    if normalize_names:
        import unicodedata
        name_parts = [unicodedata.normalize('NFKD', part).encode('ascii', 'ignore').decode('ascii').lower() for part in name_parts]

    # Check if the name_position is within the range of name_parts
    if name_position >= len(name_parts):
        return {'error': 'Invalid input: name_position is out of range.'}

    # Extract the desired name part
    extracted_name = name_parts[name_position]

    # Return the extracted name
    return {'extracted_name': extracted_name}

