def string_concatenator(strings, delimiter='', trim_whitespace=False, convert_case='none', conditional_concatenation=None):
    # Validate input parameters
    if not isinstance(strings, list) or len(strings) < 2:
        return {'error': 'At least two strings are required for concatenation.'}
    if not isinstance(delimiter, str):
        return {'error': 'Delimiter must be a string.'}
    if not isinstance(trim_whitespace, bool):
        return {'error': 'trim_whitespace must be a boolean.'}
    if convert_case not in ['none', 'lower', 'upper', 'capitalize']:
        return {'error': 'Invalid convert_case option.'}

    # Initialize result list
    result_strings = []

    # Process each string
    for s in strings:
        if s is None:
            continue

        # Apply conditional concatenation
        if conditional_concatenation:
            include_if = conditional_concatenation.get('include_if_contains')
            exclude_if = conditional_concatenation.get('exclude_if_contains')
            if include_if and include_if not in s:
                continue
            if exclude_if and exclude_if in s:
                continue

        # Trim whitespace if required
        if trim_whitespace:
            s = s.strip()

        # Convert case
        if convert_case == 'lower':
            s = s.lower()
        elif convert_case == 'upper':
            s = s.upper()
        elif convert_case == 'capitalize':
            s = s.capitalize()

        # Add processed string to result list
        result_strings.append(s)

    # Concatenate strings with delimiter
    concatenated_result = delimiter.join(result_strings)
    return concatenated_result

