def alphabetical_sorter(input: str, case_sensitive: bool = False, output_format: str = 'array', special_characters: str = 'include', sort_order: str = 'ascending', retain_duplicates: bool = True):
    # Validate output_format
    if output_format not in ['array', 'string', 'json']:
        return {'error': 'Invalid output_format. Choose from array, string, or json.'}

    # Validate special_characters
    if special_characters not in ['include', 'exclude']:
        return {'error': 'Invalid special_characters option. Choose from include or exclude.'}

    # Validate sort_order
    if sort_order not in ['ascending', 'descending']:
        return {'error': 'Invalid sort_order. Choose from ascending or descending.'}

    # Filter special characters if needed
    if special_characters == 'exclude':
        input = ''.join(filter(str.isalnum, input))

    # Sort the input string
    sorted_chars = sorted(input, key=lambda c: (c.lower(), c) if not case_sensitive else c, reverse=(sort_order == 'descending'))

    # Remove duplicates if needed
    if not retain_duplicates:
        sorted_chars = list(dict.fromkeys(sorted_chars))

    # Format the output
    if output_format == 'array':
        return sorted_chars
    elif output_format == 'string':
        return ''.join(sorted_chars)
    elif output_format == 'json':
        return {'sorted_characters': sorted_chars}

