from datetime import datetime, timedelta
import pytz


def date_calculator(input_date: str, operation: str, days: int = 0, weeks: int = 0, months: int = 0, years: int = 0, output_format: str = 'YYYY-MM-DD', time_zone: str = None, adjust_for_dst: bool = True) -> str:
    """
    Calculate a new date based on the input date and specified operations.
    """
    try:
        # Parse the input date
        if time_zone:
            tz = pytz.timezone(time_zone)
            input_dt = datetime.fromisoformat(input_date).astimezone(tz)
        else:
            input_dt = datetime.fromisoformat(input_date)

        # Adjust for DST if required
        if adjust_for_dst and time_zone:
            input_dt = tz.localize(input_dt, is_dst=None)

        # Perform the operation
        if operation == 'subtract':
            delta = timedelta(days=days + weeks * 7)
            new_date = input_dt - delta
        elif operation == 'add':
            delta = timedelta(days=days + weeks * 7)
            new_date = input_dt + delta
        else:
            raise ValueError("Unsupported operation. Use 'add' or 'subtract'.")

        # Format the output date
        if output_format == 'YYYY-MM-DD':
            return new_date.strftime('%Y-%m-%d')
        elif output_format == 'DD-MM-YYYY':
            return new_date.strftime('%d-%m-%Y')
        elif output_format == 'MM-DD-YYYY':
            return new_date.strftime('%m-%d-%Y')
        elif output_format == 'YYYY-MM-DDTHH:MM:SS':
            return new_date.isoformat()
        elif output_format == 'custom':
            # Custom format logic can be added here
            return new_date.strftime('%Y-%m-%d')
        else:
            raise ValueError("Unsupported output format.")
    except Exception as e:
        return f"Error: {str(e)}"

