def date_calculator(start_date: str, duration: dict, calendar_system: str = 'gregorian', output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Error handling for invalid date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Please use YYYY-MM-DD.'

    # Error handling for unsupported calendar systems
    if calendar_system not in ['gregorian', 'julian', 'islamic', 'hebrew']:
        return 'Error: Unsupported calendar system.'

    # Error handling for unsupported output formats
    if output_format not in ['YYYY-MM-DD', 'text', 'timestamp']:
        return 'Error: Unsupported output format.'

    # Error handling for unsupported time zones
    try:
        tz = pytz.timezone(time_zone)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Calculate the new date based on the duration
    if 'complex_duration' in duration:
        for part in duration['complex_duration']:
            if part['unit'] == 'days':
                start_date_obj += timedelta(days=part['value'])
            elif part['unit'] == 'weeks':
                start_date_obj += timedelta(weeks=part['value'])
            elif part['unit'] == 'months':
                start_date_obj += relativedelta(months=part['value'])
            elif part['unit'] == 'years':
                start_date_obj += relativedelta(years=part['value'])
    else:
        if duration['unit'] == 'days':
            start_date_obj += timedelta(days=duration['value'])
        elif duration['unit'] == 'weeks':
            start_date_obj += timedelta(weeks=duration['value'])
        elif duration['unit'] == 'months':
            start_date_obj += relativedelta(months=duration['value'])
        elif duration['unit'] == 'years':
            start_date_obj += relativedelta(years=duration['value'])

    # Convert the date to the specified time zone
    start_date_obj = start_date_obj.astimezone(tz)

    # Format the output
    if output_format == 'YYYY-MM-DD':
        return start_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'text':
        return start_date_obj.strftime('%A, %B %d, %Y')
    elif output_format == 'timestamp':
        return str(int(start_date_obj.timestamp()))

