def distinct_combinations(input: str, combination_length: int = 2, sort_combinations: bool = False, filter_criteria: dict = None, case_sensitive: bool = False, output_format: str = 'list'):
    import itertools
    import re

    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(combination_length, int) or combination_length <= 0:
        return {'error': 'Combination length must be a positive integer.'}
    if not isinstance(sort_combinations, bool):
        return {'error': 'Sort combinations must be a boolean.'}
    if filter_criteria and not isinstance(filter_criteria, dict):
        return {'error': 'Filter criteria must be a dictionary.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean.'}
    if output_format not in ['list', 'count', 'json', 'csv']:
        return {'error': 'Invalid output format.'}

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Generate combinations
    combinations = set(itertools.combinations(input, combination_length))

    # Apply filter criteria
    if filter_criteria:
        include = filter_criteria.get('include', [])
        exclude = filter_criteria.get('exclude', [])
        pattern = filter_criteria.get('pattern', '')

        if include:
            combinations = {combo for combo in combinations if all(char in combo for char in include)}
        if exclude:
            combinations = {combo for combo in combinations if not any(char in combo for char in exclude)}
        if pattern:
            regex = re.compile(pattern)
            combinations = {combo for combo in combinations if regex.match(''.join(combo))}

    # Sort combinations if required
    if sort_combinations:
        combinations = sorted(combinations)

    # Format output
    if output_format == 'list':
        return list(combinations)
    elif output_format == 'count':
        return len(combinations)
    elif output_format == 'json':
        return {'combinations': list(combinations)}
    elif output_format == 'csv':
        return ','.join(''.join(combo) for combo in combinations)

# Example usage based on the question
result = distinct_combinations(input='Saint-Cyr', combination_length=2, output_format='count')

