    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 10:
        return {'error': 'Input must be a list of 1 to 10 strings.'}
    if character_set not in ['alphabetic', 'alphanumeric', 'all']:
        return {'error': 'Invalid character set specified.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format specified.'}

    # Initialize a set to track unique characters
    unique_chars = set()

    # Define character filters based on parameters
    def is_valid_char(c):
        if character_set == 'alphabetic':
            return c.isalpha()
        elif character_set == 'alphanumeric':
            return c.isalnum()
        return True  # 'all' includes everything

    # Process each string in the input
    for string in input:
        for char in string:
            if not case_sensitive:
                char = char.lower()
            if is_valid_char(char):
                if (char.isalpha() or (include_numeric_characters and char.isdigit()) or
                        (include_special_characters and not char.isalnum())):
                    unique_chars.add(char)

    # Prepare the output based on the specified format
    if output_format == 'integer':
        return len(unique_chars)
    elif output_format == 'text':
        return f'There are {len(unique_chars)} unique characters.'
    elif output_format == 'detailed':
        return {'count': len(unique_chars), 'characters': list(unique_chars)}

    return {'error': 'Unexpected error occurred.'}

