def extract_last_name(full_name: str, name_format: str = 'first_last', delimiter: str = ' ', ignore_case: bool = True, handle_suffix: bool = False, handle_prefix: bool = False) -> str:
    """
    Extracts the last name from a full name string based on the specified parameters.

    :param full_name: The full name from which the last name will be extracted.
    :param name_format: The format of the name. Defaults to 'first_last'.
    :param delimiter: The character(s) used to separate names. Defaults to space.
    :param ignore_case: Whether to ignore case when processing the name. Defaults to true.
    :param handle_suffix: Whether to handle suffixes in the name. Defaults to false.
    :param handle_prefix: Whether to handle prefixes in the name. Defaults to false.
    :return: The extracted last name.
    """
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name:
        return "Error: 'full_name' must be a non-empty string."

    # Normalize case if ignore_case is True
    if ignore_case:
        full_name = full_name.lower()

    # Split the full name based on the delimiters
    delimiters = delimiter.split('|')
    for delim in delimiters:
        parts = full_name.split(delim)
        if len(parts) > 1:
            break

    # Handle different name formats
    if name_format == 'first_last':
        last_name = parts[-1]
    elif name_format == 'first_middle_last':
        last_name = parts[-1]
    elif name_format == 'last_first':
        last_name = parts[0]
    elif name_format == 'last_first_middle':
        last_name = parts[0]
    elif name_format == 'custom':
        # Custom logic can be implemented here
        last_name = parts[-1]
    else:
        return "Error: Invalid 'name_format' specified."

    # Handle suffixes and prefixes if specified
    if handle_suffix:
        suffixes = ['jr', 'sr', 'iii']
        last_name_parts = last_name.split()
        if last_name_parts[-1] in suffixes:
            last_name = ' '.join(last_name_parts[:-1])

    if handle_prefix:
        prefixes = ['dr', 'mr', 'ms']
        last_name_parts = last_name.split()
        if last_name_parts[0] in prefixes:
            last_name = ' '.join(last_name_parts[1:])

    return last_name.strip()

def enhanced_alphabetical_sorter(input, case_sensitive=False, ignore_non_alpha=False, reverse_order=False, include_characters='', exclude_characters='', numeric_handling='ignore'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Invalid input type, expected a string.'}
    if not isinstance(case_sensitive, bool) or not isinstance(ignore_non_alpha, bool) or not isinstance(reverse_order, bool):
        return {'error': 'Invalid parameter type, expected boolean for case_sensitive, ignore_non_alpha, and reverse_order.'}
    if numeric_handling not in ['ignore', 'sort_with_alpha', 'sort_separately']:
        return {'error': "Invalid numeric_handling value, expected 'ignore', 'sort_with_alpha', or 'sort_separately'."}

    # Filter characters based on include and exclude lists
    if include_characters:
        input = ''.join([ch for ch in input if ch in include_characters])
    if exclude_characters:
        input = ''.join([ch for ch in input if ch not in exclude_characters])

    # Handle non-alphabetic characters
    if ignore_non_alpha:
        input = ''.join(filter(str.isalpha, input))

    # Handle case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Sort characters
    sorted_chars = sorted(input, reverse=reverse_order)

    # Handle numeric characters
    if numeric_handling == 'sort_with_alpha':
        sorted_chars = sorted(input, reverse=reverse_order)
    elif numeric_handling == 'sort_separately':
        alpha_chars = ''.join(filter(str.isalpha, input))
        numeric_chars = ''.join(filter(str.isdigit, input))
        sorted_chars = sorted(alpha_chars, reverse=reverse_order) + sorted(numeric_chars, reverse=reverse_order)

    return ''.join(sorted_chars)

