def get_last_letter(name: str, output_format: str = 'character', ignore_non_alphabetic: bool = False, case_sensitive: bool = True):
    # Validate input
    if not isinstance(name, str) or not name:
        return {'error': 'Invalid input: name must be a non-empty string.'}
    if output_format not in ['character', 'ascii', 'alphabet_position', 'unicode']:
        return {'error': 'Invalid output_format: must be one of character, ascii, alphabet_position, unicode.'}

    # Process the string
    last_letter = None
    for char in reversed(name):
        if ignore_non_alphabetic and not char.isalpha():
            continue
        last_letter = char
        break

    if last_letter is None:
        return {'error': 'No valid alphabetic character found in the name.'}

    if not case_sensitive:
        last_letter = last_letter.lower()

    # Determine the output format
    if output_format == 'character':
        return last_letter
    elif output_format == 'ascii':
        return ord(last_letter)
    elif output_format == 'alphabet_position':
        return ord(last_letter.lower()) - ord('a') + 1
    elif output_format == 'unicode':
        return f'U+{ord(last_letter):04X}'

    return {'error': 'Unexpected error occurred.'}

