def char_to_binary(input: str, output_format: str = 'binary_string', encoding: str = 'ASCII', delimiter: str = '', pad_length: int = 8) -> str:
    # Error handling for input validation
    if not input:
        return 'Error: Input must be at least one character long.'
    if output_format not in ['binary_string', 'list_of_binaries', 'hexadecimal', 'octal']:
        return 'Error: Invalid output format.'
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16']:
        return 'Error: Invalid encoding type.'

    # Convert the input character to binary
    if encoding == 'ASCII':
        binary_value = format(ord(input[0]), 'b').zfill(pad_length)
    elif encoding == 'UTF-8':
        binary_value = ''.join(format(b, 'b').zfill(pad_length) for b in input[0].encode('utf-8'))
    elif encoding == 'UTF-16':
        binary_value = ''.join(format(b, 'b').zfill(pad_length) for b in input[0].encode('utf-16')[2:])

    # Format the output based on the specified output_format
    if output_format == 'binary_string':
        return binary_value
    elif output_format == 'list_of_binaries':
        return delimiter.join([binary_value])
    elif output_format == 'hexadecimal':
        return format(ord(input[0]), 'x')
    elif output_format == 'octal':
        return format(ord(input[0]), 'o')

    return binary_value

