    total_count = 0

    # Process each string in input
    for string in input:
        # Convert to lowercase if case-insensitive
        if not case_sensitive:
            string = string.lower()
            valid_chars = set(char.lower() for char in valid_chars)

        # Remove ignored characters
        for char in ignore_characters:
            string = string.replace(char, '')

        # Count valid characters
        count = 0
        for i, char in enumerate(string):
            if char in valid_chars:
                if 'first' in ignore_position and i == 0:
                    continue
                if 'last' in ignore_position and i == len(string) - 1:
                    continue
                if 'middle' in ignore_position and i != 0 and i != len(string) - 1:
                    continue
                count += 1

        total_count += count

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total count: {total_count}'
    elif output_format == 'detailed_report':
        return {'total_count': total_count, 'details': 'Detailed report not implemented.'}
    elif output_format == 'visual':
        return {'total_count': total_count, 'visual': 'Visual representation not implemented.'}
    else:
        return {'error': 'Invalid output format specified.'}

