def character_counter(input: str, characters: list, case_sensitive: bool = True, output_format: str = 'integer', range: dict = None, ignore_characters: list = None):
    # Validate input parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not all(isinstance(char, str) and len(char) == 1 for char in characters):
        return {'error': 'All characters must be single-character strings.'}
    if range:
        if not isinstance(range, dict) or 'start' not in range or 'end' not in range:
            return {'error': 'Range must be a dictionary with start and end keys.'}
        start, end = range['start'], range['end']
        if not (isinstance(start, int) and isinstance(end, int)):
            return {'error': 'Range start and end must be integers.'}
        input = input[start:end]
    if ignore_characters:
        if not all(isinstance(char, str) and len(char) == 1 for char in ignore_characters):
            return {'error': 'All ignore_characters must be single-character strings.'}
        input = ''.join(c for c in input if c not in ignore_characters)
    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        characters = [char.lower() for char in characters]
    # Count occurrences
    count_dict = {char: input.count(char) for char in characters}
    # Format output
    if output_format == 'integer':
        total_count = sum(count_dict.values())
        return total_count
    elif output_format == 'text':
        return f"Total count: {sum(count_dict.values())}"
    elif output_format == 'detailed':
        return count_dict
    else:
        return {'error': 'Invalid output format specified.'}

