def date_calculator(start_date: str, days: int = 0, weeks: int = 0, months: int = 0, years: int = 0, input_format: str = 'YYYY-MM-DD', timezone: str = 'UTC', output_format: str = 'YYYY-MM-DD') -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate input format
    if input_format not in ['YYYY-MM-DD', 'MM-DD-YYYY', 'DD-MM-YYYY']:
        raise ValueError('Invalid input format')
    if output_format not in ['YYYY-MM-DD', 'MM-DD-YYYY', 'DD-MM-YYYY']:
        raise ValueError('Invalid output format')

    # Parse the start date based on the input format
    try:
        if input_format == 'YYYY-MM-DD':
            date_obj = datetime.strptime(start_date, '%Y-%m-%d')
        elif input_format == 'MM-DD-YYYY':
            date_obj = datetime.strptime(start_date, '%m-%d-%Y')
        elif input_format == 'DD-MM-YYYY':
            date_obj = datetime.strptime(start_date, '%d-%m-%Y')
    except ValueError:
        raise ValueError('Invalid date format')

    # Adjust for timezone
    try:
        timezone_obj = pytz.timezone(timezone)
        date_obj = timezone_obj.localize(date_obj)
    except pytz.UnknownTimeZoneError:
        raise ValueError('Invalid timezone')

    # Perform date arithmetic
    date_obj += timedelta(days=days)
    date_obj += timedelta(weeks=weeks)
    date_obj += relativedelta(months=months)
    date_obj += relativedelta(years=years)

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        result_date = date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        result_date = date_obj.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        result_date = date_obj.strftime('%d-%m-%Y')

    return result_date

