def extract_name_components(names, ignore_prefixes=False, ignore_suffixes=False, extract_middle_name=False, output_format='array', name_order='first_middle_last'):
    # Validate input parameters
    if not isinstance(names, list) or len(names) < 1:
        return {'error': 'Invalid input: names must be a non-empty list of strings.'}
    if output_format not in ['array', 'string', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: array, string, detailed.'}
    if name_order not in ['first_middle_last', 'last_first_middle']:
        return {'error': 'Invalid name_order. Must be one of: first_middle_last, last_first_middle.'}

    # Helper function to process a single name
    def process_name(full_name):
        # Remove prefixes and suffixes if needed
        if ignore_prefixes:
            full_name = full_name.replace('Mr. ', '').replace('Ms. ', '')
        if ignore_suffixes:
            full_name = full_name.replace(' Jr.', '').replace(' Sr.', '')

        # Split the name into components
        name_parts = full_name.split()
        if name_order == 'last_first_middle':
            name_parts = name_parts[-1:] + name_parts[:-1]

        # Extract components based on the order
        first_name = name_parts[0] if name_parts else ''
        middle_name = name_parts[1] if len(name_parts) > 2 else ''
        last_name = name_parts[-1] if len(name_parts) > 1 else ''

        if not extract_middle_name:
            middle_name = ''

        return first_name, middle_name, last_name

    # Process each name in the list
    results = [process_name(name) for name in names]

    # Format the output based on the specified format
    if output_format == 'array':
        return [result[0] for result in results]
    elif output_format == 'string':
        return ' '.join([result[0] for result in results])
    elif output_format == 'detailed':
        return [{'first_name': result[0], 'middle_name': result[1], 'last_name': result[2]} for result in results]

    return {'error': 'Unexpected error occurred.'}

