def get_last_letter(input: str, case_sensitive: bool = True, error_handling: str = 'warn', trim_whitespace: bool = False, character_set: str = 'all', include_special_characters: bool = True) -> str:
    """
    Retrieves the last letter of a given string based on specified parameters.
    """
    # Error handling for empty input
    if not input:
        if error_handling == 'error':
            raise ValueError('Input string is empty.')
        elif error_handling == 'warn':
            print('Warning: Input string is empty.')
        return ''

    # Trim whitespace if specified
    if trim_whitespace:
        input = input.strip()

    # Determine valid character set
    def is_valid_char(c):
        if character_set == 'alphabetic':
            return c.isalpha()
        elif character_set == 'numeric':
            return c.isdigit()
        elif character_set == 'alphanumeric':
            return c.isalnum()
        return True  # 'all' includes all characters

    # Iterate from the end to find the last valid character
    for char in reversed(input):
        if is_valid_char(char) and (include_special_characters or char.isalnum()):
            return char if case_sensitive else char.lower()

    # If no valid character is found
    if error_handling == 'error':
        raise ValueError('No valid character found in input string.')
    elif error_handling == 'warn':
        print('Warning: No valid character found in input string.')
    return ''

