def date_calculator(start_date: str, interval: float, unit: str, operation: str, time_zone: str = 'UTC', calendar_system: str = 'gregorian') -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate input parameters
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%dT%H:%M:%SZ')
    except ValueError:
        return 'Error: Invalid date format. Please use ISO 8601 format (YYYY-MM-DDTHH:MM:SSZ).'

    if unit not in ['seconds', 'minutes', 'hours', 'days', 'weeks', 'months', 'years']:
        return 'Error: Unsupported time unit. Please use one of the following: seconds, minutes, hours, days, weeks, months, years.'

    if operation not in ['add', 'subtract']:
        return 'Error: Unsupported operation. Please use either "add" or "subtract".'

    # Convert interval to timedelta
    if unit == 'weeks':
        delta = timedelta(weeks=interval)
    elif unit == 'days':
        delta = timedelta(days=interval)
    elif unit == 'hours':
        delta = timedelta(hours=interval)
    elif unit == 'minutes':
        delta = timedelta(minutes=interval)
    elif unit == 'seconds':
        delta = timedelta(seconds=interval)
    else:
        return 'Error: Currently, only weeks, days, hours, minutes, and seconds are supported for interval calculations.'

    # Perform the operation
    if operation == 'subtract':
        result_date = start_date_obj - delta
    else:
        result_date = start_date_obj + delta

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        result_date = result_date.astimezone(tz)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone. Please provide a valid IANA time zone identifier.'

    # Return the result in ISO 8601 format
    return result_date.strftime('%Y-%m-%d')

