def extract_last_name(full_name, delimiter=' ', cultural_convention='western', include_middle_name=False, handle_suffixes=True, title_handling='ignore'):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}
    if cultural_convention not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid input: cultural_convention must be one of ["western", "eastern", "custom"].'}
    if not isinstance(include_middle_name, bool):
        return {'error': 'Invalid input: include_middle_name must be a boolean.'}
    if not isinstance(handle_suffixes, bool):
        return {'error': 'Invalid input: handle_suffixes must be a boolean.'}
    if title_handling not in ['ignore', 'include', 'separate']:
        return {'error': 'Invalid input: title_handling must be one of ["ignore", "include", "separate"].'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle title if necessary
    if title_handling == 'ignore':
        name_parts = [part for part in name_parts if part.lower() not in ['mr', 'mrs', 'ms', 'dr']]
    elif title_handling == 'separate':
        titles = [part for part in name_parts if part.lower() in ['mr', 'mrs', 'ms', 'dr']]
        name_parts = [part for part in name_parts if part.lower() not in ['mr', 'mrs', 'ms', 'dr']]

    # Determine last name based on cultural convention
    if cultural_convention == 'western':
        last_name = name_parts[-1] if name_parts else ''
    elif cultural_convention == 'eastern':
        last_name = name_parts[0] if name_parts else ''
    else:  # custom
        last_name = name_parts[-1] if name_parts else ''

    # Handle suffixes if necessary
    if handle_suffixes and last_name.lower() in ['jr', 'sr', 'iii']:
        last_name = name_parts[-2] if len(name_parts) > 1 else last_name

    # Include middle name if required
    if include_middle_name and len(name_parts) > 2:
        last_name = ' '.join(name_parts[1:]) if cultural_convention == 'western' else ' '.join(name_parts[:-1])

    return {'last_name': last_name}

