def date_calculator(start_date, weeks_to_adjust=0, days_to_adjust=0, months_to_adjust=0, years_to_adjust=0, business_days_only=False, output_format='date'):
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import calendar

    # Validate start_date format
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Calculate the new date
    try:
        # Adjust for years, months, and weeks
        adjusted_date = start_date_obj + relativedelta(years=years_to_adjust, months=months_to_adjust)
        adjusted_date += timedelta(weeks=weeks_to_adjust, days=days_to_adjust)

        # If business_days_only is True, adjust for business days
        if business_days_only:
            while adjusted_date.weekday() >= 5:  # 5 = Saturday, 6 = Sunday
                adjusted_date -= timedelta(days=1)

        # Format the output
        if output_format == 'date':
            return {'result': adjusted_date.strftime('%Y-%m-%d')}
        elif output_format == 'text':
            return {'result': adjusted_date.strftime('%A, %B %d, %Y')}
        elif output_format == 'timestamp':
            return {'result': int(adjusted_date.timestamp())}
        else:
            return {'error': 'Invalid output_format. Expected one of ["date", "text", "timestamp"].'}
    except Exception as e:
        return {'error': str(e)}

