def vowel_counter(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, vowels_to_count=['a', 'e', 'i', 'o', 'u']):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Invalid input type, expected a string.'}
    if not isinstance(ignore_characters, list) or not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid ignore_characters, expected a list of strings.'}
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position, expected a list with values "first" or "last".'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format, expected "integer", "text", or "detailed".'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive, expected a boolean.'}
    if not isinstance(vowels_to_count, list) or not all(v in ['a', 'e', 'i', 'o', 'u'] for v in vowels_to_count):
        return {'error': 'Invalid vowels_to_count, expected a list with vowels "a", "e", "i", "o", "u".'}

    # Prepare the input string
    if not case_sensitive:
        input = input.lower()
        vowels_to_count = [v.lower() for v in vowels_to_count]

    # Remove ignored characters
    input = ''.join([char for char in input if char not in ignore_characters])

    # Remove ignored positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]

    # Count vowels
    vowel_count = {v: 0 for v in vowels_to_count}
    for char in input:
        if char in vowels_to_count:
            vowel_count[char] += 1

    total_count = sum(vowel_count.values())

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'There are {total_count} vowels in the input.'
    elif output_format == 'detailed':
        return {'total': total_count, 'breakdown': vowel_count}

