    if not all(isinstance(v, str) and v in 'aeiou' for v in vowels):
        return {'error': 'Vowels must be a list of characters from [a, e, i, o, u].'}
    if not all(isinstance(c, str) and c in 'bcdfghjklmnpqrstvwxyz' for c in consonants):
        return {'error': 'Consonants must be a list of characters from [b, c, d, f, g, h, j, k, l, m, n, p, q, r, s, t, v, w, x, y, z].'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Output format must be one of [integer, text, detailed].'}

    # Normalize case if ignore_case is True
    if ignore_case:
        input = input.lower()
        vowels = [v.lower() for v in vowels]
        consonants = [c.lower() for c in consonants]

    # Count vowels and consonants
    vowel_count = sum(input.count(v) for v in vowels)
    consonant_count = sum(input.count(c) for c in consonants)

    # Prepare output based on format
    if output_format == 'integer':
        return vowel_count
    elif output_format == 'text':
        return f'There are {vowel_count} vowels.'
    elif output_format == 'detailed':
        details = {v: input.count(v) for v in vowels}
        if include_statistics:
            total_chars = len(input)
            vowel_percentage = (vowel_count / total_chars) * 100 if total_chars > 0 else 0
            consonant_percentage = (consonant_count / total_chars) * 100 if total_chars > 0 else 0
            return {
                'vowel_count': vowel_count,
                'consonant_count': consonant_count,
                'details': details,
                'vowel_percentage': vowel_percentage,
                'consonant_percentage': consonant_percentage
            }
        return {'vowel_count': vowel_count, 'consonant_count': consonant_count, 'details': details}

