def ascii_converter(characters, output_format='list', encoding='ascii', delimiter='', error_handling='strict'):
    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'string', 'json']:
        raise ValueError("Invalid 'output_format'. Must be 'list', 'string', or 'json'.")
    if encoding not in ['ascii', 'utf-8']:
        raise ValueError("Invalid 'encoding'. Must be 'ascii' or 'utf-8'.")
    if error_handling not in ['ignore', 'replace', 'strict']:
        raise ValueError("Invalid 'error_handling'. Must be 'ignore', 'replace', or 'strict'.")

    # Conversion logic
    ascii_codes = {}
    for char in characters:
        try:
            if encoding == 'ascii':
                ascii_code = ord(char)
            else:  # utf-8
                ascii_code = ord(char.encode('utf-8').decode('utf-8'))
            ascii_codes[char] = ascii_code
        except Exception as e:
            if error_handling == 'ignore':
                continue
            elif error_handling == 'replace':
                ascii_codes[char] = ord('?')  # Using '?' as a placeholder
            else:  # strict
                raise ValueError(f"Invalid character '{char}' encountered.")

    # Output formatting
    if output_format == 'list':
        return list(ascii_codes.values())
    elif output_format == 'string':
        return delimiter.join(str(code) for code in ascii_codes.values())
    elif output_format == 'json':
        return ascii_codes

