    titles = ['Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss']
    suffixes = ['Jr.', 'Sr.', 'III']

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Remove titles if ignore_titles is True
    if ignore_titles:
        name_parts = [part for part in name_parts if part not in titles]

    # Handle name order
    if name_order == 'eastern':
        # In eastern order, the last name is typically the first part
        last_name = name_parts[0]
    else:
        # In western order, the last name is typically the last part
        last_name = name_parts[-1]

        # Handle compound last names
        if handle_compound_names and len(name_parts) > 1:
            if name_parts[-2].lower() in ['de', 'la', 'van', 'von']:
                last_name = name_parts[-2] + delimiter + last_name

    # Include suffixes if include_suffixes is True
    if include_suffixes and len(name_parts) > 1:
        if name_parts[-1] in suffixes:
            last_name += delimiter + name_parts[-1]

    # Handle case sensitivity
    if not case_sensitive:
