    if multi_word_mode == 'first_word':
        words = name.split()
        target_word = words[0] if words else ''
    elif multi_word_mode == 'all_words':
        words = name.split()
        target_word = ''.join(words)
    elif multi_word_mode == 'custom':
        words = name.split(custom_delimiter)
