def ascii_lookup(characters, output_format='integer', filter_non_printable=False, extended_ascii=False):
    # Validate input parameters
    if not isinstance(characters, list) or not (1 <= len(characters) <= 100):
        return {'error': 'Invalid input: characters must be a list with 1 to 100 single-character strings.'}
    if output_format not in ['integer', 'text', 'hexadecimal', 'binary']:
        return {'error': 'Invalid input: output_format must be one of integer, text, hexadecimal, binary.'}
    if not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: each item in characters must be a single character string.'}

    # ASCII lookup logic
    ascii_codes = []
    for char in characters:
        ascii_code = ord(char)
        # Filter non-printable characters if required
        if filter_non_printable and not (32 <= ascii_code <= 126):
            continue
        # Check for extended ASCII
        if not extended_ascii and ascii_code > 127:
            continue
        # Convert ASCII code to the desired format
        if output_format == 'integer':
            ascii_codes.append(ascii_code)
        elif output_format == 'text':
            ascii_codes.append(chr(ascii_code))
        elif output_format == 'hexadecimal':
            ascii_codes.append(hex(ascii_code))
        elif output_format == 'binary':
            ascii_codes.append(bin(ascii_code))

    return {'ascii_codes': ascii_codes}

