    elif character_set == 'numeric':
        input = ''.join(filter(str.isdigit, input))

    # Handle special characters if required
    if not handle_special_characters:
        input = ''.join(filter(str.isalnum, input))

    # Extract the last letter
    if not input:
        return 'Error: No valid characters found for extraction.'
