    :param characters: List of single-character strings to convert.
    :param output_format: Format of the output ('list', 'string', 'json', 'csv').
    :param encoding: Character encoding to use ('ascii', 'utf-8', 'latin-1').
    :param error_handling: Error handling strategy ('ignore', 'strict', 'replace').
    :return: ASCII codes in the specified format.
    """
    import json

    # Validate characters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: characters must be a list of single-character strings.'}

    # Validate output_format
    if output_format not in ['list', 'string', 'json', 'csv']:
        return {'error': 'Invalid output_format: must be one of list, string, json, csv.'}

    # Validate encoding
    if encoding not in ['ascii', 'utf-8', 'latin-1']:
        return {'error': 'Invalid encoding: must be one of ascii, utf-8, latin-1.'}

    # Validate error_handling
    if error_handling not in ['ignore', 'strict', 'replace']:
        return {'error': 'Invalid error_handling: must be one of ignore, strict, replace.'}

    ascii_codes = []
    for char in characters:
        try:
            ascii_code = ord(char)
            ascii_codes.append(ascii_code)
        except Exception as e:
            if error_handling == 'strict':
                return {'error': str(e)}
            elif error_handling == 'replace':
                ascii_codes.append(ord('?'))  # Use '?' as a placeholder

    # Format the output
    if output_format == 'list':
        return ascii_codes
    elif output_format == 'string':
        return ''.join(map(str, ascii_codes))
    elif output_format == 'json':
        return json.dumps({'ascii_codes': ascii_codes})
    elif output_format == 'csv':
        return ','.join(map(str, ascii_codes))

