    # Validate vowels
    if not all(isinstance(v, str) and len(v) == 1 for v in vowels):
        return {'error': 'vowels must be a list of single-character strings'}

    # Validate ignore_special_characters
    if not isinstance(ignore_special_characters, bool):
        return {'error': 'ignore_special_characters must be a boolean'}

    # Validate case_sensitive
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}

    # Validate count_statistics
    if not isinstance(count_statistics, bool):
        return {'error': 'count_statistics must be a boolean'}

    # Validate language_support
    if not isinstance(language_support, str):
        return {'error': 'language_support must be a string'}

    # Validate batch_processing
    if batch_processing is not None and not all(isinstance(s, str) for s in batch_processing):
        return {'error': 'batch_processing must be a list of strings'}

    # Prepare the input string
    if ignore_special_characters:
        input_string = ''.join(c for c in input_string if c.isalnum() or c.isspace())

    # Adjust for case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        vowels = [v.lower() for v in vowels]

    # Count vowels
    vowel_count = 0
    vowel_stats = {}
    for char in input_string:
        if char in vowels:
            vowel_count += 1
            if count_statistics:
                if char in vowel_stats:
                    vowel_stats[char] += 1
                else:
                    vowel_stats[char] = 1

