def char_to_binary(character, encoding='ASCII', bit_length=8, output_format='string', padding=True):
    # Validate input
    if not isinstance(character, str) or len(character) != 1:
        raise ValueError("'character' must be a single character string.")
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16', 'ISO-8859-1', 'UTF-32']:
        raise ValueError("Unsupported encoding. Choose from 'ASCII', 'UTF-8', 'UTF-16', 'ISO-8859-1', 'UTF-32'.")
    if not isinstance(bit_length, int) or bit_length <= 0:
        raise ValueError("'bit_length' must be a positive integer.")
    if output_format not in ['string', 'array', 'hex', 'base64']:
        raise ValueError("Unsupported output format. Choose from 'string', 'array', 'hex', 'base64'.")

    # Convert character to binary
    binary_representation = format(ord(character), 'b')

    # Apply padding if required
    if padding:
        binary_representation = binary_representation.zfill(bit_length)

    # Format output
    if output_format == 'array':
        return list(binary_representation)
    elif output_format == 'hex':
        return hex(int(binary_representation, 2))
    elif output_format == 'base64':
        import base64
        byte_array = int(binary_representation, 2).to_bytes((len(binary_representation) + 7) // 8, byteorder='big')
        return base64.b64encode(byte_array).decode('utf-8')
    else:  # default to 'string'
        return binary_representation

