def character_extractor_v2(input: str, position: str = 'last', custom_index: int = None, range_start: int = None, range_end: int = None, output_format: str = 'character', multiple: bool = False):
    # Validate input parameters
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}
    if position not in ['first', 'last', 'custom', 'range']:
        return {'error': 'Invalid position value. Must be one of: first, last, custom, range.'}
    if output_format not in ['character', 'ascii', 'unicode', 'hex']:
        return {'error': 'Invalid output format. Must be one of: character, ascii, unicode, hex.'}

    # Extract character(s) based on position
    try:
        if position == 'last':
            result = input[-1]
        elif position == 'first':
            result = input[0]
        elif position == 'custom':
            if custom_index is None:
                return {'error': 'custom_index must be provided for custom position.'}
            result = input[custom_index]
        elif position == 'range':
            if range_start is None or range_end is None:
                return {'error': 'range_start and range_end must be provided for range position.'}
            result = input[range_start:range_end]

        # Format the output
        if output_format == 'ascii':
            result = [ord(char) for char in result]
        elif output_format == 'unicode':
            result = [f'U+{ord(char):04X}' for char in result]
        elif output_format == 'hex':
            result = [f'{ord(char):02x}' for char in result]

        # Handle multiple extraction
        if not multiple and isinstance(result, list):
            result = result[0]

        return {'result': result}
    except IndexError:
        return {'error': 'Index out of range.'}
    except Exception as e:
        return {'error': str(e)}

