def prime_factorizer(number, show_steps=False, output_format='list', max_factor=None, include_multiplicity=False):
    """
    Computes the prime factors of a given integer with options for detailed output.

    :param number: The integer to be factorized.
    :param show_steps: Whether to display the steps of the factorization process.
    :param output_format: The format of the output ('list', 'text', 'json').
    :param max_factor: The maximum prime factor to consider.
    :param include_multiplicity: Whether to include the multiplicity of each prime factor.
    :return: Prime factors in the specified format.
    """
    import math

    if not isinstance(number, int):
        return {'error': 'Invalid input: number must be an integer.'}
    if output_format not in ['list', 'text', 'json']:
        return {'error': 'Invalid output format. Choose from list, text, or json.'}

    def factorize(n):
        factors = {}
        abs_n = abs(n)
        for i in range(2, int(math.sqrt(abs_n)) + 1):
            while abs_n % i == 0:
                if max_factor and i > max_factor:
                    break
                if i in factors:
                    factors[i] += 1
                else:
                    factors[i] = 1
                abs_n //= i
        if abs_n > 1:
            if not max_factor or abs_n <= max_factor:
                factors[abs_n] = 1
        return factors

    factors = factorize(number)

    if include_multiplicity:
        result = factors
    else:
        result = list(factors.keys())

    if output_format == 'list':
        return result
    elif output_format == 'text':
        return ', '.join(str(f) for f in result)
    elif output_format == 'json':
        return {'factors': result}

    return result

