def sum_calculator(numbers, output_format='float', weights=None, condition=None, parallel_processing=False):
    """
    Perform summation of numerical arrays with optional weighted and conditional summation.

    :param numbers: List of numbers to be summed.
    :param output_format: Format of the output ('integer', 'float', 'scientific', 'currency').
    :param weights: Optional list of weights for weighted summation.
    :param condition: Optional condition for conditional summation.
    :param parallel_processing: Flag to enable parallel processing.
    :return: The sum in the specified format.
    """
    # Error handling for non-numeric inputs
    if not all(isinstance(num, (int, float)) for num in numbers):
        raise ValueError("All elements in 'numbers' must be integers or floats.")

    # Error handling for weights
    if weights is not None:
        if len(weights) != len(numbers):
            raise ValueError("'weights' must be the same length as 'numbers'.")

    # Apply condition if provided
    if condition is not None:
        operator = condition.get('operator')
        value = condition.get('value')
        if operator == 'greater_than':
            numbers = [num for num in numbers if num > value]
        elif operator == 'less_than':
            numbers = [num for num in numbers if num < value]
        elif operator == 'equal_to':
            numbers = [num for num in numbers if num == value]

    # Calculate sum
    if weights is not None:
        total = sum(num * weight for num, weight in zip(numbers, weights))
    else:
        total = sum(numbers)

    # Format output
    if output_format == 'integer':
        return int(total)
    elif output_format == 'scientific':
        return f"{total:.2e}"
    elif output_format == 'currency':
        return f"${total:,.2f}"
    else:  # Default to float
        return float(total)

