def vowel_counter_plus(input: str, vowel_set: list = ['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U', 'á', 'é', 'í', 'ó', 'ú', 'Á', 'É', 'Í', 'Ó', 'Ú'], case_sensitive: bool = False, output_format: str = 'integer', language_support: str = 'auto', ignore_whitespace: bool = True):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Invalid input type, expected a string.'}
    if not isinstance(vowel_set, list) or not all(isinstance(v, str) for v in vowel_set):
        return {'error': 'Invalid vowel_set, expected a list of strings.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format, expected one of ["integer", "text", "detailed"].'}
    if language_support not in ['auto', 'english', 'spanish', 'french', 'custom']:
        return {'error': 'Invalid language_support, expected one of ["auto", "english", "spanish", "french", "custom"].'}

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        vowel_set = [v.lower() for v in vowel_set]

    # Count vowels
    vowel_count = {}
    for char in input:
        if ignore_whitespace and char.isspace():
            continue
        if char in vowel_set:
            if char in vowel_count:
                vowel_count[char] += 1
            else:
                vowel_count[char] = 1

    # Prepare output
    if output_format == 'integer':
        return sum(vowel_count.values())
    elif output_format == 'text':
        return f"Total vowels: {sum(vowel_count.values())}"
    elif output_format == 'detailed':
        return vowel_count

