def calculate_difference(numbers, output_format='float', precision=2, numerical_system='decimal'):
    # Validate input parameters
    if not isinstance(numbers, list) or len(numbers) < 2:
        return {'error': 'Invalid input: numbers must be a list with at least two elements.'}
    if output_format not in ['integer', 'float', 'text', 'percentage', 'scientific']:
        return {'error': 'Invalid output_format: must be one of integer, float, text, percentage, scientific.'}
    if not isinstance(precision, int) or precision < 0:
        return {'error': 'Invalid precision: must be a non-negative integer.'}
    if numerical_system not in ['decimal', 'binary', 'hexadecimal']:
        return {'error': 'Invalid numerical_system: must be one of decimal, binary, hexadecimal.'}

    # Calculate the difference
    difference = numbers[0]
    for num in numbers[1:]:
        difference -= num

    # Format the result based on output_format
    if output_format == 'integer':
        result = int(difference)
    elif output_format == 'float':
        result = round(difference, precision)
    elif output_format == 'text':
        result = str(difference)
    elif output_format == 'percentage':
        result = f'{difference * 100:.{precision}f}%'
    elif output_format == 'scientific':
        result = f'{difference:.{precision}e}'

    # Convert result to the specified numerical system
    if numerical_system == 'binary':
        result = bin(int(result))
    elif numerical_system == 'hexadecimal':
        result = hex(int(result))

    return {'result': result}

