def digit_extractor(number, position, length=1, handle_negative=False, direction='left-to-right', handle_decimal=False):
    # Convert the number to a string for easy manipulation
    num_str = str(number)

    # Handle negative numbers if required
    if not handle_negative and num_str[0] == '-':
        num_str = num_str[1:]

    # Handle decimal numbers if required
    if not handle_decimal and '.' in num_str:
        num_str = num_str.replace('.', '')

    # Determine the direction of extraction
    if direction == 'right-to-left':
        num_str = num_str[::-1]

    # Validate position and length
    if position < 1 or position > len(num_str):
        return {'error': 'Position out of range'}
    if length < 1:
        return {'error': 'Invalid length'}

    # Extract the digits
    start_index = position - 1
    end_index = start_index + length
    extracted_digits = num_str[start_index:end_index]

    # Return the extracted digits
    return {'extracted_digits': extracted_digits}

