def digit_extractor(number, position, length=1, direction='left-to-right', output_format='integer'):
    # Convert the number to a string to facilitate digit extraction
    num_str = str(number)
    num_length = len(num_str)

    # Validate the position
    if position < 1 or position > num_length:
        if output_format == 'error':
            return 'Position out of bounds.'
        else:
            return None

    # Adjust position for 0-based index
    start_index = position - 1

    # Extract digits based on direction
    if direction == 'left-to-right':
        extracted = num_str[start_index:start_index + length]
    elif direction == 'right-to-left':
        extracted = num_str[::-1][start_index:start_index + length]
    else:
        return 'Invalid direction specified.'

    # Format the output
    if output_format == 'integer':
        return int(extracted)
    elif output_format == 'text':
        return extracted
    elif output_format == 'json':
        return {'extracted': extracted}
    elif output_format == 'list':
        return list(extracted)
    elif output_format == 'error':
        return 'Invalid output format specified.'
    else:
        return 'Unsupported output format.'

