    if not isinstance(numbers, list) or len(numbers) < 2:
        return {'error': 'Invalid input: At least two numbers are required.'}
    if not all(isinstance(num, (int, float)) for num in numbers):
        return {'error': 'Invalid input: All items in numbers must be of type int or float.'}
    if output_format not in ['string', 'array']:
        return {'error': 'Invalid output_format: Must be either "string" or "array".'}
    if number_format not in ['decimal', 'scientific', 'fixed']:
        return {'error': 'Invalid number_format: Must be "decimal", "scientific", or "fixed".'}

    # Format numbers
    formatted_numbers = []
    for num in numbers:
        if number_format == 'decimal':
            formatted_numbers.append(str(num))
        elif number_format == 'scientific':
            formatted_numbers.append(f'{num:e}')
        elif number_format == 'fixed':
