def extract_first_digit(number: str, ignore_sign: bool = True, strip_leading_zeros: bool = True, first_non_zero: bool = False, error_handling: str = 'warn') -> str:
    """
    Extracts the first digit from the given number string based on specified parameters.

    :param number: The number from which to extract the first digit, provided as a string.
    :param ignore_sign: Whether to ignore the sign of the number.
    :param strip_leading_zeros: Whether to strip leading zeros before extracting the first digit.
    :param first_non_zero: Whether to extract the first non-zero digit.
    :param error_handling: Defines the behavior when encountering invalid inputs.
    :return: The first digit as a string.
    """
    try:
        # Handle sign ignoring
        if ignore_sign and number.startswith('-'):
            number = number[1:]

        # Strip leading zeros if required
        if strip_leading_zeros:
            number = number.lstrip('0')

        # Extract first non-zero digit if required
        if first_non_zero:
            for char in number:
                if char.isdigit() and char != '0':
                    return char
            return '0'  # Return '0' if no non-zero digit is found

        # Default behavior: return the first digit
        for char in number:
            if char.isdigit():
                return char

        # If no digit is found, handle based on error_handling
        if error_handling == 'warn':
            return 'Warning: No digit found'
        elif error_handling == 'error':
            raise ValueError('No digit found in the input')
        else:  # 'ignore'
            return ''

    except Exception as e:
        if error_handling == 'error':
            raise e
        elif error_handling == 'warn':
            return f'Warning: {str(e)}'
        else:  # 'ignore'
            return ''

