def concatenate_values(inputs, separator='', output_format='string', null_handling='ignore', replacement_value=''):
    # Validate inputs
    if not isinstance(inputs, list) or len(inputs) < 2:
        return {'error': 'Invalid input: At least two items are required in the inputs list.'}

    # Handle null values based on null_handling parameter
    processed_inputs = []
    for item in inputs:
        if item is None:
            if null_handling == 'include':
                processed_inputs.append('null')
            elif null_handling == 'replace':
                processed_inputs.append(replacement_value)
            # If 'ignore', simply skip adding the item
        else:
            processed_inputs.append(str(item))

    # Concatenate values with the specified separator
    concatenated_result = separator.join(processed_inputs)

    # Format output based on output_format parameter
    if output_format == 'string':
        return concatenated_result
    elif output_format == 'array':
        return processed_inputs
    elif output_format == 'json':
        import json
        return json.dumps(processed_inputs)
    else:
        return {'error': 'Invalid output format specified.'}

