def closest_palindrome_year(year, direction='both', output_format='integer', year_range=None, preference='smallest_difference'):
    # Helper function to check if a year is a palindrome
    def is_palindrome(y):
        return str(y) == str(y)[::-1]

    # Validate input parameters
    if not isinstance(year, int):
        return {'error': 'Invalid year: must be an integer.'}
    if direction not in ['both', 'past', 'future']:
        return {'error': 'Invalid direction: must be one of both, past, future.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, detailed.'}
    if year_range:
        if not isinstance(year_range, dict) or 'start' not in year_range or 'end' not in year_range:
            return {'error': 'Invalid year_range: must be a dictionary with start and end keys.'}
        if not isinstance(year_range['start'], int) or not isinstance(year_range['end'], int):
            return {'error': 'Invalid year_range values: start and end must be integers.'}

    # Initialize variables
    closest_year = None
    smallest_diff = float('inf')

    # Determine search range
    start_year = year_range['start'] if year_range else year - 1000
    end_year = year_range['end'] if year_range else year + 1000

    # Search for the closest palindrome year
    for y in range(start_year, end_year + 1):
        if is_palindrome(y):
            diff = abs(year - y)
            if direction == 'past' and y >= year:
                continue
            if direction == 'future' and y <= year:
                continue
            if diff < smallest_diff:
                smallest_diff = diff
                closest_year = y
            elif diff == smallest_diff:
                if preference == 'earliest_future' and y > closest_year:
                    closest_year = y

    # Prepare output
    if output_format == 'integer':
        return closest_year
    elif output_format == 'text':
        return f'The closest palindrome year to {year} is {closest_year}.'
    elif output_format == 'detailed':
        return {
            'closest_year': closest_year,
            'difference': smallest_diff,
            'input_year': year
        }

