def closest_palindrome_finder(year, direction='both', output_format='integer', search_range=None, return_multiple=False):
    """
    Find the closest palindrome number to a given year.

    Parameters:
    - year (int): The year for which the closest palindrome number is to be found.
    - direction (str): The direction in which to search for the palindrome ('both', 'before', 'after').
    - output_format (str): The format of the output ('integer', 'text').
    - search_range (int): The range (in years) within which to search for palindromes.
    - return_multiple (bool): Whether to return multiple palindromes if they are equidistant.

    Returns:
    - int or str: The closest palindrome year in the specified format.
    """
    def is_palindrome(num):
        return str(num) == str(num)[::-1]

    if not isinstance(year, int):
        raise ValueError("Year must be an integer.")
    if direction not in ['both', 'before', 'after']:
        raise ValueError("Direction must be 'both', 'before', or 'after'.")
    if output_format not in ['integer', 'text']:
        raise ValueError("Output format must be 'integer' or 'text'.")

    closest_palindrome = None
    min_distance = float('inf')
    palindromes = []

    # Search for palindromes
    for i in range(search_range if search_range is not None else 10000):
        if direction in ['both', 'before']:
            if is_palindrome(year - i):
                palindromes.append(year - i)
                if i < min_distance:
                    closest_palindrome = year - i
                    min_distance = i
        if direction in ['both', 'after']:
            if is_palindrome(year + i):
                palindromes.append(year + i)
                if i < min_distance:
                    closest_palindrome = year + i
                    min_distance = i

    if return_multiple:
        equidistant_palindromes = [p for p in palindromes if abs(p - year) == min_distance]
        if output_format == 'text':
            return ', '.join(map(str, equidistant_palindromes))
        return equidistant_palindromes

    if output_format == 'text':
        return str(closest_palindrome)
    return closest_palindrome

