def vowel_counter(input: str, vowels_to_count=['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'], case_sensitive=False, count_individual_vowels=False, ignore_non_alphabetic=True, custom_vowel_set=[]):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Determine the set of vowels to count
    if custom_vowel_set:
        vowels = set(custom_vowel_set)
    else:
        vowels = set(vowels_to_count)

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        vowels = set(v.lower() for v in vowels)

    # Initialize vowel counts
    if count_individual_vowels:
        vowel_counts = {v: 0 for v in vowels}
    else:
        total_vowels = 0

    # Count vowels
    for char in input:
        if ignore_non_alphabetic and not char.isalpha():
            continue
        if char in vowels:
            if count_individual_vowels:
                vowel_counts[char] += 1
            else:
                total_vowels += 1

    # Return results
    if count_individual_vowels:
        return vowel_counts
    else:
        return {'total_vowels': total_vowels}

