def advanced_consonant_counter(input, consonant_set=None, case_sensitive=False, output_detail='summary', performance_mode='speed'):
    # Default consonant set if none is provided
    if consonant_set is None:
        consonant_set = ['b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z']

    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 100:
        return {'error': 'Input must be a list of 1 to 100 strings.'}
    if not all(isinstance(item, str) for item in input):
        return {'error': 'All items in the input list must be strings.'}
    if output_detail not in ['summary', 'detailed']:
        return {'error': "Output detail must be 'summary' or 'detailed'."}
    if performance_mode not in ['speed', 'accuracy']:
        return {'error': "Performance mode must be 'speed' or 'accuracy'."}

    # Prepare consonant set based on case sensitivity
    if not case_sensitive:
        consonant_set = [c.lower() for c in consonant_set]

    # Function to count consonants in a single string
    def count_consonants(s):
        if not case_sensitive:
            s = s.lower()
        return sum(1 for char in s if char in consonant_set)

