def date_calculator(start_date: str, years_to_add: int = 0, months_to_add: int = 0, days_to_add: int = 0, output_format: str = 'YYYY-MM-DD', include_time: bool = False, time_zone: str = 'UTC') -> str:
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: start_date must be in YYYY-MM-DD format.'

    # Apply date arithmetic
    try:
        date_obj += relativedelta(years=years_to_add, months=months_to_add, days=days_to_add)
    except Exception as e:
        return f'Error: {str(e)}'

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        result_date = date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        result_date = date_obj.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        result_date = date_obj.strftime('%d-%m-%Y')
    elif output_format == 'timestamp':
        result_date = str(int(date_obj.timestamp()))
    elif output_format == 'ISO 8601':
        result_date = date_obj.isoformat()
    else:
        return 'Error: Invalid output_format specified.'

    return result_date

