def extract_first_name(full_name, ignore_titles=False, ignore_suffixes=False, case_sensitive=False, handle_special_characters=True, cultural_convention='Western'):
    # Error handling for incorrect input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(ignore_titles, bool) or not isinstance(ignore_suffixes, bool) or not isinstance(case_sensitive, bool) or not isinstance(handle_special_characters, bool):
        return {'error': 'Invalid input: Boolean parameters must be of type bool.'}
    if not isinstance(cultural_convention, str):
        return {'error': 'Invalid input: cultural_convention must be a string.'}

    # Define common titles and suffixes
    titles = ['Mr.', 'Mrs.', 'Dr.', 'Ms.'] if ignore_titles else []
    suffixes = ['Jr.', 'Sr.', 'III'] if ignore_suffixes else []

    # Split the full name into components
    name_parts = full_name.split()

    # Remove titles and suffixes if specified
    if ignore_titles:
        name_parts = [part for part in name_parts if part not in titles]
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Handle special characters if specified
    if handle_special_characters:
        name_parts = [part.replace('-', '').replace("'", '') for part in name_parts]

    # Extract the first name based on cultural convention
    first_name = ''
    if cultural_convention == 'Western':
        first_name = name_parts[0] if name_parts else ''
    elif cultural_convention == 'Eastern':
        first_name = name_parts[-1] if name_parts else ''
    else:
        return {'error': 'Unsupported cultural convention specified.'}

    # Apply case sensitivity if specified
    if not case_sensitive:
        first_name = first_name.capitalize()

    return {'first_name': first_name}

