def string_length_counter(input, ignore_characters=[], ignore_position=[], case_sensitive=False, character_type='all', output_format='integer'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate ignore_characters
    if not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'All ignore_characters must be strings.'}

    # Validate ignore_position
    valid_positions = {'first', 'last', 'even', 'odd'}
    if not all(pos in valid_positions for pos in ignore_position):
        return {'error': 'Invalid ignore_position value.'}

    # Validate character_type
    valid_character_types = {'all', 'vowels', 'consonants', 'digits', 'special'}
    if character_type not in valid_character_types:
        return {'error': 'Invalid character_type value.'}

    # Validate output_format
    valid_output_formats = {'integer', 'text', 'json'}
    if output_format not in valid_output_formats:
        return {'error': 'Invalid output_format value.'}

    # Prepare the string for counting
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Filter the string based on ignore_characters
    filtered_string = ''.join(char for char in input if char not in ignore_characters)

    # Filter based on ignore_position
    if 'first' in ignore_position:
        filtered_string = filtered_string[1:]
    if 'last' in ignore_position:
        filtered_string = filtered_string[:-1]
    if 'even' in ignore_position:
        filtered_string = ''.join(char for i, char in enumerate(filtered_string) if i % 2 != 0)
    if 'odd' in ignore_position:
        filtered_string = ''.join(char for i, char in enumerate(filtered_string) if i % 2 == 0)

    # Filter based on character_type
    if character_type == 'vowels':
