def count_total_letters(input, ignore_characters=None, ignore_position=None, case_sensitive=False, output_format='integer'):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 10:
        return {'error': 'Input must be a list of 1 to 10 strings.'}
    if ignore_characters is not None and not isinstance(ignore_characters, list):
        return {'error': 'ignore_characters must be a list of strings.'}
    if ignore_position is not None and not isinstance(ignore_position, list):
        return {'error': 'ignore_position must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'output_format must be one of integer, text, or detailed.'}

    # Initialize total count
    total_count = 0
    detailed_counts = []

    # Define helper function to check if a position should be ignored
    def should_ignore_position(index, length):
        if ignore_position is None:
            return False
        if 'first' in ignore_position and index == 0:
            return True
        if 'last' in ignore_position and index == length - 1:
            return True
        if 'even' in ignore_position and index % 2 == 0:
            return True
        if 'odd' in ignore_position and index % 2 != 0:
            return True
        return False

    # Process each string
    for string in input:
        count = 0
        for i, char in enumerate(string):
            if ignore_characters and char in ignore_characters:
                continue
            if should_ignore_position(i, len(string)):
                continue
            if not case_sensitive:
                char = char.lower()
            if char.isalpha():
                count += 1
        total_count += count
        detailed_counts.append({'string': string, 'count': count})

    # Format output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total letters counted: {total_count}'
    elif output_format == 'detailed':
        return {'total_count': total_count, 'details': detailed_counts}

