def date_difference_calculator(start_date: str, end_date: str, calendar_system: str = 'Gregorian', output_format: str = 'integer', time_zone: str = 'UTC') -> dict:
    from datetime import datetime
    from dateutil import tz
    import calendar

    # Validate calendar system
    if calendar_system not in ['Gregorian', 'Julian', 'Hebrew', 'Islamic']:
        return {'error': 'Unsupported calendar system'}

    # Validate output format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Unsupported output format'}

    # Parse dates
    try:
        start_dt = datetime.strptime(start_date, '%Y-%m-%d')
        end_dt = datetime.strptime(end_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format, should be YYYY-MM-DD'}

    # Convert to specified time zone
    try:
        from_zone = tz.gettz('UTC')
        to_zone = tz.gettz(time_zone)
        start_dt = start_dt.replace(tzinfo=from_zone).astimezone(to_zone)
        end_dt = end_dt.replace(tzinfo=from_zone).astimezone(to_zone)
    except Exception as e:
        return {'error': f'Time zone conversion error: {str(e)}'}

    # Calculate difference in days
    delta_days = (end_dt - start_dt).days

    # Handle different output formats
    if output_format == 'integer':
        return {'days': delta_days}
    elif output_format == 'text':
        return {'days': f'The number of days between {start_date} and {end_date} is {delta_days} days.'}
    elif output_format == 'detailed':
        years, remainder = divmod(delta_days, 365)
        months, days = divmod(remainder, 30)
        return {'years': years, 'months': months, 'days': days}

    return {'error': 'Unexpected error'}

