def date_calculator(start_date: str, interval: int, unit: str = 'days', output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC') -> str:
    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate unit
    if unit not in ['days', 'weeks', 'months', 'hours', 'minutes']:
        return 'Error: Unsupported time unit.'

    # Validate output_format
    if output_format not in ['YYYY-MM-DD', 'MM/DD/YYYY', 'DD-MM-YYYY']:
        return 'Error: Unsupported output format.'

    # Parse the start_date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start date format. Use YYYY-MM-DD.'

    # Apply time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return 'Error: Unknown time zone.'

    # Calculate the new date
    if unit == 'days':
        new_date_obj = start_date_obj + timedelta(days=interval)
    elif unit == 'weeks':
        new_date_obj = start_date_obj + timedelta(weeks=interval)
    elif unit == 'months':
        new_date_obj = start_date_obj + relativedelta(months=interval)
    elif unit == 'hours':
        new_date_obj = start_date_obj + timedelta(hours=interval)
    elif unit == 'minutes':
        new_date_obj = start_date_obj + timedelta(minutes=interval)

    # Format the new date
    if output_format == 'YYYY-MM-DD':
        formatted_date = new_date_obj.strftime('%Y-%m-%d')
    elif output_format == 'MM/DD/YYYY':
        formatted_date = new_date_obj.strftime('%m/%d/%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = new_date_obj.strftime('%d-%m-%Y')

    return formatted_date

# Example usage based on the question
result = date_calculator('2014-03-09', 10, 'weeks')
print(result)  # Output: '2014-05-18'

def extract_first_name(names, delimiter=' ', case_sensitive=True, prefix_handling=False, suffix_handling=False, output_format='plain', special_character_handling=True):
    # Validate input
    if not isinstance(names, list) or not all(isinstance(name, str) for name in names):
        return {'error': 'Invalid input: names must be a list of strings.'}
    if not names:
        return {'error': 'Invalid input: names list cannot be empty.'}

    # Define prefixes and suffixes
    prefixes = ['Mr.', 'Mrs.', 'Dr.', 'Ms.'] if prefix_handling else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if suffix_handling else []

    # Function to extract first name
    def get_first_name(full_name):
        # Split the name by the delimiter
        parts = full_name.split(delimiter)

        # Remove prefixes
        if prefix_handling and parts[0] in prefixes:
            parts.pop(0)

        # Remove suffixes
        if suffix_handling and parts[-1] in suffixes:
            parts.pop()

        # Return the first part as the first name
        first_name = parts[0]

        # Handle case sensitivity
        if not case_sensitive:
            first_name = first_name.lower()

        return first_name

    # Process each name in the list
    extracted_names = [get_first_name(name) for name in names]

    # Return result in the specified format
    if output_format == 'json':
        return {'first_names': extracted_names}
    else:
        return ', '.join(extracted_names)

