def extract_last_character(input, output_format='character', empty_string_behavior='ignore', character_encoding='UTF-8', trim_whitespace=False, ignore_characters=[]):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        raise ValueError('Input must be an array of strings.')
    if len(input) < 1:
        raise ValueError('Input array must contain at least one string.')

    # Process each string in the input array
    results = []
    for string in input:
        # Handle empty strings
        if string == '':
            if empty_string_behavior == 'error':
                raise ValueError('Empty string encountered.')
            elif empty_string_behavior == 'return_empty':
                results.append('')
                continue
            elif empty_string_behavior == 'ignore':
                continue

        # Trim whitespace if required
        if trim_whitespace:
            string = string.rstrip()

        # Ignore specified characters
        if ignore_characters:
            string = ''.join([ch for ch in string if ch not in ignore_characters])

        # Extract the last character
        if string:
            last_char = string[-1]
        else:
            last_char = ''

        # Append result based on output format
        if output_format == 'character':
            results.append(last_char)
        elif output_format == 'text':
            results.append(last_char)
        elif output_format == 'json':
            results.append({'last_character': last_char})
        elif output_format == 'list':
            results.append(last_char)

    # Return results based on output format
    if output_format == 'character':
        return results[0] if results else ''
    elif output_format == 'text':
        return ''.join(results)
    elif output_format == 'json':
        return results
    elif output_format == 'list':
        return results

