def char_to_binary(input, encoding='utf-8', delimiter=' ', output_format='binary_string', error_handling='strict', case_sensitive=True):
    """
    Convert a character or string to its binary representation.

    Parameters:
    - input (str): The character or string to be converted.
    - encoding (str): The character encoding to use. Defaults to 'utf-8'.
    - delimiter (str): The delimiter between binary codes. Defaults to a single space.
    - output_format (str): The format of the output. Defaults to 'binary_string'.
    - error_handling (str): Strategy for handling encoding errors. Defaults to 'strict'.
    - case_sensitive (bool): Whether the conversion should be case-sensitive. Defaults to True.

    Returns:
    - str, list, or dict: The binary representation of the input based on the specified output format.
    """
    if not case_sensitive:
        input = input.lower()

    try:
        # Encode the input string
        encoded_bytes = input.encode(encoding, errors=error_handling)
        # Convert each byte to its binary representation
        binary_list = [format(byte, '08b') for byte in encoded_bytes]
    except Exception as e:
        return {'error': str(e)}

    # Format the output based on the specified output format
    if output_format == 'binary_string':
        return delimiter.join(binary_list)
    elif output_format == 'list':
        return binary_list
    elif output_format == 'json':
        return {'binary': binary_list}
    else:
        return {'error': 'Invalid output format specified.'}

