def sum_date_digits(dates, date_format='DD MM YYYY', output_format='integer', ignore_leap_years=False, include_time=False):
    import re
    from datetime import datetime

    def sum_digits(s):
        return sum(int(char) for char in s if char.isdigit())

    results = []
    for date_str in dates:
        try:
            # Attempt to parse the date based on the provided format or auto-detect
            if date_format == 'auto':
                # Try multiple formats
                for fmt in ['%d %m %Y', '%m-%d-%Y', '%Y/%m/%d']:
                    try:
                        date_obj = datetime.strptime(date_str, fmt)
                        break
                    except ValueError:
                        continue
                else:
                    raise ValueError('Date format not recognized')
            else:
                date_obj = datetime.strptime(date_str, date_format.replace('DD', '%d').replace('MM', '%m').replace('YYYY', '%Y'))

            # Extract components
            day = date_obj.day
            month = date_obj.month
            year = date_obj.year

            # Sum digits
            total_sum = sum_digits(str(day)) + sum_digits(str(month)) + sum_digits(str(year))

            if output_format == 'detailed':
                results.append({'date': date_str, 'day_sum': sum_digits(str(day)), 'month_sum': sum_digits(str(month)), 'year_sum': sum_digits(str(year)), 'total_sum': total_sum})
            elif output_format == 'text':
                results.append(f'The sum of digits for {date_str} is {total_sum}')
            else:  # Default to integer
                results.append(total_sum)

        except Exception as e:
            results.append({'error': str(e), 'date': date_str})

    return results

