    if not handle_special_characters:
        full_name = ''.join(e for e in full_name if e.isalnum() or e.isspace())

    # Split the name based on spaces
    name_parts = full_name.split()

    # Extract last name based on format
    last_name = ''
    if name_format == 'first_last':
        last_name = name_parts[-1] if len(name_parts) >= 2 else ''
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1] if len(name_parts) >= 3 else ''
    elif name_format == 'first_last_suffix':
