def date_digit_sum(date, date_format='YYYY-MM-DD', handle_invalid='error', summation_method='all_digits', return_breakdown=False):
    import datetime
    from collections import defaultdict

    def parse_date(date_str, date_format):
        try:
            if date_format == 'YYYY-MM-DD':
                return datetime.datetime.strptime(date_str, '%Y-%m-%d')
            elif date_format == 'MM/DD/YYYY':
                return datetime.datetime.strptime(date_str, '%m/%d/%Y')
            elif date_format == 'DD-MM-YYYY':
                return datetime.datetime.strptime(date_str, '%d-%m-%Y')
            elif date_format == 'DD.MM.YYYY':
                return datetime.datetime.strptime(date_str, '%d.%m.%Y')
            else:
                raise ValueError('Unsupported date format')
        except ValueError:
            if handle_invalid == 'error':
                raise
            elif handle_invalid == 'default_date':
                return datetime.datetime(1970, 1, 1)
            else:
                return None

    def sum_digits(number_str, unique=False):
        digits = set(number_str) if unique else number_str
        return sum(int(d) for d in digits if d.isdigit())

    parsed_date = parse_date(date, date_format)
    if parsed_date is None:
        return {'error': 'Invalid date and handle_invalid set to ignore'}

    day_str = str(parsed_date.day)
    month_str = str(parsed_date.month)
    year_str = str(parsed_date.year)

    if summation_method == 'all_digits':
        total_sum = sum_digits(day_str) + sum_digits(month_str) + sum_digits(year_str)
    elif summation_method == 'unique_digits':
        total_sum = sum_digits(day_str, unique=True) + sum_digits(month_str, unique=True) + sum_digits(year_str, unique=True)
    else:
        raise ValueError('Unsupported summation method')

    if return_breakdown:
        breakdown = {
            'day_sum': sum_digits(day_str, unique=(summation_method == 'unique_digits')),
            'month_sum': sum_digits(month_str, unique=(summation_method == 'unique_digits')),
            'year_sum': sum_digits(year_str, unique=(summation_method == 'unique_digits'))
        }
        return {'total_sum': total_sum, 'breakdown': breakdown}
    else:
        return {'total_sum': total_sum}

