def longest_alphabetical_substring(input_string, case_sensitive=False, alphabet='latin', output_format='substring', include_position=False):
    # Validate input parameters
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if alphabet not in ['latin', 'cyrillic', 'greek']:
        return {'error': 'alphabet must be one of latin, cyrillic, greek'}
    if output_format not in ['substring', 'length', 'details']:
        return {'error': 'output_format must be one of substring, length, details'}
    if not isinstance(include_position, bool):
        return {'error': 'include_position must be a boolean'}

    # Define the alphabet order based on the specified alphabet
    if alphabet == 'latin':
        order = 'abcdefghijklmnopqrstuvwxyz'
    elif alphabet == 'cyrillic':
        order = 'абвгдеёжзийклмнопрстуфхцчшщъыьэюя'
    elif alphabet == 'greek':
        order = 'αβγδεζηθικλμνξοπρστυφχψω'

    if not case_sensitive:
        input_string = input_string.lower()

    max_length = 0
    max_substring = ''
    current_length = 1
    current_substring = input_string[0] if input_string else ''
    start_position = 0
    max_start_position = 0

    for i in range(1, len(input_string)):
        if order.index(input_string[i]) >= order.index(input_string[i - 1]):
            current_length += 1
            current_substring += input_string[i]
        else:
            if current_length > max_length:
                max_length = current_length
                max_substring = current_substring
                max_start_position = start_position
            current_length = 1
            current_substring = input_string[i]
            start_position = i

    # Check last substring
    if current_length > max_length:
