def date_parser(date_input: str, output_component: str = 'month', output_format: str = 'integer', calendar_system: str = 'gregorian', validate_input: bool = True, error_handling: str = 'raise'):
    import datetime
    from dateutil import parser

    # Error handling setup
    def handle_error(message):
        if error_handling == 'raise':
            raise ValueError(message)
        elif error_handling == 'ignore':
            return None
        elif error_handling == 'default':
            return 'Invalid Date'

    # Validate input if required
    if validate_input:
        try:
            # Attempt to parse the date
            parsed_date = parser.parse(date_input, yearfirst=True)
        except (ValueError, OverflowError) as e:
            return handle_error(f'Error parsing date: {e}')
    else:
        parsed_date = parser.parse(date_input, yearfirst=True, fuzzy=True)

    # Extract the required component
    try:
        if output_component == 'day':
            result = parsed_date.day
        elif output_component == 'month':
            result = parsed_date.month
        elif output_component == 'year':
            result = parsed_date.year
        elif output_component == 'weekday':
            result = parsed_date.strftime('%A')
        else:
            return handle_error('Invalid output component specified.')

        # Format the output
        if output_format == 'integer':
            return result
        elif output_format == 'text':
            if output_component == 'month':
                return parsed_date.strftime('%b')
            elif output_component == 'weekday':
                return parsed_date.strftime('%a')
            else:
                return handle_error('Text format is not applicable for this component.')
        elif output_format == 'full_text':
            if output_component == 'month':
                return parsed_date.strftime('%B')
            elif output_component == 'weekday':
                return parsed_date.strftime('%A')
            else:
                return handle_error('Full text format is not applicable for this component.')
        else:
            return handle_error('Invalid output format specified.')
    except Exception as e:
        return handle_error(f'Error extracting component: {e}')

