def day_of_week_calculator(date, calendar_system='gregorian', output_format='full', locale='en-US'):
    from datetime import datetime
    import calendar
    import locale as loc

    # Set locale for day names
    try:
        loc.setlocale(loc.LC_TIME, locale)
    except Exception as e:
        return {'error': f'Invalid locale: {locale}. Error: {str(e)}'}

    # Parse the date
    date_formats = ['%Y-%m-%d', '%d-%m-%Y', '%m/%d/%Y', '%B %d, %Y']
    parsed_date = None
    for fmt in date_formats:
        try:
            parsed_date = datetime.strptime(date, fmt)
            break
        except ValueError:
            continue
    if not parsed_date:
        return {'error': 'Invalid date format. Supported formats are YYYY-MM-DD, DD-MM-YYYY, MM/DD/YYYY, Month DD, YYYY.'}

    # Check calendar system
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': f'Unsupported calendar system: {calendar_system}. Supported systems are gregorian, julian, hebrew, islamic.'}

    # Calculate day of the week
    if calendar_system == 'gregorian':
        day_index = parsed_date.weekday()  # Monday is 0, Sunday is 6
    else:
        return {'error': 'Currently, only the Gregorian calendar system is supported for calculations.'}

    # Convert day index to desired output format
    days_full = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
    days_abbr = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun']
    if output_format == 'full':
        day_name = days_full[day_index]
    elif output_format == 'abbreviated':
        day_name = days_abbr[day_index]
    elif output_format == 'numeric':
        day_name = day_index
    else:
        return {'error': f'Invalid output format: {output_format}. Supported formats are full, abbreviated, numeric.'}

    return {'day_of_week': day_name}

