def calculate_combined_length(names, include_characters=None, exclude_characters=None, case_sensitive=False, ignore_whitespace=False, output_format='integer'):
    # Error handling for required parameters
    if not isinstance(names, list) or len(names) < 1:
        return {'error': 'The parameter "names" must be a list with at least one string.'}

    # Initialize combined length
    combined_length = 0

    # Normalize include/exclude characters
    include_characters = set(include_characters) if include_characters else None
    exclude_characters = set(exclude_characters) if exclude_characters else set()

    # Iterate over each name
    for name in names:
        # Adjust for case sensitivity
        if not case_sensitive:
            name = name.lower()
            if include_characters:
                include_characters = set(char.lower() for char in include_characters)
            exclude_characters = set(char.lower() for char in exclude_characters)

        # Calculate length for each name
        for char in name:
            if ignore_whitespace and char.isspace():
                continue
            if include_characters and char not in include_characters:
                continue
            if char in exclude_characters:
                continue
            combined_length += 1

    # Format output
    if output_format == 'text':
        return f'The combined length is {combined_length}.'
    elif output_format == 'detailed':
        return {
            'total_length': combined_length,
            'details': [{'name': name, 'length': len(name)} for name in names]
        }
    else:  # Default to integer
        return combined_length

