    if not isinstance(exclude_characters, list) or not all(isinstance(char, str) for char in exclude_characters):
        return {'error': 'exclude_characters must be a list of strings.'}

    # Calculate combined length
    total_length = 0
    detailed_breakdown = {}

    for name in names:
        if not case_sensitive:
            name = name.lower()
        if ignore_spaces:
            name = name.replace(' ', '')
        for char in exclude_characters:
            name = name.replace(char, '')
        name_length = len(name)
        total_length += name_length
        detailed_breakdown[name] = name_length

    # Return result based on output_format
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'The combined length is {total_length}.'
    elif output_format == 'detailed':
        return {'total_length': total_length, 'breakdown': detailed_breakdown}

