        if error_handling == 'exception':
            raise ValueError('No valid characters found.')
        elif error_handling == 'empty_string_warning':
            return 'Warning: No valid characters found.'
        else:
            return None

    last_char = input[-1]

    # Return the output in the specified format
    if output_format == 'ascii_code':
