def advanced_string_concatenator(strings, separator='', case_transformation='none', conditional_concatenation=None):
    # Validate input parameters
    if not isinstance(strings, list) or len(strings) < 2:
        return {'error': 'Invalid input: At least two strings are required.'}
    if not isinstance(separator, str):
        return {'error': 'Invalid input: Separator must be a string.'}
    if case_transformation not in ['none', 'uppercase', 'lowercase', 'capitalize']:
        return {'error': 'Invalid input: Case transformation must be one of none, uppercase, lowercase, capitalize.'}
    if conditional_concatenation:
        if not isinstance(conditional_concatenation, dict):
            return {'error': 'Invalid input: Conditional concatenation must be a dictionary.'}
        include_if = conditional_concatenation.get('include_if', '')
        exclude_if = conditional_concatenation.get('exclude_if', '')
    else:
        include_if = ''
        exclude_if = ''

    # Apply conditional concatenation
    filtered_strings = []
    for s in strings:
        if include_if and include_if not in s:
            continue
        if exclude_if and exclude_if in s:
            continue
        filtered_strings.append(s)

    # Apply case transformation
    transformed_strings = []
    for s in filtered_strings:
        if case_transformation == 'uppercase':
            transformed_strings.append(s.upper())
        elif case_transformation == 'lowercase':
            transformed_strings.append(s.lower())
        elif case_transformation == 'capitalize':
            transformed_strings.append(s.capitalize())
        else:
            transformed_strings.append(s)

    # Concatenate strings
    result = separator.join(transformed_strings)
    return result

