def first_letter_extractor(input: str, output_format: str = 'character', case_sensitive: bool = True, handle_empty: str = 'error', default_character: str = '') -> str:
    # Check if the input string is empty
    if not input:
        if handle_empty == 'error':
            raise ValueError('Input string is empty and handle_empty is set to error.')
        elif handle_empty == 'null':
            return 'null'
        elif handle_empty == 'default':
            return default_character

    # Extract the first letter
    first_letter = input[0] if case_sensitive else input[0].lower()

    # Format the output based on the output_format parameter
    if output_format == 'character':
        return first_letter
    elif output_format == 'ascii':
        return str(ord(first_letter))
    elif output_format == 'unicode':
        return f'U+{ord(first_letter):04X}'
    elif output_format == 'hex':
        return hex(ord(first_letter))
    else:
        raise ValueError('Invalid output format specified.')

