def ascii_converter(characters, output_format='list', ignore_non_ascii=True, placeholder='?'):
    # Validate input parameters
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")
    if output_format not in ['list', 'string', 'json', 'csv']:
        raise ValueError("'output_format' must be one of ['list', 'string', 'json', 'csv'].")
    if not isinstance(ignore_non_ascii, bool):
        raise ValueError("'ignore_non_ascii' must be a boolean.")

    # Convert characters to ASCII codes
    ascii_codes = []
    for char in characters:
        if ord(char) < 128:  # ASCII range check
            ascii_codes.append(ord(char))
        elif not ignore_non_ascii:
            ascii_codes.append(ord(placeholder))

    # Format the output based on 'output_format'
    if output_format == 'list':
        return ascii_codes
    elif output_format == 'string':
        return ''.join(map(str, ascii_codes))
    elif output_format == 'json':
        return {char: ord(char) if ord(char) < 128 else placeholder for char in characters}
    elif output_format == 'csv':
        return ','.join(map(str, ascii_codes))

