def date_calculator(start_date: str, months_to_add: int = 0, weeks_to_add: int = 0, days_to_add: int = 0, output_format: str = 'YYYY-MM-DD', time_zone: str = None) -> str:
    from datetime import datetime, timedelta
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate start_date format
    try:
        date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return 'Error: Invalid start_date format. Expected YYYY-MM-DD.'

    # Adjust date based on months, weeks, and days
    try:
        date_obj += relativedelta(months=months_to_add)
        date_obj += timedelta(weeks=weeks_to_add, days=days_to_add)
    except Exception as e:
        return f'Error: {str(e)}'

    # Handle time zone conversion if specified
    if time_zone:
        try:
            tz = pytz.timezone(time_zone)
            date_obj = date_obj.astimezone(tz)
        except pytz.UnknownTimeZoneError:
            return 'Error: Unknown time zone specified.'

    # Format the output date
    formats = {
        'YYYY-MM-DD': '%Y-%m-%d',
        'MM/DD/YYYY': '%m/%d/%Y',
        'DD-MM-YYYY': '%d-%m-%Y',
        'DD/MM/YYYY': '%d/%m/%Y',
        'YYYY/MM/DD': '%Y/%m/%d'
    }
    if output_format not in formats:
        return 'Error: Invalid output_format specified.'

    return date_obj.strftime(formats[output_format])

