def advanced_date_calculator(input_date: str, years_to_adjust: int = 0, months_to_adjust: int = 0, days_to_adjust: int = 0, output_format: str = 'YYYY-MM-DD', time_zone: str = 'UTC', calculate_date_range: bool = False):
    from datetime import datetime
    from dateutil.relativedelta import relativedelta
    import pytz

    # Validate input date format
    try:
        date_obj = datetime.strptime(input_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid input date format. Expected YYYY-MM-DD.'}

    # Adjust the date
    adjusted_date = date_obj + relativedelta(years=years_to_adjust, months=months_to_adjust, days=days_to_adjust)

    # Handle time zone conversion
    try:
        tz = pytz.timezone(time_zone)
        adjusted_date = tz.localize(adjusted_date)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Unknown time zone specified.'}

    # Format the output date
    if output_format == 'YYYY-MM-DD':
        formatted_date = adjusted_date.strftime('%Y-%m-%d')
    elif output_format == 'MM-DD-YYYY':
        formatted_date = adjusted_date.strftime('%m-%d-%Y')
    elif output_format == 'DD-MM-YYYY':
        formatted_date = adjusted_date.strftime('%d-%m-%Y')
    else:
        return {'error': 'Invalid output format specified.'}

    # Calculate date range if requested
    if calculate_date_range:
        date_range = (date_obj.strftime('%Y-%m-%d'), formatted_date)
        return {'adjusted_date': formatted_date, 'date_range': date_range}

    return {'adjusted_date': formatted_date}

