    from datetime import datetime, timedelta
    import pytz
    from dateutil.relativedelta import relativedelta

    # Validate start_date
    try:
        start_date_obj = datetime.strptime(start_date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid start_date format. Expected YYYY-MM-DD.'}

    # Validate duration
    if 'value' not in duration or 'unit' not in duration:
        return {'error': 'Duration must include both value and unit.'}
    if not isinstance(duration['value'], int) or duration['unit'] not in ['days', 'weeks', 'months', 'years']:
        return {'error': 'Invalid duration value or unit.'}

    # Validate operation
    if operation not in ['add', 'subtract']:
        return {'error': 'Invalid operation. Must be add or subtract.'}

    # Adjust for time zone
    try:
        tz = pytz.timezone(time_zone)
        start_date_obj = tz.localize(start_date_obj)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone specified.'}

    # Calculate new date
    delta = None
    if duration['unit'] == 'days':
        delta = timedelta(days=duration['value'])
    elif duration['unit'] == 'weeks':
        delta = timedelta(weeks=duration['value'])
    elif duration['unit'] == 'months':
        delta = relativedelta(months=duration['value'])
    elif duration['unit'] == 'years':
        delta = relativedelta(years=duration['value'])

    if operation == 'subtract':
        delta = -delta

    new_date_obj = start_date_obj + delta

    # Convert back to string
    new_date_str = new_date_obj.strftime('%Y-%m-%d')

    return {'result': new_date_str}

