def distinct_combinations(input_string, combination_length=2, case_sensitive=True, output_format='count', exclude_characters='', include_only_characters='', sort_order='none'):
    # Validate input_string length
    if len(input_string) < 2:
        return {'error': 'Input string must be at least two characters long.'}

    # Validate combination_length
    if combination_length < 2:
        return {'error': 'Combination length must be at least 2.'}

    # Adjust input_string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Apply include_only_characters or exclude_characters
    if include_only_characters:
        input_string = ''.join([char for char in input_string if char in include_only_characters])
    else:
        input_string = ''.join([char for char in input_string if char not in exclude_characters])

    # Generate combinations
    from itertools import combinations
    all_combinations = set(combinations(input_string, combination_length))

    # Convert combinations to strings
    all_combinations = {''.join(comb) for comb in all_combinations}

    # Sort combinations if needed
    if sort_order == 'alphabetical':
        all_combinations = sorted(all_combinations)
    elif sort_order == 'frequency':
        from collections import Counter
        frequency = Counter(all_combinations)
        all_combinations = sorted(all_combinations, key=lambda x: frequency[x], reverse=True)

    # Return based on output_format
    if output_format == 'count':
        return len(all_combinations)
    elif output_format == 'list':
        return list(all_combinations)
    else:
        return {'error': 'Invalid output format.'}

