def date_digit_sum_plus(date, calendar_system='Gregorian', output_format='integer', error_handling='strict', validation=True):
    """
    Calculate the sum of all digits in the day, month, and year of a given date.
    """
    import re
    from datetime import datetime

    # Helper function to sum digits
    def sum_digits(s):
        return sum(int(char) for char in s if char.isdigit())

    # Validate date format
    if validation:
        try:
            if calendar_system == 'Gregorian':
                datetime.strptime(date, '%d-%m-%Y')
            # Add additional calendar systems validation if needed
        except ValueError:
            if error_handling == 'strict':
                raise ValueError('Invalid date format')
            elif error_handling == 'lenient':
                # Attempt to correct the date format
                date = re.sub(r'[^0-9]', '-', date)

    # Extract digits and calculate sum
    digit_sum = sum_digits(date)

    # Format output
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The sum of the digits is {digit_sum}'
    elif output_format == 'json':
        return {'digit_sum': digit_sum}

    # Default return
    return digit_sum

