def enhanced_day_of_week_calculator(date, calendar_system='gregorian', output_format='day_name', additional_info=None):
    import datetime
    from dateutil import parser

    # Default additional_info if None
    if additional_info is None:
        additional_info = {'week_number': False, 'weekend_status': False, 'day_of_year': False}

    # Validate calendar_system
    if calendar_system not in ['gregorian', 'julian', 'hebrew', 'islamic']:
        return {'error': 'Invalid calendar system. Supported systems are: gregorian, julian, hebrew, islamic.'}

    # Validate output_format
    if output_format not in ['day_name', 'day_number', 'full_details']:
        return {'error': 'Invalid output format. Supported formats are: day_name, day_number, full_details.'}

    try:
        # Parse the date
        parsed_date = parser.parse(date)
    except ValueError:
        return {'error': 'Invalid date format. Please use a valid date format such as YYYY-MM-DD, DD-MM-YYYY, or MM-DD-YYYY.'}

    # Calculate the day of the week
    day_number = parsed_date.weekday()  # Monday is 0 and Sunday is 6
    day_name = parsed_date.strftime('%A')

    # Adjust for Sunday as 0
    day_number = (day_number + 1) % 7

    # Prepare the output
    result = {}

    if output_format == 'day_name':
        result['day_name'] = day_name
    elif output_format == 'day_number':
        result['day_number'] = day_number
    elif output_format == 'full_details':
        result['day_name'] = day_name
        result['day_number'] = day_number
        if additional_info.get('week_number', False):
            result['week_number'] = parsed_date.isocalendar()[1]
        if additional_info.get('weekend_status', False):
            result['weekend_status'] = day_number in [0, 6]
        if additional_info.get('day_of_year', False):
            result['day_of_year'] = parsed_date.timetuple().tm_yday

    return result

