def extract_first_name(full_name: str, ignore_special_characters: bool = False, case_sensitive: bool = True, include_middle_name: bool = False, handle_prefixes_suffixes: bool = False, cultural_convention: str = 'Western') -> str:
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        raise ValueError("'full_name' must be a non-empty string.")

    # Handle special characters if needed
    if ignore_special_characters:
        import re
        full_name = re.sub(r'[^\w\s]', '', full_name)

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle prefixes and suffixes if specified
    if handle_prefixes_suffixes:
        prefixes = {'Mr.', 'Mrs.', 'Dr.', 'Ms.'}
        suffixes = {'Jr.', 'Sr.', 'III'}
        name_parts = [part for part in name_parts if part not in prefixes and part not in suffixes]

    # Determine the first name based on cultural convention
    if cultural_convention == 'Western':
        first_name = name_parts[0] if name_parts else ''
    else:
        # For simplicity, assume Eastern convention uses the last part as the first name
        first_name = name_parts[-1] if name_parts else ''

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + ' '.join(name_parts[1:-1])

    # Adjust case sensitivity
    if not case_sensitive:
        first_name = first_name.lower()

    return first_name

