def closest_palindrome_finder(year, direction='both', output_format='integer', range_limit=None, multiple_results=False):
    """
    Finds the closest palindrome number to the given year.

    Parameters:
    - year (int): The year for which the closest palindrome number is to be found.
    - direction (str): The direction to search for the palindrome ('both', 'lower', 'higher').
    - output_format (str): The format of the output ('integer', 'text').
    - range_limit (int): The maximum range within which to search for palindromes.
    - multiple_results (bool): If true, return all closest palindromes if they exist at the same distance.

    Returns:
    - The closest palindrome number in the specified format.
    """
    def is_palindrome(n):
        return str(n) == str(n)[::-1]

    if not isinstance(year, int):
        raise ValueError("Year must be an integer.")

    if direction not in ['both', 'lower', 'higher']:
        raise ValueError("Direction must be 'both', 'lower', or 'higher'.")

    if output_format not in ['integer', 'text']:
        raise ValueError("Output format must be 'integer' or 'text'.")

    closest_palindromes = []
    min_distance = float('inf')

    def check_palindrome(y):
        nonlocal min_distance
        if is_palindrome(y):
            distance = abs(year - y)
            if distance < min_distance:
                min_distance = distance
                closest_palindromes.clear()
                closest_palindromes.append(y)
            elif distance == min_distance and multiple_results:
                closest_palindromes.append(y)

    if direction in ['both', 'lower']:
        for y in range(year - 1, (year - range_limit) if range_limit else 0, -1):
            check_palindrome(y)
            if min_distance < float('inf') and not multiple_results:
                break

    if direction in ['both', 'higher']:
        for y in range(year + 1, (year + range_limit) if range_limit else float('inf')):
            check_palindrome(y)
            if min_distance < float('inf') and not multiple_results:
                break

    if not closest_palindromes:
        raise ValueError("No palindrome found within the specified range.")

    result = closest_palindromes if multiple_results else closest_palindromes[0]

    if output_format == 'text':
        return f"The closest palindrome(s) to {year} is/are: {result}"
    return result

