def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', ignore_characters: str = '', only_alphabetic: bool = True):
    # Validate output_format
    if output_format not in ['integer', 'list', 'detailed']:
        raise ValueError("Invalid output_format. Must be 'integer', 'list', or 'detailed'.")

    # Prepare the input string
    if not case_sensitive:
        input = input.lower()

    # Filter out ignored characters
    input = ''.join([char for char in input if char not in ignore_characters])

    # Filter to only alphabetic characters if required
    if only_alphabetic:
        input = ''.join([char for char in input if char.isalpha()])

    # Count occurrences of each character
    from collections import Counter
    char_count = Counter(input)

    # Identify repeated letters
    repeated_letters = {char: count for char, count in char_count.items() if count > 1}

    # Generate output based on the specified format
    if output_format == 'integer':
        return len(repeated_letters)
    elif output_format == 'list':
        return list(repeated_letters.keys())
    elif output_format == 'detailed':
        return repeated_letters

