def enhanced_unique_letter_counter(input: str, case_sensitive: bool = False, exclude_characters: list = [], include_character_range: list = [], alphabetic_only: bool = True, output_format: str = 'integer'):
    # Validate the input parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if not isinstance(exclude_characters, list) or not all(isinstance(c, str) for c in exclude_characters):
        return {'error': 'exclude_characters must be a list of strings.'}
    if not isinstance(include_character_range, list) or len(include_character_range) % 2 != 0:
        return {'error': 'include_character_range must be a list with an even number of elements.'}
    if not isinstance(alphabetic_only, bool):
        return {'error': 'alphabetic_only must be a boolean.'}
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': 'output_format must be one of the following: integer, list, detailed.'}

    # Normalize the input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Initialize a set to store unique letters
    unique_letters = set()

    # Define a function to check if a character is within the specified ranges
    def is_in_range(char):
        if not include_character_range:
            return True
        for i in range(0, len(include_character_range), 2):
            start, end = include_character_range[i], include_character_range[i+1]
            if start <= char <= end:
                return True
        return False

    # Iterate over each character in the input string
    for char in input:
        # Check if the character should be counted
        if alphabetic_only and not char.isalpha():
            continue
        if char in exclude_characters:
            continue
        if not is_in_range(char):
            continue
        # Add the character to the set of unique letters
        unique_letters.add(char)

    # Prepare the output based on the specified format
    if output_format == 'integer':
        return len(unique_letters)
    elif output_format == 'list':
        return list(unique_letters)
    elif output_format == 'detailed':
        return {char: input.count(char) for char in unique_letters}

