def date_digit_sum(date, date_format='Month DD, YYYY', output_format='integer', include_components=['day', 'month', 'year'], numeral_system='decimal'):
    """
    Calculate the sum of all digits in the specified components of a given date.

    Parameters:
    - date (str): The date input in a recognized format.
    - date_format (str): The format of the input date.
    - output_format (str): The format of the output.
    - include_components (list): Specifies which components of the date to include in the digit sum.
    - numeral_system (str): The numeral system to use for the digit sum calculation.

    Returns:
    - The sum of the digits in the specified format.
    """
    import re
    from datetime import datetime

    # Error handling for unsupported numeral systems
    if numeral_system not in ['decimal', 'binary', 'hexadecimal']:
        return {'error': 'Unsupported numeral system'}

    # Parse the date based on the provided format
    try:
        if date_format == 'Month DD, YYYY':
            date_obj = datetime.strptime(date, '%B %d, %Y')
        elif date_format == 'YYYY-MM-DD':
            date_obj = datetime.strptime(date, '%Y-%m-%d')
        elif date_format == 'MM/DD/YYYY':
            date_obj = datetime.strptime(date, '%m/%d/%Y')
        elif date_format == 'DD-MM-YYYY':
            date_obj = datetime.strptime(date, '%d-%m-%Y')
        elif date_format == 'YYYY/MM/DD':
            date_obj = datetime.strptime(date, '%Y/%m/%d')
        else:
            return {'error': 'Unsupported date format'}
    except ValueError:
        return {'error': 'Invalid date format'}

    # Extract components
    components = {
        'day': date_obj.day,
        'month': date_obj.month,
        'year': date_obj.year
    }

    # Calculate digit sum
    digit_sum = 0
    for component in include_components:
        if component in components:
            digits = str(components[component])
            digit_sum += sum(int(d) for d in digits)

    # Format the output
    if output_format == 'integer':
        return digit_sum
    elif output_format == 'text':
        return f'The digit sum is {digit_sum}'
    elif output_format == 'json':
        return {'digit_sum': digit_sum}
    else:
        return {'error': 'Unsupported output format'}

# Example usage
result = date_digit_sum('November 3, 1867')
print(result)  # Output: 27

