def count_repeated_letters(input: str, case_sensitive: bool = False, ignore_characters: list = [], repetition_type: str = 'all', output_detail: str = 'count'):
    # Validate input parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if repetition_type not in ['all', 'consecutive']:
        return {'error': 'Invalid repetition_type. Must be "all" or "consecutive".'}
    if output_detail not in ['count', 'detailed']:
        return {'error': 'Invalid output_detail. Must be "count" or "detailed".'}

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Remove ignored characters
    input = ''.join([char for char in input if char not in ignore_characters])

    # Initialize variables for counting
    repeated_count = 0
    detailed_info = {}

    # Analyze the string for repeated letters
    if repetition_type == 'all':
        seen = set()
        for char in input:
            if char in seen:
                if char not in detailed_info:
                    detailed_info[char] = {'count': 0, 'positions': []}
                detailed_info[char]['count'] += 1
                detailed_info[char]['positions'].append(input.index(char))
            else:
                seen.add(char)
        repeated_count = sum(info['count'] for info in detailed_info.values())
    elif repetition_type == 'consecutive':
        i = 0
        while i < len(input) - 1:
            if input[i] == input[i + 1]:
                char = input[i]
                if char not in detailed_info:
                    detailed_info[char] = {'count': 0, 'positions': []}
                detailed_info[char]['count'] += 1
                detailed_info[char]['positions'].append(i)
                while i < len(input) - 1 and input[i] == input[i + 1]:
                    i += 1
            i += 1
        repeated_count = sum(info['count'] for info in detailed_info.values())

    # Return result based on output_detail
    if output_detail == 'count':
        return repeated_count
    elif output_detail == 'detailed':
        return detailed_info

