def find_longest_word(input_string, ignore_punctuation=True, case_sensitive=False, language='en', hyphenated_words=True, custom_delimiters=[], return_all_longest=False):
    import re

    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}

    # Define delimiters based on punctuation and custom delimiters
    delimiters = r'\s'  # default to whitespace
    if ignore_punctuation:
        delimiters += r'|[\.,!?;:]'
    if custom_delimiters:
        delimiters += '|' + '|'.join(map(re.escape, custom_delimiters))

    # Split the input string into words
    words = re.split(delimiters, input_string)

    # Handle case sensitivity
    if not case_sensitive:
        words = [word.lower() for word in words]

    # Handle hyphenated words
    if hyphenated_words:
        words = [word.replace('-', '') for word in words]

    # Find the longest word(s)
    max_length = 0
    longest_words = []
    for word in words:
        if len(word) > max_length:
            max_length = len(word)
            longest_words = [word]
        elif len(word) == max_length:
            longest_words.append(word)

    # Return all longest words or just one
    if return_all_longest:
        return longest_words
    else:
        return longest_words[0] if longest_words else ''

