def extract_first_name(full_name, ignore_titles=True, name_delimiters=[' '], output_format='string', handle_middle_names=False, handle_suffixes=False, cultural_variations='western'):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name.strip():
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Define titles and suffixes to ignore
    titles = ['Mr.', 'Mrs.', 'Dr.', 'Ms.'] if ignore_titles else []
    suffixes = ['Jr.', 'Sr.', 'II', 'III'] if handle_suffixes else []

    # Split the full name based on delimiters
    import re
    delimiters_regex = '|'.join(map(re.escape, name_delimiters))
    name_parts = re.split(delimiters_regex, full_name)

    # Remove titles and suffixes
    name_parts = [part for part in name_parts if part not in titles + suffixes]

    # Handle cultural variations
    if cultural_variations == 'eastern':
        # Eastern naming convention might have family name first
        first_name = name_parts[-1] if name_parts else ''
    else:
        # Default to western naming convention
        first_name = name_parts[0] if name_parts else ''

    # Format the output
    if output_format == 'array':
        return list(first_name)
    elif output_format == 'detailed':
        return {'first_name': first_name, 'full_name': full_name, 'cultural_variation': cultural_variations}
    else:
        return first_name

