def last_vowel_finder(input_string, case_sensitive=False, output_format='character', vowels_to_consider=['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'], ignore_special_characters=True):
    # Error handling for required parameter
    if not isinstance(input_string, str):
        return {'error': 'Invalid input: input_string must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if output_format not in ['character', 'position', 'both']:
        return {'error': 'Invalid input: output_format must be one of character, position, or both.'}
    if not isinstance(vowels_to_consider, list) or not all(isinstance(v, str) and v in 'aeiouAEIOU' for v in vowels_to_consider):
        return {'error': 'Invalid input: vowels_to_consider must be a list of vowels.'}
    if not isinstance(ignore_special_characters, bool):
        return {'error': 'Invalid input: ignore_special_characters must be a boolean.'}

    # Prepare the string for processing
    if ignore_special_characters:
        input_string = ''.join(filter(str.isalnum, input_string))

    # Adjust case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        vowels_to_consider = [v.lower() for v in vowels_to_consider]

    # Find the last vowel
    last_vowel = None
    last_position = -1
    for i in range(len(input_string) - 1, -1, -1):
        if input_string[i] in vowels_to_consider:
            last_vowel = input_string[i]
            last_position = i
            break

    # Return based on output_format
    if last_vowel is None:
        return {'result': None}
    if output_format == 'character':
        return {'result': last_vowel}
    elif output_format == 'position':
        return {'result': last_position}
    elif output_format == 'both':
        return {'result': {'character': last_vowel, 'position': last_position}}

