def extract_initials(phrase, ignore_punctuation=True, case_sensitive=False, output_format='uppercase', handle_special_characters=False, include_numbers=False, whitespace_handling='collapse'):
    # Error handling for required parameter
    if not isinstance(phrase, str):
        return 'Error: The phrase must be a string.'

    # Handle whitespace according to the specified method
    if whitespace_handling == 'trim':
        phrase = phrase.strip()
    elif whitespace_handling == 'collapse':
        phrase = ' '.join(phrase.split())
    # 'preserve' does nothing special

    # Split the phrase into words
    words = phrase.split()
    initials = []

    for word in words:
        # Handle punctuation
        if ignore_punctuation:
            word = ''.join(char for char in word if char.isalnum() or char.isspace())

        # Handle special characters
        if not handle_special_characters:
            word = ''.join(char for char in word if char.isalnum())

        # Handle numbers
        if not include_numbers:
            word = ''.join(char for char in word if not char.isdigit())

        # Extract the initial
        if word:
            initial = word[0]
            if not case_sensitive:
                initial = initial.upper()
            initials.append(initial)

    # Format the output
    if output_format == 'lowercase':
        initials = [initial.lower() for initial in initials]
    elif output_format == 'titlecase':
        initials = [initial.title() for initial in initials]
    # 'uppercase' is the default

    return ''.join(initials)

