    if not isinstance(ignore_whitespace, bool):
        return 'Error: ignore_whitespace must be a boolean.'
    if not isinstance(case_sensitive, bool):
        return 'Error: case_sensitive must be a boolean.'

    # Adjust input string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        character_set = character_set.lower()

    # Filter characters based on character_set
    if character_set:
        input_string = ''.join([ch for ch in input_string if ch in character_set])

    # Handle whitespace
    if ignore_whitespace:
        input_string = ''.join(input_string.split())

