def extract_initials(phrase: str, ignore_non_alpha: bool = True, case_sensitive: bool = False, language: str = 'en', delimiter: str = '', handle_hyphenated: bool = True, acronyms_as_initials: bool = False) -> str:
    # Error handling for invalid input
    if not isinstance(phrase, str) or not phrase.strip():
        raise ValueError('The phrase must be a non-empty string.')

    # Split the phrase into words
    words = phrase.split()
    initials = []

    for word in words:
        # Handle hyphenated words if necessary
        if handle_hyphenated and '-' in word:
            sub_words = word.split('-')
        else:
            sub_words = [word]

        for sub_word in sub_words:
            # Extract the first letter of each sub-word
            if ignore_non_alpha:
                sub_word = ''.join(filter(str.isalpha, sub_word))
            if sub_word:
                initial = sub_word[0]
                if not case_sensitive:
                    initial = initial.upper()
                initials.append(initial)

    # Join initials with the specified delimiter
    result = delimiter.join(initials)

    # Handle acronyms as single initials if specified
    if acronyms_as_initials:
        # This is a simplified example; actual acronym handling might be more complex
        result = ''.join([word[0] for word in words if word.isupper()])

    return result

