def enhanced_unique_letter_counter(input, ignore_characters=[], case_sensitive=False, output_format='integer', character_range=[], statistics=False):
    # Validate input parameter
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Validate ignore_characters parameter
    if not all(isinstance(char, str) and len(char) == 1 for char in ignore_characters):
        return {'error': 'Invalid ignore_characters. Each item must be a single character string.'}

    # Validate output_format parameter
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: integer, text, detailed.'}

    # Validate character_range parameter
    if len(character_range) == 2:
        if not all(isinstance(char, str) and len(char) == 1 for char in character_range):
            return {'error': 'Invalid character_range. Each item must be a single character string.'}
    elif len(character_range) != 0:
        return {'error': 'Invalid character_range. Must be an array with two elements or empty.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]
        character_range = [char.lower() for char in character_range]

    # Filter characters based on ignore_characters and character_range
    filtered_input = ''.join(
        char for char in input
        if char not in ignore_characters and
        (not character_range or (character_range[0] <= char <= character_range[1]))
    )

    # Count unique letters
    unique_letters = set(filtered_input)
    unique_count = len(unique_letters)

    # Prepare detailed statistics if required
    detailed_stats = {}
    if statistics or output_format == 'detailed':
        for char in unique_letters:
            count = filtered_input.count(char)
            percentage = (count / len(filtered_input)) * 100
            detailed_stats[char] = {'count': count, 'percentage': percentage}

    # Return result based on output_format
    if output_format == 'integer':
        return unique_count
    elif output_format == 'text':
        return f'There are {unique_count} unique letters.'
    elif output_format == 'detailed':
        return {'unique_count': unique_count, 'details': detailed_stats}

