def consonant_counter(input, case_sensitive=False, ignore_characters=[], ignore_position=[], consonant_type='all', ignore_patterns=[]):
    # Define consonant sets
    all_consonants = set('bcdfghjklmnpqrstvwxyz')
    voiced_consonants = set('bdgvzjlmrn')
    voiceless_consonants = set('cfhkpstwx')

    # Select consonant set based on type
    if consonant_type == 'voiced':
        consonants = voiced_consonants
    elif consonant_type == 'voiceless':
        consonants = voiceless_consonants
    else:
        consonants = all_consonants

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        consonants = {c.lower() for c in consonants}
        ignore_characters = [c.lower() for c in ignore_characters]
        ignore_patterns = [p.lower() for p in ignore_patterns]

    # Remove ignored patterns
    for pattern in ignore_patterns:
        input = input.replace(pattern, '')

    # Initialize consonant count
    consonant_count = 0

    # Iterate over characters in the input
    for i, char in enumerate(input):
        # Check if character should be ignored
        if char in ignore_characters:
            continue
        if 'first' in ignore_position and i == 0:
            continue
        if 'last' in ignore_position and i == len(input) - 1:
            continue
        if 'even' in ignore_position and i % 2 == 0:
            continue
        if 'odd' in ignore_position and i % 2 != 0:
            continue

        # Count consonant if not ignored
        if char in consonants:
            consonant_count += 1

    return consonant_count

