def advanced_letter_counter(input, letters, case_sensitive=False, output_format='count'):
    # Validate input parameters
    if not isinstance(input, list) or not all(isinstance(s, str) for s in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if not isinstance(letters, list) or not all(isinstance(l, str) and len(l) == 1 for l in letters):
        return {'error': 'Invalid letters: letters must be a list of single-character strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive: must be a boolean.'}
    if output_format not in ['count', 'frequency', 'positions']:
        return {'error': "Invalid output_format: must be 'count', 'frequency', or 'positions'."}

    # Initialize result based on output format
    result = {}
    for letter in letters:
        result[letter] = [] if output_format == 'positions' else 0

    # Process each string in input
    for string in input:
        for letter in letters:
            count = 0
            positions = []
            for index, char in enumerate(string):
                if not case_sensitive:
                    char = char.lower()
                    letter = letter.lower()
                if char == letter:
                    count += 1
                    if output_format == 'positions':
                        positions.append(index)
            if output_format == 'count':
                result[letter] += count
            elif output_format == 'frequency':
                result[letter] += count / len(string) if len(string) > 0 else 0
            elif output_format == 'positions':
                result[letter].extend(positions)

    return result

