def artwork_info_retriever(artwork_name: str, details_required: list = ['creator'], output_format: str = 'text') -> str:
    """
    Retrieve comprehensive information about artworks and their creators.

    Parameters:
    - artwork_name (str): The name of the artwork for which information is being requested.
    - details_required (list): The specific details required about the artwork. Defaults to ['creator'].
    - output_format (str): The format of the output. Defaults to 'text'.

    Returns:
    - str: Information about the artwork in the specified format.
    """

    # Predefined data for demonstration purposes
    artwork_data = {
        'The Mud Bath': {
            'creator': 'David Bomberg',
            'year': '1914',
            'style': 'Vorticism',
            'location': 'Tate, London',
            'medium': 'Oil on canvas',
            'dimensions': '152.4 cm × 224.2 cm',
            'ownership': 'Tate',
            'historical_significance': 'A key work in the Vorticist movement'
        }
    }

    # Error handling for missing artwork name
    if not artwork_name:
        return 'Error: Artwork name is required.'

    # Check if the artwork exists in the data
    if artwork_name not in artwork_data:
        return f'Error: Information for artwork "{artwork_name}" not found.'

    # Retrieve the requested details
    artwork_info = artwork_data[artwork_name]
    result = {}
    for detail in details_required:
        if detail in artwork_info:
            result[detail] = artwork_info[detail]
        else:
            return f'Error: Detail "{detail}" is not available for artwork "{artwork_name}".'

    # Format the output based on the specified format
    if output_format == 'text':
        return ', '.join([f'{key}: {value}' for key, value in result.items()])
    elif output_format == 'json':
        import json
        return json.dumps(result)
    elif output_format == 'xml':
        import dicttoxml
        return dicttoxml.dicttoxml(result).decode()
    elif output_format == 'csv':
        import csv
        import io
        output = io.StringIO()
        writer = csv.writer(output)
        writer.writerow(result.keys())
        writer.writerow(result.values())
        return output.getvalue().strip()
    else:
        return 'Error: Unsupported output format.'

