def last_vowel_finder(input_string, case_sensitive=False, ignore_special_characters=True, consider_y_as_vowel=False, vowels_to_consider=['a', 'e', 'i', 'o', 'u', 'A', 'E', 'I', 'O', 'U'], return_position=False):
    # Validate input_string
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    # Validate vowels_to_consider
    if not isinstance(vowels_to_consider, list) or not all(isinstance(v, str) for v in vowels_to_consider):
        return {'error': 'vowels_to_consider must be a list of strings'}
    # Add 'y' to vowels if consider_y_as_vowel is True
    if consider_y_as_vowel:
        vowels_to_consider.extend(['y', 'Y'])
    # Prepare the string for processing
    if not case_sensitive:
        input_string = input_string.lower()
        vowels_to_consider = [v.lower() for v in vowels_to_consider]
    # Remove special characters if ignore_special_characters is True
    if ignore_special_characters:
        input_string = ''.join(filter(str.isalpha, input_string))
    # Find the last vowel
    last_vowel = None
    last_position = -1
    for index, char in enumerate(input_string):
        if char in vowels_to_consider:
            last_vowel = char
            last_position = index
    # Return result based on return_position
    if last_vowel is not None:
        if return_position:
            return {'last_vowel': last_vowel, 'position': last_position}
        else:
            return {'last_vowel': last_vowel}
    else:
        return {'error': 'No vowel found in the input string'}

