def enhanced_unique_character_counter(input_string, case_sensitive=False, include_non_alphabetic=False, character_set='alphabetic', ignore_characters='', detailed_output=False):
    # Validate input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if not isinstance(include_non_alphabetic, bool):
        return {'error': 'include_non_alphabetic must be a boolean'}
    if not isinstance(character_set, str):
        return {'error': 'character_set must be a string'}
    if not isinstance(ignore_characters, str):
        return {'error': 'ignore_characters must be a string'}
    if not isinstance(detailed_output, bool):
        return {'error': 'detailed_output must be a boolean'}

    # Prepare the input string based on parameters
    if not case_sensitive:
        input_string = input_string.lower()

    # Define character sets
    if character_set == 'alphabetic':
        allowed_chars = set('abcdefghijklmnopqrstuvwxyz')
    elif character_set == 'numeric':
        allowed_chars = set('0123456789')
    elif character_set == 'alphanumeric':
        allowed_chars = set('abcdefghijklmnopqrstuvwxyz0123456789')
    else:
        return {'error': 'Invalid character_set specified'}

    # Include non-alphabetic characters if specified
    if include_non_alphabetic:
        allowed_chars.update(set(input_string) - set('abcdefghijklmnopqrstuvwxyz0123456789'))

    # Remove ignored characters
    allowed_chars -= set(ignore_characters)

    # Count unique characters
    unique_chars = set(c for c in input_string if c in allowed_chars)

    # Prepare output
    if detailed_output:
        return {'unique_count': len(unique_chars), 'unique_characters': list(unique_chars)}
    else:
        return {'unique_count': len(unique_chars)}

