def extract_name_components(full_name, output_format='string', component='first_name', case_format='original'):
    # Error handling for required parameter
    if not full_name or not isinstance(full_name, str):
        return {'error': 'Invalid or missing full_name parameter.'}

    # Error handling for output_format
    if output_format not in ['string', 'json', 'array']:
        return {'error': 'Invalid output_format. Choose from string, json, or array.'}

    # Error handling for component
    if component not in ['first_name', 'middle_name', 'last_name', 'prefix', 'suffix', 'all']:
        return {'error': 'Invalid component. Choose from first_name, middle_name, last_name, prefix, suffix, or all.'}

    # Error handling for case_format
    if case_format not in ['original', 'uppercase', 'lowercase', 'titlecase']:
        return {'error': 'Invalid case_format. Choose from original, uppercase, lowercase, or titlecase.'}

    # Splitting the full name into components
    name_parts = full_name.split()
    first_name = name_parts[0] if len(name_parts) > 0 else ''
    middle_name = ' '.join(name_parts[1:-1]) if len(name_parts) > 2 else ''
    last_name = name_parts[-1] if len(name_parts) > 1 else ''

    # Selecting the component to return
    if component == 'first_name':
        result = first_name
    elif component == 'middle_name':
        result = middle_name
    elif component == 'last_name':
        result = last_name
    elif component == 'all':
        result = {'first_name': first_name, 'middle_name': middle_name, 'last_name': last_name}
    else:
