def vowel_counter(input: str, vowels=['a', 'e', 'i', 'o', 'u'], case_sensitive=False, output_format='integer', ignore_non_alphabetic=True, individual_counts=False):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not all(v in ['a', 'e', 'i', 'o', 'u', 'y'] for v in vowels):
        return {'error': 'Vowels must be one of ["a", "e", "i", "o", "u", "y"].'}

    # Prepare the input string
    if ignore_non_alphabetic:
        input = ''.join(filter(str.isalpha, input))
    if not case_sensitive:
        input = input.lower()
        vowels = [v.lower() for v in vowels]

    # Count vowels
    vowel_count = {v: 0 for v in vowels}
    total_count = 0
    for char in input:
        if char in vowels:
            vowel_count[char] += 1
            total_count += 1

    # Prepare output
    if output_format == 'integer':
        return total_count
    elif output_format == 'text':
        return f'Total vowels: {total_count}'
    elif output_format == 'detailed':
        return vowel_count if individual_counts else {'total': total_count, 'details': vowel_count}
    else:
        return {'error': 'Invalid output format specified.'}

