def extract_name_part(full_name, delimiter=' ', name_part='last', case_sensitive=True, multiple_delimiters=[' ', '-'], ignore_titles=False, ignore_suffixes=False):
    # Error handling for required parameter
    if not full_name:
        return {'error': 'The full_name parameter is required.'}

    # Define titles and suffixes to ignore if specified
    titles = ['Dr.', 'Mr.', 'Ms.', 'Mrs.'] if ignore_titles else []
    suffixes = ['Jr.', 'Sr.', 'III'] if ignore_suffixes else []

    # Split the full name using the specified delimiters
    import re
    delimiters = '|'.join(map(re.escape, multiple_delimiters))
    name_parts = re.split(delimiters, full_name)

    # Remove titles and suffixes if specified
    if ignore_titles:
        name_parts = [part for part in name_parts if part not in titles]
    if ignore_suffixes:
        name_parts = [part for part in name_parts if part not in suffixes]

    # Extract the requested name part
    if name_part == 'first':
        result = name_parts[0] if name_parts else ''
    elif name_part == 'middle':
        result = name_parts[1] if len(name_parts) > 2 else ''
    elif name_part == 'last':
        result = name_parts[-1] if name_parts else ''
    elif name_part == 'title':
        result = name_parts[0] if name_parts and name_parts[0] in titles else ''
    elif name_part == 'suffix':
        result = name_parts[-1] if name_parts and name_parts[-1] in suffixes else ''
    else:
        return {'error': 'Invalid name_part specified.'}

    # Handle case sensitivity
    if not case_sensitive:
        result = result.lower()

    return {'result': result}

