def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'count', ignore_characters: str = '', alphabetic_only: bool = True):
    # Validate output_format
    if output_format not in ['count', 'list', 'detailed']:
        return {'error': 'Invalid output_format. Choose from count, list, or detailed.'}

    # Normalize case if case_sensitive is False
    if not case_sensitive:
        input = input.lower()
        ignore_characters = ignore_characters.lower()

    # Filter out ignored characters
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Filter to alphabetic characters if alphabetic_only is True
    if alphabetic_only:
        filtered_input = ''.join([char for char in filtered_input if char.isalpha()])

    # Count occurrences of each character
    from collections import Counter
    char_count = Counter(filtered_input)

    # Identify repeated characters
    repeated_chars = {char: count for char, count in char_count.items() if count > 1}

    # Generate output based on output_format
    if output_format == 'count':
        return len(repeated_chars)
    elif output_format == 'list':
        return list(repeated_chars.keys())
    elif output_format == 'detailed':
        return repeated_chars

