def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', ignore_characters: str = '', min_repetitions: int = 2, include_non_alphabetic: bool = False):
    # Error handling for invalid inputs
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if min_repetitions < 1:
        return {'error': 'min_repetitions must be at least 1.'}
    if output_format not in ['integer', 'detailed', 'detailed_with_positions']:
        return {'error': 'Invalid output_format specified.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = ignore_characters.lower()

    # Initialize a dictionary to count occurrences of each character
    from collections import defaultdict
    letter_count = defaultdict(lambda: {'count': 0, 'positions': []})

    # Count occurrences of each character
    for index, char in enumerate(input):
        if char in ignore_characters:
            continue
        if not include_non_alphabetic and not char.isalpha():
            continue
        letter_count[char]['count'] += 1
        letter_count[char]['positions'].append(index)

    # Filter letters based on min_repetitions
    repeated_letters = {char: info for char, info in letter_count.items() if info['count'] >= min_repetitions}

    # Generate output based on the specified format
    if output_format == 'integer':
        return len(repeated_letters)
    elif output_format == 'detailed':
        return {char: info['count'] for char, info in repeated_letters.items()}
    elif output_format == 'detailed_with_positions':
        return repeated_letters

