def character_counter(input_string, characters_to_count, case_sensitive=True, ignore_whitespace=False, detailed_statistics=False):
    # Validate input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(characters_to_count, list) or len(characters_to_count) == 0:
        return {'error': 'characters_to_count must be a non-empty list of strings'}
    if not all(isinstance(char, str) for char in characters_to_count):
        return {'error': 'All items in characters_to_count must be strings'}

    # Prepare the input string based on options
    if not case_sensitive:
        input_string = input_string.lower()
        characters_to_count = [char.lower() for char in characters_to_count]
    if ignore_whitespace:
        input_string = ''.join(input_string.split())

    # Count occurrences
    counts = {char: 0 for char in characters_to_count}
    for char in characters_to_count:
        counts[char] = input_string.count(char)

    # Prepare detailed statistics if required
    if detailed_statistics:
        total_chars = len(input_string)
        statistics = {char: {'count': count, 'percentage': (count / total_chars) * 100 if total_chars > 0 else 0} for char, count in counts.items()}
        return {'statistics': statistics}

    return {'counts': counts}

