def count_repeated_characters(input: str, case_sensitive: bool = False, character_types: list = ['letters'], repetition_threshold: int = 2, output_format: str = 'integer'):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Must be a boolean.'}
    if not isinstance(character_types, list) or not all(isinstance(ct, str) for ct in character_types):
        return {'error': 'Invalid character_types. Must be a list of strings.'}
    if not isinstance(repetition_threshold, int) or repetition_threshold < 1:
        return {'error': 'Invalid repetition_threshold. Must be a positive integer.'}
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of ["integer", "list", "detailed"].'}

    # Normalize input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter characters based on character types
    filtered_input = ''
    for char in input:
        if 'letters' in character_types and char.isalpha():
            filtered_input += char
        elif 'digits' in character_types and char.isdigit():
            filtered_input += char
        elif 'symbols' in character_types and not char.isalnum():
            filtered_input += char

    # Count character occurrences
    from collections import Counter
    char_count = Counter(filtered_input)

    # Filter characters by repetition threshold
    repeated_chars = {char: count for char, count in char_count.items() if count >= repetition_threshold}

    # Format output
    if output_format == 'integer':
        return len(repeated_chars)
    elif output_format == 'list':
        return list(repeated_chars.keys())
    elif output_format == 'detailed':
        return repeated_chars

