def count_letters(input, ignore_characters=None, ignore_position=None, case_sensitive=False, character_type='all', output_format='integer'):
    # Validate input
    if not isinstance(input, list) or len(input) < 1 or len(input) > 20:
        return {'error': 'Input must be a list of 1 to 20 strings.'}
    if ignore_characters is not None and not isinstance(ignore_characters, list):
        return {'error': 'ignore_characters must be a list of strings.'}
    if ignore_position is not None and not isinstance(ignore_position, list):
        return {'error': 'ignore_position must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if character_type not in ['all', 'vowels', 'consonants']:
        return {'error': "character_type must be 'all', 'vowels', or 'consonants'."}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': "output_format must be 'integer', 'text', or 'detailed'."}

    # Define helper functions
    def is_vowel(char):
        return char.lower() in 'aeiou'

    def is_consonant(char):
        return char.isalpha() and not is_vowel(char)

    # Initialize count
    total_count = 0

    # Process each string in input
    for string in input:
        # Apply case sensitivity
        if not case_sensitive:
            string = string.lower()

        # Initialize character list
        characters = list(string)

        # Apply ignore_characters
        if ignore_characters:
            characters = [char for char in characters if char not in ignore_characters]

        # Apply ignore_position
        if ignore_position:
            if 'first' in ignore_position and characters:
                characters.pop(0)
            if 'last' in ignore_position and characters:
                characters.pop(-1)
            if 'middle' in ignore_position and len(characters) > 2:
                middle_index = len(characters) // 2
                characters.pop(middle_index)

        # Count based on character_type
        for char in characters:
            if character_type == 'all':
                total_count += 1
            elif character_type == 'vowels' and is_vowel(char):
                total_count += 1
