    if not isinstance(ignore_ranges, list) or not all(isinstance(r, dict) and 'start' in r and 'end' in r for r in ignore_ranges):
        return {'error': 'Ignore ranges must be a list of dictionaries with "start" and "end" keys.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case sensitive must be a boolean value.'}
    if output_format not in ['integer', 'text', 'json']:
        return {'error': 'Output format must be "integer", "text", or "json".'}

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [c.lower() for c in ignore_characters]

    # Initialize count
    count = 0

    # Iterate over each character in the input string
    for i, char in enumerate(input):
        # Check if character should be ignored
        if char in ignore_characters:
            continue
        # Check if position should be ignored
        if ('first' in ignore_position and i == 0) or ('last' in ignore_position and i == len(input) - 1):
            continue
        # Check if character is in an ignored range
        if any(r['start'] <= i <= r['end'] for r in ignore_ranges):
            continue
        # Increment count
        count += 1

    # Format output
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f'The total number of characters is {count}.'
    elif output_format == 'json':
        return {'count': count}

