def extract_last_name(full_name: str, name_format: str = 'western', delimiter: str = ' ', include_middle_names: bool = False, handle_titles: bool = False, multiple_delimiters: list = None) -> str:
    """
    Extracts the last name from a full name string based on the specified format and delimiters.
    """
    # Error handling for required parameter
    if not full_name:
        raise ValueError("The 'full_name' parameter is required.")

    # Default multiple delimiters to a single space if not provided
    if multiple_delimiters is None:
        multiple_delimiters = [delimiter]

    # Handle titles if specified
    if handle_titles:
        titles = ['Dr.', 'Mr.', 'Ms.', 'Mrs.', 'Miss']
        for title in titles:
            if full_name.startswith(title):
                full_name = full_name[len(title):].strip()

    # Split the full name based on the provided delimiters
    import re
    delimiter_pattern = '|'.join(map(re.escape, multiple_delimiters))
    name_parts = re.split(delimiter_pattern, full_name)

    # Determine the last name based on the name format
    if name_format == 'western':
        last_name = name_parts[-1]
    elif name_format == 'eastern':
        last_name = name_parts[0]
    elif name_format == 'arabic':
        last_name = name_parts[-1]
    elif name_format == 'hispanic':
        last_name = name_parts[-2] if len(name_parts) > 1 else name_parts[-1]
    elif name_format == 'custom':
        last_name = name_parts[-1]  # Custom logic can be added here
    else:
        raise ValueError("Unsupported 'name_format' provided.")

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        last_name = ' '.join(name_parts[1:])

    return last_name

