def string_length_counter(input, ignore_characters=[], ignore_case_sensitive=False, ignore_position=[], ignore_indices=[], output_format='integer'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate ignore_indices
    if not all(isinstance(index, int) for index in ignore_indices):
        return {'error': 'All ignore_indices must be integers.'}

    # Initialize variables
    length = 0
    ignored_elements = []

    # Normalize case if ignore_case_sensitive is True
    if ignore_case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Iterate over each character in the input string
    for i, char in enumerate(input):
        # Check if character should be ignored
        if char in ignore_characters:
            ignored_elements.append((i, char, 'character'))
            continue
        if i in ignore_indices:
            ignored_elements.append((i, char, 'index'))
            continue
        if ('first' in ignore_position and i == 0) or \
           ('last' in ignore_position and i == len(input) - 1) or \
           ('even' in ignore_position and i % 2 == 0) or \
           ('odd' in ignore_position and i % 2 != 0):
            ignored_elements.append((i, char, 'position'))
            continue
        # Increment length for non-ignored characters
        length += 1

    # Return result based on output_format
    if output_format == 'integer':
        return length
    elif output_format == 'text':
        return f'The total number of characters is {length}.'
    elif output_format == 'detailed':
        return {
            'count': length,
            'ignored': ignored_elements
        }
    else:
        return {'error': 'Invalid output_format specified.'}

