def consonant_counter(input, ignore_characters=None, ignore_position=None, ignore_range=None, case_sensitive=False, output_format='integer', output_verbosity='summary'):
    # Validate input
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if ignore_characters and not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'All ignore_characters must be strings.'}
    if ignore_position and not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position value.'}
    if ignore_range:
        for r in ignore_range:
            if not isinstance(r, dict) or 'start' not in r or 'end' not in r:
                return {'error': 'Each ignore_range must be a dictionary with start and end keys.'}
            if not (0 <= r['start'] <= r['end'] < len(input)):
                return {'error': 'Ignore range indices are out of bounds.'}

    # Define consonants
    consonants = 'bcdfghjklmnpqrstvwxyz'
    if not case_sensitive:
        consonants += consonants.upper()

    # Initialize count
    count = 0
    ignored_details = {'characters': [], 'positions': []}

    # Iterate over the input string
    for i, char in enumerate(input):
        # Check ignore conditions
        if ignore_characters and char in ignore_characters:
            ignored_details['characters'].append(char)
            continue
        if ignore_position:
            if 'first' in ignore_position and i == 0:
                ignored_details['positions'].append('first')
                continue
            if 'last' in ignore_position and i == len(input) - 1:
                ignored_details['positions'].append('last')
                continue
        if ignore_range:
            if any(r['start'] <= i <= r['end'] for r in ignore_range):
                ignored_details['positions'].append(f'range({i})')
                continue

        # Count consonants
        if char in consonants:
            count += 1

    # Prepare output
    if output_format == 'text':
        result = f'There are {count} consonants.'
    else:
        result = count

    if output_verbosity == 'detailed':
        return {'count': result, 'ignored_details': ignored_details}
    else:
        return {'count': result}

