        target_letters = [letter.lower() for letter in target_letters]

    if ignore_non_alphabetic:
        input_string = ''.join(filter(str.isalpha, input_string))

    # Count frequencies
    frequency = {letter: input_string.count(letter) for letter in target_letters}

