def character_performer_lookup(character_name, media_type='movie', version=None, output_format='name_only', release_year=None, performer_nationality=None):
    """
    Identifies the performer(s) of a given character across diverse media.

    Parameters:
    - character_name (str): The name of the character whose performer is being queried.
    - media_type (str): The type of media in which the character appears. Defaults to 'movie'.
    - version (str): The specific version or adaptation of the media, if applicable.
    - output_format (str): The format of the output. Defaults to 'name_only'.
    - release_year (int): The year of release of the media.
    - performer_nationality (str): Filter results by the nationality of the performer.

    Returns:
    - str: The name of the performer or detailed information based on the output_format.
    """
    # Error handling for required parameter
    if not character_name:
        return 'Error: character_name is required.'

    # Simulated database of character performers
    performers_db = {
        'Terminator': {
            'movie': {
                'Arnold Schwarzenegger': {'release_year': 1984, 'nationality': 'Austrian-American'}
            }
        }
    }

    # Check if character exists in the database
    if character_name not in performers_db:
        return 'Error: Character not found.'

    # Check if media type exists for the character
    media_data = performers_db[character_name].get(media_type)
    if not media_data:
        return 'Error: Media type not found for the character.'

    # Filter by release year and nationality if provided
    for performer, details in media_data.items():
        if release_year and details.get('release_year') != release_year:
            continue
        if performer_nationality and details.get('nationality') != performer_nationality:
            continue

        # Return based on output format
        if output_format == 'name_only':
            return performer
        elif output_format == 'detailed':
            return f"{performer} (Year: {details.get('release_year')}, Nationality: {details.get('nationality')})"
        elif output_format == 'full_profile':
            return f"Performer: {performer}, Year: {details.get('release_year')}, Nationality: {details.get('nationality')}"
        else:
            return 'Error: Invalid output format.'

    return 'Error: No matching performer found.'

