def extract_last_name(full_name: str, consider_suffix: bool = False, hyphenated_names: bool = True, compound_last_names: bool = True, cultural_name_order: str = 'Western', extract_middle_name: bool = False) -> str:
    """
    Extracts the last name from a full name string, considering various name structures and cultural variations.
    """
    if not isinstance(full_name, str) or not full_name.strip():
        raise ValueError("Invalid input: 'full_name' must be a non-empty string.")

    # Split the full name into parts
    name_parts = full_name.split()

    # Handle cultural name order
    if cultural_name_order == 'Eastern':
        # In Eastern order, the last name is typically the first element
        last_name = name_parts[0]
    else:
        # Default to Western order where the last name is the last element
        last_name = name_parts[-1]

    # Handle hyphenated names
    if hyphenated_names and '-' in last_name:
        last_name = '-'.join(last_name.split('-'))

    # Handle compound last names
    if compound_last_names:
        # Check for common compound last name indicators
        compound_indicators = ['de', 'la', 'van', 'von']
        for i in range(len(name_parts) - 1, 0, -1):
            if name_parts[i - 1].lower() in compound_indicators:
                last_name = ' '.join(name_parts[i - 1:])
                break

    # Consider suffixes
    if consider_suffix and len(name_parts) > 1:
        suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV']
        if name_parts[-1] in suffixes:
            last_name = ' '.join(name_parts[-2:])

    # Extract middle name if required
    middle_name = ''
    if extract_middle_name and len(name_parts) > 2:
        middle_name = ' '.join(name_parts[1:-1])

    # Return the result
    return f"{middle_name} {last_name}".strip()

