def first_letter_extractor(input: str, ignore_whitespace: bool = True, output_format: str = 'character', extract_mode: str = 'first_letter', handle_non_alphabetic: str = 'ignore', replacement_character: str = '') -> str:
    # Error handling for invalid input types
    if not isinstance(input, str):
        return 'Error: Input must be a string.'
    if extract_mode not in ['first_letter', 'first_letter_each_word']:
        return 'Error: Invalid extract mode.'
    if output_format not in ['character', 'uppercase', 'lowercase', 'titlecase']:
        return 'Error: Invalid output format.'
    if handle_non_alphabetic not in ['ignore', 'include', 'replace']:
        return 'Error: Invalid handle_non_alphabetic option.'
    if handle_non_alphabetic == 'replace' and not replacement_character:
        return 'Error: Replacement character must be provided when handle_non_alphabetic is set to replace.'

    # Trim leading whitespace if ignore_whitespace is True
    if ignore_whitespace:
        input = input.lstrip()

    # Extract the first letter based on the extract_mode
    if extract_mode == 'first_letter':
        first_char = input[0] if input else ''
    elif extract_mode == 'first_letter_each_word':
        first_char = ''.join(word[0] for word in input.split() if word)

    # Handle non-alphabetic characters
    if handle_non_alphabetic == 'ignore':
        first_char = ''.join(c for c in first_char if c.isalpha())
    elif handle_non_alphabetic == 'replace':
        first_char = ''.join(c if c.isalpha() else replacement_character for c in first_char)

    # Format the output
    if output_format == 'uppercase':
        first_char = first_char.upper()
    elif output_format == 'lowercase':
        first_char = first_char.lower()
    elif output_format == 'titlecase':
        first_char = first_char.title()

    return first_char

