        return {'error': 'Invalid output format. Supported formats are array, string, json.'}
    if sort_algorithm not in ['default', 'reverse']:
        return {'error': 'Invalid sort algorithm. Supported algorithms are default, reverse.'}

    # Prepare the string for sorting
    if ignore_spaces:
        input = input.replace(' ', '')
    if not case_sensitive:
        input = input.lower()

    # Sort the string
    sorted_chars = sorted(input, reverse=(sort_algorithm == 'reverse'))

    # Prepare the output
    if output_format == 'array':
        result = sorted_chars
    elif output_format == 'string':
        result = ''.join(sorted_chars)
    elif output_format == 'json':
        result = {'sorted': sorted_chars}

    # Include original string if required
    if include_original:
        if output_format == 'json':
            result['original'] = input
        else:
            result = {'original': input, 'sorted': result}

    return result

