def count_repeated_characters(input: str, case_sensitive: bool = False, character_types: list = ['letters'], output_format: str = 'integer'):
    # Error handling for input types
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Case_sensitive must be a boolean.'}
    if not isinstance(character_types, list) or not all(isinstance(ct, str) for ct in character_types):
        return {'error': 'Character_types must be a list of strings.'}
    if output_format not in ['integer', 'list', 'detailed']:
        return {'error': 'Output_format must be one of ["integer", "list", "detailed"].'}

    # Normalize input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Filter characters based on character_types
    filtered_input = ''
    for char in input:
        if 'letters' in character_types and char.isalpha():
            filtered_input += char
        elif 'digits' in character_types and char.isdigit():
            filtered_input += char
        elif 'special' in character_types and not char.isalnum():
            filtered_input += char

    # Count repeated characters
    from collections import Counter
    char_count = Counter(filtered_input)
    repeated_chars = {char: count for char, count in char_count.items() if count > 1}

    # Prepare output based on output_format
    if output_format == 'integer':
        return len(repeated_chars)
    elif output_format == 'list':
        return list(repeated_chars.keys())
    elif output_format == 'detailed':
        return repeated_chars

