    """
    Retrieve detailed cast information for a specified movie.

    :param movie_title: The title of the movie for which the performer or cast information is requested.
    :param performer_role: The role of the performer to be retrieved. Defaults to 'lead'.
    :param title_format: The format of the movie title provided. Defaults to 'exact'.
    :param release_year: The year the movie was released. Used to filter search results.
    :param genre: The genre of the movie. Used to filter search results.
    :param performer_name: The name of a specific performer to search for within the movie's cast.
    :return: Detailed cast information or specific performer details.
    """
    # Simulated database of movies and performers
    movie_database = {
        'Terminator': {
            'release_year': 1984,
            'genre': 'Action',
            'cast': {
                'lead': 'Arnold Schwarzenegger',
                'supporting': ['Linda Hamilton', 'Michael Biehn']
