        }
    }

    # Error handling for invalid parameters
    if performer_role not in ['lead', 'supporting', 'all']:
        return {'error': 'Invalid performer role specified.'}
    if title_format not in ['exact', 'partial']:
        return {'error': 'Invalid title format specified.'}

    # Search logic based on title format
    if title_format == 'exact':
        movie_info = movie_database.get(movie_title)
    else:  # partial match
        movie_info = next((info for title, info in movie_database.items() if movie_title in title), None)

