def extract_last_letter(names, output_format='character', case_sensitive=False, filter_characters=None):
    # Validate input parameters
    if not isinstance(names, list) or len(names) == 0:
        raise ValueError("'names' must be a non-empty list of strings.")
    if output_format not in ['character', 'text', 'json', 'csv']:
        raise ValueError("Invalid 'output_format'. Must be one of: 'character', 'text', 'json', 'csv'.")
    if filter_characters is not None and not all(isinstance(c, str) and len(c) == 1 for c in filter_characters):
        raise ValueError("'filter_characters' must be a list of single-character strings.")

    # Process each name to extract the last letter
    results = []
    for name in names:
        if not name:  # Handle empty string
            results.append('')
            continue
        last_letter = name[-1]
        if not case_sensitive:
            last_letter = last_letter.lower()
        if filter_characters and last_letter in filter_characters:
            results.append('')
        else:
            results.append(last_letter)

    # Format the output based on 'output_format'
    if output_format == 'character':
        return results
    elif output_format == 'text':
        return ' '.join(results)
    elif output_format == 'json':
        import json
        return json.dumps(results)
    elif output_format == 'csv':
        return ','.join(results)

