def last_letter_extractor_v2(input: str, ignore_special_characters: bool = False, ignore_digits: bool = False, ignore_whitespace: bool = False, output_format: str = 'character', multiple_inputs: list = None):
    # Validate output_format
    if output_format not in ['character', 'ascii', 'unicode']:
        return {'error': 'Invalid output format specified.'}

    # Determine the strings to process
    strings_to_process = multiple_inputs if multiple_inputs else [input]

    results = []

    for string in strings_to_process:
        # Start from the end of the string
        for char in reversed(string):
            # Check for ignore conditions
            if ignore_whitespace and char.isspace():
                continue
            if ignore_digits and char.isdigit():
                continue
            if ignore_special_characters and not char.isalnum():
                continue

            # Determine the output format
            if output_format == 'character':
                results.append(char)
            elif output_format == 'ascii':
                results.append(ord(char))
            elif output_format == 'unicode':
                results.append(f'U+{ord(char):04X}')
            break
        else:
            # If no valid character is found
            results.append(None)

    # Return single result if only one input was processed
    return results[0] if len(results) == 1 else results

