def count_letters(input, ignore_characters=[], ignore_position=[], output_format='integer', case_sensitive=False, character_type='all'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Validate ignore_characters type
    if not isinstance(ignore_characters, list) or not all(isinstance(char, str) for char in ignore_characters):
        return {'error': 'Invalid ignore_characters type. Must be a list of strings.'}

    # Validate ignore_position type
    if not isinstance(ignore_position, list) or not all(pos in ['first', 'last'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position value. Must be a list containing "first" or "last".'}

    # Validate output_format
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be "integer", "text", or "detailed".'}

    # Validate case_sensitive
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive value. Must be a boolean.'}

    # Validate character_type
    if character_type not in ['all', 'vowels', 'consonants']:
        return {'error': 'Invalid character_type. Must be "all", "vowels", or "consonants".'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Define vowels and consonants
    vowels = 'aeiou'
    consonants = 'bcdfghjklmnpqrstvwxyz'

    # Filter input based on character_type
    if character_type == 'vowels':
        input = ''.join([char for char in input if char in vowels])
    elif character_type == 'consonants':
        input = ''.join([char for char in input if char in consonants])

    # Remove ignored characters
    input = ''.join([char for char in input if char not in ignore_characters])

    # Remove characters based on ignore_position
    if 'first' in ignore_position and input:
        input = input[1:]
    if 'last' in ignore_position and input:
        input = input[:-1]

    # Count the letters
    letter_count = len(input)

    # Return the result based on output_format
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The number of letters is {letter_count}.'
    elif output_format == 'detailed':
        return {
            'total_letters': letter_count,
            'details': {
                'vowels': sum(1 for char in input if char in vowels),
                'consonants': sum(1 for char in input if char in consonants)
            }
        }

