def extract_last_name(full_name, delimiter=' ', ignore_case=False, output_format='string', include_middle_names=False, suffix_handling='exclude', cultural_format='western'):
    # Error handling for required parameter
    if not full_name or not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a non-empty string.'}

    # Normalize case if ignore_case is True
    if ignore_case:
        full_name = full_name.lower()

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Handle suffixes based on suffix_handling parameter
    if suffix_handling == 'exclude':
        # Common suffixes to exclude
        suffixes = ['Jr.', 'Sr.', 'II', 'III', 'IV']
        name_parts = [part for part in name_parts if part not in suffixes]
    elif suffix_handling == 'separate':
        # Separate suffix if present
        suffix = name_parts[-1] if name_parts[-1] in ['Jr.', 'Sr.', 'II', 'III', 'IV'] else None
        if suffix:
            name_parts = name_parts[:-1]

    # Determine last name based on cultural format
    if cultural_format == 'western':
        last_name = name_parts[-1]
    elif cultural_format == 'eastern':
        last_name = name_parts[0]
    else:  # custom
        last_name = name_parts[-1]  # Default to western style for custom

    # Include middle names if specified
    if include_middle_names and len(name_parts) > 2:
        middle_names = name_parts[1:-1]
        last_name = ' '.join(middle_names + [last_name])

    # Return the last name in the specified output format
    if output_format == 'array':
        return {'result': [last_name]}
    else:
        return {'result': last_name}

