    # Validate input
    if not isinstance(input, str):
        raise ValueError("Input must be a string.")
    if ignore_characters and not all(isinstance(char, str) for char in ignore_characters):
        raise ValueError("All ignore_characters must be strings.")
    if specific_indices and not all(isinstance(index, int) for index in specific_indices):
