    if ignore_case:
        input = input.lower()
        consonants = consonants.lower()

    # Initialize variables
    count = 0
    detailed_report = {}

    # Process each character in the input
    for i, char in enumerate(input):
        # Check if character should be ignored
        if ignore_characters and char in ignore_characters:
            continue
        if ignore_position:
            if 'first' in ignore_position and i == 0:
                continue
            if 'last' in ignore_position and i == len(input) - 1:
                continue
            if 'specific' in ignore_position and specific_indices and i in specific_indices:
                continue

        # Check if character is a consonant
        if char in consonants:
            count += 1
            if output_format == 'detailed_report':
                if char in detailed_report:
                    detailed_report[char] += 1
                else:
                    detailed_report[char] = 1

    # Return result based on output_format
    if output_format == 'integer':
        return count
    elif output_format == 'text':
        return f"The number of consonants is {count}."
    elif output_format == 'detailed_report':
        return detailed_report
    elif output_format == 'visual':
