def extract_last_letter(input, ignore_whitespace=True, case_sensitive=True, num_characters=1, include_special_characters=True, validation='none'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Validate num_characters
    if not isinstance(num_characters, int) or num_characters < 1:
        return {'error': 'num_characters must be a positive integer.'}

    # Handle validation
    if validation == 'alpha' and not input.isalpha():
        return {'error': 'Input must contain only alphabetic characters.'}
    elif validation == 'alphanumeric' and not input.isalnum():
        return {'error': 'Input must contain only alphanumeric characters.'}

    # Ignore trailing whitespace if specified
    if ignore_whitespace:
        input = input.rstrip()

    # Extract the last character(s)
    if len(input) < num_characters:
        return {'error': 'Input is shorter than the number of characters to extract.'}

    result = input[-num_characters:]

    # Handle case sensitivity
    if not case_sensitive:
        result = result.lower()

    # Handle special characters
    if not include_special_characters:
        result = ''.join(filter(str.isalnum, result))

    return {'result': result}

