def extract_character(input: str, position: str = 'last', index: int = None, range: list = None, handle_short_strings: str = 'ignore') -> str:
    """
    Extracts specific characters from a string based on the given position.

    :param input: The string from which to extract characters.
    :param position: The position of the character to extract ('first', 'last', 'index').
    :param index: The zero-based index of the character to extract, used when position is 'index'.
    :param range: An array specifying the start and end indices for extracting a range of characters.
    :param handle_short_strings: Specifies how to handle short strings ('ignore', 'pad', 'truncate').
    :return: The extracted character(s) or an error message.
    """
    if not input:
        return 'Error: Input string must be non-empty.'

    if position == 'first':
        return input[0]
    elif position == 'last':
        return input[-1]
    elif position == 'index':
        if index is None or index < 0 or index >= len(input):
            return 'Error: Invalid index for extraction.'
        return input[index]
    elif position == 'range':
        if range is None or len(range) != 2:
            return 'Error: Range must be a list of two integers.'
        start, end = range
        if start < 0 or end >= len(input) or start > end:
            return 'Error: Invalid range for extraction.'
        return input[start:end+1]
    else:
        return 'Error: Invalid position specified.'

