    elif output_format == 'ascii':
        return str(ord(first_char))
    elif output_format == 'unicode':
        return f'U+{ord(first_char):04X}'
    elif output_format == 'hex':
        return hex(ord(first_char))
    else:
        raise ValueError('Invalid output format specified.')

