def char_to_binary(input: str, encoding: str = 'ASCII', separator: str = ' ', output_format: str = 'string', case_sensitive: bool = True, binary_length: int = 8):
    """
    Convert a character or string into its binary representation.

    Parameters:
    - input (str): The character or string to be converted.
    - encoding (str): The encoding scheme to use. Defaults to 'ASCII'.
    - separator (str): The separator between binary codes. Defaults to a space.
    - output_format (str): The format of the output. Defaults to 'string'.
    - case_sensitive (bool): Whether the conversion is case-sensitive. Defaults to True.
    - binary_length (int): The length of the binary output for each character. Defaults to 8 bits.

    Returns:
    - str or list: The binary representation of the input.
    """
    # Validate encoding
    if encoding not in ['ASCII', 'UTF-8', 'UTF-16', 'UTF-32']:
        return {'error': 'Unsupported encoding scheme.'}

    # Validate output_format
    if output_format not in ['string', 'array']:
        return {'error': 'Invalid output format.'}

    # Validate binary_length
    if not isinstance(binary_length, int) or binary_length <= 0:
        return {'error': 'Binary length must be a positive integer.'}

    # Convert input to binary
    if not case_sensitive:
        input = input.lower()

    binary_codes = []
    for char in input:
        if encoding == 'ASCII':
            binary_code = format(ord(char), 'b').zfill(binary_length)
        else:
            # For simplicity, only ASCII is implemented here
            return {'error': 'Encoding not implemented.'}
        binary_codes.append(binary_code)

    # Format output
    if output_format == 'string':
        return separator.join(binary_codes)
    elif output_format == 'array':
        return binary_codes

