def vowel_counter(input_string, vowels=['a', 'e', 'i', 'o', 'u'], case_sensitive=False, language='en', detailed_count=False, ignore_special_characters=True, optimize_for_large_input=False):
    # Error handling for required parameter
    if not isinstance(input_string, str):
        return {'error': 'Invalid input: input_string must be a string.'}

    # Ensure vowels is a list of strings
    if not all(isinstance(v, str) for v in vowels):
        return {'error': 'Invalid input: vowels must be a list of strings.'}

    # Normalize input string based on case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        vowels = [v.lower() for v in vowels]

    # Initialize vowel count dictionary
    vowel_count = {v: 0 for v in vowels}

    # Count vowels
    for char in input_string:
        if ignore_special_characters and not char.isalnum():
            continue
        if char in vowels:
            vowel_count[char] += 1

    # Prepare the result
    if detailed_count:
        return {'vowel_count': vowel_count}
    else:
        total_vowels = sum(vowel_count.values())
        return {'total_vowels': total_vowels}

