def consonant_counter(input: str, consider_hyphen: bool = False, custom_consonants: list = None, output_format: str = 'integer', case_sensitive: bool = False, include_numbers: bool = False, language_code: str = 'en'):
    # Default consonants
    default_consonants = ['b', 'c', 'd', 'f', 'g', 'h', 'j', 'k', 'l', 'm', 'n', 'p', 'q', 'r', 's', 't', 'v', 'w', 'x', 'y', 'z']
    consonants = custom_consonants if custom_consonants else default_consonants

    # Adjust for case sensitivity
    if not case_sensitive:
        input = input.lower()
        consonants = [c.lower() for c in consonants]

    # Initialize consonant count
    consonant_count = 0
    consonant_positions = []

    # Iterate over the input string
    for index, char in enumerate(input):
        if char in consonants or (consider_hyphen and char == '-'):
            consonant_count += 1
            consonant_positions.append(index)
        elif include_numbers and char.isdigit():
            consonant_count += 1
            consonant_positions.append(index)

    # Return based on output format
    if output_format == 'integer':
        return consonant_count
    elif output_format == 'text':
        return f'There are {consonant_count} consonants.'
    elif output_format == 'list':
        return [char for char in input if char in consonants]
    elif output_format == 'positions':
        return consonant_positions
    else:
        raise ValueError('Invalid output format specified.')

