def longest_alphabetical_substring(input_string, case_sensitive=False, output_format='substring', custom_alphabet=None, ignore_non_alphabetic=True):
    # Validate input_string
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}

    # Validate case_sensitive
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}

    # Validate output_format
    if output_format not in ['substring', 'length', 'both']:
        return {'error': "output_format must be one of ['substring', 'length', 'both']"}

    # Validate custom_alphabet
    if custom_alphabet is not None and not isinstance(custom_alphabet, str):
        return {'error': 'custom_alphabet must be a string or None'}

    # Validate ignore_non_alphabetic
    if not isinstance(ignore_non_alphabetic, bool):
        return {'error': 'ignore_non_alphabetic must be a boolean'}

    # Set default alphabet
    if custom_alphabet is None:
        alphabet = 'abcdefghijklmnopqrstuvwxyz'
    else:
        alphabet = custom_alphabet

    # Adjust for case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()
        alphabet = alphabet.lower()

    # Initialize variables
    longest_substring = ''
    current_substring = ''
    previous_char = ''

    # Iterate through the input string
    for char in input_string:
        if ignore_non_alphabetic and char not in alphabet:
            continue

        if previous_char == '' or alphabet.index(char) >= alphabet.index(previous_char):
            current_substring += char
        else:
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
            current_substring = char
        previous_char = char

    # Final check for the last substring
    if len(current_substring) > len(longest_substring):
        longest_substring = current_substring

    # Prepare the output
    if output_format == 'substring':
        return longest_substring
    elif output_format == 'length':
        return len(longest_substring)
    elif output_format == 'both':
        return {'substring': longest_substring, 'length': len(longest_substring)}

