    # Error handling for empty input
    if not input:
        if handle_empty == 'error':
            return 'Error: Input string is empty.'
        elif handle_empty == 'empty':
            return ''
        elif handle_empty == 'null':
            return None
        elif handle_empty == 'ignore':
            return ''

    # Adjust input based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Handle non-alphabetic characters
    if non_alpha_handling == 'exclude':
        input = ''.join(filter(str.isalpha, input))
        if not input:
            return 'Error: No alphabetic characters to extract.'
    elif non_alpha_handling == 'error' and not input[0].isalpha():
        return 'Error: Input starts with a non-alphabetic character.'

    # Extract the specified number of characters
    return input[:character_count]

