def enhanced_combinations(input_string, combination_length=2, case_sensitive=True, output_format='count', filter=None, sort_order='none'):
    import itertools
    import re

    # Error handling for input types
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(combination_length, int) or combination_length < 1:
        return {'error': 'combination_length must be an integer greater than 0'}
    if output_format not in ['list', 'count', 'set']:
        return {'error': 'Invalid output_format'}
    if sort_order not in ['none', 'ascending', 'descending']:
        return {'error': 'Invalid sort_order'}

    # Adjust case sensitivity
    if not case_sensitive:
        input_string = input_string.lower()

    # Generate combinations
    combinations = [''.join(comb) for comb in itertools.combinations(input_string, combination_length)]

    # Apply filter if provided
    if filter:
        pattern = re.compile(filter)
        combinations = [comb for comb in combinations if pattern.match(comb)]

    # Sort combinations if required
    if sort_order == 'ascending':
        combinations.sort()
    elif sort_order == 'descending':
        combinations.sort(reverse=True)

    # Format output
    if output_format == 'list':
        return combinations
    elif output_format == 'set':
        return set(combinations)
    elif output_format == 'count':
        return len(set(combinations))

