def letter_counter(input, ignore_characters=None, ignore_position=None, case_sensitive=False, character_type='all', output_format='integer'):
    # Validate input
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if ignore_characters and not all(isinstance(c, str) for c in ignore_characters):
        return {'error': 'Invalid ignore_characters: must be a list of strings.'}
    if ignore_position and not all(pos in ['first', 'last', 'middle'] for pos in ignore_position):
        return {'error': 'Invalid ignore_position: must be a list containing "first", "last", or "middle".'}
    if character_type not in ['all', 'vowels', 'consonants']:
        return {'error': 'Invalid character_type: must be "all", "vowels", or "consonants".'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be "integer", "text", or "detailed".'}

    # Define helper functions
    def is_vowel(c):
        return c.lower() in 'aeiou'

    def is_consonant(c):
        return c.isalpha() and not is_vowel(c)

    # Initialize count
    total_count = 0

    # Process each string in input
    for string in input:
        # Adjust case sensitivity
        if not case_sensitive:
            string = string.lower()

        # Filter characters
        filtered_string = ''.join(c for c in string if not ignore_characters or c not in ignore_characters)

        # Ignore positions
        if ignore_position:
            if 'first' in ignore_position and len(filtered_string) > 0:
                filtered_string = filtered_string[1:]
            if 'last' in ignore_position and len(filtered_string) > 0:
                filtered_string = filtered_string[:-1]
            if 'middle' in ignore_position and len(filtered_string) > 2:
                filtered_string = filtered_string[0] + filtered_string[1:-1].replace('', '') + filtered_string[-1]

        # Count characters based on type
        for c in filtered_string:
            if character_type == 'all' or (character_type == 'vowels' and is_vowel(c)) or (character_type == 'consonants' and is_consonant(c)):
                total_count += 1

    # Format output
    if output_format == 'integer':
        return total_count
