def character_counter(input: str, ignore_characters: list = None, ignore_whitespace: bool = False, case_sensitive: bool = True, count_types: list = None, output_format: str = 'integer'):
    # Validate input types
    if not isinstance(input, str):
        return {'error': 'Invalid input type, expected a string.'}
    if ignore_characters is not None and not all(isinstance(ch, str) for ch in ignore_characters):
        return {'error': 'Invalid ignore_characters type, expected a list of strings.'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'Invalid ignore_whitespace type, expected a boolean.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type, expected a boolean.'}
    if count_types is not None and not all(ct in ['letters', 'digits', 'symbols'] for ct in count_types):
        return {'error': 'Invalid count_types value, expected a list containing any of ["letters", "digits", "symbols"].'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format value, expected one of ["integer", "text", "detailed"].'}

    # Default behavior if count_types is not specified
    if count_types is None:
        count_types = ['letters', 'digits', 'symbols']

    # Initialize counters
    letter_count = 0
    digit_count = 0
    symbol_count = 0

    # Process the input string
    for char in input:
        if ignore_whitespace and char.isspace():
            continue
        if ignore_characters and char in ignore_characters:
            continue
        if not case_sensitive:
            char = char.lower()

        if 'letters' in count_types and char.isalpha():
            letter_count += 1
        elif 'digits' in count_types and char.isdigit():
            digit_count += 1
        elif 'symbols' in count_types and not char.isalnum():
            symbol_count += 1

    # Prepare the output
    if output_format == 'integer':
        return letter_count + digit_count + symbol_count
    elif output_format == 'text':
        return f'Total count: {letter_count + digit_count + symbol_count}'
    elif output_format == 'detailed':
        return {
            'letters': letter_count,
            'digits': digit_count,
            'symbols': symbol_count
        }

