def extract_last_name(full_name, delimiters=[' '], name_format='first_last', handle_special_characters=False, normalize_last_name=False):
    # Error handling for required parameter
    if not isinstance(full_name, str) or not full_name:
        return {'error': 'Invalid full_name parameter. It must be a non-empty string.'}

    # Error handling for optional parameters
    if not isinstance(delimiters, list) or not all(isinstance(d, str) for d in delimiters):
        return {'error': 'Invalid delimiters parameter. It must be a list of strings.'}
    if name_format not in ['first_last', 'first_middle_last', 'last_first', 'title_first_last', 'first_last_suffix']:
        return {'error': 'Invalid name_format parameter. It must be one of the specified formats.'}
    if not isinstance(handle_special_characters, bool):
        return {'error': 'Invalid handle_special_characters parameter. It must be a boolean.'}
    if not isinstance(normalize_last_name, bool):
        return {'error': 'Invalid normalize_last_name parameter. It must be a boolean.'}

    # Split the full name based on the provided delimiters
    import re
    delimiter_pattern = '|'.join(map(re.escape, delimiters))
    name_parts = re.split(delimiter_pattern, full_name)

    # Determine the last name based on the name format
    last_name = ''
    if name_format == 'first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_middle_last':
        last_name = name_parts[-1]
    elif name_format == 'last_first':
        last_name = name_parts[0]
    elif name_format == 'title_first_last':
        last_name = name_parts[-1]
    elif name_format == 'first_last_suffix':
        last_name = name_parts[-2]

    # Handle special characters if required
    if handle_special_characters:
        last_name = re.sub(r'[^\w\s]', '', last_name)

    # Normalize the last name if required
    if normalize_last_name:
        last_name = last_name.lower()

    return last_name

