def enhanced_combined_length_calculator(names, ignore_characters=None, ignore_position=None, case_sensitive=False, output_format='integer', error_handling='warn'):
    """
    Calculate the combined length of multiple strings with customization options.
    """
    # Error handling for required 'names' parameter
    if not isinstance(names, list) or len(names) < 2:
        if error_handling == 'strict':
            raise ValueError("At least two names are required.")
        elif error_handling == 'warn':
            print("Warning: At least two names are required.")
            return None
        else:  # ignore
            return None

    # Initialize combined length
    combined_length = 0
    detailed_output = []

    # Process each name
    for name in names:
        # Apply case sensitivity
        if not case_sensitive:
            name = name.lower()

        # Ignore specified characters
        if ignore_characters:
            for char in ignore_characters:
                name = name.replace(char, '')

        # Ignore specified positions
        if ignore_position:
            if 'first' in ignore_position and len(name) > 0:
                name = name[1:]
            if 'last' in ignore_position and len(name) > 0:
                name = name[:-1]

        # Calculate length of the processed name
        name_length = len(name)
        combined_length += name_length
        detailed_output.append((name, name_length))

    # Return output based on specified format
    if output_format == 'integer':
        return combined_length
    elif output_format == 'text':
        return f"The combined length is {combined_length}."
    elif output_format == 'detailed':
        return {
            'total_length': combined_length,
            'details': detailed_output
        }
    else:
        if error_handling == 'strict':
            raise ValueError("Invalid output format specified.")
        elif error_handling == 'warn':
            print("Warning: Invalid output format specified.")
            return combined_length
        else:  # ignore
            return combined_length

