    movie_database = {
        ('Return to Nim\'s Island', 2013): {
            'Nim': 'Bindi Irwin',
            'Jack': 'Matthew Lillard'
        }
    }

    # Attempt to find the movie in the database
    movie_key = (movie_title, release_year)
    if movie_key not in movie_database:
        return {'error': 'Movie not found in the database.'}

    # Retrieve cast information
    cast_info = movie_database[movie_key]
    result = {}
    for character in character_names:
        if character in cast_info:
            if output_format == 'actor_name':
                result[character] = cast_info[character]
            elif output_format == 'full_cast':
                result = cast_info
                break
            elif output_format == 'detailed_actor_info':
