def count_repeated_letters(input: str, case_sensitive: bool = False, output_format: str = 'integer', letters_to_count: list = [], ignore_patterns: list = []) -> str:
    # Error handling for input types
    if not isinstance(input, str):
        return 'Error: Input must be a string.'
    if output_format not in ['integer', 'text', 'detailed']:
        return 'Error: Invalid output format specified.'

    # Apply case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Remove ignored patterns
    for pattern in ignore_patterns:
        input = input.replace(pattern, '')

    # Count occurrences of each letter
    from collections import Counter
    letter_counts = Counter(input)

    # Filter letters to count if specified
    if letters_to_count:
        letter_counts = {letter: count for letter, count in letter_counts.items() if letter in letters_to_count}

    # Identify repeated letters
    repeated_letters = {letter: count for letter, count in letter_counts.items() if count > 1}

    # Format output
    if output_format == 'integer':
        return str(len(repeated_letters))
    elif output_format == 'text':
        return f'There are {len(repeated_letters)} repeated letters.'
    elif output_format == 'detailed':
        return str(repeated_letters)

