def string_length_counter(input, ignore_characters=[], ignore_position=[], case_sensitive=True, ignore_patterns=[], output_format='integer'):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Invalid input type. Input must be a string.'}

    # Initialize variables
    filtered_string = input

    # Apply ignore_characters
    if ignore_characters:
        for char in ignore_characters:
            filtered_string = filtered_string.replace(char, '')

    # Apply ignore_position
    if ignore_position:
        if 'first' in ignore_position and len(filtered_string) > 0:
            filtered_string = filtered_string[1:]
        if 'last' in ignore_position and len(filtered_string) > 0:
            filtered_string = filtered_string[:-1]
        if 'even' in ignore_position:
            filtered_string = ''.join([char for i, char in enumerate(filtered_string) if i % 2 != 0])
        if 'odd' in ignore_position:
            filtered_string = ''.join([char for i, char in enumerate(filtered_string) if i % 2 == 0])

    # Apply ignore_patterns
    import re
    for pattern in ignore_patterns:
        filtered_string = re.sub(pattern, '', filtered_string)

    # Count characters
    count = len(filtered_string)

    # Format output
    if output_format == 'text':
        return f'The string contains {count} characters.'
    elif output_format == 'detailed':
        from collections import Counter
        return dict(Counter(filtered_string))
    else:
        return count

