def enhanced_unique_letter_counter(input, ignore_case=True, ignore_characters=[], alphabetic_only=True, non_latin_support=False, detailed_count=False, custom_character_set=[]):
    # Validate input type
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}

    # Initialize a set to track unique letters
    unique_letters = set()
    detailed_counts = {}

    # Normalize case if ignore_case is True
    if ignore_case:
        input = input.lower()

    # Define a function to check if a character is valid
    def is_valid_character(char):
        if char in ignore_characters:
            return False
        if custom_character_set and char not in custom_character_set:
            return False
        if alphabetic_only and not char.isalpha():
            return False
        if not non_latin_support and not ('a' <= char <= 'z'):
            return False
        return True

    # Iterate over each character in the input string
    for char in input:
        if is_valid_character(char):
            unique_letters.add(char)
            if detailed_count:
                if char in detailed_counts:
                    detailed_counts[char] += 1
                else:
                    detailed_counts[char] = 1

    # Prepare the result
    result = {'unique_count': len(unique_letters)}
    if detailed_count:
        result['detailed_counts'] = detailed_counts

    return result

