def advanced_character_counter(input, characters, case_sensitive=True, output_format='integer', count_mode='total'):
    # Validate input parameters
    if not isinstance(input, list) or not all(isinstance(i, str) for i in input):
        return {'error': 'Invalid input: input must be a list of strings.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) for c in characters):
        return {'error': 'Invalid characters: characters must be a list of strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive: must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of ["integer", "text", "detailed"].'}
    if count_mode not in ['total', 'individual']:
        return {'error': 'Invalid count_mode: must be one of ["total", "individual"].'}

    # Initialize count
    total_count = 0
    individual_counts = []

    # Process each string in input
    for string in input:
        string_count = 0
        for pattern in characters:
            if not case_sensitive:
                string = string.lower()
                pattern = pattern.lower()
            count = string.count(pattern)
            string_count += count
        individual_counts.append(string_count)
        total_count += string_count

    # Determine output format
    if output_format == 'integer':
        return total_count if count_mode == 'total' else individual_counts
    elif output_format == 'text':
        return f'Total occurrences: {total_count}' if count_mode == 'total' else f'Occurrences per string: {individual_counts}'
    elif output_format == 'detailed':
        detailed_counts = {pattern: sum(string.count(pattern) for string in input) for pattern in characters}
        return detailed_counts

