def monarch_reign_analyzer(monarchs_data, current_date=None, output_format='name_only'):
    from datetime import datetime
    import dateutil.parser

    def calculate_reign_duration(start_date, end_date):
        try:
            start = dateutil.parser.parse(start_date)
            end = dateutil.parser.parse(end_date) if end_date != 'present' else dateutil.parser.parse(current_date)
            return (end - start).days
        except Exception as e:
            raise ValueError(f"Invalid date format: {e}")

    if not isinstance(monarchs_data, list):
        raise ValueError("monarchs_data must be a list of monarch objects.")

    longest_reign = {'name': '', 'duration': 0}
    detailed_info = []

    for monarch in monarchs_data:
        try:
            name = monarch['name']
            start_date = monarch['start_date']
            end_date = monarch.get('end_date', 'present')
            end_reason = monarch.get('end_reason', 'other')

            if end_reason not in ['abdication', 'death', 'end_of_monarchy', 'other']:
                raise ValueError(f"Invalid end_reason: {end_reason}")

            duration = calculate_reign_duration(start_date, end_date)

            if duration > longest_reign['duration']:
                longest_reign = {'name': name, 'duration': duration}

            detailed_info.append({
                'name': name,
                'duration': duration,
                'end_reason': end_reason
            })

        except KeyError as e:
            raise ValueError(f"Missing required field: {e}")

    if output_format == 'name_only':
        return longest_reign['name']
    elif output_format == 'detailed':
        return next((info for info in detailed_info if info['name'] == longest_reign['name']), None)
    elif output_format == 'full_report':
        return detailed_info
    else:
        raise ValueError("Invalid output_format. Choose from 'name_only', 'detailed', or 'full_report'.")

