def longest_alphabetical_substring(input: str, case_sensitive: bool = False, output_format: str = 'substring', ignore_non_alpha: bool = True, max_results: int = 1):
    # Validate parameters
    if not isinstance(input, str):
        return {'error': 'Input must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean.'}
    if output_format not in ['substring', 'length', 'detailed']:
        return {'error': "output_format must be one of ['substring', 'length', 'detailed']."}
    if not isinstance(ignore_non_alpha, bool):
        return {'error': 'ignore_non_alpha must be a boolean.'}
    if not isinstance(max_results, int) or max_results < 1:
        return {'error': 'max_results must be an integer greater than or equal to 1.'}

    # Prepare the input string based on case sensitivity
    if not case_sensitive:
        input = input.lower()

    # Initialize variables
    longest_substring = ''
    current_substring = ''

    # Iterate over the input string
    for i in range(len(input)):
        if ignore_non_alpha and not input[i].isalpha():
            continue
        if i == 0 or input[i] >= input[i - 1]:
            current_substring += input[i]
        else:
            if len(current_substring) > len(longest_substring):
                longest_substring = current_substring
            current_substring = input[i]
    if len(current_substring) > len(longest_substring):
        longest_substring = current_substring

    # Prepare the output based on the specified format
    if output_format == 'substring':
        return longest_substring
    elif output_format == 'length':
        return len(longest_substring)
    elif output_format == 'detailed':
        return {'substring': longest_substring, 'length': len(longest_substring)}

    return longest_substring

