    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid case_sensitive type. Must be a boolean.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format. Must be one of: integer, text, detailed.'}
    if not isinstance(output_statistics, bool):
        return {'error': 'Invalid output_statistics type. Must be a boolean.'}

    # Adjust case sensitivity
    if not case_sensitive:
        input = input.lower()
        ignore_characters = [char.lower() for char in ignore_characters]

    # Remove ignored characters
    for char in ignore_characters:
        input = input.replace(char, '')

    # Remove ignored positions
    if 'first' in ignore_position and len(input) > 0:
        input = input[1:]
    if 'last' in ignore_position and len(input) > 0:
        input = input[:-1]
    if 'even' in ignore_position:
        input = ''.join(char for i, char in enumerate(input) if i % 2 != 0)
    if 'odd' in ignore_position:
        input = ''.join(char for i, char in enumerate(input) if i % 2 == 0)

    # Count letters
    letter_count = sum(char.isalpha() for char in input)

    # Prepare output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The string contains {letter_count} letters.'
