def enhanced_name_length_counter(name, ignore_characters=[], ignore_position=[], ignore_character_types=[], output_format='integer'):
    # Validate the 'name' parameter
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}

    # Validate 'ignore_position' and 'ignore_character_types' parameters
    valid_positions = {'first', 'last', 'middle'}
    valid_character_types = {'vowels', 'consonants'}
    if any(pos not in valid_positions for pos in ignore_position):
        return {'error': 'Invalid input: ignore_position contains invalid values.'}
    if any(ct not in valid_character_types for ct in ignore_character_types):
        return {'error': 'Invalid input: ignore_character_types contains invalid values.'}

    # Define vowels and consonants
    vowels = set('aeiouAEIOU')
    consonants = set('bcdfghjklmnpqrstvwxyzBCDFGHJKLMNPQRSTVWXYZ')

    # Filter the name based on ignore parameters
    filtered_name = name

    # Ignore specific characters
    for char in ignore_characters:
        filtered_name = filtered_name.replace(char, '')

    # Ignore positions
    if 'first' in ignore_position and len(filtered_name) > 0:
        filtered_name = filtered_name[1:]
    if 'last' in ignore_position and len(filtered_name) > 0:
        filtered_name = filtered_name[:-1]
    if 'middle' in ignore_position and len(filtered_name) > 2:
        filtered_name = filtered_name[0] + filtered_name[1:-1].replace(filtered_name[1:-1], '') + filtered_name[-1]

    # Ignore character types
    if 'vowels' in ignore_character_types:
        filtered_name = ''.join([c for c in filtered_name if c not in vowels])
    if 'consonants' in ignore_character_types:
        filtered_name = ''.join([c for c in filtered_name if c not in consonants])

    # Count the letters
    letter_count = len(filtered_name)

    # Prepare the output
    if output_format == 'integer':
        return letter_count
    elif output_format == 'text':
        return f'The name "{name}" has {letter_count} letters after applying the filters.'
    elif output_format == 'detailed':
        vowel_count = sum(1 for c in filtered_name if c in vowels)
        consonant_count = sum(1 for c in filtered_name if c in consonants)
        return {
            'total': letter_count,
            'vowels': vowel_count,
            'consonants': consonant_count
        }
    else:
        return {'error': 'Invalid output format specified.'}

