def first_letter_extractor_v2(input, output_format='character', ignore_non_alpha=False, default_value=''):
    """
    Extracts the first letter from the input based on the specified output format.

    Parameters:
    - input (str or list): The input from which the first letter is to be extracted.
    - output_format (str): The format of the output. Options are 'character', 'ascii', 'unicode', 'uppercase', 'lowercase'.
    - ignore_non_alpha (bool): If true, non-alphabetic characters are ignored.
    - default_value (str): A default value to return if no valid letter is found.

    Returns:
    - str: The first letter in the specified format or the default value.
    """
    # Helper function to process a single string
    def extract_first_letter(s):
        for char in s:
            if char.isalpha() or not ignore_non_alpha:
                return char
        return None

    # Determine the first letter based on input type
    first_letter = None
    if isinstance(input, str):
        first_letter = extract_first_letter(input)
    elif isinstance(input, list):
        for item in input:
            first_letter = extract_first_letter(item)
            if first_letter:
                break

    # If no valid letter is found, return the default value
    if not first_letter:
        return default_value

    # Format the output based on the specified output_format
    if output_format == 'ascii':
        return str(ord(first_letter))
    elif output_format == 'unicode':
        return f'U+{ord(first_letter):04X}'
    elif output_format == 'uppercase':
        return first_letter.upper()
    elif output_format == 'lowercase':
        return first_letter.lower()
    else:
        return first_letter

