def ascii_converter(characters, error_handling='ignore', replacement_character='?', output_format='list', encoding='ASCII'):
    """
    Converts a list of characters to their ASCII codes.

    :param characters: List of single-character strings to convert.
    :param error_handling: Strategy for handling non-ASCII characters ('ignore', 'error_message', 'replace').
    :param replacement_character: Character to replace non-ASCII characters if 'replace' is chosen.
    :param output_format: Format of the output ('list', 'string', 'json').
    :param encoding: Encoding to use ('ASCII', 'UTF-8', 'ISO-8859-1').
    :return: Converted ASCII codes in the specified format.
    """
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        raise ValueError("'characters' must be a list of single-character strings.")

    ascii_codes = []
    errors = []

    for char in characters:
        try:
            if encoding == 'ASCII':
                ascii_code = ord(char)
                if ascii_code > 127:
                    raise ValueError(f"Non-ASCII character: {char}")
            else:
                ascii_code = ord(char.encode(encoding))
            ascii_codes.append(ascii_code)
        except Exception as e:
            if error_handling == 'ignore':
                continue
            elif error_handling == 'error_message':
                errors.append(str(e))
            elif error_handling == 'replace':
                ascii_codes.append(ord(replacement_character))

    if output_format == 'list':
        return ascii_codes
    elif output_format == 'string':
        return ''.join(map(str, ascii_codes))
    elif output_format == 'json':
        return {char: ascii_code for char, ascii_code in zip(characters, ascii_codes)}
    else:
        raise ValueError("Invalid output format specified.")

