    """
    Extracts the last letter of the given string 'name' based on the specified parameters.
    """
    # Error handling for invalid 'name' input
    if not isinstance(name, str):
        return {'error': 'Invalid input: name must be a string.'}

    # Handle empty string case
    if not name.strip() and ignore_whitespace:
        return {'error': 'Invalid input: name is empty after ignoring whitespace.'}

    # Determine the last character to consider
    if ignore_whitespace:
        name = name.rstrip()

    if not name:  # If name is empty after stripping
        return {'error': 'Invalid input: name is empty.'}

    last_char = name[-1]

