def first_letter_extractor(input: str, case_sensitive: bool = True, ignore_special_characters: bool = False, extract_from_each_word: bool = False, include_numeric: bool = False, default_character: str = '') -> str:
    # Validate input
    if not isinstance(input, str) or not input:
        raise ValueError('Input must be a non-empty string.')

    # Helper function to extract the first valid character
    def extract_first_character(word):
        for char in word:
            if char.isalpha() or (include_numeric and char.isdigit()):
                return char
        return default_character

    # Process input based on parameters
    if extract_from_each_word:
        words = input.split()
        first_letters = [extract_first_character(word) for word in words]
        result = ''.join(first_letters)
    else:
        result = extract_first_character(input)

    # Handle case sensitivity
    if not case_sensitive:
        result = result.lower()

    return result

