def monarch_reign_analyzer(region, monarch_data, output_format='name_only', time_period=None):
    from datetime import datetime
    import dateutil.parser

    def parse_date(date_str):
        if date_str.lower() == 'present':
            return datetime.now()
        return dateutil.parser.parse(date_str)

    def calculate_reign_duration(start, end):
        start_date = parse_date(start)
        end_date = parse_date(end)
        return (end_date - start_date).days

    if not isinstance(region, str) or not region:
        return {'error': 'Invalid or missing region parameter.'}

    if not isinstance(monarch_data, list) or not monarch_data:
        return {'error': 'Monarch data must be a non-empty list.'}

    longest_reign = None
    longest_monarch = None

    for monarch in monarch_data:
        try:
            name = monarch['name']
            reign_start = monarch['reign_start']
            reign_end = monarch['reign_end']
        except KeyError as e:
            return {'error': f'Missing required field: {str(e)}'}

        if time_period:
            try:
                period_start = parse_date(time_period['start_date'])
                period_end = parse_date(time_period['end_date'])
            except KeyError as e:
                return {'error': f'Missing time period field: {str(e)}'}

            reign_start_date = parse_date(reign_start)
            reign_end_date = parse_date(reign_end)

            if reign_end_date < period_start or reign_start_date > period_end:
                continue

        reign_duration = calculate_reign_duration(reign_start, reign_end)

        if longest_reign is None or reign_duration > longest_reign:
            longest_reign = reign_duration
            longest_monarch = monarch

    if not longest_monarch:
        return {'error': 'No monarch found for the specified criteria.'}

    if output_format == 'name_only':
        return {'result': longest_monarch['name']}
    elif output_format == 'detailed':
        return {'result': {
            'name': longest_monarch['name'],
            'reign_duration': longest_reign
        }}
    elif output_format == 'full':
        return {'result': longest_monarch}
    else:
        return {'error': 'Invalid output format specified.'}

