def extract_first_name(full_name, delimiter=' ', ignore_titles=True, output_format='string', include_middle_name=False, ignore_suffixes=True, case_sensitive=False):
    # Define common titles and suffixes to ignore
    titles = {'Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.'}
    suffixes = {'Jr.', 'Sr.', 'III', 'IV'}

    # Split the full name using the specified delimiter
    name_parts = full_name.split(delimiter)

    # Initialize variables for first name and middle name
    first_name = ''
    middle_name = ''

    # Iterate over name parts to find the first name
    for part in name_parts:
        # Skip titles if ignore_titles is True
        if ignore_titles and part in titles:
            continue
        # Skip suffixes if ignore_suffixes is True
        if ignore_suffixes and part in suffixes:
            continue
        # Assign the first non-title, non-suffix part as the first name
        if not first_name:
            first_name = part
        elif include_middle_name and not middle_name:
            middle_name = part
        else:
            break

    # Combine first name and middle name if needed
    if include_middle_name and middle_name:
        first_name = f'{first_name} {middle_name}'

    # Adjust case sensitivity
    if not case_sensitive:
        first_name = first_name.capitalize()

    # Return the result in the specified format
    if output_format == 'json':
        return {'first_name': first_name}
    return first_name

