def character_counter(string, characters, case_sensitive=True, ignore_whitespace=False, range=None, output_format='integer'):
    # Validate input types
    if not isinstance(string, str):
        return {'error': 'Invalid input: string must be of type str.'}
    if not isinstance(characters, list) or not all(isinstance(c, str) and len(c) == 1 for c in characters):
        return {'error': 'Invalid input: characters must be a list of single-character strings.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(ignore_whitespace, bool):
        return {'error': 'Invalid input: ignore_whitespace must be a boolean.'}
    if range is not None:
        if not (isinstance(range, list) and len(range) == 2 and all(isinstance(i, int) for i in range)):
            return {'error': 'Invalid input: range must be a list of two integers.'}
        start, end = range
        if start < 0 or end > len(string) or start >= end:
            return {'error': 'Invalid range: start and end must be within string length and start < end.'}
    else:
        start, end = 0, len(string)
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output_format: must be one of integer, text, detailed.'}

    # Adjust string based on parameters
    substring = string[start:end]
    if not case_sensitive:
        substring = substring.lower()
        characters = [c.lower() for c in characters]
    if ignore_whitespace:
        substring = ''.join(substring.split())

    # Count occurrences
    counts = {c: 0 for c in characters}
    positions = {c: [] for c in characters}
    for index, char in enumerate(substring):
        if char in counts:
            counts[char] += 1
            positions[char].append(index + start)

    # Format output
    if output_format == 'integer':
        return sum(counts.values())
    elif output_format == 'text':
        return ', '.join(f"'{char}': {count}" for char, count in counts.items())
    elif output_format == 'detailed':
        return {char: {'count': count, 'positions': positions[char]} for char, count in counts.items()}

