def timezone_converter(input_datetime: str, source_timezone_offset: float, target_timezone: str, output_format: str = 'ISO 8601', custom_format: str = '', daylight_saving_adjustment: bool = True) -> str:
    from datetime import datetime, timedelta
    import pytz

    # Validate input_datetime format
    try:
        dt = datetime.fromisoformat(input_datetime)
    except ValueError:
        return 'Error: Invalid input_datetime format. Must be ISO 8601.'

    # Validate target_timezone
    valid_timezones = ['AoE', 'UTC', 'PST', 'EST', 'CET', 'IST', 'JST', 'AEST', 'GMT', 'CST', 'MST']
    if target_timezone not in valid_timezones:
        return 'Error: Invalid target_timezone. Must be one of ' + ', '.join(valid_timezones)

    # Convert input_datetime to UTC
    utc_dt = dt - timedelta(hours=source_timezone_offset)

    # Adjust for daylight saving if needed
    if daylight_saving_adjustment:
        # This is a simplified example, real implementation would need more complex logic
        utc_dt += timedelta(hours=1)

    # Convert UTC to target timezone
    if target_timezone == 'AoE':
        target_offset = -12
    elif target_timezone == 'UTC':
        target_offset = 0
    elif target_timezone == 'PST':
        target_offset = -8
    elif target_timezone == 'EST':
        target_offset = -5
    elif target_timezone == 'CET':
        target_offset = 1
    elif target_timezone == 'IST':
        target_offset = 5.5
    elif target_timezone == 'JST':
        target_offset = 9
    elif target_timezone == 'AEST':
        target_offset = 10
    elif target_timezone == 'GMT':
        target_offset = 0
    elif target_timezone == 'CST':
        target_offset = -6
    elif target_timezone == 'MST':
        target_offset = -7

    target_dt = utc_dt + timedelta(hours=target_offset)

    # Format output
    if output_format == 'ISO 8601':
        return target_dt.isoformat()
    elif output_format == 'RFC 2822':
        return target_dt.strftime('%a, %d %b %Y %H:%M:%S +0000')
    elif output_format == 'custom' and custom_format:
        return target_dt.strftime(custom_format)
    elif output_format == 'UNIX timestamp':
        return str(int(target_dt.timestamp()))
    else:
        return 'Error: Invalid output_format or missing custom_format.'

