def enhanced_timezone_difference_calculator(locations, reference_time, date=None, output_format='hours', custom_time_format=None, error_handling='strict'):
    """
    Calculate the time difference between specified locations and UTC.

    Parameters:
    - locations (list of str): A list of location names for which the time differences are to be calculated.
    - reference_time (str): Specifies whether to use standard time or daylight saving time for the calculation.
    - date (str, optional): The date for which the time difference is to be calculated.
    - output_format (str, optional): The format of the output, either in hours, minutes, or detailed.
    - custom_time_format (str, optional): A custom format string for the output time.
    - error_handling (str, optional): Specifies the error handling mode, either strict or lenient.

    Returns:
    - dict: A dictionary containing the time differences and any errors or warnings.
    """
    import pytz
    from datetime import datetime

    # Initialize the result dictionary
    result = {'time_differences': {}, 'errors': []}

    # Validate required parameters
    if not locations or not reference_time:
        if error_handling == 'strict':
            raise ValueError("'locations' and 'reference_time' are required parameters.")
        else:
            result['errors'].append("'locations' and 'reference_time' are required parameters.")
            return result

    # Set the date to today if not provided
    if not date:
        date = datetime.now().strftime('%Y-%m-%d')

    # Convert date to datetime object
    try:
        date_obj = datetime.strptime(date, '%Y-%m-%d')
    except ValueError:
        if error_handling == 'strict':
            raise ValueError("Invalid date format. Expected 'YYYY-MM-DD'.")
        else:
            result['errors'].append("Invalid date format. Expected 'YYYY-MM-DD'.")
            return result

    # Calculate time differences
    for location in locations:
        try:
            # Get the timezone for the location
            timezone = pytz.timezone(location)
            # Get the offset from UTC
            if reference_time == 'standard':
                offset = timezone.utcoffset(date_obj, is_dst=False)
            else:
                offset = timezone.utcoffset(date_obj, is_dst=True)

            # Convert offset to the desired output format
            if output_format == 'hours':
                time_difference = offset.total_seconds() / 3600
            elif output_format == 'minutes':
                time_difference = offset.total_seconds() / 60
            else:
                time_difference = f"{timezone.tzname(date_obj)}: {offset}"

            result['time_differences'][location] = time_difference
        except Exception as e:
            if error_handling == 'strict':
                raise e
            else:
                result['errors'].append(f"Error processing location '{location}': {str(e)}")

    return result

