def enhanced_timezone_difference_calculator(from_timezone: str, to_timezone: str, dates: list = None, time: str = None, output_format: str = 'hours') -> str:
    import pytz
    from datetime import datetime

    # Default to current date and time if not provided
    if dates is None:
        dates = [datetime.now().strftime('%Y-%m-%d')]
    if time is None:
        time = datetime.now().strftime('%H:%M')

    # Validate output_format
    if output_format not in ['hours', 'detailed', 'json', 'text']:
        return 'Error: Invalid output format specified.'

    try:
        # Initialize time zones
        from_tz = pytz.timezone(from_timezone)
        to_tz = pytz.timezone(to_timezone)

        # Calculate time differences
        differences = []
        for date in dates:
            # Parse date and time
            dt = datetime.strptime(f'{date} {time}', '%Y-%m-%d %H:%M')
            from_dt = from_tz.localize(dt)
            to_dt = from_dt.astimezone(to_tz)

            # Calculate difference in hours
            difference = (to_dt - from_dt).total_seconds() / 3600
            differences.append(difference)

        # Format output
        if output_format == 'hours':
            return str(differences[0])
        elif output_format == 'detailed':
            return f'Time difference from {from_timezone} to {to_timezone} on {dates[0]} at {time} is {differences[0]} hours.'
        elif output_format == 'json':
            return str({"from_timezone": from_timezone, "to_timezone": to_timezone, "dates": dates, "time": time, "differences": differences})
        elif output_format == 'text':
            return f'Time difference: {differences[0]} hours.'
    except Exception as e:
        return f'Error: {str(e)}'

def enhanced_timezone_difference_calculator(locations, base_location, date, consider_dst=True, output_format='json', historical_data=False):
    import pytz
    from datetime import datetime

    # Validate date format
    try:
        date_obj = datetime.strptime(date, '%Y-%m-%d')
    except ValueError:
        return {'error': 'Invalid date format. Please use YYYY-MM-DD.'}

    # Validate output format
    if output_format not in ['text', 'json', 'xml']:
        return {'error': 'Invalid output format. Choose from text, json, or xml.'}

    # Initialize results
    results = {}

    # Base timezone
    try:
        base_tz = pytz.timezone(base_location)
    except pytz.UnknownTimeZoneError:
        return {'error': f'Unknown base location timezone: {base_location}'}

    base_time = base_tz.localize(date_obj, is_dst=consider_dst)

    # Calculate differences
    for location in locations:
        try:
            loc_tz = pytz.timezone(location)
            loc_time = loc_tz.localize(date_obj, is_dst=consider_dst)
            time_difference = (loc_time.utcoffset() - base_time.utcoffset()).total_seconds() / 3600
            results[location] = time_difference
        except pytz.UnknownTimeZoneError:
            results[location] = 'Unknown timezone'

    # Format output
    if output_format == 'json':
        return {'results': results}
    elif output_format == 'text':
        return {'results': ', '.join([f'{loc}: {diff} hours' for loc, diff in results.items()])}
    elif output_format == 'xml':
        xml_result = '<results>'
        for loc, diff in results.items():
            xml_result += f'<location name="{loc}">{diff} hours</location>'
        xml_result += '</results>'
        return {'results': xml_result}

