def time_zone_converter(input_datetime=None, source_offset=None, target_timezone=None, output_format='ISO', daylight_saving=True, batch_conversion=None):
    from datetime import datetime, timedelta
    import pytz

    # Error handling for required parameters
    if source_offset is None or target_timezone is None:
        return {'error': 'source_offset and target_timezone are required parameters.'}

    # Error handling for input_datetime and batch_conversion
    if input_datetime is None and batch_conversion is None:
        return {'error': 'Either input_datetime or batch_conversion must be provided.'}

    # Convert input_datetime to datetime object
    try:
        if input_datetime:
            dt = datetime.fromisoformat(input_datetime)
        elif batch_conversion:
            dt_list = [datetime.fromisoformat(dt_str) for dt_str in batch_conversion]
    except ValueError:
        return {'error': 'Invalid date-time format. Please provide ISO 8601 format.'}

    # Calculate the target time zone offset
    target_offset = 0  # Default to UTC
    if target_timezone == 'AoE':
        target_offset = -12
    elif target_timezone == 'PST':
        target_offset = -8
    elif target_timezone == 'EST':
        target_offset = -5
    elif target_timezone == 'CET':
        target_offset = 1
    elif target_timezone == 'IST':
        target_offset = 5.5
    elif target_timezone == 'JST':
        target_offset = 9
    elif target_timezone == 'AEST':
        target_offset = 10
    elif target_timezone == 'GMT':
        target_offset = 0
    elif target_timezone == 'CST':
        target_offset = -6
    elif target_timezone == 'MST':
        target_offset = -7

    # Adjust for daylight saving time
    if daylight_saving:
        if target_timezone in ['PST', 'EST', 'CST', 'MST']:
            target_offset += 1

    # Calculate the time difference
    time_difference = target_offset - source_offset

    # Convert the time
    if input_datetime:
        converted_time = dt + timedelta(hours=time_difference)
    elif batch_conversion:
        converted_times = [dt + timedelta(hours=time_difference) for dt in dt_list]

    # Format the output
    def format_output(dt):
        if output_format == 'ISO':
            return dt.isoformat()
        elif output_format == 'human_readable':
            return dt.strftime('%Y-%m-%d %H:%M:%S')
        elif output_format == 'UNIX_timestamp':
            return int(dt.timestamp())
        elif output_format == 'RFC_2822':
            return dt.strftime('%a, %d %b %Y %H:%M:%S +0000')

    if input_datetime:
        return {'converted_time': format_output(converted_time)}
    elif batch_conversion:
        return {'converted_times': [format_output(dt) for dt in converted_times]}

