def timezone_converter(input_datetime, input_timezone, output_timezone, output_timezone_offset=None, output_format='ISO 8601', handle_dst=True, historical_data=False, custom_format=None):
    import pytz
    from datetime import datetime

    try:
        # Parse the input datetime
        input_dt = datetime.fromisoformat(input_datetime)

        # Set the input timezone
        input_tz = pytz.timezone(input_timezone)
        input_dt = input_tz.localize(input_dt, is_dst=handle_dst)

        # Determine the output timezone
        if output_timezone:
            output_tz = pytz.timezone(output_timezone)
        elif output_timezone_offset is not None:
            output_tz = pytz.FixedOffset(output_timezone_offset * 60)
        else:
            raise ValueError('Either output_timezone or output_timezone_offset must be specified.')

        # Convert to the output timezone
        output_dt = input_dt.astimezone(output_tz)

        # Format the output datetime
        if output_format == 'ISO 8601':
            return output_dt.isoformat()
        elif output_format == 'RFC 2822':
            return output_dt.strftime('%a, %d %b %Y %H:%M:%S %z')
        elif output_format == 'UNIX timestamp':
            return int(output_dt.timestamp())
        elif output_format == 'custom' and custom_format:
            return output_dt.strftime(custom_format)
        else:
            raise ValueError('Invalid output format or missing custom format string.')

    except Exception as e:
        return str(e)

