def enhanced_timezone_difference_calculator(timezones, date_time=None, output_format='hours', consider_historical_changes=False):
    import pytz
    from datetime import datetime

    # Validate input parameters
    if not isinstance(timezones, list) or len(timezones) < 2:
        return {'error': 'Invalid input: At least two time zones must be specified.'}
    if output_format not in ['hours', 'detailed', 'seconds', 'summary']:
        return {'error': 'Invalid output format specified.'}

    # Set default date_time to current if not provided
    if date_time is None:
        date_time = datetime.now().isoformat()

    try:
        # Parse the date_time
        date_time_obj = datetime.fromisoformat(date_time)
    except ValueError:
        return {'error': 'Invalid date_time format. Must be ISO 8601.'}

    try:
        # Convert date_time to each timezone and calculate differences
        tz1 = pytz.timezone(timezones[0])
        tz2 = pytz.timezone(timezones[1])
        dt1 = tz1.localize(date_time_obj, is_dst=None)
        dt2 = tz2.localize(date_time_obj, is_dst=None)

        # Calculate time difference
        difference = (dt2 - dt1).total_seconds()

        # Format output based on output_format
        if output_format == 'hours':
            result = difference / 3600
        elif output_format == 'detailed':
            hours = difference // 3600
            minutes = (difference % 3600) // 60
            result = f'{int(hours)} hours, {int(minutes)} minutes'
        elif output_format == 'seconds':
            result = difference
        elif output_format == 'summary':
            result = f'The time difference between {timezones[0]} and {timezones[1]} is {difference / 3600} hours.'

        return {'result': result}
    except pytz.UnknownTimeZoneError:
        return {'error': 'One or more specified time zones are invalid.'}
    except Exception as e:
        return {'error': f'An unexpected error occurred: {str(e)}'}

