def timezone_difference_calculator(timezone1: str, timezone2: str, date: str = None, time: str = None, timezone_offset1: str = None, timezone_offset2: str = None, batch_mode: bool = False, output_format: str = 'simple') -> dict:
    import datetime
    import pytz
    from pytz import timezone

    try:
        # Validate time zones
        tz1 = timezone(timezone1)
        tz2 = timezone(timezone2)

        # Use current date and time if not provided
        if date is None:
            date = datetime.datetime.now().strftime('%Y-%m-%d')
        if time is None:
            time = datetime.datetime.now().strftime('%H:%M:%S')

        # Parse date and time
        dt = datetime.datetime.strptime(f'{date} {time}', '%Y-%m-%d %H:%M:%S')

        # Apply offsets if provided
        if timezone_offset1:
            offset1 = datetime.timedelta(hours=int(timezone_offset1[:3]), minutes=int(timezone_offset1[4:]))
            dt_tz1 = dt + offset1
        else:
            dt_tz1 = tz1.localize(dt)

        if timezone_offset2:
            offset2 = datetime.timedelta(hours=int(timezone_offset2[:3]), minutes=int(timezone_offset2[4:]))
            dt_tz2 = dt + offset2
        else:
            dt_tz2 = tz2.localize(dt)

        # Calculate time difference
        time_difference = (dt_tz1 - dt_tz2).total_seconds() / 3600

        # Prepare output
        if output_format == 'simple':
            return {'time_difference': time_difference}
        elif output_format == 'detailed':
            return {
                'time_difference': time_difference,
                'timezone1': timezone1,
                'timezone2': timezone2,
                'date': date,
                'time': time,
                'timezone_offset1': timezone_offset1,
                'timezone_offset2': timezone_offset2
            }
    except Exception as e:
        return {'error': str(e)}

