def enhanced_timezone_difference_calculator(timezone1, timezone2, date=None, date_range=None, output_format='hours', include_metadata=False):
    import pytz
    from datetime import datetime

    # Validate time zones
    try:
        tz1 = pytz.timezone(timezone1)
        tz2 = pytz.timezone(timezone2)
    except pytz.UnknownTimeZoneError:
        return {'error': 'Invalid time zone specified.'}

    # Determine the date to use
    if date_range:
        start_date = date_range.get('start_date')
        end_date = date_range.get('end_date')
        if not start_date or not end_date:
            return {'error': 'Both start_date and end_date must be specified in date_range.'}
        try:
            start_date = datetime.strptime(start_date, '%Y-%m-%d')
            end_date = datetime.strptime(end_date, '%Y-%m-%d')
        except ValueError:
            return {'error': 'Invalid date format in date_range. Use YYYY-MM-DD.'}
        # For simplicity, use the start date for calculation
        date_to_use = start_date
    else:
        if date:
            try:
                date_to_use = datetime.strptime(date, '%Y-%m-%d')
            except ValueError:
                return {'error': 'Invalid date format. Use YYYY-MM-DD.'}
        else:
            date_to_use = datetime.now()

    # Calculate time difference
    dt1 = tz1.localize(date_to_use)
    dt2 = tz2.localize(date_to_use)
    time_difference = (dt1.utcoffset() - dt2.utcoffset()).total_seconds() / 3600

    # Format the output
    if output_format == 'hours':
        result = time_difference
    elif output_format == 'minutes':
        result = time_difference * 60
    elif output_format == 'detailed':
        result = {
            'hours': int(time_difference),
            'minutes': int((time_difference * 60) % 60),
            'seconds': int((time_difference * 3600) % 60)
        }
    else:
        return {'error': 'Invalid output_format specified.'}

    # Include metadata if requested
    metadata = {}
    if include_metadata:
        metadata = {
            'timezone1': {
                'utc_offset': dt1.utcoffset().total_seconds() / 3600,
                'dst': dt1.dst().total_seconds() / 3600
            },
            'timezone2': {
                'utc_offset': dt2.utcoffset().total_seconds() / 3600,
                'dst': dt2.dst().total_seconds() / 3600
            }
        }

    return {
        'time_difference': result,
        'metadata': metadata
    }

def timezone_converter(input_datetime, source_timezone_offset=None, target_timezone='AoE', output_format='date-time', custom_format=None):
    from datetime import datetime, timedelta
    import pytz

    # Validate input_datetime
    try:
        dt = datetime.fromisoformat(input_datetime)
    except ValueError:
        return {'error': 'Invalid input_datetime format. Must be ISO 8601.'}

    # Validate source_timezone_offset
    if source_timezone_offset is not None:
        if not isinstance(source_timezone_offset, (int, float)):
            return {'error': 'source_timezone_offset must be a number.'}
    else:
        # Auto-detect source timezone offset (not implemented, placeholder)
        source_timezone_offset = 0  # Default to UTC if not provided

    # Validate target_timezone
    valid_timezones = ['AoE', 'UTC', 'PST', 'EST', 'CET', 'IST', 'JST', 'AEST', 'GMT', 'BST', 'CST', 'MST']
    if target_timezone not in valid_timezones:
        return {'error': f'Invalid target_timezone. Must be one of {valid_timezones}.'}

    # Validate output_format
    valid_formats = ['date-time', 'timestamp', 'custom']
    if output_format not in valid_formats:
        return {'error': f'Invalid output_format. Must be one of {valid_formats}.'}

    # Calculate the target time
    source_offset_delta = timedelta(hours=source_timezone_offset)
    target_offset_delta = timedelta(hours=-12)  # AoE is UTC-12
    target_dt = dt + source_offset_delta + target_offset_delta

    # Format the output
    if output_format == 'date-time':
        return {'converted_datetime': target_dt.isoformat()}
    elif output_format == 'timestamp':
        return {'converted_datetime': target_dt.timestamp()}
    elif output_format == 'custom':
        if custom_format:
            return {'converted_datetime': target_dt.strftime(custom_format)}
        else:
            return {'error': 'custom_format must be provided when output_format is custom.'}

    return {'error': 'An unknown error occurred.'}

