def last_digit_extractor_v2(number, output_format='integer', handle_negative=False):
    """
    Extracts the last digit from a given integer or a list of integers.

    Parameters:
    - number: An integer or a list of integers from which the last digit(s) will be extracted.
    - output_format: The format of the output ('integer', 'string', 'detailed'). Defaults to 'integer'.
    - handle_negative: Boolean indicating whether to consider the sign of the number. Defaults to False.

    Returns:
    - The last digit(s) in the specified format.
    """
    # Error handling for incorrect input types
    if not isinstance(number, (int, list)):
        return {'error': 'Invalid input type for number. Must be integer or list of integers.'}
    if isinstance(number, list) and not all(isinstance(n, int) for n in number):
        return {'error': 'All elements in the list must be integers.'}
    if output_format not in ['integer', 'string', 'detailed']:
        return {'error': 'Invalid output format. Must be one of: integer, string, detailed.'}

    def extract_last_digit(n):
        if handle_negative:
            last_digit = abs(n) % 10
        else:
            last_digit = n % 10
        return last_digit

    if isinstance(number, int):
        last_digit = extract_last_digit(number)
        if output_format == 'integer':
            return last_digit
        elif output_format == 'string':
            return str(last_digit)
        elif output_format == 'detailed':
            return {'original': number, 'last_digit': last_digit}
    else:  # number is a list
        results = []
        for n in number:
            last_digit = extract_last_digit(n)
            if output_format == 'integer':
                results.append(last_digit)
            elif output_format == 'string':
                results.append(str(last_digit))
            elif output_format == 'detailed':
                results.append({'original': n, 'last_digit': last_digit})
        return results

