def extract_first_name(full_name, delimiter=' ', case_sensitive=True, include_middle_name=False, title_handling='ignore', cultural_format='western'):
    # Validate input types
    if not isinstance(full_name, str):
        return {'error': 'Invalid input: full_name must be a string.'}
    if not isinstance(delimiter, str):
        return {'error': 'Invalid input: delimiter must be a string.'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'Invalid input: case_sensitive must be a boolean.'}
    if not isinstance(include_middle_name, bool):
        return {'error': 'Invalid input: include_middle_name must be a boolean.'}
    if title_handling not in ['ignore', 'extract', 'remove']:
        return {'error': 'Invalid input: title_handling must be one of ignore, extract, remove.'}
    if cultural_format not in ['western', 'eastern', 'custom']:
        return {'error': 'Invalid input: cultural_format must be one of western, eastern, custom.'}

    # Split the full name based on the delimiter
    name_parts = full_name.split(delimiter)

    # Handle title based on title_handling parameter
    if title_handling == 'remove':
        # Remove common titles
        titles = ['Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.']
        name_parts = [part for part in name_parts if part not in titles]
    elif title_handling == 'extract':
        # Extract title if present
        title = name_parts[0] if name_parts[0] in ['Mr.', 'Mrs.', 'Ms.', 'Dr.', 'Prof.'] else ''

    # Determine first name based on cultural format
    if cultural_format == 'western':
        first_name = name_parts[0]
    elif cultural_format == 'eastern':
        first_name = name_parts[-1]
    else:  # custom
        first_name = name_parts[0]  # Default to western-like behavior

    # Include middle name if specified
    if include_middle_name and len(name_parts) > 2:
        first_name += ' ' + name_parts[1]

    # Adjust case sensitivity
    if not case_sensitive:
        first_name = first_name.lower()

    return {'first_name': first_name}

