def combined_length_calculator(strings, ignore_characters=[], ignore_position=[], ignore_substrings=[], case_sensitive=True, output_format='integer'):
    # Validate input
    if len(strings) < 2:
        return {'error': 'At least two strings are required.'}
    if output_format not in ['integer', 'text', 'detailed']:
        return {'error': 'Invalid output format specified.'}

    # Initialize total length
    total_length = 0
    detailed_info = []

    # Process each string
    for string in strings:
        original_string = string
        # Apply case sensitivity
        if not case_sensitive:
            string = string.lower()
            ignore_characters = [char.lower() for char in ignore_characters]
            ignore_substrings = [substr.lower() for substr in ignore_substrings]

        # Ignore specified characters
        for char in ignore_characters:
            string = string.replace(char, '')

        # Ignore specified substrings
        for substr in ignore_substrings:
            string = string.replace(substr, '')

        # Ignore specified positions
        if 'first' in ignore_position and len(string) > 0:
            string = string[1:]
        if 'last' in ignore_position and len(string) > 0:
            string = string[:-1]

        # Calculate length
        length = len(string)
        total_length += length

        # Collect detailed info
        if output_format == 'detailed':
            detailed_info.append({'original': original_string, 'processed': string, 'length': length})

    # Format output
    if output_format == 'integer':
        return total_length
    elif output_format == 'text':
        return f'The combined length is {total_length}.'
    elif output_format == 'detailed':
        return {'total_length': total_length, 'details': detailed_info}

