def last_letter_identifier(input: str, ignore_characters: list = [], character_set: str = '[a-zA-Z]', multi_character_suffix: bool = False, output_format: str = 'character') -> str:
    import re

    # Validate input type
    if not isinstance(input, str):
        return 'Error: Input must be a string.'

    # Validate ignore_characters type
    if not all(isinstance(char, str) for char in ignore_characters):
        return 'Error: All ignore_characters must be strings.'

    # Validate output_format
    if output_format not in ['character', 'text', 'json']:
        return 'Error: Invalid output_format. Must be one of character, text, json.'

    # Prepare the regex pattern
    try:
        pattern = re.compile(character_set)
    except re.error:
        return 'Error: Invalid regex pattern in character_set.'

    # Remove ignored characters
    filtered_input = ''.join([char for char in input if char not in ignore_characters])

    # Find all matches
    matches = pattern.findall(filtered_input)

    if not matches:
        return 'Error: No valid characters found in input.'

    # Determine the last meaningful character or sequence
    last_match = matches[-1] if not multi_character_suffix else ''.join(matches)

    # Format the output
    if output_format == 'character':
        return last_match[-1]  # Return the last character of the last match
    elif output_format == 'text':
        return last_match
    elif output_format == 'json':
        return {'last_character': last_match[-1], 'full_match': last_match}

