            'type': 'painting',
            'medium': 'oil',
            'location': 'Tate Gallery, London',
            'significance': 'A significant work of the Vorticism movement.'
        }
    }

    # Retrieve artwork information
    artwork_info = database.get(artwork_title)
    if not artwork_info:
