def educational_background_retriever(individual_names, include_fields_of_study=True, include_degrees=True, include_graduation_years=False, output_format='text'):
    """
    Retrieve educational background information for notable individuals.

    Parameters:
    - individual_names (list of str): A list of names of individuals whose educational backgrounds are being queried.
    - include_fields_of_study (bool): Whether to include fields of study in the output. Defaults to true.
    - include_degrees (bool): Whether to include degrees obtained in the output. Defaults to true.
    - include_graduation_years (bool): Whether to include graduation years in the output. Defaults to false.
    - output_format (str): The format of the output. Defaults to text. Must be one of ['text', 'json', 'xml'].

    Returns:
    - str: Educational background information in the specified format.
    """
    # Error handling for input types
    if not isinstance(individual_names, list) or not all(isinstance(name, str) for name in individual_names):
        return "Error: 'individual_names' must be a list of strings."
    if not isinstance(include_fields_of_study, bool):
        return "Error: 'include_fields_of_study' must be a boolean."
    if not isinstance(include_degrees, bool):
        return "Error: 'include_degrees' must be a boolean."
    if not isinstance(include_graduation_years, bool):
        return "Error: 'include_graduation_years' must be a boolean."
    if output_format not in ['text', 'json', 'xml']:
        return "Error: 'output_format' must be one of ['text', 'json', 'xml']."

    # Simulated database of educational backgrounds
    educational_data = {
        'David Bomberg': {
            'institutions': ['Slade School of Art'],
            'fields_of_study': ['Art'],
            'degrees': ['Diploma'],
            'graduation_years': ['1913']
        }
    }

    # Constructing the output
    results = {}
    for name in individual_names:
        if name in educational_data:
            data = educational_data[name]
            result = {'institutions': data['institutions']}
            if include_fields_of_study:
                result['fields_of_study'] = data['fields_of_study']
            if include_degrees:
                result['degrees'] = data['degrees']
            if include_graduation_years:
                result['graduation_years'] = data['graduation_years']
            results[name] = result
        else:
            results[name] = 'No data available'

    # Formatting the output
    if output_format == 'json':
        import json
        return json.dumps(results)
    elif output_format == 'xml':
        import dicttoxml
        return dicttoxml.dicttoxml(results).decode()
    else:
        return str(results)

