def find_shortest_word(input_string, ignore_punctuation=True, case_sensitive=False, ignore_characters='', return_positions=False, return_all_shortest=True):
    import re

    # Error handling for input type
    if not isinstance(input_string, str):
        return {'error': 'input_string must be a string'}
    if not isinstance(ignore_punctuation, bool):
        return {'error': 'ignore_punctuation must be a boolean'}
    if not isinstance(case_sensitive, bool):
        return {'error': 'case_sensitive must be a boolean'}
    if not isinstance(ignore_characters, str):
        return {'error': 'ignore_characters must be a string'}
    if not isinstance(return_positions, bool):
        return {'error': 'return_positions must be a boolean'}
    if not isinstance(return_all_shortest, bool):
        return {'error': 'return_all_shortest must be a boolean'}

    # Prepare the input string
    if not case_sensitive:
        input_string = input_string.lower()

    # Remove ignore_characters
    if ignore_characters:
        input_string = input_string.translate(str.maketrans('', '', ignore_characters))

    # Handle punctuation
    if ignore_punctuation:
        input_string = re.sub(r'[\W_]+', ' ', input_string)

    # Split the string into words
    words = input_string.split()

    # Find the shortest word(s)
    if not words:
        return {'shortest_words': [], 'positions': []} if return_positions else {'shortest_words': []}

    min_length = min(len(word) for word in words)
    shortest_words = [word for word in words if len(word) == min_length]

    # Return positions if required
    if return_positions:
        positions = [i for i, word in enumerate(words) if len(word) == min_length]
        return {'shortest_words': shortest_words, 'positions': positions}

    # Return all shortest words if required
    if return_all_shortest:
        return {'shortest_words': shortest_words}
    else:
        return {'shortest_words': [shortest_words[0]]}

# Example usage based on the question
result = find_shortest_word('Slade School of Art')
print(result)  # Expected output: {'shortest_words': ['of']}
